app = Flask(__name__)
# SECRET_KEY: prefer env var; otherwise use a per-install random key persisted in
# instance/secret_key so sessions survive restarts without a hardcoded fallback.
_secret_key = os.environ.get('SECRET_KEY')
if not _secret_key:
    _secret_key_file = os.path.join(app.instance_path, 'secret_key')
    try:
        with open(_secret_key_file, 'r') as _f:
            _secret_key = _f.read().strip()
    except OSError:
        _secret_key = None
    if not _secret_key:
        import secrets as _secrets
        _secret_key = _secrets.token_hex(32)
        os.makedirs(app.instance_path, exist_ok=True)
        with open(_secret_key_file, 'w') as _f:
            _f.write(_secret_key)
app.config['SECRET_KEY'] = _secret_key
app.config['SQLALCHEMY_DATABASE_URI'] = os.environ.get('DATABASE_URI', 'sqlite:///menteebom.db')
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)

# SQLite performance tuning — applied on every new connection
# Uses Engine class-level event so it doesn't trigger engine creation at import time
from sqlalchemy import event as sa_event, engine as sa_engine

_indexes_created = False

@sa_event.listens_for(sa_engine.Engine, "connect")
def _set_sqlite_pragma(dbapi_connection, connection_record):
    # Only apply to SQLite connections
    if not hasattr(dbapi_connection, 'execute'):
        return
    try:
        cursor = dbapi_connection.cursor()
        cursor.execute("PRAGMA journal_mode=WAL")       # Better concurrent reads (2-5x)
        # NOTE: foreign_keys=ON intentionally omitted — app uses ALTER TABLE at startup
        # which conflicts with SQLite FK enforcement (renames table to _old internally)
        cursor.execute("PRAGMA synchronous=NORMAL")      # Safe with WAL, faster writes
        cursor.execute("PRAGMA cache_size=-64000")        # 64 MB in-memory page cache
        cursor.execute("PRAGMA temp_store=MEMORY")        # Temp tables in RAM
        cursor.execute("PRAGMA busy_timeout=30000")       # Wait for write lock (concurrent imports)

        # Create missing FK indexes once per process (idempotent)
        global _indexes_created
        if not _indexes_created:
            _indexes_created = True
            for stmt in [
                "CREATE INDEX IF NOT EXISTS idx_rfq_item_rfq_id ON rfq_item(rfq_id)",
                "CREATE INDEX IF NOT EXISTS idx_rfq_item_part_id ON rfq_item(part_id)",
                "CREATE INDEX IF NOT EXISTS idx_po_item_po_id ON po_item(po_id)",
                "CREATE INDEX IF NOT EXISTS idx_po_item_part_id ON po_item(part_id)",
                "CREATE INDEX IF NOT EXISTS idx_po_qc_item_po_id ON po_qc_item(po_id)",
                "CREATE INDEX IF NOT EXISTS idx_po_qc_item_po_item_id ON po_qc_item(po_item_id)",
                "CREATE INDEX IF NOT EXISTS idx_bom_instance_badge_id ON bom_instance(badge_id)",
                "CREATE INDEX IF NOT EXISTS idx_rfq_bom_id ON rfq(bom_id)",
                "CREATE INDEX IF NOT EXISTS idx_po_rfq_id ON po(rfq_id)",
            ]:
                try:
                    cursor.execute(stmt)
                except Exception:
                    pass  # Table may not exist yet on first run
        cursor.close()
    except Exception:
        pass  # Skip if not SQLite

