class BOMVersion(db.Model):
    """Track BOM versions and changes"""
    id = db.Column(db.Integer, primary_key=True)
    bom_id = db.Column(db.Integer, db.ForeignKey('bom_data.id', ondelete='CASCADE'), nullable=False)
    version_number = db.Column(db.String(50), nullable=False)
    change_description = db.Column(db.Text, nullable=True)
    change_type = db.Column(db.String(50), nullable=True)  # major, minor, patch, hotfix
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    
    # Enhanced fields for better version control
    is_latest = db.Column(db.Boolean, default=True)  # Track which version is latest
    assembly_path = db.Column(db.String(500), nullable=True)  # Store original assembly path for updates
    bom_layout = db.Column(db.String(100), nullable=True)  # Store BOM layout used
    configuration = db.Column(db.String(100), nullable=True)  # Store configuration used
