# New Database Models for Parts Library Structure

class Part(db.Model):
    """Master Parts Library - Stores ALL unique parts/assemblies by part_number + revision"""
    __tablename__ = 'part'
    
    id = db.Column(db.Integer, primary_key=True)
    part_number = db.Column(db.String(100), nullable=False, index=True)
    revision = db.Column(db.String(50), nullable=False)
    part_name = db.Column(db.String(200), nullable=True)
    description = db.Column(db.Text, nullable=True)
    material = db.Column(db.String(100), nullable=True)
    finish1 = db.Column(db.String(100), nullable=True)
    finish2 = db.Column(db.String(100), nullable=True)
    state = db.Column(db.String(100), nullable=True)
    part_type = db.Column(db.String(50), nullable=True)  # Auto-classified: Assembly, Mechanical part, etc.
    part_type_manual = db.Column(db.Boolean, default=False)  # True if user manually overrode part_type
    thumbnail_data = deferred(db.Column(db.Text, nullable=True))  # JSON with base64 thumbnail — deferred to avoid loading on bulk queries
    thumbnail_path = db.Column(db.String(500), nullable=True)  # Relative path to thumbnail file in instance/

    # File availability flags (updated during import/update by scanning PDM directory)
    has_pdf = db.Column(db.Boolean, default=False)
    has_ai_pdf = db.Column(db.Boolean, default=False)
    has_step = db.Column(db.Boolean, default=False)
    step_files = db.Column(db.Text, nullable=True)  # JSON array of STEP filenames
    has_xt = db.Column(db.Boolean, default=False)

    # Shared editable fields (apply to all BOMs using this part)
    vendor = db.Column(db.String(200), nullable=True)
    manufacturer = db.Column(db.String(200), nullable=True)  # Manufacturer name
    manufacturer_pn = db.Column(db.String(200), nullable=True)  # Manufacturer Part Number
    unit_cost = db.Column(db.Float, nullable=True)  # Cost in USD
    lead_time = db.Column(db.Integer, nullable=True)  # in days
    inventory = db.Column(db.Integer, nullable=True)
    source_currency = db.Column(db.String(10), nullable=True)  # Currency from PO if applicable
    source_unit_cost = db.Column(db.Float, nullable=True)  # Original cost in source currency
    warehouse_box_number = db.Column(db.String(50), nullable=True)
    order_qty = db.Column(db.Float, nullable=True)  # Auto-updated from PO orders
    po_orders = db.Column(db.Text, nullable=True)  # JSON array of PO references
    notes = db.Column(db.Text, nullable=True)
    
    # ECO tracking fields
    eco_number = db.Column(db.String(100), nullable=True)  # Engineering Change Order reference
    eco_description = db.Column(db.Text, nullable=True)  # What changed in this revision
    backward_compatible = db.Column(db.Boolean, default=True)  # Can this revision replace previous ones
    
    # Datasheet (Google Drive URL)
    datasheet_drive_url = db.Column(db.String(500), nullable=True)

    # Status and metadata
    status = db.Column(db.String(20), default='active')  # active/obsolete/pending
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_parts', lazy=True))
    bom_parts = db.relationship('BOMPart', backref='part', lazy=True, passive_deletes=True)
    
    # Unique constraint on part_number + revision
    __table_args__ = (
        db.UniqueConstraint('part_number', 'revision', name='_part_number_revision_uc'),
    )
    
    def __repr__(self):
        return f'<Part {self.part_number} REV{self.revision}>'


class InventoryTransaction(db.Model):
    """Audit trail for every Part.inventory change.

    Rows are created automatically by a SQLAlchemy attribute listener on
    Part.inventory (see _on_part_inventory_set below), so every code path that
    mutates stock is captured — including future ones. Routes can attach a
    human-readable reason/reference via set_inventory_context()."""
    __tablename__ = 'inventory_transaction'

    id = db.Column(db.Integer, primary_key=True)
    part_id = db.Column(db.Integer, db.ForeignKey('part.id'), nullable=True, index=True)
    part_number = db.Column(db.String(100), nullable=False, index=True)  # denormalized — survives part deletion
    revision = db.Column(db.String(20), nullable=True)
    qty_before = db.Column(db.Float, nullable=True)
    qty_after = db.Column(db.Float, nullable=True)
    qty_change = db.Column(db.Float, nullable=False)  # positive = stock added, negative = withdrawn
    reason = db.Column(db.String(100), nullable=False, index=True)  # e.g. po_received, picking, manual_edit
    reference = db.Column(db.String(200), nullable=True)  # PO number / process number / stage label
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    username = db.Column(db.String(100), nullable=True)  # denormalized; 'menteeflow'/'system' for webhooks
    created_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            'id': self.id,
            'part_id': self.part_id,
            'part_number': self.part_number,
            'revision': self.revision,
            'qty_before': self.qty_before,
            'qty_after': self.qty_after,
            'qty_change': self.qty_change,
            'reason': self.reason,
            'reference': self.reference,
            'username': self.username,
            'created_at': self.created_at.isoformat() if self.created_at else None,
        }

    def __repr__(self):
        return f'<InventoryTransaction {self.part_number} {self.qty_change:+g} ({self.reason})>'


def set_inventory_context(reason, reference=None):
    """Attach a human-readable reason/reference to inventory changes made
    during the current request. Falls back to the Flask endpoint name when
    not set. Call at the top of routes that move stock."""
    try:
        from flask import g
        g.inventory_reason = reason
        g.inventory_reference = reference
    except RuntimeError:
        pass


def suppress_inventory_log(suppress=True):
    """Disable transaction logging for derived/rollup recalculations
    (assembly inventory roll-ups are computed values, not stock movements)."""
    try:
        from flask import g
        g.suppress_inventory_log = suppress
    except RuntimeError:
        pass


from sqlalchemy import event as _sqla_event
from sqlalchemy.orm.base import NO_VALUE as _NO_VALUE


@_sqla_event.listens_for(Part.inventory, 'set', active_history=True)
def _on_part_inventory_set(part, value, oldvalue, initiator):
    """Automatically record an InventoryTransaction whenever Part.inventory
    changes on a persistent Part. New Parts (initial import) are skipped."""
    try:
        if part.id is None:
            return  # brand-new part being created — initial stock, not a movement
        old = None if oldvalue is _NO_VALUE or oldvalue is None else float(oldvalue)
        new = None if value is None else float(value)
        if old == new:
            return
        change = (new or 0) - (old or 0)
        if change == 0:
            return

        reason, reference, user_id, username = None, None, None, None
        try:
            from flask import g, request, has_request_context
            if has_request_context():
                if getattr(g, 'suppress_inventory_log', False):
                    return
                reason = getattr(g, 'inventory_reason', None)
                reference = getattr(g, 'inventory_reference', None)
                if not reason:
                    reason = request.endpoint or request.path or 'unknown'
                try:
                    if current_user and current_user.is_authenticated:
                        user_id = current_user.id
                        username = current_user.username
                    elif request.headers.get('X-MenteeFlow-API-Key'):
                        username = 'menteeflow'
                except Exception:
                    pass
        except Exception:
            pass

        db.session.add(InventoryTransaction(
            part_id=part.id,
            part_number=part.part_number,
            revision=part.revision,
            qty_before=old,
            qty_after=new,
            qty_change=change,
            reason=(reason or 'unknown')[:100],
            reference=(reference[:200] if reference else None),
            user_id=user_id,
            username=username,
        ))
    except Exception as e:
        # Auditing must never break a stock operation
        print(f"WARNING: inventory transaction logging failed: {e}")


class ECO(db.Model):
    """ECO (Engineering Change Order) Database - Pre-seeded with ECO-001 to ECO-999"""
    __tablename__ = 'eco'
    
    id = db.Column(db.Integer, primary_key=True)
    eco_code = db.Column(db.String(20), nullable=False, unique=True, index=True)  # ECO-001, ECO-002, etc.
    description = db.Column(db.Text, nullable=True)  # ECO description
    backward_compatible = db.Column(db.Boolean, default=True)  # Backward compatibility flag
    status = db.Column(db.String(20), default='available')  # available, in_use, completed
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_ecos', lazy=True))
    
    def __repr__(self):
        return f'<ECO {self.eco_code}>'

class ProjectBadge(db.Model):
    """Project Badges - Used to categorize and filter BOMs"""
    __tablename__ = 'project_badge'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False, unique=True)  # Badge name (e.g., "V3.1")
    color = db.Column(db.String(20), nullable=False, default='#1976d2')  # Badge color (hex)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    is_active = db.Column(db.Boolean, default=True)
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_badges', lazy=True))
    bom_instances = db.relationship('BOMInstance', backref='badge', lazy=True)
    
    def __repr__(self):
        return f'<ProjectBadge {self.name}>'

class PartClassificationRule(db.Model):
    """Part Classification Rules - Database-driven part type classification"""
    __tablename__ = 'part_classification_rule'
    
    id = db.Column(db.Integer, primary_key=True)
    part_type = db.Column(db.String(100), nullable=False)  # Classification name (e.g., "Bearings", "Fasteners")
    keyword = db.Column(db.String(200), nullable=False)  # Keyword/pattern to match
    classification_method = db.Column(db.String(50), default='keyword')  # "keyword", "pattern", "3d_printing"
    priority = db.Column(db.Integer, default=100)  # Order of evaluation (lower = higher priority)
    is_active = db.Column(db.Boolean, default=True)  # Enable/disable rule
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_classification_rules', lazy=True))
    
    def __repr__(self):
        return f'<PartClassificationRule {self.keyword} -> {self.part_type}>'

class PartType(db.Model):
    """Managed Part Types - Centralized list of all part types"""
    __tablename__ = 'part_type'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False, unique=True)  # Part type name (e.g., "Bearings", "Fasteners")
    color = db.Column(db.String(20), nullable=True, default='#6c757d')  # Hex color for display
    is_active = db.Column(db.Boolean, default=True)  # For soft deletion
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_part_types', lazy=True))
    
    def __repr__(self):
        return f'<PartType {self.name}>'

class BOMInstance(db.Model):
    """BOM Instances - Each BOM revision (REV01, REV02, REV03) is a SEPARATE record"""
    __tablename__ = 'bom_instance'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(200), nullable=False)  # Display name (derived from assembly description)
    assembly_part_number = db.Column(db.String(100), nullable=False)  # Root assembly part number
    assembly_revision = db.Column(db.String(50), nullable=False)  # Root assembly revision (from PDM, for reference)
    version = db.Column(db.String(50), nullable=False, default='v1')  # BOM version number (v1, v2, v3, etc.)
    configuration = db.Column(db.String(100), nullable=True)  # PDM configuration
    bom_layout = db.Column(db.String(100), nullable=True)  # PDM BOM layout
    is_latest = db.Column(db.Boolean, default=False)  # TRUE only for the most recent version
    status = db.Column(db.String(20), default='active')  # active/obsolete/archived
    description = db.Column(db.Text, nullable=True)
    tags = db.Column(db.String(500), nullable=True)  # Comma-separated tags for filtering
    badge_id = db.Column(db.Integer, db.ForeignKey('project_badge.id'), nullable=True)  # Project badge
    
    # Store unit_cost in BOMInstance - single source of truth for assembly costs
    unit_cost = db.Column(db.Float, nullable=True)  # Calculated cost from BOM parts (sum of price_per_bom excluding parent)

    # PDM staleness (set by the nightly check job — detection only, never auto-updated)
    pdm_stale = db.Column(db.Boolean, default=False)
    pdm_stale_details = db.Column(db.Text, nullable=True)  # JSON list of {part_number, kind, bom_revision, pdm_revision, eco_number}
    last_pdm_check = db.Column(db.DateTime, nullable=True)

    # Metadata
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    previous_bom_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)  # Links to previous revision
    
    # Relationships
    creator = db.relationship('User', backref=db.backref('created_bom_instances', lazy=True))
    bom_parts = db.relationship('BOMPart', backref='bom_instance', lazy=True, passive_deletes=True)
    previous_bom = db.relationship('BOMInstance', remote_side=[id], backref='next_bom')
    
    # Unique constraint on assembly_part_number + version (not assembly_revision)
    __table_args__ = (
        db.UniqueConstraint('assembly_part_number', 'version', name='_assembly_part_version_uc'),
        db.Index('idx_assembly_latest', 'assembly_part_number', 'is_latest'),
        db.Index('idx_previous_bom', 'previous_bom_id'),
    )
    
    def __repr__(self):
        return f'<BOMInstance {self.assembly_part_number} {self.assembly_revision}>'

class BOMPart(db.Model):
    """Link Table - Links parts to BOMs with BOM-specific data and hierarchy"""
    __tablename__ = 'bom_part'
    
    id = db.Column(db.Integer, primary_key=True)
    bom_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id', ondelete='CASCADE'), nullable=False)
    part_id = db.Column(db.Integer, db.ForeignKey('part.id', ondelete='CASCADE'), nullable=False)
    
    # BOM-specific data
    quantity = db.Column(db.Float, nullable=False, default=1.0)  # BOM-specific quantity
    price_per_bom = db.Column(db.Float, nullable=True)  # Calculated: unit_cost × quantity
    bom_notes = db.Column(db.Text, nullable=True)  # BOM-specific notes (different from Part.notes)
    
    # Hierarchy data
    parent_bom_part_id = db.Column(db.Integer, db.ForeignKey('bom_part.id'), nullable=True)  # Parent-child relationship
    level = db.Column(db.Integer, nullable=False, default=0)  # Hierarchy level (0=root)
    sequence = db.Column(db.Integer, nullable=False, default=0)  # Order in BOM
    
    # Metadata
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    
    # Relationships
    parent_bom_part = db.relationship('BOMPart', remote_side=[id], backref='child_bom_parts')
    
    # Indexes for performance
    __table_args__ = (
        db.Index('idx_bom_part', 'bom_id', 'part_id'),
        db.Index('idx_parent_bom_part', 'parent_bom_part_id'),
        db.Index('idx_bom_level', 'bom_id', 'level'),
    )
    
    def __repr__(self):
        return f'<BOMPart BOM{self.bom_id} Part{self.part_id} Qty{self.quantity}>'

class Notification(db.Model):
    """Per-user server notifications (stale-BOM alerts, future event types)"""
    __tablename__ = 'notification'

    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id', ondelete='CASCADE'), nullable=False)
    type = db.Column(db.String(50), nullable=False)  # 'pdm_stale' for now
    title = db.Column(db.String(200), nullable=False)
    message = db.Column(db.Text, nullable=True)
    link = db.Column(db.String(300), nullable=True)  # frontend route, e.g. /assembly-bom?bom_id=12
    payload = db.Column(db.Text, nullable=True)  # JSON string
    dedupe_key = db.Column(db.String(200), nullable=True)  # e.g. 'pdm_stale:{bom_id}:{hash12}'
    is_read = db.Column(db.Boolean, nullable=False, default=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    user = db.relationship('User', backref=db.backref('notifications', lazy=True, passive_deletes=True))

    __table_args__ = (
        db.Index('idx_notif_user_read', 'user_id', 'is_read'),
        db.Index('idx_notif_user_id', 'user_id', 'id'),
    )

    def __repr__(self):
        return f'<Notification {self.id} user{self.user_id} {self.type}>'

# RFQ/PO Database Models
class RFQ(db.Model):
    """Track all RFQ exports"""
    __tablename__ = 'rfq'
    
    id = db.Column(db.Integer, primary_key=True)
    bom_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)
    bom_name = db.Column(db.String(200), nullable=False)  # Store BOM name/revision
    bom_revision = db.Column(db.String(50), nullable=True)
    rfq_name = db.Column(db.String(200), nullable=False)  # "BOM_NAME - RFQ - DATE"
    created_date = db.Column(db.DateTime, default=datetime.utcnow)
    status = db.Column(db.String(20), default='active')  # active, converted_to_po, cancelled
    google_drive_folder_id = db.Column(db.String(200), nullable=True)
    google_drive_folder_url = db.Column(db.Text, nullable=True)
    excluded_parts_note = db.Column(db.Text, nullable=True)  # Note about excluded parts in PO
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    
    # Relationships
    bom_instance = db.relationship('BOMInstance', backref='rfqs')
    creator = db.relationship('User', backref='created_rfqs')
    rfq_items = db.relationship('RFQItem', backref='rfq', lazy=True, cascade='all, delete-orphan')
    po = db.relationship('PO', backref='rfq', uselist=False)  # One RFQ -> One PO
    
    def __repr__(self):
        return f'<RFQ {self.rfq_name}>'

class RFQItem(db.Model):
    """Parts included in each RFQ"""
    __tablename__ = 'rfq_item'
    
    id = db.Column(db.Integer, primary_key=True)
    rfq_id = db.Column(db.Integer, db.ForeignKey('rfq.id', ondelete='CASCADE'), nullable=False)
    part_id = db.Column(db.Integer, db.ForeignKey('part.id'), nullable=True)
    part_number = db.Column(db.String(100), nullable=False)  # Store for reference
    revision = db.Column(db.String(50), nullable=False)
    quantity = db.Column(db.Float, nullable=False)
    material = db.Column(db.String(100), nullable=True)
    finish1 = db.Column(db.String(100), nullable=True)
    finish2 = db.Column(db.String(100), nullable=True)
    state = db.Column(db.String(100), nullable=True)
    
    # Relationships
    part = db.relationship('Part', backref='rfq_items')
    
    def __repr__(self):
        return f'<RFQItem {self.part_number} REV{self.revision} Qty{self.quantity}>'

class PO(db.Model):
    """Track all Purchase Orders"""
    __tablename__ = 'po'
    
    id = db.Column(db.Integer, primary_key=True)
    rfq_id = db.Column(db.Integer, db.ForeignKey('rfq.id'), nullable=True)  # Links to source RFQ
    bom_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)
    bom_name = db.Column(db.String(200), nullable=False)
    bom_revision = db.Column(db.String(50), nullable=True)
    po_number = db.Column(db.String(100), nullable=False, unique=True)  # "PO-001"
    vendor = db.Column(db.String(200), nullable=False)
    po_date = db.Column(db.DateTime, default=datetime.utcnow)
    status = db.Column(db.String(20), default='pending')  # pending, sent_to_vendor, received, cancelled
    pre_receive_status = db.Column(db.String(20), nullable=True)  # Status before marking received, for undo
    po_received = db.Column(db.Boolean, default=False)  # Checkbox in UI
    received_date = db.Column(db.DateTime, nullable=True)
    google_drive_folder_id = db.Column(db.String(200), nullable=True)
    google_drive_folder_url = db.Column(db.Text, nullable=True)
    quotation_file_path = db.Column(db.String(500), nullable=True)  # Store uploaded quotation path
    waybill = db.Column(db.String(200), nullable=True)  # Tracking number
    invoice_number = db.Column(db.String(200), nullable=True)  # Invoice number
    total_cost = db.Column(db.Float, nullable=True)  # Total cost of PO (can be edited by admin)
    lead_time = db.Column(db.Integer, nullable=True)  # Lead time in days
    parent_po_id = db.Column(db.Integer, db.ForeignKey('po.id'), nullable=True)  # Parent PO for multi-delivery orders
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'))
    currency = db.Column(db.String(10), default='USD', nullable=False)  # Currency code (USD, EUR, ILS)
    exchange_rate = db.Column(db.Float, nullable=True)  # Exchange rate used at time of PO creation
    po_doc_vars = db.Column(db.Text, nullable=True)  # JSON template_vars used to generate the PO Google Doc (for regeneration on edit)

    # Relationships
    bom_instance = db.relationship('BOMInstance', backref='pos')
    creator = db.relationship('User', backref='created_pos')
    po_items = db.relationship('POItem', backref='po', lazy=True, cascade='all, delete-orphan')
    po_qc_items = db.relationship('POQCItem', backref='po', lazy=True, cascade='all, delete-orphan')
    parent_po = db.relationship('PO', remote_side=[id], backref='child_pos')
    
    def __repr__(self):
        return f'<PO {self.po_number}>'

class POItem(db.Model):
    """Parts included in each PO with pricing"""
    __tablename__ = 'po_item'
    
    id = db.Column(db.Integer, primary_key=True)
    po_id = db.Column(db.Integer, db.ForeignKey('po.id', ondelete='CASCADE'), nullable=False)
    part_id = db.Column(db.Integer, db.ForeignKey('part.id'), nullable=True)
    part_number = db.Column(db.String(100), nullable=False)
    revision = db.Column(db.String(50), nullable=False)
    quantity = db.Column(db.Float, nullable=False)  # Order quantity
    unit_cost = db.Column(db.Float, nullable=False)  # Cost in USD (converted)
    total_cost = db.Column(db.Float, nullable=False)  # quantity * unit_cost (in USD)
    material = db.Column(db.String(100), nullable=True)
    finish1 = db.Column(db.String(100), nullable=True)
    finish2 = db.Column(db.String(100), nullable=True)
    currency = db.Column(db.String(10), default='USD', nullable=False)  # Original currency
    original_unit_cost = db.Column(db.Float, nullable=True)  # Original cost in PO currency
    original_currency = db.Column(db.String(10), nullable=True)  # Original currency code
    
    # Relationships
    part = db.relationship('Part', backref='po_items')
    
    def __repr__(self):
        return f'<POItem {self.part_number} REV{self.revision} Qty{self.quantity} Cost${self.total_cost}>'

class POQCItem(db.Model):
    """QC approval data for each part in a PO"""
    __tablename__ = 'po_qc_item'
    
    id = db.Column(db.Integer, primary_key=True)
    po_id = db.Column(db.Integer, db.ForeignKey('po.id', ondelete='CASCADE'), nullable=False)
    po_item_id = db.Column(db.Integer, db.ForeignKey('po_item.id', ondelete='CASCADE'), nullable=True)
    part_number = db.Column(db.String(100), nullable=False)
    revision = db.Column(db.String(50), nullable=False)
    quantity_in_po = db.Column(db.Float, nullable=False)
    qty_arrived = db.Column(db.Float, nullable=True)
    qty_approved = db.Column(db.Float, nullable=True)
    qc_approved = db.Column(db.Boolean, default=False)
    warehouse_box_number = db.Column(db.String(50), nullable=True)
    notes = db.Column(db.Text, nullable=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    # Revision mismatch tracking
    resolved_to_revision = db.Column(db.String(50), nullable=True)  # Actual revision inventory was applied to
    revision_decision = db.Column(db.String(20), nullable=True)  # 'upgrade' or 'keep_original'

    # Relationships
    # Note: backref 'po' is defined on PO model via po_qc_items relationship
    po_item = db.relationship('POItem', backref='qc_items')

    def __repr__(self):
        return f'<POQCItem {self.part_number} REV{self.revision} Approved:{self.qc_approved}>'

class VendorList(db.Model):
    """Vendor list for PO creation"""
    __tablename__ = 'vendor_list'
    
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(200), unique=True, nullable=False)
