class ProcessBOMInstance(db.Model):
    """Dissolved assembly tree for manufacturing processes - separate from regular BOMInstance"""
    __tablename__ = 'process_bom_instance'

    id = db.Column(db.Integer, primary_key=True)
    dof_mapping_id = db.Column(db.Integer, db.ForeignKey('dof_mapping.id'), nullable=False)
    badge_id = db.Column(db.Integer, db.ForeignKey('project_badge.id'), nullable=False)
    source_bom_instance_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)  # Parent BOM we extracted from

    # The dissolved tree stored as JSON
    dissolved_tree_json = db.Column(db.Text, nullable=False)

    # Versioning
    version = db.Column(db.Integer, default=1)  # Increments when BOM changes trigger re-dissolution
    is_current = db.Column(db.Boolean, default=True)

    # Metadata
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Relationships
    dof_mapping = db.relationship('DOFMapping', backref=db.backref('process_bom_instances', lazy=True))
    badge = db.relationship('ProjectBadge', backref=db.backref('process_bom_instances', lazy=True))
    source_bom = db.relationship('BOMInstance', backref=db.backref('process_bom_instances', lazy=True))
    creator = db.relationship('User', backref=db.backref('created_process_boms', lazy=True))

    __table_args__ = (
        db.Index('idx_process_bom_dof', 'dof_mapping_id', 'is_current'),
        db.Index('idx_process_bom_badge', 'badge_id'),
    )

    def __repr__(self):
        return f'<ProcessBOMInstance dof={self.dof_mapping_id} v{self.version}>'


class ManufacturingProcess(db.Model):
    """Manufacturing process ticket from MenteeFlow"""
    __tablename__ = 'manufacturing_process'

    id = db.Column(db.Integer, primary_key=True)
    process_number = db.Column(db.String(20), nullable=False, unique=True, index=True)  # "X-XXX-XXX" format
    badge_id = db.Column(db.Integer, db.ForeignKey('project_badge.id'), nullable=False)
    dof_mapping_id = db.Column(db.Integer, db.ForeignKey('dof_mapping.id'), nullable=False)
    process_bom_instance_id = db.Column(db.Integer, db.ForeignKey('process_bom_instance.id'), nullable=True)

    # Process info
    name = db.Column(db.String(300), nullable=True)  # Process name from MenteeFlow
    current_stage = db.Column(db.Integer, default=1)  # 1-6
    status = db.Column(db.String(30), default='active')  # active, completed, cancelled, on_hold, template

    # Template flag: a "no serial number" reference process per DOF, used by MenteeFlow/admin
    # to preview a DOF's stage flow read-only. Excluded from normal process lists; writes blocked.
    is_template = db.Column(db.Boolean, default=False, nullable=False, index=True)

    # Parsed from process number
    badge_digit = db.Column(db.String(5), nullable=True)  # First digit
    dof_identifier = db.Column(db.String(10), nullable=True)  # Middle 3 digits
    menteeflow_suffix = db.Column(db.String(10), nullable=True)  # Last 3 digits

    # MenteeFlow reference
    menteeflow_ticket_id = db.Column(db.String(100), nullable=True)
    menteeflow_url = db.Column(db.String(500), nullable=True)  # Direct link back to MenteeFlow

    # Reversal tracking
    revert_count = db.Column(db.Integer, default=0)

    # Metadata
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    completed_at = db.Column(db.DateTime, nullable=True)

    # Relationships
    badge = db.relationship('ProjectBadge', backref=db.backref('manufacturing_processes', lazy=True))
    dof_mapping = db.relationship('DOFMapping', backref=db.backref('manufacturing_processes', lazy=True))
    process_bom = db.relationship('ProcessBOMInstance', backref=db.backref('manufacturing_processes', lazy=True))
    stages = db.relationship('ProcessStage', backref='process', lazy=True, passive_deletes=True,
                             order_by='ProcessStage.stage_number')

    __table_args__ = (
        db.Index('idx_mfg_process_badge', 'badge_id', 'status'),
        db.Index('idx_mfg_process_dof', 'dof_mapping_id'),
    )

    def __repr__(self):
        return f'<ManufacturingProcess {self.process_number} stage={self.current_stage}>'


class ProcessStage(db.Model):
    """Individual stage progress within a manufacturing process"""
    __tablename__ = 'process_stage'

    id = db.Column(db.Integer, primary_key=True)
    process_id = db.Column(db.Integer, db.ForeignKey('manufacturing_process.id', ondelete='CASCADE'), nullable=False)
    stage_number = db.Column(db.Integer, nullable=False)  # 1, 2, 3, 4, 5, 6
    stage_sub = db.Column(db.String(10), nullable=True)  # "3.1", "3.2" for sub-stages
    stage_name = db.Column(db.String(100), nullable=False)  # "Picking", "Motor Assembly", etc.
    status = db.Column(db.String(30), default='pending')  # pending, in_progress, completed, skipped

    # Stage-specific data stored as JSON
    stage_data_json = db.Column(db.Text, nullable=True)  # Picked parts, assembly status, etc.

    # For Stage 2 (Picking): picked and unpicked parts
    picked_parts_json = db.Column(db.Text, nullable=True)
    unpicked_parts_json = db.Column(db.Text, nullable=True)

    # Re-pick tracking (JSON array of re-pick events)
    repick_history_json = db.Column(db.Text, nullable=True)

    # Metadata
    started_at = db.Column(db.DateTime, nullable=True)
    completed_at = db.Column(db.DateTime, nullable=True)
    completed_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Reversal tracking
    reverted_at = db.Column(db.DateTime, nullable=True)
    reverted_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    revert_reason = db.Column(db.String(500), nullable=True)
    original_completed_at = db.Column(db.DateTime, nullable=True)

    # Relationships
    completer = db.relationship('User', foreign_keys=[completed_by],
                                backref=db.backref('completed_process_stages', lazy=True))
    reverter = db.relationship('User', foreign_keys=[reverted_by],
                               backref=db.backref('reverted_process_stages', lazy=True))

    __table_args__ = (
        db.UniqueConstraint('process_id', 'stage_number', 'stage_sub', name='_process_stage_uc'),
        db.Index('idx_stage_process', 'process_id', 'stage_number'),
    )

    def __repr__(self):
        return f'<ProcessStage process={self.process_id} stage={self.stage_number} sub={self.stage_sub}>'


class MenteeFlowConfig(db.Model):
    """MenteeFlow integration configuration (single-row table)"""
    __tablename__ = 'menteeflow_config'

    id = db.Column(db.Integer, primary_key=True)
    base_url = db.Column(db.String(500), nullable=True)  # MenteeFlow base URL
    api_key = db.Column(db.String(200), nullable=True)  # Shared API key for outgoing calls
    webhook_secret = db.Column(db.String(200), nullable=True)  # Secret for validating incoming webhooks
    is_active = db.Column(db.Boolean, default=True)

    # Badge-to-digit mapping (JSON: {"V3.2": "2", "V3.3": "3"})
    badge_digit_mapping = db.Column(db.Text, nullable=True)

    # Badge IDs displayed in Robot Assembly tab (JSON array: [1, 3, 5])
    displayed_badge_ids = db.Column(db.Text, nullable=True)

    # Embed URL template for iframe embedding
    embed_url_template = db.Column(db.String(500), nullable=True)

    # Metadata
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    updated_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Relationships
    updater = db.relationship('User', backref=db.backref('menteeflow_config_updates', lazy=True))

    def __repr__(self):
        return f'<MenteeFlowConfig active={self.is_active}>'


class MenteeFlowApiKeyHistory(db.Model):
    """History of saved API key / webhook secret pairs"""
    __tablename__ = 'menteeflow_api_key_history'

    id = db.Column(db.Integer, primary_key=True)
    label = db.Column(db.String(200), nullable=False)  # User-given name, e.g. "Production Key #1"
    api_key = db.Column(db.String(200), nullable=False)
    webhook_secret = db.Column(db.String(200), nullable=False)
    is_active = db.Column(db.Boolean, default=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    revoked_at = db.Column(db.DateTime, nullable=True)

    creator = db.relationship('User', backref=db.backref('menteeflow_api_keys', lazy=True))

    def __repr__(self):
        return f'<MenteeFlowApiKeyHistory {self.label} active={self.is_active}>'


class EmbedToken(db.Model):
    """Short-lived tokens for embedding MenteeBOM views in MenteeFlow iframes"""
    __tablename__ = 'embed_token'

    id = db.Column(db.Integer, primary_key=True)
    token = db.Column(db.String(128), nullable=False, unique=True, index=True)
    process_id = db.Column(db.Integer, db.ForeignKey('manufacturing_process.id'), nullable=True)
    limb_process_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_process.id'), nullable=True)
    stage_scope = db.Column(db.String(10), nullable=True)  # "2", "3.1", "4", "LL1", etc.
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    expires_at = db.Column(db.DateTime, nullable=False)
    used_at = db.Column(db.DateTime, nullable=True)
    is_revoked = db.Column(db.Boolean, default=False)

    # Relationships
    process = db.relationship('ManufacturingProcess', backref=db.backref('embed_tokens', lazy=True))
    limb_process = db.relationship('LimbAssemblyProcess', backref=db.backref('embed_tokens', lazy=True))

    def __repr__(self):
        return f'<EmbedToken process={self.process_id} limb_process={self.limb_process_id} scope={self.stage_scope}>'


class PartReplacement(db.Model):
    """Records when a part is swapped during a manufacturing process (DOF or limb)"""
    __tablename__ = 'part_replacement'

    id = db.Column(db.Integer, primary_key=True)
    process_id = db.Column(db.Integer, db.ForeignKey('manufacturing_process.id'), nullable=True)
    stage_id = db.Column(db.Integer, db.ForeignKey('process_stage.id'), nullable=True)

    # For limb assembly processes
    limb_process_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_process.id'), nullable=True)
    limb_stage_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_process_stage.id'), nullable=True)

    # The part being returned
    old_part_id = db.Column(db.Integer, db.ForeignKey('part.id'), nullable=False)
    old_part_number = db.Column(db.String(100), nullable=False)
    old_revision = db.Column(db.String(50), nullable=True)

    # The replacement part (same part number, possibly different revision)
    new_part_id = db.Column(db.Integer, db.ForeignKey('part.id'), nullable=False)
    new_part_number = db.Column(db.String(100), nullable=False)
    new_revision = db.Column(db.String(50), nullable=True)

    quantity = db.Column(db.Integer, default=1)
    reason = db.Column(db.String(500), nullable=True)

    # Metadata
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Relationships
    process = db.relationship('ManufacturingProcess', backref=db.backref('part_replacements', lazy=True))
    stage = db.relationship('ProcessStage', backref=db.backref('part_replacements', lazy=True))
    old_part = db.relationship('Part', foreign_keys=[old_part_id])
    new_part = db.relationship('Part', foreign_keys=[new_part_id])
    replacer = db.relationship('User', backref=db.backref('part_replacements_made', lazy=True))

    def __repr__(self):
        return f'<PartReplacement {self.old_part_number} -> {self.new_part_number}>'


class LimbAssemblySnapshot(db.Model):
    """Per-limb assembly tree snapshot with dissolve tracking.
    Stores the limb's BOM tree state with user-applied dissolves (flattening of sub-assemblies).
    One snapshot per limb; dissolves are design decisions that persist across all processes.
    """
    __tablename__ = 'limb_assembly_snapshot'

    id = db.Column(db.Integer, primary_key=True)
    limb_id = db.Column(db.Integer, db.ForeignKey('robot_limb.id'), unique=True, nullable=False)
    source_bom_instance_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)

    # The original tree from BOM (never mutated after initial build)
    base_tree_json = db.Column(db.Text, nullable=True)
    # Current effective tree (base tree + all dissolves applied, with auto-consolidation)
    effective_tree_json = db.Column(db.Text, nullable=True)
    # JSON list of bom_part_id integers that have been dissolved
    dissolved_node_ids = db.Column(db.Text, default='[]')

    # Staleness tracking
    bom_version_ref = db.Column(db.String(64), nullable=True)  # BOMInstance.version when snapshot was last built
    is_stale = db.Column(db.Boolean, default=False)
    stale_diff_json = db.Column(db.Text, nullable=True)  # JSON describing what changed

    # Metadata
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    # Relationships
    limb = db.relationship('RobotLimb', backref=db.backref('assembly_snapshot', uselist=False))
    source_bom = db.relationship('BOMInstance', backref=db.backref('limb_snapshots', lazy=True))

    def __repr__(self):
        return f'<LimbAssemblySnapshot limb={self.limb_id} stale={self.is_stale}>'


class LimbAssemblyStageDefinition(db.Model):
    """User-defined assembly stage for a limb (post-DOF).
    Each row = one assembly that needs its own picking + assembly workflow."""
    __tablename__ = 'limb_assembly_stage_def'

    id = db.Column(db.Integer, primary_key=True)
    limb_id = db.Column(db.Integer, db.ForeignKey('robot_limb.id', ondelete='CASCADE'), nullable=False)

    # Stage identity
    stage_prefix = db.Column(db.String(10), nullable=False)       # "LL", "RA", "H"
    stage_number = db.Column(db.Integer, nullable=False)            # 1, 2, 3 (top-level order)
    stage_sub = db.Column(db.String(10), nullable=True)             # "1", "2" for sub-stages, NULL for top-level
    stage_label = db.Column(db.String(20), nullable=False)          # "LL1", "LL1.1", "LL2"
    stage_name = db.Column(db.String(200), nullable=False)          # Human name from BOM description

    # Link to BOM assembly
    bom_part_id = db.Column(db.Integer, nullable=True)              # bom_part_id from snapshot tree
    assembly_part_number = db.Column(db.String(200), nullable=False)
    bom_instance_id = db.Column(db.Integer, db.ForeignKey('bom_instance.id'), nullable=True)

    # Hierarchy & parallelism
    parent_stage_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_stage_def.id'), nullable=True)
    parallel_group = db.Column(db.Integer, nullable=True)           # Same group number = can run in parallel
    display_order = db.Column(db.Integer, default=0)

    has_drawing = db.Column(db.Boolean, default=False)
    is_active = db.Column(db.Boolean, default=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    created_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Relationships
    limb = db.relationship('RobotLimb', backref=db.backref('assembly_stage_defs', lazy=True))
    parent_stage = db.relationship('LimbAssemblyStageDefinition', remote_side=[id], backref='sub_stages')
    bom_instance = db.relationship('BOMInstance', backref=db.backref('limb_stage_defs', lazy=True))
    creator = db.relationship('User', backref=db.backref('created_limb_stage_defs', lazy=True))

    __table_args__ = (
        db.UniqueConstraint('limb_id', 'stage_label', name='_limb_stage_label_uc'),
        db.Index('idx_limb_stage_limb', 'limb_id', 'display_order'),
    )

    def __repr__(self):
        return f'<LimbAssemblyStageDefinition {self.stage_label} limb={self.limb_id}>'


class LimbAssemblyProcess(db.Model):
    """Manufacturing process for post-DOF limb assembly (one per robot per limb)."""
    __tablename__ = 'limb_assembly_process'

    id = db.Column(db.Integer, primary_key=True)
    process_number = db.Column(db.String(30), nullable=False, unique=True, index=True)  # e.g. "LL-2-001"
    badge_id = db.Column(db.Integer, db.ForeignKey('project_badge.id'), nullable=False)
    limb_id = db.Column(db.Integer, db.ForeignKey('robot_limb.id'), nullable=False)

    status = db.Column(db.String(30), default='active')  # active | completed | cancelled
    current_stage_label = db.Column(db.String(20), nullable=True)
    revert_count = db.Column(db.Integer, default=0)

    menteeflow_ticket_id = db.Column(db.String(100), nullable=True)
    menteeflow_url = db.Column(db.String(500), nullable=True)

    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    completed_at = db.Column(db.DateTime, nullable=True)

    # Relationships
    badge = db.relationship('ProjectBadge', backref=db.backref('limb_assembly_processes', lazy=True))
    limb = db.relationship('RobotLimb', backref=db.backref('assembly_processes', lazy=True))
    stages = db.relationship('LimbAssemblyProcessStage', backref='process', lazy=True,
                             passive_deletes=True, order_by='LimbAssemblyProcessStage.display_order')

    __table_args__ = (
        db.Index('idx_limb_proc_badge', 'badge_id', 'status'),
        db.Index('idx_limb_proc_limb', 'limb_id'),
    )

    def __repr__(self):
        return f'<LimbAssemblyProcess {self.process_number} status={self.status}>'


class LimbAssemblyProcessStage(db.Model):
    """Individual stage within a limb assembly process.
    Each stage has two phases: picking then assembly."""
    __tablename__ = 'limb_assembly_process_stage'

    id = db.Column(db.Integer, primary_key=True)
    process_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_process.id', ondelete='CASCADE'), nullable=False)
    stage_def_id = db.Column(db.Integer, db.ForeignKey('limb_assembly_stage_def.id'), nullable=False)

    # Denormalized from definition for display speed
    stage_label = db.Column(db.String(20), nullable=False)       # "LL1", "LL1.1"
    stage_name = db.Column(db.String(200), nullable=False)
    assembly_part_number = db.Column(db.String(200), nullable=False)
    display_order = db.Column(db.Integer, default=0)
    parallel_group = db.Column(db.Integer, nullable=True)

    # Phase tracking: pending → picking → assembly → completed
    phase = db.Column(db.String(20), default='pending')  # pending, picking, assembly, completed, skipped
    status = db.Column(db.String(30), default='pending')  # pending, in_progress, completed, reverted

    # Picking data (same JSON structure as ProcessStage)
    picked_parts_json = db.Column(db.Text, nullable=True)
    unpicked_parts_json = db.Column(db.Text, nullable=True)
    repick_history_json = db.Column(db.Text, nullable=True)

    # Timestamps
    started_at = db.Column(db.DateTime, nullable=True)
    completed_at = db.Column(db.DateTime, nullable=True)
    completed_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)

    # Reversal tracking
    reverted_at = db.Column(db.DateTime, nullable=True)
    reverted_by = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=True)
    revert_reason = db.Column(db.String(500), nullable=True)
    original_completed_at = db.Column(db.DateTime, nullable=True)

    # Relationships
    stage_def = db.relationship('LimbAssemblyStageDefinition')
    completer = db.relationship('User', foreign_keys=[completed_by], backref=db.backref('completed_limb_stages', lazy=True))
    reverter = db.relationship('User', foreign_keys=[reverted_by], backref=db.backref('reverted_limb_stages', lazy=True))

    __table_args__ = (
        db.UniqueConstraint('process_id', 'stage_def_id', name='_limb_proc_stage_uc'),
        db.Index('idx_limb_stage_proc', 'process_id', 'display_order'),
    )

    def __repr__(self):
        return f'<LimbAssemblyProcessStage {self.stage_label} phase={self.phase} status={self.status}>'


