# ---------------------------------------------------------------------------
# View-only role enforcement
#
# Most routes are guarded by @login_required alone, so a per-role permission
# table cannot make an account read-only on its own. This hook does it in one
# place: a 'viewer' user may only issue safe (GET/HEAD/OPTIONS) requests, plus
# logout. Everything else is rejected with 403 before the view runs.
# ---------------------------------------------------------------------------
VIEWER_SAFE_METHODS = frozenset({'GET', 'HEAD', 'OPTIONS'})
VIEWER_ALLOWED_WRITE_ENDPOINTS = frozenset({'login', 'logout'})


@app.before_request
def block_viewer_writes():
    if request.method in VIEWER_SAFE_METHODS:
        return None
    if not current_user.is_authenticated or getattr(current_user, 'role', None) != 'viewer':
        return None
    if request.endpoint in VIEWER_ALLOWED_WRITE_ENDPOINTS:
        return None
    message = 'Read-only account: this action is not permitted'
    wants_json = (request.path.startswith('/api/') or request.is_json
                  or 'application/json' in request.headers.get('Accept', ''))
    if wants_json:
        return jsonify({'success': False, 'error': message}), 403
    return message, 403

