# ── Live-update version bumps ────────────────────────────────────────────────
# Bump the matching poll channel whenever rows of these model groups change,
# no matter which endpoint did it. Browsers polling /api/poll/updates refetch
# their page data when a channel version changes.
from itertools import chain as _it_chain
from sqlalchemy import event as _sa_event
from utils.live_updates import bump as _bump_live_version

_LIVE_CHANNEL_MODELS = {
    'purchases': (RFQ, RFQItem, PO, POItem),
    'boms': (BOMInstance, BOMPart, DissolvedBOM),
    'parts': (Part,),
}


def _channels_for_class(cls):
    return [ch for ch, models in _LIVE_CHANNEL_MODELS.items() if issubclass(cls, models)]


@_sa_event.listens_for(db.session, 'after_flush')
def _mark_live_channels_changed(session, flush_context):
    changed = session.info.setdefault('live_channels_changed', set())
    for obj in _it_chain(session.new, session.dirty, session.deleted):
        for ch in _channels_for_class(type(obj)):
            changed.add(ch)


@_sa_event.listens_for(db.session, 'after_bulk_update')
@_sa_event.listens_for(db.session, 'after_bulk_delete')
def _mark_live_channels_bulk(op_context):
    # query(...).update()/delete() bypass session.new/dirty/deleted
    try:
        cls = op_context.mapper.class_
    except Exception:
        return
    changed = op_context.session.info.setdefault('live_channels_changed', set())
    for ch in _channels_for_class(cls):
        changed.add(ch)


@_sa_event.listens_for(db.session, 'after_commit')
def _bump_live_versions(session):
    for ch in session.info.pop('live_channels_changed', set()):
        _bump_live_version(ch)


@_sa_event.listens_for(db.session, 'after_rollback')
def _clear_live_channel_flags(session):
    session.info.pop('live_channels_changed', None)


def _guard_pdm_import(part_number, kind):
    """Concurrency guard for PDM import/update endpoints: one running
    import per assembly across all users. Returns an error response to
    return directly, or None when the import may proceed (registered in
    the activity registry; released by the teardown handler below)."""
    from utils.live_updates import try_start_import
    ok, existing = try_start_import(part_number, current_user.username, kind)
    if not ok:
        return jsonify({
            'success': False,
            'error': (f"A PDM {existing['kind']} of {existing['part_number']} is already running "
                      f"(started by {existing['username']}). Please wait for it to finish."),
        }), 409
    g.pdm_import_key = part_number
    return None


@app.teardown_request
def _end_pdm_import_activity(exc=None):
    key = g.pop('pdm_import_key', None)
    if key:
        from utils.live_updates import end_import
        end_import(key)

