# HELPER FUNCTIONS
# ============================================================================

def format_part_revision(raw):
    """Format a revision value for storage in the Part table.

    Convention used by Part / RFQItem / POItem rows in this DB: digits only,
    zero-padded to 2 chars (e.g. '01', '02', '12'). This differs from
    BOMInstance.assembly_revision which uses the 'REV01' style — use
    normalize_revision() for that table.
    """
    if raw is None:
        return '01'
    s = str(raw).strip().upper()
    while s.startswith('REV'):
        s = s[3:].strip()
    if not s:
        return '01'
    try:
        return f"{int(s):02d}"
    except ValueError:
        return s


def normalize_revision(revision_str):
    """
    Normalize revision to REVxx format.
    Examples:
      '05' -> 'REV05'
      'REV05' -> 'REV05'
      'REVREV01' -> 'REV01'  (handles double REV prefix)
      '5' -> 'REV05'
      '' -> 'REV01'
      None -> 'REV01'
    """
    if not revision_str:
        return 'REV01'
    
    # Convert to string and strip whitespace
    revision_str = str(revision_str).strip().upper()
    
    # Remove ALL 'REV' prefixes (handles cases like REVREV01)
    while revision_str.startswith('REV'):
        revision_str = revision_str[3:].strip()
    
    # Convert to integer and back to ensure proper format
    try:
        rev_num = int(revision_str)
        return f'REV{rev_num:02d}'
    except ValueError:
        return 'REV01'

# Part types where inventory/warehouse always carry over between revisions
# (standard/purchased parts - a revision change doesn't make old stock obsolete)
ALWAYS_CARRY_INVENTORY_TYPES = {
    'Fasteners', 'Bearings', 'Cross Roller Bearings', 'OTS',
    'Cables', 'Motors', 'Gears', 'Inhouse electrical part',
    'External electrical part', 'Unknown', '3D Printing part'
}

# Fields that should COPY over from a previous revision (both revisions keep the value)
# These are reference fields - knowing cost/vendor of old revision is useful context
CARRY_OVER_FIELDS = [
    'vendor', 'unit_cost', 'lead_time', 'manufacturer', 'manufacturer_pn',
    'source_unit_cost', 'source_currency', 'notes',
    'warehouse_box_number',
]

# Fields that should TRANSFER (move) from old revision to new (old gets cleared)
# These represent active orders that belong to whichever revision will receive the parts
TRANSFER_FIELDS = ['order_qty', 'po_orders']

def _carry_over_from_previous_revision(part, part_data):
    """
    When creating a new Part for a new revision, carry over user-edited fields
    from the latest existing part with the same part_number.
    Only fills in fields that are empty/None on the new part.
    Also handles inventory and active order transfer for eligible part types.
    """
    # Find the latest existing part with the same part_number (any revision)
    prev_part = Part.query.filter(
        Part.part_number == part_data['part_number'],
        Part.id != part.id
    ).order_by(Part.revision.desc()).first()

    if not prev_part:
        return

    # Copy reference fields (both revisions keep the value)
    for field in CARRY_OVER_FIELDS:
        new_val = getattr(part, field, None)
        prev_val = getattr(prev_part, field, None)
        if not new_val and prev_val:
            setattr(part, field, prev_val)

    # All revisions of the same part_number share inventory (incompatible changes
    # get a new part number), so always transfer inventory to the latest revision.
    should_transfer = True
    if should_transfer and prev_part.inventory and prev_part.inventory > 0:
        transferred_inv = prev_part.inventory
        part.inventory = (part.inventory or 0) + transferred_inv
        prev_part.inventory = 0
        print(f"INFO: Transferred inventory {transferred_inv} from {part_data['part_number']} {prev_part.revision} -> {part_data['revision']}")

    # Transfer active order data (move from old revision, clear old)
    # order_qty and po_orders represent pending orders - they belong on the revision that will receive parts
    if should_transfer:
        if prev_part.order_qty and prev_part.order_qty > 0:
            transferred_qty = prev_part.order_qty
            part.order_qty = (part.order_qty or 0) + transferred_qty
            prev_part.order_qty = 0
            print(f"INFO: Transferred order_qty {transferred_qty} from {part_data['part_number']} {prev_part.revision} -> {part_data['revision']}")

        if prev_part.po_orders:
            existing = (part.po_orders or '').strip()
            prev_orders = prev_part.po_orders.strip()
            if existing:
                existing_set = set(x.strip() for x in existing.split(',') if x.strip())
                prev_set = set(x.strip() for x in prev_orders.split(',') if x.strip())
                merged = existing_set | prev_set
                part.po_orders = ', '.join(sorted(merged))
            else:
                part.po_orders = prev_orders
            prev_part.po_orders = None
            print(f"INFO: Transferred po_orders from {part_data['part_number']} {prev_part.revision} -> {part_data['revision']}")


def _sync_part_from_po_items(part):
    """
    After a Part is created or updated during BOM import, check if any PO items
    exist for this part and sync pricing data (unit_cost, vendor, order_qty, po_orders).
    This ensures prices are never lost regardless of whether the PO or BOM import came first.
    Only fills in fields that are currently empty on the Part.
    """
    po_items = db.session.execute(
        db.text(
            "SELECT poi.unit_cost, poi.quantity, poi.currency, "
            "poi.original_unit_cost, poi.original_currency, po.vendor, po.po_number "
            "FROM po_item poi JOIN po ON po.id = poi.po_id "
            "WHERE poi.part_number = :pn AND poi.revision = :rev "
            "AND poi.unit_cost IS NOT NULL AND poi.unit_cost > 0 "
            "ORDER BY poi.id DESC"
        ),
        {"pn": part.part_number, "rev": part.revision}
    ).fetchall()

    if not po_items:
        return

    # Use the latest PO item (first row due to ORDER BY DESC)
    latest = po_items[0]
    po_cost, po_qty, currency, orig_cost, orig_currency, vendor, po_number = latest

    if not part.unit_cost:
        part.unit_cost = po_cost
        if currency and currency != 'USD' and orig_cost:
            part.source_currency = currency
            part.source_unit_cost = orig_cost

    if not part.vendor and vendor:
        part.vendor = vendor

    # Sum quantities across all PO items for this part
    if not part.order_qty:
        total_qty = sum(row[1] for row in po_items if row[1])
        part.order_qty = total_qty

    # Collect all PO numbers
    if not part.po_orders:
        po_numbers = list(set(row[6] for row in po_items if row[6]))
        if po_numbers:
            part.po_orders = ', '.join(po_numbers)

    print(f"INFO: Synced PO data to {part.part_number} REV{part.revision}: "
          f"unit_cost={part.unit_cost}, vendor={part.vendor}, order_qty={part.order_qty}")


def _sync_part_from_po_items_bulk(part, po_rows):
    """
    Same logic as _sync_part_from_po_items but uses pre-fetched PO rows
    instead of querying the DB per part. po_rows is a list of tuples:
    (part_number, revision, unit_cost, quantity, currency, original_unit_cost, original_currency, vendor, po_number)
    """
    if not po_rows:
        return

    # Use the latest PO item (first row — already ordered by id DESC)
    latest = po_rows[0]
    po_cost, po_qty, currency, orig_cost, orig_currency, vendor, po_number = latest[2], latest[3], latest[4], latest[5], latest[6], latest[7], latest[8]

    if not part.unit_cost:
        part.unit_cost = po_cost
        if currency and currency != 'USD' and orig_cost:
            part.source_currency = currency
            part.source_unit_cost = orig_cost

    if not part.vendor and vendor:
        part.vendor = vendor

    # Sum quantities across all PO items for this part
    if not part.order_qty:
        total_qty = sum(row[3] for row in po_rows if row[3])
        part.order_qty = total_qty

    # Collect all PO numbers
    if not part.po_orders:
        po_numbers = list(set(row[8] for row in po_rows if row[8]))
        if po_numbers:
            part.po_orders = ', '.join(po_numbers)

    print(f"INFO: Synced PO data to {part.part_number} REV{part.revision}: "
          f"unit_cost={part.unit_cost}, vendor={part.vendor}, order_qty={part.order_qty}")


def resolve_part_with_fallback(part_number, revision):
    """
    Try exact match first. If not found, look for a higher revision
    of the same part_number.
    For non-mechanical/non-assembly parts (fasteners, bearings, etc.),
    always resolve to the highest revision regardless of backward_compatible.
    For mechanical/assembly parts, only resolve if backward_compatible is True.
    Returns (part, used_fallback: bool).
    """
    part = Part.query.filter_by(part_number=part_number, revision=revision).first()
    if part:
        return part, False

    normalized = normalize_revision(revision)
    try:
        rev_num = int(normalized.replace('REV', ''))
    except ValueError:
        return None, False

    candidates = Part.query.filter(
        Part.part_number == part_number,
        Part.status == 'active'
    ).all()

    # Find higher revisions
    compatible = []
    for c in candidates:
        try:
            c_num = int(normalize_revision(c.revision).replace('REV', ''))
        except ValueError:
            continue
        if c_num > rev_num:
            # Non-assembly/non-mechanical parts always carry over
            if (c.part_type or '') in ALWAYS_CARRY_INVENTORY_TYPES:
                compatible.append((c_num, c))
            # Assembly/Mechanical parts require backward_compatible
            elif c.backward_compatible:
                compatible.append((c_num, c))

    if not compatible:
        return None, False

    # Return the highest compatible revision
    compatible.sort(key=lambda x: x[0], reverse=True)
    return compatible[0][1], True

def increment_version_number(current_version):
    """Increment version number (e.g., v1 -> v2, v9 -> v10)"""
    try:
        if current_version.startswith('v'):
            # Handle v format (v1, v2, etc.)
            version_number = current_version[1:]  # Get the number part
            if version_number.isdigit():
                next_number = int(version_number) + 1
                return f"v{next_number}"  # Format as v1, v2, etc.
            else:
                return "v2"  # Fallback if format is unexpected
        elif current_version.startswith('REV'):
            # Handle old REV format - convert to v format
            rev_number = current_version[3:]  # Get the number part
            if rev_number.isdigit():
                next_number = int(rev_number) + 1
                return f"v{next_number}"
            else:
                return "v2"
        elif '.' in current_version:
            # Handle old format (1.0 -> 1.1) - convert to v format
            major = current_version.split('.', 1)[0]
            if major.isdigit():
                return f"v{int(major) + 1}"
            return "v2"
        elif current_version.isdigit():
            # Convert single number to v format
            return f"v{int(current_version) + 1}"
        else:
            # Default to v2 if format is unknown
            return "v2"
    except:
        return "v2"

def validate_bom_data(tree_data):
    """Validate BOM data structure and ensure all required fields are present"""
    if not tree_data:
        return False, "No BOM data provided"
    
    if not tree_data.get('items'):
        return False, "No BOM items found"
    
    # Check if we have a valid assembly name
    assembly_name = tree_data.get('name', '')
    if not assembly_name:
        return False, "No assembly name found"
    
    # Validate that we have the required structure
    required_fields = ['PART NUMBER', 'DESCRIPTION', 'QTY.']
    for item in tree_data.get('items', []):
        for field in required_fields:
            if field not in item:
                return False, f"Missing required field: {field}"
    
    return True, "BOM data is valid"

# ============================================================================
# CURRENCY EXCHANGE RATE SERVICE
# ============================================================================

def fetch_exchange_rates():
    """
    Fetch latest exchange rates from exchangerate.host
    API returns rates where base=USD, so rate means "1 USD = X foreign_currency"
    Example: EUR: 0.92 means 1 USD = 0.92 EUR (so 1 EUR = 1/0.92 = 1.086 USD)
    Returns dict with currency codes as keys and rates as values, or None on error
    """
    logger = get_logger()
    try:
        # Use exchangerate-api.com as it's simpler and more reliable
        # This API returns: {"rates": {"EUR": 0.92, "ILS": 3.65}, "base": "USD"}
        # Meaning: 1 USD = 0.92 EUR, 1 USD = 3.65 ILS
        response = requests.get(
            'https://api.exchangerate-api.com/v4/latest/USD',
            timeout=10
        )
        response.raise_for_status()
        data = response.json()
        
        if 'rates' in data and data['rates']:
            rates = data.get('rates', {})
            # Log sample rates for debugging
            eur_rate = rates.get('EUR') or rates.get('eur')
            ils_rate = rates.get('ILS') or rates.get('ils')
            logger.info(f'Successfully fetched exchange rates from api.exchangerate-api.com. EUR={eur_rate}, ILS={ils_rate}, Total currencies: {len(rates)}')
            return rates
        else:
            logger.error('Exchange rate API returned empty rates dictionary')
            return None
    except requests.exceptions.Timeout:
        logger.error('Exchange rate API request timed out')
        return None
    except requests.exceptions.RequestException as e:
        logger.error(f'Error fetching exchange rates: {str(e)}')
        return None
    except Exception as e:
        logger.error(f'Unexpected error fetching exchange rates: {str(e)}')
        import traceback
        logger.error(traceback.format_exc())
        return None

def get_cached_or_fetch_rate(target_currency, base_currency='USD'):
    """
    Get exchange rate from cache if recent, otherwise fetch from API
    Returns rate as float, or None if unavailable
    """
    if target_currency == base_currency:
        return 1.0
    
    # Normalize currency to uppercase
    target_currency = target_currency.upper()
    base_currency = base_currency.upper()
    
    # Check cache in database
    cached_rate = CurrencyExchangeRate.query.filter_by(
        base_currency=base_currency,
        target_currency=target_currency
    ).first()
    
    # Check if cache is stale (older than 24 hours)
    cache_stale = False
    if cached_rate:
        hours_old = (datetime.utcnow() - cached_rate.last_updated).total_seconds() / 3600
        cache_stale = hours_old > 24
    
    # If cache is fresh, return it
    if cached_rate and not cache_stale:
        logger = get_logger()
        logger.info(f'Using cached exchange rate for {target_currency}: {cached_rate.rate} (source: {cached_rate.source})')
        return cached_rate.rate
    
    # Otherwise, fetch from API
    rates = fetch_exchange_rates()
    if rates:
        # Check if target currency is in the rates (case-insensitive check)
        rate_value = None
        # Try exact match first
        if target_currency in rates:
            rate_value = rates[target_currency]
        # Try uppercase
        elif target_currency.upper() in rates:
            rate_value = rates[target_currency.upper()]
        # Try lowercase
        elif target_currency.lower() in rates:
            rate_value = rates[target_currency.lower()]
        
        if rate_value is not None:
            try:
                rate = float(rate_value)
            except (ValueError, TypeError) as e:
                logger = get_logger()
                logger.error(f'Invalid rate value for {target_currency}: {rate_value} (type: {type(rate_value)})')
                # Fall through to use cached rate or default
            else:
                # Update or create cache entry
                if cached_rate:
                    cached_rate.rate = rate
                    cached_rate.last_updated = datetime.utcnow()
                    cached_rate.source = 'api'
                else:
                    cached_rate = CurrencyExchangeRate(
                        base_currency=base_currency,
                        target_currency=target_currency.upper(),  # Store in uppercase
                        rate=rate,
                        last_updated=datetime.utcnow(),
                        source='api'
                    )
                    db.session.add(cached_rate)
                
                try:
                    db.session.commit()
                    logger = get_logger()
                    logger.info(f'Fetched and cached exchange rate for {target_currency} from API: {rate}')
                except Exception as e:
                    db.session.rollback()
                    logger = get_logger()
                    logger.error(f'Error saving exchange rate to cache: {str(e)}')
                
                return rate
        else:
            logger = get_logger()
            available = list(rates.keys())[:20] if rates else []
            logger.warning(f'Currency {target_currency} not found in API response. Available currencies: {available}')
    
    # If API failed but we have cached rate, use it even if stale
    if cached_rate:
        logger = get_logger()
        logger.warning(f'Using stale exchange rate for {target_currency} (API unavailable or currency not found)')
        return cached_rate.rate
    
    # No cache and API failed - try to use default rates as fallback
    logger = get_logger()
    logger.error(f'No exchange rate available for {target_currency}')
    
    # Last resort: use approximate default rates if API completely fails
    # These rates mean: 1 USD = X foreign_currency
    default_rates = {
        'EUR': 0.92,  # 1 USD = 0.92 EUR (EUR is stronger)
        'ILS': 3.65,  # 1 USD = 3.65 ILS
    }
    if target_currency in default_rates:
        logger.warning(f'Using default fallback rate for {target_currency}: {default_rates[target_currency]}')
        # Store default rate in cache for future use
        try:
            default_rate_obj = CurrencyExchangeRate(
                base_currency=base_currency,
                target_currency=target_currency,
                rate=default_rates[target_currency],
                last_updated=datetime.utcnow(),
                source='manual'
            )
            db.session.add(default_rate_obj)
            db.session.commit()
        except Exception:
            db.session.rollback()
        return default_rates[target_currency]
    
    return None

def convert_currency(amount, from_currency, to_currency='USD'):
    """
    Convert amount from one currency to another
    Simple conversion: API returns rates where base=USD, so rate means "1 USD = X foreign_currency"
    To convert FROM foreign TO USD: amount / rate
    To convert FROM USD TO foreign: amount * rate
    """
    if from_currency == to_currency:
        return amount
    
    # Normalize currencies
    from_currency = from_currency.upper()
    to_currency = to_currency.upper()
    
    if to_currency == 'USD':
        # Converting TO USD from foreign currency
        # API rate: 1 USD = X foreign, so 1 foreign = 1/X USD
        # Therefore: USD_amount = foreign_amount / rate
        rate = get_cached_or_fetch_rate(from_currency, 'USD')
        if rate and rate > 0:
            return amount / rate
    elif from_currency == 'USD':
        # Converting FROM USD to foreign currency
        # API rate: 1 USD = X foreign
        # Therefore: foreign_amount = USD_amount * rate
        rate = get_cached_or_fetch_rate(to_currency, 'USD')
        if rate and rate > 0:
            return amount * rate
    else:
        # Converting between two non-USD currencies
        # First convert to USD, then to target
        usd_amount = convert_currency(amount, from_currency, 'USD')
        if usd_amount is not None:
            return convert_currency(usd_amount, 'USD', to_currency)
    
    return None

def update_all_exchange_rates():
    """
    Fetch and update all exchange rates for supported currencies
    Returns dict with success status and updated currencies
    """
    supported_currencies = ['EUR', 'ILS']
    rates = fetch_exchange_rates()
    
    if not rates:
        return {'success': False, 'error': 'Failed to fetch rates from API'}
    
    updated = []
    logger = get_logger()
    for currency in supported_currencies:
        # Try to find currency in rates (case-insensitive)
        rate_value = None
        if currency in rates:
            rate_value = rates[currency]
        elif currency.upper() in rates:
            rate_value = rates[currency.upper()]
        elif currency.lower() in rates:
            rate_value = rates[currency.lower()]
        
        if rate_value is not None:
            try:
                rate = float(rate_value)
            except (ValueError, TypeError) as e:
                logger.error(f'Invalid rate value for {currency}: {rate_value}')
                continue
            
            cached_rate = CurrencyExchangeRate.query.filter_by(
                base_currency='USD',
                target_currency=currency.upper()
            ).first()
            
            if cached_rate:
                cached_rate.rate = rate
                cached_rate.last_updated = datetime.utcnow()
                cached_rate.source = 'api'
            else:
                cached_rate = CurrencyExchangeRate(
                    base_currency='USD',
                    target_currency=currency.upper(),
                    rate=rate,
                    last_updated=datetime.utcnow(),
                    source='api'
                )
                db.session.add(cached_rate)
            
            updated.append(currency)
        else:
            available = list(rates.keys())[:10] if rates else []
            logger.warning(f'Currency {currency} not found in API response. Available: {available}')
    
    try:
        db.session.commit()
        return {'success': True, 'updated': updated}
    except Exception as e:
        db.session.rollback()
        logger.error(f'Error updating exchange rates: {str(e)}')
        return {'success': False, 'error': str(e)}

def detect_changes(old_items, new_items, version_id):
    """Detect and record changes between old and new BOM items"""
    changes = []
    
    print(f"DEBUG: Detecting changes between {len(old_items)} old items and {len(new_items)} new items")
    
    # Debug: Print sample data
    if old_items:
        sample_old = list(old_items.items())[0]
        print(f"DEBUG: Sample old item: {sample_old[0]} = {sample_old[1]}")
    if new_items:
        sample_new = list(new_items.items())[0]
        print(f"DEBUG: Sample new item: {sample_new[0]} = {sample_new[1]}")
    
    # Check for modified items
    for part_number, new_data in new_items.items():
        if part_number in old_items:
            old_data = old_items[part_number]
            print(f"DEBUG: Comparing {part_number}: old={old_data}, new={new_data}")
            for field, new_value in new_data.items():
                old_value = old_data.get(field, '')
                if str(old_value) != str(new_value) and old_value != new_value:
                    print(f"DEBUG: Change detected for {part_number}: {field} '{old_value}' -> '{new_value}'")
                    change = BOMChange(
                        bom_version_id=version_id,
                        part_number=part_number,
                        change_type='modified',
                        field_name=field,
                        old_value=str(old_value),
                        new_value=str(new_value),
                        change_summary=f"{field} changed from '{old_value}' to '{new_value}'",
                        created_by=current_user.id,
                        priority='high' if field in ['revision', 'state'] else 'normal',
                        is_breaking_change=field in ['revision', 'state']
                    )
                    db.session.add(change)
                    changes.append(change)
        else:
            # New item added
            change = BOMChange(
                bom_version_id=version_id,
                part_number=part_number,
                change_type='added',
                change_summary="new part",
                created_by=current_user.id,
                priority='normal'
            )
            db.session.add(change)
            changes.append(change)
    
    # Check for removed items
    for part_number, old_data in old_items.items():
        if part_number not in new_items:
            change = BOMChange(
                bom_version_id=version_id,
                part_number=part_number,
                change_type='removed',
                change_summary="removed part",
                created_by=current_user.id,
                priority='high',
                is_breaking_change=True
            )
            db.session.add(change)
            changes.append(change)
    
    print(f"DEBUG: Total changes detected: {len(changes)}")
    return changes

# Debug endpoint to check changes in BOM items
@app.route('/api/debug-bom-changes/<int:bom_id>', methods=['GET'])
@login_required
def debug_bom_changes(bom_id):
    """Debug endpoint to check what changes are stored for a BOM"""
    bom_items = BOMItem.query.filter_by(bom_id=bom_id).all()
    
    items_with_changes = []
    for item in bom_items:
        if item.changes:
            items_with_changes.append({
                'part_number': item.part_number,
                'part_name': item.part_name,
                'changes': item.changes,
                'revision': item.revision,
                'state': item.state,
                'finish1': item.finish1,
                'finish2': item.finish2
            })
    
    # Also get version information
    versions = BOMVersion.query.filter_by(bom_id=bom_id).all()
    version_info = []
    for version in versions:
        version_info.append({
            'id': version.id,
            'version_number': version.version_number,
            'is_latest': version.is_latest,
            'total_changes': version.total_changes,
            'change_description': version.change_description,
            'created_at': version.created_at.isoformat()
        })
    
    return jsonify({
        'bom_id': bom_id,
        'total_items': len(bom_items),
        'items_with_changes': len(items_with_changes),
        'changes': items_with_changes,
        'versions': version_info
    })

