@app.context_processor
def inject_permissions():
    """Make permission checking available in templates"""
    def has_permission(permission):
        if not current_user.is_authenticated:
            return False
        return current_user.has_permission(permission)
    
    def can_access_admin():
        if not current_user.is_authenticated:
            return False
        return current_user.can_access_admin()
    
    def can_import_bom():
        if not current_user.is_authenticated:
            return False
        return current_user.can_import_bom()
    
    def can_export_bom():
        if not current_user.is_authenticated:
            return False
        return current_user.can_export_bom()
    
    def can_create_rfq_po():
        if not current_user.is_authenticated:
            return False
        return current_user.can_create_rfq_po()
    
    def can_delete_bom():
        if not current_user.is_authenticated:
            return False
        return current_user.can_delete_bom()
    
    return {
        'has_permission': has_permission,
        'can_access_admin': can_access_admin,
        'can_import_bom': can_import_bom,
        'can_export_bom': can_export_bom,
        'can_create_rfq_po': can_create_rfq_po,
        'can_delete_bom': can_delete_bom
    }

