def get_thumbnail_dict(part):
    """Return thumbnail info dict for a Part, preferring filesystem over DB.
    Returns {available, thumbnail_url} for file-based, or {available, data_base64, info} for legacy DB."""
    if part.thumbnail_path:
        return {
            'available': True,
            'thumbnail_url': f'/api/parts/{part.id}/thumbnail',
        }
    if part.thumbnail_data:
        try:
            return json.loads(part.thumbnail_data)
        except (json.JSONDecodeError, TypeError):
            pass
    return {}


def save_thumbnail_from_import(part, thumbnail_json_str):
    """Save imported thumbnail data (JSON string with base64) to filesystem.
    Sets part.thumbnail_path and leaves part.thumbnail_data as None.
    If extraction fails, falls back to storing in DB."""
    if not thumbnail_json_str:
        return
    try:
        data = json.loads(thumbnail_json_str) if isinstance(thumbnail_json_str, str) else thumbnail_json_str
        if not data.get('available') or not data.get('data_base64'):
            return
        img_bytes = base64.b64decode(data['data_base64'])
        thumb_dir = os.path.join(app.instance_path, 'thumbnails')
        os.makedirs(thumb_dir, exist_ok=True)
        safe_pn = re.sub(r'[^\w\-.]', '_', part.part_number)
        safe_rev = re.sub(r'[^\w\-.]', '_', part.revision)
        filename = f"{part.id}_{safe_pn}_{safe_rev}.png"
        filepath = os.path.join(thumb_dir, filename)
        with open(filepath, 'wb') as f:
            f.write(img_bytes)
        part.thumbnail_path = f"thumbnails/{filename}"
        part.thumbnail_data = None
    except Exception:
        # Fallback: store in DB as before
        part.thumbnail_data = thumbnail_json_str if isinstance(thumbnail_json_str, str) else json.dumps(thumbnail_json_str)


@app.route('/api/parts/<int:part_id>/thumbnail')
def serve_part_thumbnail(part_id):
    """Serve a part thumbnail image from the filesystem."""
    part = Part.query.get_or_404(part_id)
    if part.thumbnail_path:
        filepath = os.path.join(app.instance_path, part.thumbnail_path)
        if os.path.exists(filepath):
            return send_file(filepath, mimetype='image/png',
                             max_age=86400)  # Cache 24h
    # Fallback: decode from DB if still there
    if part.thumbnail_data:
        try:
            data = json.loads(part.thumbnail_data)
            if data.get('data_base64'):
                img_bytes = base64.b64decode(data['data_base64'])
                return send_file(BytesIO(img_bytes), mimetype='image/png',
                                 max_age=86400)
        except Exception:
            pass
    return '', 404


