@app.route('/api/dashboard-stats', methods=['GET'])
@login_required
def dashboard_stats():
    """Get dashboard statistics — returns role-appropriate data"""
    try:
        from sqlalchemy import func
        from sqlalchemy.orm import joinedload

        user_role = current_user.role

        # --- BOM stats (all users) ---
        total_boms = BOMInstance.query.count()
        recent_boms = BOMInstance.query.order_by(BOMInstance.updated_at.desc()).limit(6).all()
        recent_activity = []
        for bom in recent_boms:
            recent_activity.append({
                'id': bom.id,
                'name': bom.name,
                'version': bom.version if hasattr(bom, 'version') else bom.assembly_revision,
                'updated_at': bom.updated_at.isoformat() if bom.updated_at else None,
                'status': bom.status
            })

        # --- Purchase pipeline (non-floor users) ---
        po_pipeline = None
        rfq_pipeline = None
        recent_pos = []
        recent_rfqs = []
        if user_role != 'floor':
            # PO counts by status
            po_counts = db.session.query(PO.status, func.count(PO.id)).group_by(PO.status).all()
            po_pipeline = {status: count for status, count in po_counts}
            po_pipeline['total'] = sum(po_pipeline.values())

            # RFQ counts by status
            rfq_counts = db.session.query(RFQ.status, func.count(RFQ.id)).group_by(RFQ.status).all()
            rfq_pipeline = {status: count for status, count in rfq_counts}
            rfq_pipeline['total'] = sum(rfq_pipeline.values())

            # Recent POs (last 5)
            latest_pos = PO.query.filter(PO.parent_po_id.is_(None)).order_by(PO.po_date.desc()).limit(5).all()
            for po in latest_pos:
                recent_pos.append({
                    'id': po.id,
                    'po_number': po.po_number,
                    'vendor': po.vendor,
                    'status': po.status,
                    'total_cost': po.total_cost,
                    'currency': po.currency or 'USD',
                    'po_date': po.po_date.isoformat() if po.po_date else None,
                    'po_received': po.po_received,
                })

            # Recent RFQs (last 5) — eager-load rfq_items to avoid N+1
            latest_rfqs = RFQ.query.options(joinedload(RFQ.rfq_items)).order_by(RFQ.created_date.desc()).limit(5).all()
            for rfq in latest_rfqs:
                recent_rfqs.append({
                    'id': rfq.id,
                    'rfq_name': rfq.rfq_name,
                    'bom_name': rfq.bom_name,
                    'status': rfq.status,
                    'created_date': rfq.created_date.isoformat() if rfq.created_date else None,
                    'parts_count': len(rfq.rfq_items) if rfq.rfq_items else 0,
                })

        # --- Robot Assembly (all users) ---
        assembly_stats = None
        recent_processes = []
        try:
            active_count = ManufacturingProcess.query.filter(
                ManufacturingProcess.status.in_(['active', 'on_hold'])
            ).count()
            completed_count = ManufacturingProcess.query.filter_by(status='completed').count()

            # Recent active processes (last 5) — eager-load badge + dof→limb to avoid N+1
            active_processes = ManufacturingProcess.query.filter(
                ManufacturingProcess.status.in_(['active', 'on_hold'])
            ).options(
                joinedload(ManufacturingProcess.badge),
                joinedload(ManufacturingProcess.dof_mapping).joinedload(DOFMapping.limb)
            ).order_by(ManufacturingProcess.updated_at.desc()).limit(5).all()
            for proc in active_processes:
                recent_processes.append({
                    'id': proc.id,
                    'process_number': proc.process_number,
                    'name': proc.name,
                    'badge_name': proc.badge.name if proc.badge else 'Unknown',
                    'current_stage': proc.current_stage,
                    'status': proc.status,
                    'limb_name': proc.dof_mapping.limb.name if proc.dof_mapping and proc.dof_mapping.limb else '',
                    'updated_at': proc.updated_at.isoformat() if proc.updated_at else None,
                })
            assembly_stats = {
                'active': active_count,
                'completed': completed_count,
            }
        except Exception:
            pass  # Robot assembly tables may not exist yet

        return jsonify({
            'success': True,
            'user_role': user_role,
            'stats': {
                'total_boms': total_boms,
            },
            'recent_activity': recent_activity,
            'po_pipeline': po_pipeline,
            'rfq_pipeline': rfq_pipeline,
            'recent_pos': recent_pos,
            'recent_rfqs': recent_rfqs,
            'assembly_stats': assembly_stats,
            'recent_processes': recent_processes,
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

