@app.route('/api/admin/backup/create', methods=['POST'])
@admin_panel_required
def create_backup():
    """Create a backup of the database and configuration files"""
    try:
        # Get user's Documents folder
        documents_path = Path.home() / "Documents"
        backup_dir = documents_path / "MenteeBOM Data" / "backups"
        backup_dir.mkdir(parents=True, exist_ok=True)
        
        # Create backup filename with timestamp
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_filename = f"menteebom_backup_{timestamp}.zip"
        backup_path = backup_dir / backup_filename
        
        # Create ZIP archive
        with zipfile.ZipFile(backup_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            # Backup database
            db_uri = app.config['SQLALCHEMY_DATABASE_URI']
            if db_uri.startswith('sqlite:///'):
                db_path = db_uri.replace('sqlite:///', '')
                if not os.path.isabs(db_path):
                    db_path = os.path.join(app.instance_path, db_path)
                
                if os.path.exists(db_path):
                    zipf.write(db_path, 'menteebom.db')
            
            # Backup configuration files (.env is deliberately excluded: secrets live in the vault,
            # see docs/BACKUP_SETUP.md)
            config_files = ['pdm_settings.json']
            for config_file in config_files:
                config_path = os.path.join(os.path.dirname(__file__), config_file)
                if os.path.exists(config_path):
                    zipf.write(config_path, config_file)
        
        backup_size = backup_path.stat().st_size
        size_str = f"{backup_size / 1024 / 1024:.2f} MB" if backup_size > 1024 * 1024 else f"{backup_size / 1024:.2f} KB"
        
        # Log the action
        log_action('BACKUP_CREATE', current_user, 
                   f'Created backup: {backup_filename} ({size_str})')
        
        return jsonify({
            'success': True,
            'backup_path': str(backup_path),
            'backup_filename': backup_filename,
            'backup_size': size_str,
            'timestamp': datetime.now().isoformat()
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/admin/backup/restore', methods=['POST'])
@admin_panel_required
def restore_backup():
    """Restore from a backup file"""
    try:
        if 'backup_file' not in request.files:
            return jsonify({'success': False, 'error': 'No backup file provided'}), 400

        backup_file = request.files['backup_file']
        if backup_file.filename == '':
            return jsonify({'success': False, 'error': 'No file selected'}), 400

        # Validate file extension
        if not backup_file.filename.lower().endswith('.zip'):
            return jsonify({'success': False, 'error': 'Invalid file type. Only .zip files are allowed'}), 400

        # Check file size (limit to 500MB)
        MAX_BACKUP_SIZE = 500 * 1024 * 1024  # 500MB
        backup_file.seek(0, os.SEEK_END)
        file_size = backup_file.tell()
        backup_file.seek(0)  # Reset file pointer

        if file_size > MAX_BACKUP_SIZE:
            return jsonify({'success': False, 'error': f'File too large. Maximum size is {MAX_BACKUP_SIZE // (1024*1024)}MB'}), 400

        if file_size == 0:
            return jsonify({'success': False, 'error': 'File is empty'}), 400

        # Create temporary directory for extraction
        temp_dir = Path(app.instance_path) / 'temp_restore'
        temp_dir.mkdir(exist_ok=True)

        # Sanitize filename to prevent path traversal
        safe_filename = os.path.basename(backup_file.filename)
        temp_backup_path = temp_dir / safe_filename
        backup_file.save(str(temp_backup_path))

        try:
            # Validate ZIP file
            try:
                with zipfile.ZipFile(temp_backup_path, 'r') as zipf:
                    # Check if database file exists in backup
                    if 'menteebom.db' not in zipf.namelist():
                        return jsonify({'success': False, 'error': 'Invalid backup file: database not found'}), 400
            except zipfile.BadZipFile:
                return jsonify({'success': False, 'error': 'Invalid backup file format'}), 400

            # Create safety backup of current database before restore
            db_uri = app.config['SQLALCHEMY_DATABASE_URI']
            if not db_uri.startswith('sqlite:///'):
                return jsonify({'success': False, 'error': 'Restore is only supported for SQLite databases'}), 400
            db_path = db_uri.replace('sqlite:///', '')
            if not os.path.isabs(db_path):
                db_path = os.path.join(app.instance_path, db_path)

            if os.path.exists(db_path):
                safety_backup_path = db_path + f".safety_backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                shutil.copy2(db_path, safety_backup_path)

            # Extract and restore files
            with zipfile.ZipFile(temp_backup_path, 'r') as zipf:
                # Restore database
                if 'menteebom.db' in zipf.namelist():
                    zipf.extract('menteebom.db', temp_dir)
                    extracted_db = temp_dir / 'menteebom.db'
                    if os.path.exists(db_path):
                        # Close any existing database connections
                        db.session.close()
                    shutil.copy2(extracted_db, db_path)

                # Restore configuration files (.env is never restored from an archive so a
                # restore cannot overwrite the live secrets)
                for config_file in ['pdm_settings.json']:
                    if config_file in zipf.namelist():
                        zipf.extract(config_file, temp_dir)
                        extracted_config = temp_dir / config_file
                        config_path = os.path.join(os.path.dirname(__file__), config_file)
                        shutil.copy2(extracted_config, config_path)
        finally:
            # Clean up temporary files on every path (including early returns)
            shutil.rmtree(temp_dir, ignore_errors=True)

        # Log the action
        log_action('BACKUP_RESTORE', current_user, 
                   f'Restored backup: {backup_file.filename}' + 
                   (f', Safety backup: {safety_backup_path}' if 'safety_backup_path' in locals() else ''))
        
        return jsonify({
            'success': True,
            'message': 'Backup restored successfully. Please restart the application.',
            'safety_backup': safety_backup_path if 'safety_backup_path' in locals() else None
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

