@app.route('/api/admin/backup/last', methods=['GET'])
@admin_panel_required
def get_last_backup():
    """Get information about the last backup and full backup history"""
    try:
        documents_path = Path.home() / "Documents"
        backup_dir = documents_path / "MenteeBOM Data" / "backups"

        if not backup_dir.exists():
            return jsonify({'success': True, 'last_backup': None, 'history': []})

        # Find all backup files
        backup_files = list(backup_dir.glob("menteebom_backup_*.zip"))
        if not backup_files:
            return jsonify({'success': True, 'last_backup': None, 'history': []})

        # Sort by modification time (most recent first)
        backup_files.sort(key=lambda p: p.stat().st_mtime, reverse=True)

        # Build history list
        history = []
        for bf in backup_files:
            stat = bf.stat()
            size = stat.st_size
            history.append({
                'filename': bf.name,
                'timestamp': datetime.fromtimestamp(stat.st_mtime).isoformat(),
                'size': size,
                'size_display': f"{size / 1024 / 1024:.2f} MB" if size > 1024 * 1024 else f"{size / 1024:.2f} KB"
            })

        latest = history[0] if history else None

        # Get scheduler status
        scheduler_status = get_scheduler_status()

        return jsonify({
            'success': True,
            'last_backup': latest,
            'history': history,
            'scheduler_status': scheduler_status
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

