@app.route('/api/bom/<int:bom_id>/flat', methods=['GET'])
@login_required
def get_bom_flat(bom_id):
    """Get BOM data in flat format (parts only, aggregated quantities)"""
    bom = BOMData.query.get_or_404(bom_id)

    # Parse the BOM data
    bom_data = json.loads(bom.data) if bom.data else {}

    # Convert to flat format using parser
    try:
        from pdm_bom_parser import PdmBomParser
        parser = PdmBomParser()

        # If the data doesn't have flat format yet, convert it
        if bom_data.get('metadata', {}).get('view_type') == 'flat':
            flat_data = bom_data
        else:
            # Convert tree format to flat format
            flat_data = parser.convert_to_flat_format(bom_data)

        # Enrich items with thumbnail data and other part info from the Part table
        # Also normalize field names to lowercase for frontend compatibility
        if flat_data.get('items'):
            normalized_items = []
            for item in flat_data['items']:
                # Normalize field names from uppercase to lowercase
                normalized_item = {
                    'part_number': item.get('PART NUMBER') or item.get('part_number') or '',
                    'revision': item.get('Revision') or item.get('revision') or '',
                    'description': item.get('DESCRIPTION') or item.get('description') or '',
                    'quantity': item.get('QTY.') or item.get('quantity') or item.get('Qty') or 1,
                    'material': item.get('Material') or item.get('material') or '',
                    'finish1': item.get('FINISH1') or item.get('finish1') or '',
                    'finish2': item.get('FINISH2') or item.get('finish2') or '',
                    'part_type': item.get('Type') or item.get('type') or item.get('part_type') or '',
                    'state': item.get('State') or item.get('state') or '',
                }

                # Copy over any extra fields that might be useful
                for key, value in item.items():
                    if key.lower() not in normalized_item:
                        normalized_item[key.lower()] = value

                part_number = normalized_item['part_number']
                revision = normalized_item['revision']

                if part_number:
                    # Try to find the part in the database to get the latest thumbnail
                    part = Part.query.filter_by(part_number=part_number, revision=revision).first()
                    if not part and revision:
                        # Fallback: try without exact revision match
                        part = Part.query.filter_by(part_number=part_number).order_by(Part.revision.desc()).first()

                    if part:
                        # Add thumbnail data from Part table
                        if part.thumbnail_path or part.thumbnail_data:
                            thumbnail_data = None
                            if part.thumbnail_data:
                                try:
                                    thumbnail_data = json.loads(part.thumbnail_data) if isinstance(part.thumbnail_data, str) else part.thumbnail_data
                                except:
                                    thumbnail_data = part.thumbnail_data
                            elif part.thumbnail_path:
                                thumbnail_data = {'path': part.thumbnail_path}

                            normalized_item['thumbnail'] = thumbnail_data

                        # Ensure description is from Part table
                        if part.description:
                            normalized_item['description'] = part.description

                        # Add eco info
                        normalized_item['eco_number'] = part.eco_number or ''
                        normalized_item['eco_description'] = part.eco_description or ''
                        normalized_item['backward_compatible'] = part.backward_compatible if part.backward_compatible is not None else True

                normalized_items.append(normalized_item)

            flat_data['items'] = normalized_items

        return jsonify({
            'success': True,
            'bom_id': bom.id,
            'name': bom.name,
            'version': bom.version,
            'flat_data': flat_data
        })
    except Exception as e:
        return jsonify({'success': False, 'error': f'Error converting to flat format: {str(e)}'}), 500

@app.route('/api/bom/item/<int:item_id>/update', methods=['PUT'])
@login_required
def update_bom_item(item_id):
    """Update editable fields of a BOM item - distinguishes between Part-level (shared) and BOMPart-level (BOM-specific) fields"""
    # Check if user has permission (admin, engineer, or floor_manager)
    if not current_user.can_edit_bom():
        return jsonify({'success': False, 'error': 'Insufficient permissions to edit BOM items'}), 403
    set_inventory_context('manual_edit')

    data = request.json
    
    try:
        # Try to find BOMPart record first (new structure)
        bom_part = BOMPart.query.get(item_id)
        
        if bom_part:
            # New structure - update BOMPart and/or Part records
            return update_bom_part_new_structure(bom_part, data)
        else:
            # Fallback to old structure for backward compatibility
            bom_item = BOMItem.query.get_or_404(item_id)
            return update_bom_item_old_structure(bom_item, data)
            
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': f'Error updating BOM item: {str(e)}'}), 500

def update_bom_part_new_structure(bom_part, data):
    """Update BOMPart and Part records in new database structure"""
    try:
        # Get the associated Part record
        part = Part.query.get(bom_part.part_id)
        if not part:
            return jsonify({'success': False, 'error': 'Part not found'}), 404
        
        # Define field categories
        part_level_fields = {
            'vendor', 'manufacturer', 'manufacturer_pn', 'unit_cost', 'lead_time', 'inventory', 'warehouse_box_number', 
            'order_qty', 'po_orders', 'notes', 'part_type'
        }
        bom_part_level_fields = {
            'quantity', 'price_per_bom', 'bom_notes'
        }
        
        # Track what was updated
        updated_fields = []
        affected_boms = []
        
        # Update Part-level fields (shared across all BOMs)
        for field in part_level_fields:
            if field in data:
                value = data[field]

                # Handle empty strings for numeric fields
                if field in ['unit_cost', 'lead_time', 'inventory', 'order_qty']:
                    if value == '' or value is None:
                        setattr(part, field, None)
                    else:
                        try:
                            setattr(part, field, float(value))
                        except (ValueError, TypeError):
                            return jsonify({'success': False, 'error': f'Invalid numeric value for {field}: {value}'}), 400
                else:
                    # For text fields, allow empty strings
                    setattr(part, field, value if value is not None else '')

                updated_fields.append(field)

                # Mark part_type as manually set so BOM imports won't overwrite it
                if field == 'part_type':
                    part.part_type_manual = True

                # If updating po_orders, recalculate order_qty
                if field == 'po_orders' and value:
                    try:
                        po_list = json.loads(value) if isinstance(value, str) else value
                        if isinstance(po_list, list):
                            total_order_qty = sum(float(po.get('quantity', 0)) for po in po_list if isinstance(po, dict))
                            part.order_qty = total_order_qty
                            updated_fields.append('order_qty')
                    except (json.JSONDecodeError, TypeError, ValueError):
                        pass  # Keep existing order_qty if po_orders is invalid
        
        # Update BOMPart-level fields (BOM-specific)
        for field in bom_part_level_fields:
            if field in data:
                value = data[field]
                
                # Handle empty strings for numeric fields
                if field in ['quantity', 'price_per_bom']:
                    if value == '' or value is None:
                        setattr(bom_part, field, None)
                    else:
                        try:
                            setattr(bom_part, field, float(value))
                        except (ValueError, TypeError):
                            return jsonify({'success': False, 'error': f'Invalid numeric value for {field}: {value}'}), 400
                else:
                    # For text fields, allow empty strings
                    setattr(bom_part, field, value if value is not None else '')
                
                updated_fields.append(field)
        
        # Auto-calculate price_per_bom if unit_cost or quantity changed
        if 'unit_cost' in updated_fields or 'quantity' in updated_fields:
            if part.unit_cost and bom_part.quantity:
                bom_part.price_per_bom = float(part.unit_cost) * float(bom_part.quantity)
                updated_fields.append('price_per_bom')
        
        # Update timestamps
        part.updated_at = datetime.utcnow()
        bom_part.updated_at = datetime.utcnow()
        
        # Get list of affected BOMs for Part-level changes
        if any(field in part_level_fields for field in updated_fields):
            affected_boms = db.session.query(BOMInstance.id, BOMInstance.name).join(BOMPart).filter(
                BOMPart.part_id == part.id
            ).distinct().all()
        
        db.session.commit()
        
        # Cascade price updates to assemblies if unit_cost was changed
        if 'unit_cost' in updated_fields:
            try:
                cascade_price_updates([part.id])
            except Exception as e:
                print(f"Warning: Error cascading price updates: {e}")
                # Don't fail the whole request if cascading fails
        
        # Update assembly inventories if inventory was changed
        if 'inventory' in updated_fields:
            try:
                update_assembly_inventories_for_part(part.id)
            except Exception as e:
                print(f"Warning: Error updating assembly inventories: {e}")
                # Don't fail the whole request if this fails
        
        return jsonify({
            'success': True,
            'message': 'BOM item updated successfully',
            'updated_fields': updated_fields,
            'affected_boms': [{'id': bom_id, 'name': bom_name} for bom_id, bom_name in affected_boms],
            'item': {
                'id': bom_part.id,
                'part_id': part.id,
                'part_number': part.part_number,
                'revision': part.revision,
                'vendor': part.vendor,
                'manufacturer': part.manufacturer,
                'manufacturer_pn': part.manufacturer_pn,
                'unit_cost': part.unit_cost,
                'lead_time': part.lead_time,
                'inventory': get_inventory_for_part_number(part.part_number),
                'warehouse_box_number': part.warehouse_box_number,
                'order_qty': part.order_qty,
                'po_orders': get_po_orders_for_part_number(part.part_number),
                'notes': part.notes,
                'quantity': bom_part.quantity,
                'price_per_bom': bom_part.price_per_bom,
                'bom_notes': bom_part.bom_notes,
                'updated_at': bom_part.updated_at.isoformat()
            }
        })
        
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': f'Error updating BOM part: {str(e)}'}), 500

@app.route('/api/bom/item/<int:bom_part_id>/replace-part', methods=['POST'])
@admin_required
def replace_bom_part(bom_part_id):
    """Replace a part in a BOM with another part (admin only)"""
    try:
        data = request.json
        new_part_id = data.get('new_part_id')
        
        if not new_part_id:
            return jsonify({'success': False, 'error': 'new_part_id is required'}), 400
        
        # Get the BOMPart record
        bom_part = BOMPart.query.get_or_404(bom_part_id)
        old_part_id = bom_part.part_id
        
        # Validate new part exists
        new_part = Part.query.get(new_part_id)
        if not new_part:
            return jsonify({'success': False, 'error': 'New part not found'}), 404
        
        # Get old part for logging
        old_part = Part.query.get(old_part_id)
        old_part_name = f"{old_part.part_number} REV{old_part.revision}" if old_part else f"Part ID {old_part_id}"
        new_part_name = f"{new_part.part_number} REV{new_part.revision}"
        
        # Update the BOMPart to reference the new part
        bom_part.part_id = new_part_id
        
        # Recalculate price_per_bom based on new part's unit_cost
        if new_part.unit_cost and bom_part.quantity:
            bom_part.price_per_bom = float(new_part.unit_cost) * float(bom_part.quantity)
        else:
            bom_part.price_per_bom = None
        
        bom_part.updated_at = datetime.utcnow()
        
        # Update BOM cost
        try:
            recalculate_bom_instance_cost(bom_part.bom_id)
        except Exception as e:
            print(f"Warning: Error recalculating BOM cost: {e}")
        
        db.session.commit()
        
        # Log the action
        log_action('REPLACE_BOM_PART', current_user,
                  f'Replaced part {old_part_name} with {new_part_name} in BOM {bom_part.bom_id}')
        
        return jsonify({
            'success': True,
            'message': f'Part replaced successfully',
            'old_part': {
                'id': old_part_id,
                'part_number': old_part.part_number if old_part else None,
                'revision': old_part.revision if old_part else None,
            },
            'new_part': {
                'id': new_part_id,
                'part_number': new_part.part_number,
                'revision': new_part.revision,
            },
            'bom_part': {
                'id': bom_part.id,
                'price_per_bom': bom_part.price_per_bom,
            }
        })
        
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': f'Error replacing part: {str(e)}'}), 500

@app.route('/api/parts/search', methods=['GET'])
@login_required
def search_parts():
    """Search parts by part number, name, or description"""
    try:
        search_term = (request.args.get('q') or '').strip()
        try:
            limit = int(request.args.get('limit', 50))
        except (TypeError, ValueError):
            limit = 50
        
        if not search_term:
            return jsonify({'success': True, 'parts': []})
        
        # Search in part_number, part_name, and description
        search_pattern = f'%{search_term}%'
        parts = Part.query.filter(
            db.or_(
                Part.part_number.like(search_pattern),
                Part.part_name.like(search_pattern),
                Part.description.like(search_pattern)
            )
        ).limit(limit).all()
        
        return jsonify({
            'success': True,
            'parts': [{
                'id': part.id,
                'part_number': part.part_number,
                'revision': part.revision,
                'part_name': part.part_name,
                'description': part.description,
                'part_type': part.part_type,
                'unit_cost': part.unit_cost,
                'vendor': part.vendor,
                'state': part.state,
            } for part in parts]
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


