@app.route('/api/bom-export-arrangement', methods=['POST'])
@login_required
def export_bom_arrangement():
    """Export dissolved sub-assembly parts (MP only) for part arrangement.

    Dissolves the sub-assembly tree within the parent BOM, filters to -MP- parts,
    and exports to Excel (with thumbnails) or Google Sheets (without).
    Read-only: does NOT modify the BOM structure.
    """
    if not current_user.can_export_bom():
        return jsonify({'success': False, 'error': 'Insufficient permissions'}), 403

    data = request.get_json()
    bom_id = data.get('bom_id')
    part_number = (data.get('part_number') or '').strip()
    export_type = data.get('export_type', 'excel')  # 'excel' or 'sheets'

    if not bom_id or not part_number:
        return jsonify({'success': False, 'error': 'bom_id and part_number are required'}), 400

    try:
        bom_instance = BOMInstance.query.get(bom_id)
        if not bom_instance:
            return jsonify({'success': False, 'error': 'BOM not found'}), 404

        # Load all BOMPart+Part records for this BOM
        bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
            BOMPart.bom_id == bom_instance.id
        ).order_by(BOMPart.level, BOMPart.sequence).all()

        # Find the sub-assembly BOMPart by part_number
        root_bp = None
        for bp, p in bom_parts:
            if p.part_number == part_number:
                root_bp = bp
                break

        if not root_bp:
            return jsonify({'success': False, 'error': f'Part {part_number} not found in this BOM'}), 404

        # Dissolve sub-tree into flat parts (read-only, no DB changes)
        consolidated = dissolve_subtree_to_flat(bom_parts, root_bp.id, parent_qty=1)

        # Filter to -MP- parts only
        mp_items = [
            item for item in consolidated.values()
            if '-MP-' in (item.get('PART NUMBER') or '')
        ]

        if not mp_items:
            return jsonify({'success': False, 'error': 'No mechanical parts (-MP-) found in this sub-assembly'}), 404

        # Sort by part number for consistent output
        mp_items.sort(key=lambda x: x.get('PART NUMBER', ''))

        flat_data = {
            'name': part_number,
            'items': mp_items,
            'metadata': {
                'view_type': 'flat',
                'total_items': len(mp_items),
                'assembly_name': part_number
            }
        }

        if export_type == 'sheets':
            # Google Sheets (no thumbnails, simplified columns)
            # Reformat items for sheets - keep only arrangement columns
            sheets_items = []
            for item in mp_items:
                sheets_items.append({
                    'PART NUMBER': item.get('PART NUMBER', ''),
                    'DESCRIPTION': item.get('DESCRIPTION', ''),
                    'QTY.': item.get('QTY.', ''),
                    'Warehouse Box': item.get('Warehouse Box', ''),
                    'Inventory': item.get('Inventory', ''),
                    'State': item.get('State', ''),
                    'Type': item.get('Type', ''),
                })
            sheets_flat_data = {
                'name': part_number,
                'items': sheets_items,
                'metadata': flat_data['metadata']
            }

            spreadsheet_name = re.sub(r'[^A-Za-z0-9._\s-]+', '_', part_number.strip())[:100]
            spreadsheet_name = f"{spreadsheet_name} - Part Arrangement"

            BOMS_FOLDER_ID = '1D0yUPyMpBbGFSRj3YBGTKBV8XOfd54ub'
            from google_sheets.google_drive_upload import create_sheets_from_data
            result = create_sheets_from_data(sheets_flat_data, spreadsheet_name, BOMS_FOLDER_ID)

            if not result:
                return jsonify({'success': False, 'error': 'Failed to create Google Sheets'}), 500

            return jsonify({
                'success': True,
                'spreadsheet_id': result.get('spreadsheet_id'),
                'spreadsheet_url': result.get('spreadsheet_url')
            })
        else:
            # Excel with thumbnails (simplified columns)
            workbook_stream = build_arrangement_excel(flat_data)

            safe_name = re.sub(r'[^A-Za-z0-9._-]+', '_', part_number.strip()) or 'arrangement'
            filename = f"{safe_name}_arrangement.xlsx"

            return send_file(
                workbook_stream,
                as_attachment=True,
                download_name=filename,
                mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            )
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': f'Error exporting arrangement: {str(e)}'}), 500

def build_excel_with_thumbnails(flat_data):
    """Create an Excel workbook with thumbnails placed next to part numbers."""
    wb = Workbook()
    ws = wb.active
    ws.title = 'BOM'

    headers = [
        '#', 'Thumbnail', 'Type', 'Part Number', 'Revision', 'ECO',
        'Description', 'Material', 'Finish 1', 'Finish 2', 'QTY',
        'Vendor', 'Manufacturer', 'Manufacturer PN',
        'Order Qty', 'Unit Cost', 'Price/BOM', 'PO Orders',
        'Inventory', 'Warehouse Box', 'State'
    ]

    header_fill = PatternFill(start_color="F3F4F6", end_color="F3F4F6", fill_type="solid")
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col_idx, value=header)
        cell.font = Font(bold=True)
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center", vertical="center")

    column_widths = {
        1: 4,   # #
        2: 16,  # Thumbnail
        3: 12,  # Type
        4: 20,  # Part Number
        5: 10,  # Revision
        6: 10,  # ECO
        7: 40,  # Description
        8: 14,  # Material
        9: 12,  # Finish 1
        10: 12, # Finish 2
        11: 8,  # QTY
        12: 16, # Vendor
        13: 20, # Manufacturer
        14: 20, # Manufacturer PN
        15: 12, # Order Qty
        16: 12, # Unit Cost
        17: 12, # Price/BOM
        18: 12, # PO Orders
        19: 12, # Inventory
        20: 16, # Warehouse Box
        21: 10  # State
    }
    for col_idx, width in column_widths.items():
        ws.column_dimensions[get_column_letter(col_idx)].width = width

    def parse_thumbnail(raw_thumbnail):
        if not raw_thumbnail:
            return {}
        if isinstance(raw_thumbnail, str):
            try:
                return json.loads(raw_thumbnail)
            except Exception:
                return {}
        return raw_thumbnail if isinstance(raw_thumbnail, dict) else {}

    items = flat_data.get('items', [])
    max_thumb_height_points = 110  # cap row height for thumbnails

    for idx, item in enumerate(items, start=1):
        revision = item.get('Revision') or item.get('revision') or ''
        thumb = parse_thumbnail(item.get('thumbnail'))

        row_values = [
            idx,
            None,  # placeholder for thumbnail image
            item.get('Type') or item.get('part_type') or '',
            item.get('PART NUMBER') or item.get('part_number') or '',
            revision,
            item.get('ECO Number') or item.get('eco_number') or '',
            item.get('DESCRIPTION') or item.get('description') or '',
            item.get('Material') or '',
            item.get('FINISH1') or '',
            item.get('FINISH2') or '',
            item.get('QTY.') or item.get('qty') or '',
            item.get('Vendor') or item.get('vendor') or '',
            item.get('Manufacturer') or item.get('manufacturer') or '',
            item.get('Manufacturer PN') or item.get('manufacturer_pn') or '',
            item.get('Order Qty') or item.get('order_qty') or '',
            item.get('Unit Cost') or item.get('unit_cost') or '',
            item.get('Price/BOM') or item.get('price_per_bom') or '',
            item.get('PO Orders') or item.get('po_orders') or '',
            item.get('Inventory') if item.get('Inventory') is not None else '',
            item.get('Warehouse Box') or '',
            item.get('State') or item.get('state') or ''
        ]

        ws.append(row_values)
        excel_row = idx + 1  # account for header row

        # Align text nicely
        for col_idx in range(1, len(headers) + 1):
            cell = ws.cell(row=excel_row, column=col_idx)
            if col_idx in (1, 11, 15, 16, 17, 19):  # numeric-ish columns
                cell.alignment = Alignment(horizontal="center", vertical="center")
            else:
                cell.alignment = Alignment(vertical="center", wrap_text=True)

        # Insert thumbnail image if available
        image_bytes = None
        if thumb.get('available'):
            if thumb.get('data_base64'):
                # Legacy: base64 data still in DB
                image_bytes = base64.b64decode(thumb['data_base64'])
            elif thumb.get('thumbnail_url'):
                # Filesystem-based: read from disk
                part_id = item.get('part_id')
                if part_id:
                    part_obj = Part.query.get(part_id)
                    if part_obj and part_obj.thumbnail_path:
                        fpath = os.path.join(app.instance_path, part_obj.thumbnail_path)
                        if os.path.exists(fpath):
                            with open(fpath, 'rb') as f:
                                image_bytes = f.read()
        if image_bytes:
            try:
                pil_img = PILImage.open(BytesIO(image_bytes)).convert("RGBA")
                # Resize to a reasonable thumbnail size
                pil_img.thumbnail((140, 140))

                # Save to in-memory PNG for openpyxl Image
                img_buf = BytesIO()
                pil_img.save(img_buf, format="PNG")
                img_buf.seek(0)

                img = XLImage(img_buf)
                _anchor_image_in_cell(ws, img, col=1, row=excel_row - 1)

                row_height_points = min(max(pil_img.height * 0.75, 20), max_thumb_height_points)
                ws.row_dimensions[excel_row].height = row_height_points
            except Exception as thumb_err:
                print(f"Thumbnail embed skipped for row {excel_row}: {thumb_err}")

    output = BytesIO()
    wb.save(output)
    output.seek(0)
    return output

