def build_tree_from_bom_parts(bom_parts, bom_instance):
    """Build tree structure from BOMPart records"""
    # Create a map of bom_part_id -> BOMPart for quick lookup
    bom_part_map = {bp.id: bp for bp, _ in bom_parts}
    
    # Create a map of part_id -> Part for quick lookup
    part_map = {p.id: p for _, p in bom_parts}

    # Batch-load total inventory and merged po_orders per part_number (all revisions)
    _tree_part_numbers = list({p.part_number for _, p in bom_parts})
    _tree_inv_map = dict(
        db.session.query(Part.part_number, db.func.sum(Part.inventory))
        .filter(Part.part_number.in_(_tree_part_numbers))
        .group_by(Part.part_number).all()
    ) if _tree_part_numbers else {}
    # Build po_orders map: merge all revision rows for each part_number
    _tree_po_map: dict = {}
    if _tree_part_numbers:
        for pn in _tree_part_numbers:
            _tree_po_map[pn] = get_po_orders_for_part_number(pn)

    # Find root parts (level 0)
    root_parts = [(bp, p) for bp, p in bom_parts if bp.level == 0]
    
    if not root_parts:
        return {
            'name': bom_instance.assembly_part_number,
            'children': [],
            'metadata': {
                'view_type': 'tree',
                'total_items': len(bom_parts)
            }
        }
    
    # Build tree recursively
    def build_tree_node(bom_part, part):
        node = {
            'name': part.part_number,
            'file': part.part_name,
            'description': part.description or '',
            'qty': bom_part.quantity,
            'level': bom_part.level,
            'state': part.state or '',
            'part_type': part.part_type or '',
            'eco_number': part.eco_number or '',
            'eco_description': part.eco_description or '',
            'backward_compatible': part.backward_compatible,
            'bom_columns': {
                'PART NUMBER': part.part_number,
                'PART NAME': part.part_name,
                'DESCRIPTION': part.description or '',
                'QTY.': bom_part.quantity,
                'Material': part.material or '',
                'FINISH1': part.finish1 or '',
                'FINISH2': part.finish2 or '',
                'Revision': part.revision or '',
                'State': part.state or '',
                'Vendor': part.vendor or '',
                'Unit Cost': part.unit_cost,
                'Price/BOM': bom_part.price_per_bom,
                'Order Qty': part.order_qty,  # Add order_qty from Part table
                'PO Orders': _tree_po_map.get(part.part_number, ''),
                'Inventory': int(_tree_inv_map.get(part.part_number) or 0),
                'Warehouse Box': part.warehouse_box_number or '',
                'ECO Number': part.eco_number or '',
                'ECO Description': part.eco_description or '',
                'Backward Compatible': part.backward_compatible,
                'Manufacturer': part.manufacturer or '',
                'Manufacturer PN': part.manufacturer_pn or '',
            },
            'thumbnail': get_thumbnail_dict(part),
            'datasheet_drive_url': part.datasheet_drive_url or None,
            'has_pdf': part.has_pdf or False,
            'has_ai_pdf': part.has_ai_pdf or False,
            'has_step': part.has_step or False,
            'step_files': json.loads(part.step_files) if part.step_files else [],
            'has_xt': part.has_xt or False,
            'children': []
        }
        
        # Find children
        children = [(bp, p) for bp, p in bom_parts if bp.parent_bom_part_id == bom_part.id]
        for child_bp, child_part in children:
            child_node = build_tree_node(child_bp, child_part)
            node['children'].append(child_node)
        
        return node
    
    # Build root node
    root_bp, root_part = root_parts[0]  # Take first root part
    tree_data = build_tree_node(root_bp, root_part)
    
    # Calculate and save assembly costs to database
    def calculate_and_save_assembly_cost(node):
        """Calculate total cost from children's price_per_bom and save to DB"""
        if not node.get('children'):
            # Leaf node - return its price_per_bom
            return node.get('bom_columns', {}).get('Price/BOM', 0) or 0
        
        # Sum children costs
        total_cost = sum(
            child.get('bom_columns', {}).get('Price/BOM', 0) or 0 
            for child in node['children']
        )
        
        # Save to database
        part = Part.query.filter_by(
            part_number=node['name'],
            revision=node.get('bom_columns', {}).get('Revision')
        ).first()
        
        if part and part.unit_cost != total_cost:
            part.unit_cost = total_cost
            db.session.commit()
        
        return total_cost
    
    # Calculate and save assembly cost for the root
    calculate_and_save_assembly_cost(tree_data)
    
    # Add metadata
    tree_data['metadata'] = {
        'view_type': 'tree',
        'total_items': len(bom_parts),
        'assembly_name': bom_instance.assembly_part_number,
        'extraction_date': bom_instance.created_at.isoformat(),
        'parser_type': 'PdmBomParser_Tree',
        'bom_layout': bom_instance.bom_layout or 'MenteeBOM',
        'configuration': bom_instance.configuration or 'Default'
    }
    
    return tree_data

def dissolve_subtree_to_flat(bom_parts, root_bom_part_id, parent_qty=1):
    """Recursively dissolve a sub-assembly tree into a flat list of leaf parts.

    Read-only: does NOT modify any database records. Works entirely with
    the BOMPart+Part tuples already loaded from the parent BOM.

    Args:
        bom_parts: list of (BOMPart, Part) tuples from the parent BOM
        root_bom_part_id: BOMPart.id of the sub-assembly root node
        parent_qty: cumulative quantity multiplier from ancestor levels

    Returns:
        dict keyed by part_number -> dict with part fields and summed QTY
    """
    # Build a children lookup: parent_bom_part_id -> list of (BOMPart, Part)
    children_map = {}
    for bp, p in bom_parts:
        pid = bp.parent_bom_part_id
        if pid not in children_map:
            children_map[pid] = []
        children_map[pid].append((bp, p))

    consolidated = {}  # key: part_number -> item dict

    def _recurse(node_id, qty_multiplier):
        children = children_map.get(node_id, [])
        for bp, part in children:
            effective_qty = (bp.quantity or 0) * qty_multiplier
            child_children = children_map.get(bp.id, [])

            if child_children:
                # Sub-assembly with children -> recurse (dissolve it)
                _recurse(bp.id, effective_qty)
            else:
                # Leaf part -> add to result (consolidate by part_number)
                key = part.part_number
                if key in consolidated:
                    consolidated[key]['QTY.'] += effective_qty
                    # Recalculate price
                    unit_cost = consolidated[key].get('Unit Cost') or 0
                    consolidated[key]['Price/BOM'] = float(unit_cost) * float(consolidated[key]['QTY.'])
                else:
                    unit_cost = part.unit_cost or 0
                    price_per_bom = float(unit_cost) * float(effective_qty) if unit_cost and effective_qty else 0
                    consolidated[key] = {
                        'part_id': part.id,
                        'bom_part_id': bp.id,
                        'PART NUMBER': part.part_number,
                        'PART NAME': part.part_name,
                        'DESCRIPTION': part.description or '',
                        'QTY.': effective_qty,
                        'Material': part.material or '',
                        'FINISH1': part.finish1 or '',
                        'FINISH2': part.finish2 or '',
                        'Revision': part.revision or '',
                        'State': part.state or '',
                        'Vendor': part.vendor or '',
                        'Unit Cost': unit_cost,
                        'Price/BOM': price_per_bom,
                        'Order Qty': part.order_qty,
                        'PO Orders': get_po_orders_for_part_number(part.part_number),
                        'Inventory': get_inventory_for_part_number(part.part_number),
                        'Warehouse Box': part.warehouse_box_number or '',
                        'ECO Number': part.eco_number or '',
                        'ECO Description': part.eco_description or '',
                        'Backward Compatible': part.backward_compatible,
                        'Type': part.part_type or '',
                        'thumbnail': get_thumbnail_dict(part),
                        'source_currency': part.source_currency,
                        'source_unit_cost': part.source_unit_cost,
                        'datasheet_drive_url': part.datasheet_drive_url
                    }

    _recurse(root_bom_part_id, parent_qty)
    return consolidated


def build_arrangement_excel(flat_data):
    """Create an Excel workbook for part arrangement with simplified columns and thumbnails."""
    wb = Workbook()
    ws = wb.active
    ws.title = 'Part Arrangement'

    headers = ['#', 'Thumbnail', 'Part Number', 'Description', 'QTY', 'Warehouse Box', 'Inventory', 'State']

    header_fill = PatternFill(start_color="F3F4F6", end_color="F3F4F6", fill_type="solid")
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col_idx, value=header)
        cell.font = Font(bold=True)
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center", vertical="center")

    column_widths = {
        1: 4,   # #
        2: 16,  # Thumbnail
        3: 22,  # Part Number
        4: 40,  # Description
        5: 8,   # QTY
        6: 16,  # Warehouse Box
        7: 12,  # Inventory
        8: 12,  # State
    }
    for col_idx, width in column_widths.items():
        ws.column_dimensions[get_column_letter(col_idx)].width = width

    def parse_thumbnail(raw_thumbnail):
        if not raw_thumbnail:
            return {}
        if isinstance(raw_thumbnail, str):
            try:
                return json.loads(raw_thumbnail)
            except Exception:
                return {}
        return raw_thumbnail if isinstance(raw_thumbnail, dict) else {}

    items = flat_data.get('items', [])
    max_thumb_height_points = 110

    for idx, item in enumerate(items, start=1):
        thumb = parse_thumbnail(item.get('thumbnail'))

        row_values = [
            idx,
            None,  # placeholder for thumbnail image
            item.get('PART NUMBER') or '',
            item.get('DESCRIPTION') or '',
            item.get('QTY.') or '',
            item.get('Warehouse Box') or '',
            item.get('Inventory') if item.get('Inventory') is not None else '',
            item.get('State') or ''
        ]

        ws.append(row_values)
        excel_row = idx + 1  # account for header row

        for col_idx in range(1, len(headers) + 1):
            cell = ws.cell(row=excel_row, column=col_idx)
            if col_idx in (1, 5, 7):  # numeric columns
                cell.alignment = Alignment(horizontal="center", vertical="center")
            else:
                cell.alignment = Alignment(vertical="center", wrap_text=True)

        # Insert thumbnail image anchored in cell
        image_bytes = None
        if thumb.get('available'):
            if thumb.get('data_base64'):
                image_bytes = base64.b64decode(thumb['data_base64'])
            elif thumb.get('thumbnail_url'):
                part_id = item.get('part_id')
                if part_id:
                    part_obj = Part.query.get(part_id)
                    if part_obj and part_obj.thumbnail_path:
                        fpath = os.path.join(app.instance_path, part_obj.thumbnail_path)
                        if os.path.exists(fpath):
                            with open(fpath, 'rb') as f:
                                image_bytes = f.read()
        if image_bytes:
            try:
                pil_img = PILImage.open(BytesIO(image_bytes)).convert("RGBA")
                pil_img.thumbnail((140, 140))

                img_buf = BytesIO()
                pil_img.save(img_buf, format="PNG")
                img_buf.seek(0)

                img = XLImage(img_buf)
                _anchor_image_in_cell(ws, img, col=1, row=excel_row - 1)

                row_height_points = min(max(pil_img.height * 0.75, 20), max_thumb_height_points)
                ws.row_dimensions[excel_row].height = row_height_points
            except Exception as thumb_err:
                print(f"Thumbnail embed skipped for row {excel_row}: {thumb_err}")

    output = BytesIO()
    wb.save(output)
    output.seek(0)
    return output


def _anchor_image_in_cell(ws, img, col, row):
    """Anchor an openpyxl Image inside a cell using TwoCellAnchor (move and size with cells).

    Args:
        ws: worksheet to add image to
        img: openpyxl Image object
        col: 0-indexed column number (e.g. 1 for column B)
        row: 0-indexed row number
    """
    from openpyxl.drawing.spreadsheet_drawing import AnchorMarker, TwoCellAnchor
    from openpyxl.utils.units import pixels_to_EMU

    p2e = pixels_to_EMU
    margin = p2e(2)

    marker_from = AnchorMarker(col=col, colOff=margin, row=row, rowOff=margin)
    marker_to = AnchorMarker(col=col + 1, colOff=0, row=row + 1, rowOff=0)

    img.anchor = TwoCellAnchor(editAs='oneCell', _from=marker_from, to=marker_to)
    ws.add_image(img)


def build_flat_from_bom_parts(bom_parts, bom_instance):
    """Build flat structure from BOMPart records with proper quantity accumulation.

    Quantities are multiplied through the hierarchy so that a part with qty=1
    inside a sub-assembly with qty=3 correctly contributes 3 to the total.
    Intermediate assemblies (Assembly type with children in this BOM and no
    standalone BOMInstance) are dissolved into their leaf parts.
    """
    # Build a children-map for tree traversal: bom_part_id -> [(BOMPart, Part)]
    children_map = {}
    part_lookup = {}  # bom_part.id -> Part
    for bp, p in bom_parts:
        pid = bp.parent_bom_part_id
        if pid not in children_map:
            children_map[pid] = []
        children_map[pid].append((bp, p))
        part_lookup[bp.id] = p

    # Pre-load which assembly part_numbers have their own BOMInstance (one DB query)
    all_assembly_part_numbers = {
        p.part_number for bp, p in bom_parts if (p.part_type or '') == 'Assembly'
    }
    assemblies_with_bom = set()
    if all_assembly_part_numbers:
        rows = BOMInstance.query.filter(
            BOMInstance.assembly_part_number.in_(all_assembly_part_numbers)
        ).with_entities(BOMInstance.assembly_part_number).all()
        assemblies_with_bom = {r[0] for r in rows}

    # Find root BOMPart (level 0)
    root_entries = [(bp, p) for bp, p in bom_parts if bp.level == 0]
    if not root_entries:
        return {
            'name': bom_instance.assembly_part_number,
            'items': [],
            'metadata': {'total_items': 0}
        }
    root_bp, root_part = root_entries[0]

    # Recursively traverse the tree, multiplying quantities through the hierarchy.
    # Intermediate assemblies (Assembly type + has children in this BOM + no own BOMInstance)
    # are dissolved into their children. Everything else is added to the flat list.
    consolidated_parts = {}

    def traverse(bom_part_id, parent_cumulative_qty):
        for bp, part in children_map.get(bom_part_id, []):
            effective_qty = (bp.quantity or 1) * parent_cumulative_qty
            part_children = children_map.get(bp.id, [])
            is_assembly = (part.part_type or '') == 'Assembly'
            has_children = bool(part_children)
            has_own_bom = part.part_number in assemblies_with_bom

            # Skip the root assembly itself (it's added as a header row separately)
            if part.part_number == bom_instance.assembly_part_number:
                continue

            # Decide whether this part should appear in the flat list.
            # Only "intermediate" assemblies (Assembly type + has children in this BOM
            # + no standalone BOMInstance) are dissolved / hidden; everything else is shown.
            is_intermediate = is_assembly and has_children and not has_own_bom

            if not is_intermediate:
                # Add this part to the flat list with properly accumulated qty
                key = (part.part_number, part.revision or '')
                unit_cost = part.unit_cost or 0
                if key in consolidated_parts:
                    existing = consolidated_parts[key]
                    existing['QTY.'] += effective_qty
                    total_qty = existing['QTY.']
                    existing['Price/BOM'] = float(unit_cost) * float(total_qty) if unit_cost and total_qty else 0
                    if 'bom_part_ids' not in existing:
                        existing['bom_part_ids'] = [existing.get('bom_part_id')]
                    existing['bom_part_ids'].append(bp.id)
                else:
                    price_per_bom = float(unit_cost) * float(effective_qty) if unit_cost and effective_qty else 0
                    consolidated_parts[key] = {
                        'part_id': part.id,
                        'bom_part_id': bp.id,
                        'PART NUMBER': part.part_number,
                        'PART NAME': part.part_name,
                        'DESCRIPTION': part.description or '',
                        'QTY.': effective_qty,
                        'Material': part.material or '',
                        'FINISH1': part.finish1 or '',
                        'FINISH2': part.finish2 or '',
                        'Revision': part.revision or '',
                        'State': part.state or '',
                        'Vendor': part.vendor or '',
                        'Unit Cost': unit_cost,
                        'Price/BOM': price_per_bom,
                        'Order Qty': part.order_qty,
                        'PO Orders': get_po_orders_for_part_number(part.part_number),
                        'Inventory': get_inventory_for_part_number(part.part_number),
                        'Warehouse Box': part.warehouse_box_number or '',
                        'ECO Number': part.eco_number or '',
                        'ECO Description': part.eco_description or '',
                        'Backward Compatible': part.backward_compatible,
                        'Manufacturer': part.manufacturer or '',
                        'Manufacturer PN': part.manufacturer_pn or '',
                        'Level': bp.level,
                        'Sequence': bp.sequence,
                        'Type': part.part_type or '',
                        'thumbnail': get_thumbnail_dict(part),
                        'source_currency': part.source_currency,
                        'source_unit_cost': part.source_unit_cost,
                        'datasheet_drive_url': part.datasheet_drive_url or None,
                        'has_pdf': part.has_pdf or False,
                        'has_ai_pdf': part.has_ai_pdf or False,
                        'has_step': part.has_step or False,
                        'step_files': json.loads(part.step_files) if part.step_files else [],
                        'has_xt': part.has_xt or False,
                    }

            # Always recurse into children so every reachable part is visited and
            # quantities are correctly multiplied through the full hierarchy.
            if has_children:
                traverse(bp.id, effective_qty)

    traverse(root_bp.id, 1.0)

    items = list(consolidated_parts.values())

    print(f"DEBUG build_flat_from_bom_parts: {len(items)} items after traversal")
    for item in items:
        print(f"DEBUG build_flat_from_bom_parts: Item: {item.get('PART NUMBER')} REV{item.get('Revision')} QTY={item.get('QTY.')}")

    # Sort by part number for consistent display
    items.sort(key=lambda x: (x.get('PART NUMBER', ''), x.get('Revision', '')))

    # Calculate total assembly cost (sum of all Price/BOM values)
    total_assembly_cost = sum(item.get('Price/BOM', 0) or 0 for item in items)

    # Get the assembly Part record - first check if it's in the BOMPart records
    assembly_part = None
    assembly_bom_part = None
    for bom_part, part in bom_parts:
        if part.part_number == bom_instance.assembly_part_number and bom_part.level == 0:
            assembly_part = part
            assembly_bom_part = bom_part
            break
    
    # If not found in BOMPart records, query the database
    if not assembly_part:
        # Try to find the Part with the exact revision first
        assembly_part = Part.query.filter_by(
            part_number=bom_instance.assembly_part_number,
            revision=bom_instance.assembly_revision
        ).first()
        # Fallback: if exact revision not found, try to get the latest revision for this part number
        if not assembly_part:
            # Get the latest revision (highest revision number) for this part
            latest_assembly_part = Part.query.filter_by(
                part_number=bom_instance.assembly_part_number
            ).order_by(Part.revision.desc()).first()
            assembly_part = latest_assembly_part
    
    # Save the calculated assembly cost to the database
    if assembly_part:
        if assembly_part.unit_cost != total_assembly_cost:
            assembly_part.unit_cost = total_assembly_cost
            db.session.commit()

    # Create assembly row (first row in the table)
    assembly_row = {
        'part_id': assembly_part.id if assembly_part else None,
        'bom_part_id': assembly_bom_part.id if assembly_bom_part else None,  # Use BOMPart ID if assembly is in BOM
        'PART NUMBER': bom_instance.assembly_part_number,
        'PART NAME': assembly_part.part_name if assembly_part else bom_instance.name,
        'DESCRIPTION': assembly_part.description if assembly_part else (bom_instance.description or ''),
        'QTY.': 1,  # Assembly quantity is always 1
        'Material': assembly_part.material if assembly_part else '',
        'FINISH1': assembly_part.finish1 if assembly_part else '',
        'FINISH2': assembly_part.finish2 if assembly_part else '',
        'Revision': assembly_part.revision if assembly_part else bom_instance.assembly_revision,
        'State': assembly_part.state if assembly_part else '',
        'Vendor': assembly_part.vendor if assembly_part else '',
        'Unit Cost': total_assembly_cost,  # Assembly unit cost = sum of children
        'Price/BOM': total_assembly_cost,  # Same as unit cost for assembly
        'Order Qty': assembly_part.order_qty if assembly_part else '',
        'PO Orders': get_po_orders_for_part_number(assembly_part.part_number) if assembly_part else '',
        'Inventory': get_inventory_for_part_number(assembly_part.part_number) if assembly_part else '',
        'Warehouse Box': assembly_part.warehouse_box_number if assembly_part else '',
        'ECO Number': assembly_part.eco_number if assembly_part else '',
        'ECO Description': assembly_part.eco_description if assembly_part else '',
        'Backward Compatible': assembly_part.backward_compatible if assembly_part else True,
        'Level': 0,  # Assembly is level 0
        'Sequence': 0,
        'Type': 'Assembly',  # Mark as assembly
        'thumbnail': get_thumbnail_dict(assembly_part) if assembly_part else {},
        'has_pdf': assembly_part.has_pdf or False if assembly_part else False,
        'has_ai_pdf': assembly_part.has_ai_pdf or False if assembly_part else False,
        'has_step': assembly_part.has_step or False if assembly_part else False,
        'step_files': json.loads(assembly_part.step_files) if assembly_part and assembly_part.step_files else [],
        'has_xt': assembly_part.has_xt or False if assembly_part else False,
        'datasheet_drive_url': assembly_part.datasheet_drive_url or None if assembly_part else None,
    }
    
    # Insert assembly row at the beginning
    items.insert(0, assembly_row)
    
    flat_data = {
        'name': bom_instance.assembly_part_number,
        'items': items,
        'metadata': {
            'view_type': 'flat',
            'total_items': len(items),
            'assembly_name': bom_instance.assembly_part_number,
            'extraction_date': bom_instance.created_at.isoformat(),
            'parser_type': 'PdmBomParser_Flat',
            'bom_layout': bom_instance.bom_layout or 'MenteeBOM',
            'configuration': bom_instance.configuration or 'Default'
        }
    }
    
    return flat_data

def dissolve_assemblies_in_bom(bom_id, recursive=True):
    """Dissolve assemblies with BOM IDs (no children) into their parts.
    
    Args:
        bom_id: BOM instance ID to process
        recursive: If True, recursively dissolve nested assemblies
        
    Returns:
        List of dictionaries representing parts with adjusted quantities
        Each dict has: part_id, bom_part_id, PART NUMBER, PART NAME, QTY., and other part fields
    """
    bom_instance = BOMInstance.query.get(bom_id)
    if not bom_instance:
        return []
    
    dissolved_parts = []

    # Get all BOM parts for this BOM
    bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
        BOMPart.bom_id == bom_instance.id
    ).order_by(BOMPart.level, BOMPart.sequence).all()

    # Build a quantity multiplier map: for each bom_part, compute the product of all ancestor quantities
    # This handles nested assemblies where qty=4 at a parent means all children appear 4 times
    qty_multiplier = {}
    bom_part_qty_map = {bp.id: (bp.quantity or 1) for bp, _ in bom_parts}
    bom_part_parent_map = {bp.id: bp.parent_bom_part_id for bp, _ in bom_parts}
    for bp, _ in bom_parts:
        multiplier = 1.0
        parent_id = bp.parent_bom_part_id
        while parent_id and parent_id in bom_part_qty_map:
            multiplier *= bom_part_qty_map[parent_id]
            parent_id = bom_part_parent_map.get(parent_id)
        qty_multiplier[bp.id] = multiplier

    # Process each part from this BOM
    for bom_part, part in bom_parts:
        # Skip the assembly itself if it appears in the parts list
        if part.part_number == bom_instance.assembly_part_number:
            continue

        # Check if this part has a BOMInstance (BOM ID)
        has_bom_instance = BOMInstance.query.filter_by(
            assembly_part_number=part.part_number
        ).first() is not None

        # Check if this part has children in the current BOM
        has_children = BOMPart.query.filter_by(
            parent_bom_part_id=bom_part.id
        ).count() > 0

        # If part has BOM ID and no children, dissolve it
        if has_bom_instance and not has_children:
            # Get the latest BOM instance for this assembly
            assembly_bom_instance = (
                BOMInstance.query.filter_by(assembly_part_number=part.part_number, is_latest=True).first()
                or BOMInstance.query.filter_by(assembly_part_number=part.part_number).first()
            )

            if assembly_bom_instance:
                # Get all parts from the assembly's BOM
                assembly_bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
                    BOMPart.bom_id == assembly_bom_instance.id
                ).order_by(BOMPart.level, BOMPart.sequence).all()

                parts_before = len(dissolved_parts)  # Snapshot to detect whether the sub-BOM contributes anything

                # Process each part from the assembly's BOM
                for assembly_bom_part, assembly_part in assembly_bom_parts:
                    # Skip the assembly itself
                    if assembly_part.part_number == assembly_bom_instance.assembly_part_number:
                        continue
                    
                    # If recursive, check if this nested part also needs dissolving
                    if recursive:
                        nested_has_bom = BOMInstance.query.filter_by(
                            assembly_part_number=assembly_part.part_number
                        ).first() is not None
                        
                        # Check if nested assembly has children in its own BOM
                        nested_has_children = False
                        if nested_has_bom:
                            nested_bom_instance = (
                                BOMInstance.query.filter_by(assembly_part_number=assembly_part.part_number, is_latest=True).first()
                                or BOMInstance.query.filter_by(assembly_part_number=assembly_part.part_number).first()
                            )
                            if nested_bom_instance:
                                # Find the bom_part for this nested assembly in its BOM
                                nested_assembly_bom_part = BOMPart.query.filter_by(
                                    bom_id=nested_bom_instance.id,
                                    part_id=assembly_part.id
                                ).first()
                                if nested_assembly_bom_part:
                                    nested_has_children = BOMPart.query.filter_by(
                                        parent_bom_part_id=nested_assembly_bom_part.id
                                    ).count() > 0

                        if nested_has_bom and not nested_has_children:
                            # Recursively dissolve this nested assembly
                            nested_bom_instance = (
                                BOMInstance.query.filter_by(assembly_part_number=assembly_part.part_number, is_latest=True).first()
                                or BOMInstance.query.filter_by(assembly_part_number=assembly_part.part_number).first()
                            )
                            
                            if nested_bom_instance:
                                nested_bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
                                    BOMPart.bom_id == nested_bom_instance.id
                                ).order_by(BOMPart.level, BOMPart.sequence).all()
                                
                                for nested_bom_part, nested_part in nested_bom_parts:
                                    if nested_part.part_number == nested_bom_instance.assembly_part_number:
                                        continue
                                    
                                    # Multiply quantity: ancestor multiplier * parent assembly qty * nested assembly qty * nested part qty
                                    multiplied_qty = qty_multiplier.get(bom_part.id, 1) * (bom_part.quantity or 0) * (assembly_bom_part.quantity or 0) * (nested_bom_part.quantity or 0)
                                    
                                    unit_cost = nested_part.unit_cost or 0
                                    price_per_bom = float(unit_cost) * float(multiplied_qty) if unit_cost and multiplied_qty else 0
                                    
                                    dissolved_parts.append({
                                        'part_id': nested_part.id,
                                        'bom_part_id': nested_bom_part.id,
                                        'PART NUMBER': nested_part.part_number,
                                        'PART NAME': nested_part.part_name,
                                        'DESCRIPTION': nested_part.description or '',
                                        'QTY.': multiplied_qty,
                                        'Material': nested_part.material or '',
                                        'FINISH1': nested_part.finish1 or '',
                                        'FINISH2': nested_part.finish2 or '',
                                        'Revision': nested_part.revision or '',
                                        'State': nested_part.state or '',
                                        'Vendor': nested_part.vendor or '',
                                        'Unit Cost': unit_cost,
                                        'Price/BOM': price_per_bom,
                                        'Order Qty': nested_part.order_qty,
                                        'PO Orders': get_po_orders_for_part_number(nested_part.part_number),
                                        'Inventory': get_inventory_for_part_number(nested_part.part_number),
                                        'Warehouse Box': nested_part.warehouse_box_number or '',
                                        'ECO Number': nested_part.eco_number or '',
                                        'ECO Description': nested_part.eco_description or '',
                                        'Backward Compatible': nested_part.backward_compatible,
                                        'Level': bom_part.level,  # Keep original level
                                        'Sequence': bom_part.sequence,  # Keep original sequence
                                        'Type': nested_part.part_type or '',
                                        'thumbnail': get_thumbnail_dict(nested_part),
                                        'source_currency': nested_part.source_currency,
                                        'source_unit_cost': nested_part.source_unit_cost
                                    })
                                continue
                    
                    # Multiply quantity: ancestor multiplier * parent assembly qty * assembly part qty
                    multiplied_qty = qty_multiplier.get(bom_part.id, 1) * (bom_part.quantity or 0) * (assembly_bom_part.quantity or 0)
                    
                    unit_cost = assembly_part.unit_cost or 0
                    price_per_bom = float(unit_cost) * float(multiplied_qty) if unit_cost and multiplied_qty else 0
                    
                    dissolved_parts.append({
                        'part_id': assembly_part.id,
                        'bom_part_id': assembly_bom_part.id,
                        'PART NUMBER': assembly_part.part_number,
                        'PART NAME': assembly_part.part_name,
                        'DESCRIPTION': assembly_part.description or '',
                        'QTY.': multiplied_qty,
                        'Material': assembly_part.material or '',
                        'FINISH1': assembly_part.finish1 or '',
                        'FINISH2': assembly_part.finish2 or '',
                        'Revision': assembly_part.revision or '',
                        'State': assembly_part.state or '',
                        'Vendor': assembly_part.vendor or '',
                        'Unit Cost': unit_cost,
                        'Price/BOM': price_per_bom,
                        'Order Qty': assembly_part.order_qty,
                        'PO Orders': get_po_orders_for_part_number(assembly_part.part_number),
                        'Inventory': get_inventory_for_part_number(assembly_part.part_number),
                        'Warehouse Box': assembly_part.warehouse_box_number or '',
                        'ECO Number': assembly_part.eco_number or '',
                        'ECO Description': assembly_part.eco_description or '',
                        'Backward Compatible': assembly_part.backward_compatible,
                        'Level': bom_part.level,  # Keep original level
                        'Sequence': bom_part.sequence,  # Keep original sequence
                        'Type': assembly_part.part_type or '',
                        'thumbnail': get_thumbnail_dict(assembly_part),
                        'source_currency': assembly_part.source_currency,
                        'source_unit_cost': assembly_part.source_unit_cost
                    })

                # Fallback: if the sub-BOM was empty or all its entries were skipped (e.g. the
                # BOM only contained the root assembly row), the assembly itself would silently
                # disappear.  Add it as a leaf so no part is ever lost.
                if len(dissolved_parts) == parts_before:
                    _unit_cost = part.unit_cost or 0
                    _quantity = (bom_part.quantity or 0) * qty_multiplier.get(bom_part.id, 1)
                    _price = float(_unit_cost) * float(_quantity) if _unit_cost and _quantity else 0
                    dissolved_parts.append({
                        'part_id': part.id, 'bom_part_id': bom_part.id,
                        'PART NUMBER': part.part_number, 'PART NAME': part.part_name,
                        'DESCRIPTION': part.description or '', 'QTY.': _quantity,
                        'Material': part.material or '', 'FINISH1': part.finish1 or '',
                        'FINISH2': part.finish2 or '', 'Revision': part.revision or '',
                        'State': part.state or '', 'Vendor': part.vendor or '',
                        'Unit Cost': _unit_cost, 'Price/BOM': _price,
                        'Order Qty': part.order_qty, 'PO Orders': get_po_orders_for_part_number(part.part_number),
                        'Inventory': get_inventory_for_part_number(part.part_number), 'Warehouse Box': part.warehouse_box_number or '',
                        'ECO Number': part.eco_number or '', 'ECO Description': part.eco_description or '',
                        'Backward Compatible': part.backward_compatible,
                        'Level': bom_part.level, 'Sequence': bom_part.sequence,
                        'Type': part.part_type or '', 'thumbnail': get_thumbnail_dict(part),
                        'source_currency': part.source_currency,
                        'source_unit_cost': part.source_unit_cost,
                    })
            else:
                # BOMInstance record not found — add the assembly as a leaf so it isn't dropped
                _unit_cost = part.unit_cost or 0
                _quantity = (bom_part.quantity or 0) * qty_multiplier.get(bom_part.id, 1)
                _price = float(_unit_cost) * float(_quantity) if _unit_cost and _quantity else 0
                dissolved_parts.append({
                    'part_id': part.id, 'bom_part_id': bom_part.id,
                    'PART NUMBER': part.part_number, 'PART NAME': part.part_name,
                    'DESCRIPTION': part.description or '', 'QTY.': _quantity,
                    'Material': part.material or '', 'FINISH1': part.finish1 or '',
                    'FINISH2': part.finish2 or '', 'Revision': part.revision or '',
                    'State': part.state or '', 'Vendor': part.vendor or '',
                    'Unit Cost': _unit_cost, 'Price/BOM': _price,
                    'Order Qty': part.order_qty, 'PO Orders': get_po_orders_for_part_number(part.part_number),
                    'Inventory': get_inventory_for_part_number(part.part_number), 'Warehouse Box': part.warehouse_box_number or '',
                    'ECO Number': part.eco_number or '', 'ECO Description': part.eco_description or '',
                    'Backward Compatible': part.backward_compatible,
                    'Level': bom_part.level, 'Sequence': bom_part.sequence,
                    'Type': part.part_type or '', 'thumbnail': get_thumbnail_dict(part),
                    'source_currency': part.source_currency,
                    'source_unit_cost': part.source_unit_cost,
                })
        elif not has_children:
            # Leaf part (no children, no sub-BOM to dissolve) - add it as-is
            # Multiply by ancestor quantities (e.g., if parent assembly has qty=4, this part appears 4 times)
            unit_cost = part.unit_cost or 0
            quantity = (bom_part.quantity or 0) * qty_multiplier.get(bom_part.id, 1)
            price_per_bom = float(unit_cost) * float(quantity) if unit_cost and quantity else 0
            
            dissolved_parts.append({
                'part_id': part.id,
                'bom_part_id': bom_part.id,
                'PART NUMBER': part.part_number,
                'PART NAME': part.part_name,
                'DESCRIPTION': part.description or '',
                'QTY.': quantity,
                'Material': part.material or '',
                'FINISH1': part.finish1 or '',
                'FINISH2': part.finish2 or '',
                'Revision': part.revision or '',
                'State': part.state or '',
                'Vendor': part.vendor or '',
                'Unit Cost': unit_cost,
                'Price/BOM': price_per_bom,
                'Order Qty': part.order_qty,
                'PO Orders': get_po_orders_for_part_number(part.part_number),
                'Inventory': get_inventory_for_part_number(part.part_number),
                'Warehouse Box': part.warehouse_box_number or '',
                'ECO Number': part.eco_number or '',
                'ECO Description': part.eco_description or '',
                'Backward Compatible': part.backward_compatible,
                'Level': bom_part.level,
                'Sequence': bom_part.sequence,
                'Type': part.part_type or '',
                'thumbnail': get_thumbnail_dict(part),
                'source_currency': part.source_currency,
                'source_unit_cost': part.source_unit_cost
            })
    
    return dissolved_parts

def consolidate_multiple_boms(bom_ids, dissolve_assemblies=False, bom_multipliers=None):
    """Consolidate multiple BOMs into a single flat data structure.

    Args:
        bom_ids: List of BOM instance IDs to consolidate
        dissolve_assemblies: If True, dissolve assemblies with BOM IDs (no children) into their parts
        bom_multipliers: Optional dict {bom_id: multiplier} to scale quantities per BOM

    Returns:
        Dictionary with consolidated flat data structure similar to build_flat_from_bom_parts
    """
    bom_multipliers = bom_multipliers or {}
    if not bom_ids:
        return {
            'name': 'Consolidated BOM',
            'items': [],
            'metadata': {
                'view_type': 'flat',
                'total_items': 0,
                'assembly_name': 'Consolidated BOM',
                'bom_ids': bom_ids
            }
        }
    
    # Dictionary to consolidate parts by (part_number, revision) across all BOMs
    consolidated_parts = {}
    all_assembly_names = []
    
    # Process each BOM
    for bom_id in bom_ids:
        bom_instance = BOMInstance.query.get(bom_id)
        if not bom_instance:
            continue
            
        all_assembly_names.append(bom_instance.assembly_part_number or bom_instance.name)
        
        # If dissolving is enabled, use the dissolve function
        if dissolve_assemblies:
            dissolved_items = dissolve_assemblies_in_bom(bom_id, recursive=True)
            multiplier = float(bom_multipliers.get(str(bom_id), bom_multipliers.get(bom_id, 1)) or 1)
            # Process dissolved items
            for item in dissolved_items:
                # Create a key for consolidation (part_number + revision)
                key = (item.get('PART NUMBER'), item.get('Revision', '') or '')

                if key in consolidated_parts:
                    # Part already exists - consolidate quantities
                    existing = consolidated_parts[key]
                    existing_qty = existing.get('QTY.', 0) or 0
                    new_qty = (item.get('QTY.', 0) or 0) * multiplier
                    existing['QTY.'] = existing_qty + new_qty
                    
                    # Recalculate Price/BOM based on consolidated quantity
                    unit_cost = existing.get('Unit Cost', 0) or 0
                    total_qty = existing['QTY.']
                    existing['Price/BOM'] = float(unit_cost) * float(total_qty) if unit_cost and total_qty else 0
                    
                    # Track all bom_part_ids
                    if 'bom_part_ids' not in existing:
                        existing['bom_part_ids'] = [existing.get('bom_part_id')]
                    if item.get('bom_part_id'):
                        existing['bom_part_ids'].append(item.get('bom_part_id'))
                else:
                    # New part - add to consolidated dictionary
                    consolidated_parts[key] = item.copy()
                    if item.get('bom_part_id'):
                        consolidated_parts[key]['bom_part_ids'] = [item.get('bom_part_id')]
            continue
        
        # Original logic when not dissolving
        multiplier = float(bom_multipliers.get(str(bom_id), bom_multipliers.get(bom_id, 1)) or 1)
        # Get all BOM parts for this BOM
        bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
            BOMPart.bom_id == bom_instance.id
        ).order_by(BOMPart.level, BOMPart.sequence).all()

        # Build effective-quantity map: multiply each part's qty by all ancestor qtys.
        # This handles cases like a Finger Assembly stored with qty=4 in the Hand BOM,
        # where its children (stored with qty=1 per finger) should become qty=4 in total.
        bp_own_qty = {bp.id: (bp.quantity or 0) for bp, _ in bom_parts}
        bp_parent  = {bp.id: bp.parent_bom_part_id for bp, _ in bom_parts}

        def effective_qty(bp_id):
            qty = 1.0
            current = bp_id
            while current is not None:
                qty *= bp_own_qty.get(current, 1)
                current = bp_parent.get(current)
            return qty

        # Process each part from this BOM
        for bom_part, part in bom_parts:
            # Skip the assembly itself if it appears in the parts list
            if part.part_number == bom_instance.assembly_part_number:
                continue

            # Create a key for consolidation (part_number + revision)
            key = (part.part_number, part.revision or '')

            if key in consolidated_parts:
                # Part already exists - consolidate quantities
                existing = consolidated_parts[key]
                existing_qty = existing.get('QTY.', 0) or 0
                new_qty = effective_qty(bom_part.id) * multiplier
                existing['QTY.'] = existing_qty + new_qty

                # Recalculate Price/BOM based on consolidated quantity
                unit_cost = existing.get('Unit Cost', 0) or 0
                total_qty = existing['QTY.']
                existing['Price/BOM'] = float(unit_cost) * float(total_qty) if unit_cost and total_qty else 0

                # Track all bom_part_ids
                if 'bom_part_ids' not in existing:
                    existing['bom_part_ids'] = [existing.get('bom_part_id')]
                existing['bom_part_ids'].append(bom_part.id)
            else:
                # New part - add to consolidated dictionary
                unit_cost = part.unit_cost or 0
                quantity = effective_qty(bom_part.id) * multiplier
                price_per_bom = float(unit_cost) * float(quantity) if unit_cost and quantity else 0

                item = {
                    'part_id': part.id,
                    'bom_part_id': bom_part.id,
                    'PART NUMBER': part.part_number,
                    'PART NAME': part.part_name,
                    'DESCRIPTION': part.description or '',
                    'QTY.': quantity,
                    'Material': part.material or '',
                    'FINISH1': part.finish1 or '',
                    'FINISH2': part.finish2 or '',
                    'Revision': part.revision or '',
                    'State': part.state or '',
                    'Vendor': part.vendor or '',
                    'Unit Cost': unit_cost,
                    'Price/BOM': price_per_bom,
                    'Order Qty': part.order_qty,
                    'PO Orders': get_po_orders_for_part_number(part.part_number),
                    'Inventory': get_inventory_for_part_number(part.part_number),
                    'Warehouse Box': part.warehouse_box_number or '',
                    'ECO Number': part.eco_number or '',
                    'ECO Description': part.eco_description or '',
                    'Backward Compatible': part.backward_compatible,
                    'Level': bom_part.level,
                    'Sequence': bom_part.sequence,
                    'Type': part.part_type or '',
                    'thumbnail': get_thumbnail_dict(part),
                    'source_currency': part.source_currency,
                    'source_unit_cost': part.source_unit_cost
                }
                consolidated_parts[key] = item
    
    # Convert consolidated dictionary to list
    items = list(consolidated_parts.values())
    
    # Filter out assembly parts that have children but no BOM ID (for part-only view in exports)
    # These are intermediate assemblies that should only appear in tree view
    # Note: Dissolved assemblies are already excluded because they're expanded into their parts
    filtered_items = []
    for item in items:
        part_id = item.get('part_id')
        
        if part_id:
            part = Part.query.get(part_id)
            if not part:
                filtered_items.append(item)
                continue
            
            # Check if this part has a BOMInstance (BOM ID)
            has_bom_id = BOMInstance.query.filter_by(
                assembly_part_number=part.part_number
            ).first() is not None
            
            # Check if this part has children within the BOMs being consolidated.
            # We deliberately scope the check to bom_ids only — using a global check
            # (all BOMs in the system) would incorrectly filter out parts that happen
            # to be intermediate assemblies in OTHER BOMs but are plain leaf parts here.
            has_children = False
            bom_parts_for_part = BOMPart.query.filter(
                BOMPart.part_id == part_id,
                BOMPart.bom_id.in_(bom_ids)
            ).all()
            for bp in bom_parts_for_part:
                if BOMPart.query.filter_by(parent_bom_part_id=bp.id).count() > 0:
                    has_children = True
                    break

            # If it has children (within these BOMs) but no dedicated BOM record, skip it —
            # it's an intermediate assembly that is already represented by its children.
            if has_children and not has_bom_id:
                continue
        
        filtered_items.append(item)
    
    items = filtered_items
    
    # Sort by part number for consistent display
    items.sort(key=lambda x: (x.get('PART NUMBER', ''), x.get('Revision', '')))
    
    # Calculate total cost
    total_cost = sum(item.get('Price/BOM', 0) or 0 for item in items)
    
    # Create consolidated assembly row
    assembly_name = ' + '.join(all_assembly_names) if all_assembly_names else 'Consolidated BOM'
    assembly_row = {
        'part_id': None,
        'bom_part_id': None,
        'PART NUMBER': assembly_name,
        'PART NAME': 'Consolidated Assembly',
        'DESCRIPTION': f'Consolidated from {len(bom_ids)} BOM(s)',
        'QTY.': 1,
        'Material': '',
        'FINISH1': '',
        'FINISH2': '',
        'Revision': '',
        'State': '',
        'Vendor': '',
        'Unit Cost': total_cost,
        'Price/BOM': total_cost,
        'Order Qty': '',
        'PO Orders': '',
        'Inventory': '',
        'Warehouse Box': '',
        'ECO Number': '',
        'ECO Description': '',
        'Backward Compatible': True,
        'Level': 0,
        'Sequence': 0,
        'Type': 'Assembly',
        'thumbnail': {}
    }
    
    # Insert assembly row at the beginning
    items.insert(0, assembly_row)
    
    flat_data = {
        'name': assembly_name,
        'items': items,
        'metadata': {
            'view_type': 'flat',
            'total_items': len(items),
            'assembly_name': assembly_name,
            'bom_ids': bom_ids,
            'parser_type': 'MultiBOM_Consolidated',
            'extraction_date': datetime.utcnow().isoformat()
        }
    }
    
    return flat_data

@app.route('/api/bom/parts-bom-breakdown', methods=['POST'])
@login_required
def get_parts_bom_breakdown():
    """For a set of selected parts, find their quantities in each of the specified BOMs.
    Used in General RFQ flow: user selects parts first, then chooses BOMs to calculate quantities."""
    try:
        data = request.get_json()
        part_ids = data.get('part_ids', [])
        bom_ids = data.get('bom_ids', [])

        if not part_ids or not bom_ids:
            return jsonify({'success': False, 'error': 'part_ids and bom_ids are required'}), 400

        # Get the selected parts
        parts = Part.query.filter(Part.id.in_(part_ids)).all()
        parts_by_id = {p.id: p for p in parts}

        # Build lookup: (part_number, revision) -> part_id
        part_key_to_id = {(p.part_number, p.revision or ''): p.id for p in parts}

        # For each BOM, find quantities for the selected parts
        boms_used = []
        # part_id -> list of {bom_id, bom_name, qty}
        part_bom_breakdown = {pid: [] for pid in part_ids}

        for bom_id in bom_ids:
            bom_instance = BOMInstance.query.get(bom_id)
            if not bom_instance:
                continue
            bom_name = bom_instance.assembly_part_number or bom_instance.name or f'BOM #{bom_id}'
            boms_used.append({'id': bom_id, 'name': bom_name})

            # Get all parts in this BOM (flat, with dissolution)
            dissolved_items = dissolve_assemblies_in_bom(bom_id, recursive=True)

            # Also get direct BOM parts (non-dissolved)
            direct_bom_parts = db.session.query(BOMPart, Part).join(Part).filter(
                BOMPart.bom_id == bom_id
            ).all()

            # Consolidate quantities per part_number+revision for this BOM
            bom_part_qtys = {}  # (part_number, revision) -> total_qty

            # From dissolved items
            for item in dissolved_items:
                key = (item.get('PART NUMBER'), item.get('Revision', '') or '')
                qty = item.get('QTY.', 0) or 0
                bom_part_qtys[key] = bom_part_qtys.get(key, 0) + qty

            # From direct parts (for parts not covered by dissolution)
            for bom_part, part in direct_bom_parts:
                if part.part_number == bom_instance.assembly_part_number:
                    continue
                key = (part.part_number, part.revision or '')
                if key not in bom_part_qtys:
                    bom_part_qtys[key] = bom_part.quantity or 0

            # Match against selected parts
            for key, qty in bom_part_qtys.items():
                if key in part_key_to_id and qty > 0:
                    pid = part_key_to_id[key]
                    part_bom_breakdown[pid].append({
                        'bom_id': bom_id,
                        'bom_name': bom_name,
                        'qty': qty
                    })

        # Build response
        result_parts = []
        for pid in part_ids:
            part = parts_by_id.get(pid)
            if not part:
                continue
            breakdown = part_bom_breakdown.get(pid, [])
            total_qty = sum(b['qty'] for b in breakdown)
            result_parts.append({
                'part_id': part.id,
                'part_number': part.part_number,
                'revision': part.revision or '',
                'description': part.description or '',
                'vendor': part.vendor or '',
                'unit_cost': part.unit_cost or 0,
                'part_type': part.part_type or '',
                'material': part.material or '',
                'finish1': part.finish1 or '',
                'finish2': part.finish2 or '',
                'bom_breakdown': breakdown,
                'total_qty': total_qty
            })

        return jsonify({
            'success': True,
            'parts': result_parts,
            'boms_used': boms_used
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/dissolved-boms', methods=['GET'])
@login_required
def get_dissolved_boms():
    """List all saved dissolved BOMs"""
    try:
        dissolved = DissolvedBOM.query.order_by(DissolvedBOM.updated_at.desc()).all()
        result = []
        for d in dissolved:
            source_ids = json.loads(d.source_bom_ids_json) if d.source_bom_ids_json else []
            result.append({
                'id': d.id,
                'name': d.name,
                'source_bom_ids': source_ids,
                'source_bom_count': len(source_ids),
                'dissolve_mode': d.dissolve_mode,
                'created_at': d.created_at.isoformat() if d.created_at else None,
                'updated_at': d.updated_at.isoformat() if d.updated_at else None,
                'created_by': d.creator.username if d.creator else None
            })
        return jsonify({'success': True, 'dissolved_boms': result})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/dissolved-boms', methods=['POST'])
@login_required
def create_dissolved_bom():
    """Create a new dissolved BOM by dissolving selected BOMs"""
    try:
        data = request.get_json()
        name = data.get('name')
        bom_ids = data.get('bom_ids', [])
        dissolve_mode = data.get('dissolve_mode', 'full')

        if not name or not bom_ids:
            return jsonify({'success': False, 'error': 'Name and bom_ids are required'}), 400

        # Dissolve the BOMs using existing function
        if dissolve_mode == 'full':
            flat_data = consolidate_multiple_boms(bom_ids, dissolve_assemblies=True)
        else:
            # One level: dissolve without recursive
            flat_data = consolidate_multiple_boms(bom_ids, dissolve_assemblies=False)

        # Extract items (skip the first assembly row)
        items = flat_data.get('items', [])
        parts_list = []
        for item in items:
            if item.get('part_id') is None:
                continue  # Skip assembly summary row
            # Look up Part record for file flags and extra fields
            _part_obj = Part.query.get(item.get('part_id')) if item.get('part_id') else None
            parts_list.append({
                'part_id': item.get('part_id'),
                'bom_part_id': item.get('bom_part_id'),
                'part_number': item.get('PART NUMBER', ''),
                'part_name': item.get('PART NAME', ''),
                'description': item.get('DESCRIPTION', ''),
                'quantity': item.get('QTY.', 0),
                'material': item.get('Material', ''),
                'finish1': item.get('FINISH1', ''),
                'finish2': item.get('FINISH2', ''),
                'revision': item.get('Revision', ''),
                'state': item.get('State', ''),
                'vendor': item.get('Vendor', ''),
                'manufacturer': item.get('Manufacturer', '') or (_part_obj.manufacturer if _part_obj else '') or '',
                'manufacturer_pn': item.get('ManufacturerPN', '') or (_part_obj.manufacturer_pn if _part_obj else '') or '',
                'unit_cost': item.get('Unit Cost', 0),
                'price_per_bom': item.get('Price/BOM', 0),
                'order_qty': item.get('Order Qty', ''),
                'po_orders': item.get('PO Orders', ''),
                'part_type': item.get('Type', ''),
                'inventory': item.get('Inventory', ''),
                'warehouse_box_number': item.get('Warehouse Box', ''),
                'eco_number': item.get('ECO Number', ''),
                'eco_description': item.get('ECO Description', ''),
                'thumbnail': item.get('thumbnail', {}),
                'source_currency': item.get('source_currency', ''),
                'source_unit_cost': item.get('source_unit_cost', ''),
                'has_pdf': _part_obj.has_pdf if _part_obj else False,
                'has_ai_pdf': _part_obj.has_ai_pdf if _part_obj else False,
                'has_step': _part_obj.has_step if _part_obj else False,
                'datasheet_drive_url': _part_obj.datasheet_drive_url if _part_obj else None,
            })

        dissolved = DissolvedBOM(
            name=name,
            source_bom_ids_json=json.dumps(bom_ids),
            dissolve_mode=dissolve_mode,
            dissolved_parts_json=json.dumps(parts_list),
            created_by=current_user.id if current_user else None
        )
        db.session.add(dissolved)
        db.session.commit()

        return jsonify({
            'success': True,
            'dissolved_bom': {
                'id': dissolved.id,
                'name': dissolved.name,
                'source_bom_ids': bom_ids,
                'dissolve_mode': dissolve_mode,
                'parts_count': len(parts_list),
                'created_at': dissolved.created_at.isoformat() if dissolved.created_at else None,
            }
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/dissolved-boms/<int:dissolved_id>', methods=['GET'])
@login_required
def get_dissolved_bom(dissolved_id):
    """Get a specific dissolved BOM with its parts"""
    try:
        dissolved = DissolvedBOM.query.get(dissolved_id)
        if not dissolved:
            return jsonify({'success': False, 'error': 'Dissolved BOM not found'}), 404

        parts = json.loads(dissolved.dissolved_parts_json) if dissolved.dissolved_parts_json else []
        source_ids = json.loads(dissolved.source_bom_ids_json) if dissolved.source_bom_ids_json else []

        # Get source BOM names
        source_boms = []
        for bid in source_ids:
            bom = BOMInstance.query.get(bid)
            if bom:
                source_boms.append({
                    'id': bom.id,
                    'name': bom.assembly_part_number or bom.name,
                    'revision': bom.assembly_revision or ''
                })

        return jsonify({
            'success': True,
            'dissolved_bom': {
                'id': dissolved.id,
                'name': dissolved.name,
                'source_bom_ids': source_ids,
                'source_boms': source_boms,
                'dissolve_mode': dissolved.dissolve_mode,
                'parts': parts,
                'parts_count': len(parts),
                'created_at': dissolved.created_at.isoformat() if dissolved.created_at else None,
                'updated_at': dissolved.updated_at.isoformat() if dissolved.updated_at else None,
                'created_by': dissolved.creator.username if dissolved.creator else None
            }
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/dissolved-boms/<int:dissolved_id>', methods=['DELETE'])
@login_required
def delete_dissolved_bom(dissolved_id):
    """Delete a dissolved BOM"""
    try:
        dissolved = DissolvedBOM.query.get(dissolved_id)
        if not dissolved:
            return jsonify({'success': False, 'error': 'Dissolved BOM not found'}), 404
        db.session.delete(dissolved)
        db.session.commit()
        return jsonify({'success': True})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/dissolved-boms/<int:dissolved_id>/refresh', methods=['PUT'])
@login_required
def refresh_dissolved_bom(dissolved_id):
    """Re-dissolve from source BOMs (if BOMs have changed)"""
    try:
        dissolved = DissolvedBOM.query.get(dissolved_id)
        if not dissolved:
            return jsonify({'success': False, 'error': 'Dissolved BOM not found'}), 404

        bom_ids = json.loads(dissolved.source_bom_ids_json) if dissolved.source_bom_ids_json else []
        if not bom_ids:
            return jsonify({'success': False, 'error': 'No source BOMs to refresh from'}), 400

        # Resolve each stored BOM ID to the latest version of that assembly.
        # BOMInstance records are per-revision; if the source BOM was updated to a new
        # revision since this dissolved BOM was created, the stored ID points to the old
        # version. We always want to dissolve from the most current revision.
        resolved_bom_ids = []
        for bom_id in bom_ids:
            old_instance = BOMInstance.query.get(bom_id)
            if not old_instance:
                continue
            latest = BOMInstance.query.filter_by(
                assembly_part_number=old_instance.assembly_part_number,
                is_latest=True
            ).first()
            resolved_bom_ids.append(latest.id if latest else bom_id)

        if not resolved_bom_ids:
            return jsonify({'success': False, 'error': 'No valid source BOMs found'}), 400

        # Re-dissolve
        if dissolved.dissolve_mode == 'full':
            flat_data = consolidate_multiple_boms(resolved_bom_ids, dissolve_assemblies=True)
        else:
            flat_data = consolidate_multiple_boms(resolved_bom_ids, dissolve_assemblies=False)

        items = flat_data.get('items', [])
        parts_list = []
        for item in items:
            if item.get('part_id') is None:
                continue
            # Look up Part record for file flags and extra fields
            _part_obj = Part.query.get(item.get('part_id')) if item.get('part_id') else None
            parts_list.append({
                'part_id': item.get('part_id'),
                'bom_part_id': item.get('bom_part_id'),
                'part_number': item.get('PART NUMBER', ''),
                'part_name': item.get('PART NAME', ''),
                'description': item.get('DESCRIPTION', ''),
                'quantity': item.get('QTY.', 0),
                'material': item.get('Material', ''),
                'finish1': item.get('FINISH1', ''),
                'finish2': item.get('FINISH2', ''),
                'revision': item.get('Revision', ''),
                'state': item.get('State', ''),
                'vendor': item.get('Vendor', ''),
                'manufacturer': item.get('Manufacturer', '') or (_part_obj.manufacturer if _part_obj else '') or '',
                'manufacturer_pn': item.get('ManufacturerPN', '') or (_part_obj.manufacturer_pn if _part_obj else '') or '',
                'unit_cost': item.get('Unit Cost', 0),
                'price_per_bom': item.get('Price/BOM', 0),
                'order_qty': item.get('Order Qty', ''),
                'po_orders': item.get('PO Orders', ''),
                'part_type': item.get('Type', ''),
                'inventory': item.get('Inventory', ''),
                'warehouse_box_number': item.get('Warehouse Box', ''),
                'eco_number': item.get('ECO Number', ''),
                'eco_description': item.get('ECO Description', ''),
                'thumbnail': item.get('thumbnail', {}),
                'source_currency': item.get('source_currency', ''),
                'source_unit_cost': item.get('source_unit_cost', ''),
                'has_pdf': _part_obj.has_pdf if _part_obj else False,
                'has_ai_pdf': _part_obj.has_ai_pdf if _part_obj else False,
                'has_step': _part_obj.has_step if _part_obj else False,
                'datasheet_drive_url': _part_obj.datasheet_drive_url if _part_obj else None,
            })

        dissolved.dissolved_parts_json = json.dumps(parts_list)
        dissolved.source_bom_ids_json = json.dumps(resolved_bom_ids)  # Update to latest BOM revision IDs
        dissolved.updated_at = datetime.utcnow()
        db.session.commit()

        return jsonify({
            'success': True,
            'parts_count': len(parts_list)
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/bom-versions/<int:bom_id>', methods=['GET'])
@login_required
def get_bom_versions(bom_id):
    """Get all versions for a specific BOM"""
    versions = BOMVersion.query.filter_by(bom_id=bom_id).order_by(BOMVersion.created_at.desc()).all()
    
    result = []
    for version in versions:
        creator = User.query.get(version.created_by) if version.created_by else None
        result.append({
            'id': version.id,
            'version': version.version_number,  # Also include 'version' for compatibility
            'version_number': version.version_number,
            'change_description': version.change_description,
            'change_type': version.change_type,
            'is_latest': version.is_latest,
            'total_changes': version.total_changes,
            'created_at': version.created_at.isoformat(),
            'created_by': version.created_by,
            'created_by_name': creator.username if creator else 'Unknown',
            'assembly_path': version.assembly_path,
            'bom_layout': version.bom_layout,
            'configuration': version.configuration
        })
    return jsonify(result)

@app.route('/api/bom/<int:bom_id>/revisions', methods=['GET'])
@login_required
def get_bom_revisions_new(bom_id):
    """Get all revisions for a specific BOM using new BOMInstance structure"""
    try:
        # Get the BOM instance to find the assembly part number
        bom_instance = BOMInstance.query.get(bom_id)
        if not bom_instance:
            return jsonify({
                'success': False,
                'error': 'BOM not found'
            }), 404
        
        # Get all BOM instances with the same assembly part number (all revisions)
        all_revisions = BOMInstance.query.filter_by(
            assembly_part_number=bom_instance.assembly_part_number
        ).order_by(BOMInstance.created_at.desc()).all()
        
        if not all_revisions:
            return jsonify({
                'success': False,
                'error': 'No revisions found for this BOM'
            }), 404
        
        # Format revisions for the assembly tree
        revisions = []
        for revision in all_revisions:
            # Get creator information
            creator = User.query.get(revision.created_by) if revision.created_by else None
            
            revisions.append({
                'id': revision.id,
                'version': revision.version,
                'created_at': revision.created_at.isoformat() if revision.created_at else None,
                'created_by': revision.created_by,
                'created_by_name': creator.username if creator else 'Unknown',
                'change_description': revision.description or 'No description',
                'is_latest': revision.is_latest,
                'bom_layout': revision.bom_layout,
                'configuration': revision.configuration
            })
        
        return jsonify({
            'success': True,
            'revisions': revisions
        })
        
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'Error fetching revisions: {str(e)}'
        }), 500


