@app.route('/api/bom-versions/<int:bom_id>/switch', methods=['POST'])
@login_required
def switch_bom_version(bom_id):
    """Switch to a specific BOM version"""
    if not current_user.can_import_bom():
        return jsonify({'success': False, 'error': 'Insufficient permissions to switch BOM versions'}), 403
    
    data = request.json
    version_number = data.get('version_number')
    
    if not version_number:
        return jsonify({'success': False, 'error': 'Version number is required'})
    
    # Get the current BOM to find its name
    current_bom = BOMData.query.get(bom_id)
    if not current_bom:
        return jsonify({'success': False, 'error': 'BOM not found'})
    
    # Find the version record with the specified version number
    target_version = BOMVersion.query.filter_by(
        bom_id=bom_id,
        version_number=version_number
    ).first()
    
    print(f"DEBUG: Looking for version '{version_number}' for BOM ID {bom_id}")
    print(f"DEBUG: Found target version: {target_version}")
    
    if not target_version:
        return jsonify({'success': False, 'error': f'Version {version_number} not found for this BOM'})
    
    # Mark all versions as not latest for this BOM
    BOMVersion.query.filter_by(bom_id=bom_id).update({'is_latest': False}, synchronize_session=False)
    
    # Mark the target version as latest
    target_version.is_latest = True
    
    # Restore BOM data from snapshot if available
    if target_version.bom_data_snapshot:
        print(f"DEBUG: Restoring BOM data from snapshot for version {version_number}")
        print(f"DEBUG: Snapshot data length: {len(target_version.bom_data_snapshot)}")
        
        # Restore the BOM data
        current_bom.data = target_version.bom_data_snapshot
        current_bom.version = target_version.version_number
        current_bom.updated_at = datetime.utcnow()
        
        # Parse the snapshot data to restore BOM items
        try:
            from part_classifier import part_classifier
            snapshot_data = json.loads(target_version.bom_data_snapshot)
            
            # Clear existing BOM items
            BOMItem.query.filter_by(bom_id=bom_id).delete()
            
            # Get changes for this specific version from BOMChange table
            version_changes = {}
            if target_version.id:
                changes_for_version = BOMChange.query.filter_by(bom_version_id=target_version.id).all()
                for change in changes_for_version:
                    if change.part_number:
                        if change.part_number not in version_changes:
                            version_changes[change.part_number] = []
                        version_changes[change.part_number].append(change.field_name or change.change_type)
                
                print(f"DEBUG: Found {len(version_changes)} parts with changes for version {version_number}")
                for part_num, changes in version_changes.items():
                    print(f"DEBUG: Part {part_num} changes: {changes}")
            
            # Restore BOM items from snapshot
            items_restored = 0
            for item_data in snapshot_data.get('items', []):
                part_number = item_data.get('PART NUMBER', '')
                
                # Classify the part type
                part_type = part_classifier.classify_part(
                    item_data.get('PART NUMBER'),
                    item_data.get('State'),
                    item_data.get('DESCRIPTION')
                )
                
                # Get changes for this part from the version
                part_changes = version_changes.get(part_number, [])
                changes_text = None
                if part_changes:
                    changes_text = '\n'.join([f"{change}" for change in part_changes])
                
                # Create BOM item from snapshot
                bom_item = BOMItem(
                    bom_id=bom_id,
                    part_number=part_number,
                    part_name=item_data.get('PART NAME', ''),
                    description=item_data.get('DESCRIPTION', ''),
                    quantity=float(item_data.get('QTY.', 1)) if item_data.get('QTY.') else 1.0,
                    material=item_data.get('Material', ''),
                    finish1=item_data.get('FINISH1', ''),
                    finish2=item_data.get('FINISH2', ''),
                    revision=item_data.get('Revision', ''),
                    state=item_data.get('State', ''),
                    part_type=part_type,
                    status='active',
                    changes=changes_text,  # Store the changes for this version
                    created_by=current_user.id
                )
                db.session.add(bom_item)
                items_restored += 1
                
                # Debug: Log the restored item
                print(f"DEBUG: Restored item {part_number} with changes: {changes_text or 'None'}")
            
            print(f"DEBUG: Restored {items_restored} BOM items from version {version_number} snapshot")
            
        except Exception as e:
            # Roll back — committing here would persist the BOMItem delete with
            # zero/partial items restored, silently losing the BOM's contents.
            db.session.rollback()
            print(f"ERROR: Failed restoring BOM items from snapshot: {str(e)}")
            return jsonify({'success': False, 'error': f'Failed to restore items from version snapshot: {str(e)}'}), 500

    db.session.commit()
    
    return jsonify({
        'success': True,
        'message': f'Switched to version {version_number}',
        'version': {
            'id': current_bom.id,
            'version_number': current_bom.version,
            'is_latest': True
        }
    })

