@app.route('/api/users', methods=['GET', 'POST', 'PUT', 'DELETE'])
@admin_required
def users_api():
    """User management API"""
    
    if request.method == 'GET':
        users = User.query.all()
        return jsonify([{
            'id': user.id,
            'username': user.username,
            'email': user.email,
            'role': user.role,
            'created_at': user.created_at.isoformat(),
            'last_login': user.last_login.isoformat() if hasattr(user, 'last_login') and user.last_login else None,
            'phone': user.phone
        } for user in users])
    
    elif request.method == 'POST':
        data = request.json
        username = data.get('username')
        email = data.get('email')
        password = data.get('password')
        role = data.get('role', 'floor')
        
        # Validate role
        valid_roles = ['admin', 'engineer', 'finance', 'floor', 'floor_manager', 'system', 'viewer']
        if role not in valid_roles:
            return jsonify({'success': False, 'error': f'Invalid role. Must be one of: {valid_roles}'})
        
        if not username or not email or not password:
            return jsonify({'success': False, 'error': 'Username, email, and password are required'})
        
        if User.query.filter_by(username=username).first():
            return jsonify({'success': False, 'error': 'Username already exists'})
        
        if User.query.filter_by(email=email).first():
            return jsonify({'success': False, 'error': 'Email already exists'})
        
        user = User(
            username=username,
            email=email,
            password_hash=generate_password_hash(password),
            role=role,
            phone=data.get('phone', '')
        )
        db.session.add(user)
        db.session.commit()
        
        # Log the action
        log_action('USER_CREATE', current_user, 
                   f'User ID: {user.id}, Username: {username}, Email: {email}, Role: {role}')
        
        return jsonify({'success': True, 'message': 'User created successfully'})
    
    elif request.method == 'PUT':
        data = request.json
        user_id = data.get('id')
        user = User.query.get(user_id)
        
        if not user:
            return jsonify({'success': False, 'error': 'User not found'})
        
        if 'username' in data:
            user.username = data['username']
        if 'email' in data:
            user.email = data['email']
        if 'role' in data:
            user.role = data['role']
        if 'phone' in data:
            user.phone = data['phone']
        if 'password' in data and data['password']:
            user.password_hash = generate_password_hash(data['password'])
        
        db.session.commit()
        
        # Log the action
        changed_fields = []
        if 'username' in data: changed_fields.append(f'username={data["username"]}')
        if 'email' in data: changed_fields.append(f'email={data["email"]}')
        if 'role' in data: changed_fields.append(f'role={data["role"]}')
        if 'phone' in data: changed_fields.append(f'phone={data["phone"]}')
        if 'password' in data and data['password']: changed_fields.append('password=***')
        changes_str = ', '.join(changed_fields) if changed_fields else 'no changes'
        log_action('USER_UPDATE', current_user, 
                   f'User ID: {user_id}, Username: {user.username}, Changes: {changes_str}')
        
        return jsonify({'success': True, 'message': 'User updated successfully'})
    
    elif request.method == 'DELETE':
        data = request.json
        user_id = data.get('id')
        user = User.query.get(user_id)
        
        if not user:
            return jsonify({'success': False, 'error': 'User not found'})
        
        if user.id == current_user.id:
            return jsonify({'success': False, 'error': 'Cannot delete your own account'})
        
        username = user.username
        email = user.email
        role = user.role
        db.session.delete(user)
        db.session.commit()
        
        # Log the action
        log_action('USER_DELETE', current_user, 
                   f'Deleted User ID: {user_id}, Username: {username}, Email: {email}, Role: {role}')
        
        return jsonify({'success': True, 'message': 'User deleted successfully'})

# Custom Column Management API
@app.route('/api/custom-columns', methods=['GET', 'POST'])
@login_required
def custom_columns_api():
    """Custom column management API"""
    
    if request.method == 'GET':
        # Get all active custom columns ordered by display_order
        columns = CustomBOMColumn.query.filter_by(is_active=True).order_by(CustomBOMColumn.display_order).all()
        return jsonify([{
            'id': col.id,
            'column_name': col.column_name,
            'column_type': col.column_type,
            'display_order': col.display_order,
            'is_active': col.is_active,
            'select_options': json.loads(col.select_options) if col.select_options else None,
            'created_by': col.created_by,
            'created_at': col.created_at.isoformat()
        } for col in columns])
    
    elif request.method == 'POST':
        # Only admins can create columns
        if current_user.role != 'admin':
            return jsonify({'success': False, 'error': 'Only admins can create custom columns'}), 403
        
        data = request.get_json()
        column_name = (data.get('column_name') or '').strip()
        column_type = data.get('column_type', 'text')
        select_options = data.get('select_options', [])
        
        # Validation
        if not column_name:
            return jsonify({'success': False, 'error': 'Column name is required'}), 400
        
        # Check for duplicate column names
        if CustomBOMColumn.query.filter_by(column_name=column_name).first():
            return jsonify({'success': False, 'error': 'Column name already exists'}), 400
        
        # Validate column type
        valid_types = ['text', 'number', 'date', 'select']
        if column_type not in valid_types:
            return jsonify({'success': False, 'error': f'Invalid column type. Must be one of: {valid_types}'}), 400
        
        # Validate select options for select type
        if column_type == 'select' and not select_options:
            return jsonify({'success': False, 'error': 'Select options are required for select type columns'}), 400
        
        # Get next display order
        max_order = db.session.query(db.func.max(CustomBOMColumn.display_order)).scalar() or 0
        
        # Create new column
        new_column = CustomBOMColumn(
            column_name=column_name,
            column_type=column_type,
            display_order=max_order + 1,
            select_options=json.dumps(select_options) if select_options else None,
            created_by=current_user.id
        )
        
        db.session.add(new_column)
        db.session.commit()
        
        # Log the action
        log_action('CUSTOM_COLUMN_CREATE', current_user, 
                   f'Custom Column ID: {new_column.id}, Name: "{column_name}", Type: {column_type}')
        
        return jsonify({
            'success': True,
            'message': 'Custom column created successfully',
            'column': {
                'id': new_column.id,
                'column_name': new_column.column_name,
                'column_type': new_column.column_type,
                'display_order': new_column.display_order,
                'select_options': select_options
            }
        })

@app.route('/api/custom-columns/<int:column_id>', methods=['PUT', 'DELETE'])
@admin_required
def custom_column_api(column_id):
    """Update or delete a specific custom column"""
    
    column = CustomBOMColumn.query.get(column_id)
    if not column:
        return jsonify({'success': False, 'error': 'Column not found'}), 404
    
    if request.method == 'PUT':
        data = request.get_json()
        
        # Update column properties
        if 'column_name' in data:
            new_name = data['column_name'].strip()
            if not new_name:
                return jsonify({'success': False, 'error': 'Column name cannot be empty'}), 400
            
            # Check for duplicate names (excluding current column)
            if CustomBOMColumn.query.filter(CustomBOMColumn.column_name == new_name, CustomBOMColumn.id != column_id).first():
                return jsonify({'success': False, 'error': 'Column name already exists'}), 400
            
            column.column_name = new_name
        
        if 'column_type' in data:
            valid_types = ['text', 'number', 'date', 'select']
            if data['column_type'] not in valid_types:
                return jsonify({'success': False, 'error': f'Invalid column type. Must be one of: {valid_types}'}), 400
            column.column_type = data['column_type']
        
        if 'select_options' in data:
            column.select_options = json.dumps(data['select_options']) if data['select_options'] else None
        
        if 'is_active' in data:
            column.is_active = data['is_active']
        
        db.session.commit()
        
        # Log the action
        changed_fields = []
        if 'column_name' in data: changed_fields.append(f'name="{data["column_name"]}"')
        if 'column_type' in data: changed_fields.append(f'type={data["column_type"]}')
        if 'is_active' in data: changed_fields.append(f'active={data["is_active"]}')
        changes_str = ', '.join(changed_fields) if changed_fields else 'no changes'
        log_action('CUSTOM_COLUMN_UPDATE', current_user, 
                   f'Custom Column ID: {column_id}, Changes: {changes_str}')
        
        return jsonify({
            'success': True,
            'message': 'Column updated successfully',
            'column': {
                'id': column.id,
                'column_name': column.column_name,
                'column_type': column.column_type,
                'display_order': column.display_order,
                'is_active': column.is_active,
                'select_options': json.loads(column.select_options) if column.select_options else None
            }
        })
    
    elif request.method == 'DELETE':
        # Soft delete - mark as inactive instead of actually deleting
        column_name = column.column_name
        column.is_active = False
        db.session.commit()
        
        # Log the action
        log_action('CUSTOM_COLUMN_DELETE', current_user, 
                   f'Custom Column ID: {column_id}, Name: "{column_name}" (marked inactive)')
        
        return jsonify({'success': True, 'message': 'Column deleted successfully'})

@app.route('/api/custom-columns/reorder', methods=['POST'])
@admin_required
def reorder_custom_columns():
    """Reorder custom columns"""
    
    data = request.get_json()
    column_orders = data.get('column_orders', [])  # List of {id: column_id, order: new_order}
    
    try:
        for item in column_orders:
            column_id = item.get('id')
            new_order = item.get('order')
            
            if column_id and new_order is not None:
                column = CustomBOMColumn.query.get(column_id)
                if column:
                    column.display_order = new_order
        
        db.session.commit()
        return jsonify({'success': True, 'message': 'Column order updated successfully'})
    
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': f'Failed to reorder columns: {str(e)}'}), 500

