@app.route('/api/rfqs/<int:rfq_id>/reopen', methods=['POST'])
@login_required
@rfq_create_required
def reopen_rfq(rfq_id):
    """Reopen a completed RFQ (status -> 'active') so it can be edited again.

    Blocks the reopen if a linked PO still exists — the user must delete or
    cancel that PO first to avoid orphaned references and inventory drift.
    """
    try:
        rfq = RFQ.query.get_or_404(rfq_id)

        if rfq.status != 'converted_to_po':
            return jsonify({
                'success': False,
                'error': f'Only completed RFQs can be reopened (current status: {rfq.status})'
            }), 400

        linked_pos = PO.query.filter_by(rfq_id=rfq.id).all()
        active_pos = [p for p in linked_pos if p.status != 'cancelled']
        if active_pos:
            po_numbers = ', '.join(p.po_number for p in active_pos)
            return jsonify({
                'success': False,
                'error': f'Cannot reopen — linked PO(s) still exist: {po_numbers}. Cancel or delete them first.',
                'linked_pos': [{'id': p.id, 'po_number': p.po_number, 'status': p.status} for p in active_pos]
            }), 409

        rfq.status = 'active'
        db.session.commit()

        log_action('RFQ_REOPEN', current_user,
                   f'Reopened RFQ ID: {rfq.id}, RFQ Name: "{rfq.rfq_name}"')

        return jsonify({
            'success': True,
            'message': f'RFQ "{rfq.rfq_name}" reopened — status set to active',
            'rfq_id': rfq.id,
            'status': rfq.status,
        })

    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/rfqs/<int:rfq_id>/update_quantities', methods=['POST'])
@login_required
@rfq_create_required
def update_rfq_quantities(rfq_id):
    """Update RFQ item quantities in the database and on the Google Drive Excel"""
    try:
        rfq = RFQ.query.get_or_404(rfq_id)
        data = request.json
        updated_items = data.get('items', [])
        removed_items = data.get('removed_items', [])

        if not updated_items and not removed_items:
            return jsonify({'success': False, 'error': 'No items provided'}), 400

        # Separate new items from existing quantity updates
        new_items = [item for item in updated_items if item.get('is_new', False)]
        existing_items = [item for item in updated_items if not item.get('is_new', False)]

        # Build a lookup of new quantities by (part_number, revision)
        qty_lookup = {}
        for item in updated_items:
            key = (item['part_number'], item.get('revision', ''))
            qty_lookup[key] = float(item['quantity'])

        # Build a set of (part_number, revision) tuples for parts being removed
        removed_keys = set()
        for item in removed_items:
            removed_keys.add((item.get('part_number', ''), item.get('revision', '')))

        # 1. Update DB records for existing items
        updated_count = 0
        for updated_item in existing_items:
            part_number = updated_item['part_number']
            revision = updated_item.get('revision', '')
            new_qty = float(updated_item['quantity'])

            rfq_item = RFQItem.query.filter_by(
                rfq_id=rfq.id,
                part_number=part_number,
                revision=revision
            ).first()

            if rfq_item and rfq_item.quantity != new_qty:
                rfq_item.quantity = new_qty
                updated_count += 1

        # 1b. Delete removed RFQItems
        removed_count = 0
        for pn, rev in removed_keys:
            rfq_item = RFQItem.query.filter_by(
                rfq_id=rfq.id,
                part_number=pn,
                revision=rev
            ).first()
            if rfq_item:
                db.session.delete(rfq_item)
                removed_count += 1

        # 2. Create new RFQItems for newly added parts
        added_count = 0
        for new_item in new_items:
            part_number = new_item['part_number']
            revision = new_item.get('revision', '')
            quantity = float(new_item['quantity'])

            # Skip if already exists
            existing = RFQItem.query.filter_by(
                rfq_id=rfq.id,
                part_number=part_number,
                revision=revision
            ).first()
            if existing:
                continue

            # Look up Part record for metadata
            part = Part.query.filter_by(
                part_number=part_number,
                revision=revision
            ).first()

            rfq_item = RFQItem(
                rfq_id=rfq.id,
                part_id=part.id if part else None,
                part_number=part_number,
                revision=revision,
                quantity=quantity,
                material=part.material if part else None,
                finish1=part.finish1 if part else None,
                finish2=part.finish2 if part else None
            )
            db.session.add(rfq_item)
            added_count += 1

        db.session.commit()

        # 3. Update the Excel file on Google Drive (quantity changes + removals; new items not written to Excel)
        excel_updated = False
        excel_error = None
        if rfq.google_drive_folder_id and (updated_count > 0 or removed_count > 0):
            try:
                from google_sheets.google_drive_upload import get_drive_service, upload_file
                import openpyxl
                import tempfile
                import io

                service = get_drive_service()
                if service:
                    # Find the Excel file in the RFQ folder by name
                    from google_sheets.google_drive_upload import escape_drive_query_value
                    excel_name = f"{rfq.rfq_name}.xlsx"
                    query = f"name='{escape_drive_query_value(excel_name)}' and '{rfq.google_drive_folder_id}' in parents and trashed=false"
                    results = service.files().list(
                        q=query, spaces='drive', fields='files(id, name)',
                        supportsAllDrives=True, includeItemsFromAllDrives=True
                    ).execute()
                    files = results.get('files', [])

                    if files:
                        file_id = files[0]['id']
                        # Download the Excel file
                        from googleapiclient.http import MediaIoBaseDownload
                        request_dl = service.files().get_media(fileId=file_id, supportsAllDrives=True)
                        fh = io.BytesIO()
                        downloader = MediaIoBaseDownload(fh, request_dl)
                        done = False
                        while not done:
                            _, done = downloader.next_chunk()
                        fh.seek(0)

                        # Open and update quantities in the Excel
                        wb = openpyxl.load_workbook(fh)
                        ws = wb.active

                        # Find column indices from header row
                        headers = {cell.value: cell.column for cell in ws[1]}
                        pn_col = headers.get('PART NUMBER')
                        rev_col = headers.get('Revision')
                        qty_col = headers.get('QTY.')

                        if pn_col and qty_col:
                            # Collect rows to delete (in reverse so indices stay valid)
                            rows_to_delete = []
                            for row in range(2, ws.max_row + 1):
                                pn = str(ws.cell(row=row, column=pn_col).value or '')
                                rev = str(ws.cell(row=row, column=rev_col).value or '') if rev_col else ''
                                key = (pn, rev)
                                if key in removed_keys:
                                    rows_to_delete.append(row)
                                elif key in qty_lookup:
                                    ws.cell(row=row, column=qty_col).value = qty_lookup[key]
                            for row in reversed(rows_to_delete):
                                ws.delete_rows(row, 1)

                            # Save to temp dir with original name so upload_file replaces it
                            tmp_dir = tempfile.mkdtemp()
                            tmp_path = os.path.join(tmp_dir, excel_name)
                            wb.save(tmp_path)

                            upload_file(service, tmp_path, rfq.google_drive_folder_id)
                            os.remove(tmp_path)
                            os.rmdir(tmp_dir)
                            excel_updated = True
                        else:
                            excel_error = 'Could not find QTY. column in Excel'
                    else:
                        excel_error = f'Excel file "{excel_name}" not found in Google Drive folder'
                else:
                    excel_error = 'Could not connect to Google Drive'
            except Exception as e:
                import traceback
                traceback.print_exc()
                excel_error = str(e)

        log_action('RFQ_QTY_UPDATE', current_user,
                   f'Updated quantities on RFQ ID: {rfq.id}, RFQ Name: "{rfq.rfq_name}", Items changed: {updated_count}, Items added: {added_count}, Items removed: {removed_count}, Excel updated: {excel_updated}')

        parts = []
        if updated_count:
            parts.append(f'Updated {updated_count} item quantities')
        if added_count:
            parts.append(f'Added {added_count} new item(s)')
        if removed_count:
            parts.append(f'Removed {removed_count} item(s)')
        message = ', '.join(parts) if parts else 'No changes made'
        if parts:
            if excel_updated:
                message += ' (database + Google Drive Excel)'
            elif excel_error:
                message += f' (database only - Excel update failed: {excel_error})'

        return jsonify({
            'success': True,
            'message': message,
            'rfq_id': rfq.id,
            'excel_updated': excel_updated,
            'excel_error': excel_error
        })

    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/rfqs/<int:rfq_id>/duplicate', methods=['POST'])
@login_required
@rfq_create_required
def duplicate_rfq(rfq_id):
    """Duplicate an RFQ with the same parts but different quantities.

    Runs the full RFQ pipeline for the copy: searches PDM for the PDF/X_T
    files, builds the Excel and the PDF+XT ZIP, uploads everything to a new
    Google Drive folder inside the RFQ folder, and creates new RFQ/RFQItem
    records in the database.

    Payload:
        custom_rfq_name: optional base name for the copy (date is appended)
        quantity_multiplier: optional global multiplier (used when no items list)
        items: optional list of {part_number, revision, quantity} with the
               FINAL quantities for the copy; parts omitted from the list
               are excluded from the duplicate
    """
    source_rfq = RFQ.query.get_or_404(rfq_id)
    try:
        import re
        from mechanical_rfq_processor import MechanicalRFQProcessor

        if not source_rfq.rfq_items:
            return jsonify({'success': False, 'error': 'Source RFQ has no items to duplicate'}), 400

        data = request.json or {}
        custom_rfq_name = (data.get('custom_rfq_name') or '').strip()
        items_override = data.get('items') or []
        try:
            quantity_multiplier = float(data.get('quantity_multiplier') or 1)
        except (ValueError, TypeError):
            quantity_multiplier = 1

        # Requested final quantities by (part_number, revision)
        qty_override = {}
        for item in items_override:
            key = (item.get('part_number', ''), item.get('revision', ''))
            try:
                qty_override[key] = float(item.get('quantity', 0))
            except (ValueError, TypeError):
                qty_override[key] = 0

        # Assemble the duplicated parts list from the source RFQ items
        parts_list = []
        for src_item in source_rfq.rfq_items:
            key = (src_item.part_number, src_item.revision)
            if qty_override:
                if key not in qty_override:
                    continue  # part removed in the duplicate dialog
                final_qty = qty_override[key]
            else:
                final_qty = (src_item.quantity or 0) * quantity_multiplier
            if final_qty <= 0:
                continue
            parts_list.append({
                'PART NUMBER': src_item.part_number,
                'Revision': src_item.revision,
                'Description': '',
                'Material': src_item.material or '',
                'FINISH1': src_item.finish1 or '',
                'FINISH2': src_item.finish2 or '',
                'QTY.': final_qty,
                'State': src_item.state or ''
            })

        if not parts_list:
            return jsonify({'success': False, 'error': 'No parts with quantity > 0 to include in the duplicated RFQ'}), 400

        # Determine a unique RFQ name: base name + today's date, with a (n)
        # suffix if an RFQ with that exact name already exists (e.g. when
        # duplicating on the same day without renaming).
        base_name = custom_rfq_name if custom_rfq_name else source_rfq.rfq_name
        base_name = re.sub(r'\s*-?\s*RFQ\s*-\s*\d{4}-\d{2}-\d{2}', '', base_name)
        base_name = re.sub(r'\s*-\s*\d{4}-\d{2}-\d{2}\s*$', '', base_name).strip(' -') or source_rfq.bom_name
        today_str = datetime.now().strftime('%Y-%m-%d')
        final_base = base_name
        rfq_name = f"{final_base} - RFQ - {today_str}"
        suffix = 2
        while RFQ.query.filter_by(rfq_name=rfq_name).first():
            final_base = f"{base_name} ({suffix})"
            rfq_name = f"{final_base} - RFQ - {today_str}"
            suffix += 1

        has_mechanical = any('-MP-' in p['PART NUMBER'] for p in parts_list)
        if has_mechanical:
            # Full mechanical pipeline: PDM file search, PDF & XT ZIP, Excel,
            # Google Drive folder upload
            processor = MechanicalRFQProcessor()
            bom_data = {'items': parts_list, 'name': rfq_name, 'metadata': {'name': rfq_name}}
            result = processor.process_rfq(bom_data, source_rfq.bom_name, rfq_name)
        else:
            # Standard-parts RFQ (no PDF/X_T files): Excel only + Drive folder
            from standard_parts_rfq_processor import StandardPartsRFQProcessor
            sp_processor = StandardPartsRFQProcessor()
            sp_parts = [{'part_number': p['PART NUMBER'], 'qty': p['QTY.']} for p in parts_list]
            result = sp_processor.process_standard_parts_rfq(
                source_rfq.bom_name, 'Standard Parts', sp_parts, final_base
            )

        if not result.get('success'):
            return jsonify({
                'success': False,
                'error': result.get('error', 'RFQ duplication failed'),
                'file_search': result.get('file_search', {}),
                'missing_files': result.get('missing_files', {}),
                'state_issues': result.get('state_issues', [])
            }), 500

        # Google Drive folder info (same handling as the export route)
        google_drive_info = result.get('google_drive', {}) or {}
        google_drive_folder_url = google_drive_info.get('folder_url')
        google_drive_folder_id = google_drive_info.get('folder_id')
        if not google_drive_folder_url and isinstance(google_drive_info.get('links'), dict):
            links = google_drive_info['links']
            google_drive_folder_url = links.get('folder_url')
            google_drive_folder_id = links.get('folder_id')

        new_rfq = RFQ(
            bom_id=source_rfq.bom_id,
            # Show the duplicate under the name given in the dialog (falls back
            # to the source base name when unchanged); bom_id keeps the link to
            # the original BOM instance.
            bom_name=final_base,
            bom_revision=source_rfq.bom_revision,
            rfq_name=rfq_name,
            google_drive_folder_id=google_drive_folder_id,
            google_drive_folder_url=google_drive_folder_url,
            created_by=current_user.id
        )
        db.session.add(new_rfq)
        db.session.flush()

        items_created = 0
        for part_data in parts_list:
            part_record = Part.query.filter_by(
                part_number=part_data['PART NUMBER'],
                revision=part_data['Revision']
            ).first()
            db.session.add(RFQItem(
                rfq_id=new_rfq.id,
                part_id=part_record.id if part_record else None,
                part_number=part_data['PART NUMBER'],
                revision=part_data['Revision'],
                quantity=part_data['QTY.'],
                material=part_data['Material'],
                finish1=part_data['FINISH1'],
                finish2=part_data['FINISH2'],
                state=part_data['State']
            ))
            items_created += 1

        db.session.commit()

        log_action('RFQ_DUPLICATE', current_user,
                   f'Duplicated RFQ ID: {source_rfq.id} ("{source_rfq.rfq_name}") -> new RFQ ID: {new_rfq.id} ("{rfq_name}"), Items: {items_created}')

        return jsonify({
            'success': True,
            'message': f'RFQ duplicated as "{rfq_name}"',
            'rfq_id': new_rfq.id,
            'rfq_name': rfq_name,
            'google_drive': google_drive_info,
            'google_drive_folder_url': google_drive_folder_url,
            'files_created': result.get('files_created', [])
        })

    except Exception as e:
        db.session.rollback()
        print(f"Error in duplicate_rfq: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/rfqs/<int:rfq_id>/refresh', methods=['POST'])
@login_required
@rfq_create_required
def refresh_rfq(rfq_id):
    """Refresh an RFQ from the current Parts DB (like Regenerate PO).

    Two phases via ?phase=detect|execute:
      detect  — compare each RFQ item's revision/material/finish/state against
                the Part table and report the differences (no changes made).
      execute — rebuild the parts list with fresh Parts-DB metadata, pull the
                latest PDF/X_T files from PDM, regenerate the RFQ Excel + ZIP
                into the EXISTING Google Drive folder (with an "_Updated_<date>"
                suffix) and update the RFQItem rows in place. Quantities are
                never changed.
    """
    try:
        import os, re, time, shutil, zipfile, tempfile
        import pandas as pd
        from mechanical_rfq_processor import MechanicalRFQProcessor

        rfq = RFQ.query.get_or_404(rfq_id)
        phase = request.args.get('phase', 'execute')

        rfq_items = rfq.rfq_items
        if not rfq_items:
            return jsonify({'success': False, 'error': 'RFQ has no items'}), 400

        def clean_rev(rev):
            return str(rev or '').replace('REV', '').replace('rev', '').strip().upper()

        def rev_num(rev):
            try:
                return int(clean_rev(rev).lstrip('0') or '0')
            except ValueError:
                return -1

        # Compare every RFQ item against the Parts DB. Metadata comes from the
        # item's own revision; a revision bump is only offered when a NEWER
        # non-Editing revision exists — an "Editing" revision lives in the DB
        # before it is released and must never be pushed into an RFQ.
        revision_updates = []
        metadata_updates = []
        missing_parts = []
        refreshed_parts = []  # data reused by the execute phase

        for item in rfq_items:
            part_rows = Part.query.filter_by(part_number=item.part_number).all()

            exact = next(
                (p for p in part_rows if clean_rev(p.revision) == clean_rev(item.revision)),
                None
            )
            stable_rows = [
                p for p in part_rows
                if str(p.state or '').strip().lower() != 'editing'
            ]
            newest_stable = max(stable_rows, key=lambda p: rev_num(p.revision), default=None)

            target = exact
            if newest_stable is not None and rev_num(newest_stable.revision) > rev_num(item.revision):
                target = newest_stable

            if target is None:
                # No Part row at the item's revision and no newer released one
                missing_parts.append(item.part_number)
                refreshed_parts.append({
                    'item': item,
                    'part': None,
                    'revision': item.revision,
                    'description': '',
                    'material': item.material or '',
                    'finish1': item.finish1 or '',
                    'finish2': item.finish2 or '',
                    'state': item.state or ''
                })
                continue

            revision_changed = clean_rev(target.revision) != clean_rev(item.revision)
            if revision_changed:
                revision_updates.append({
                    'part_number': item.part_number,
                    'old_revision': item.revision,
                    'new_revision': target.revision
                })

            for field, old_val, new_val in (
                ('material', item.material, target.material),
                ('finish1', item.finish1, target.finish1),
                ('finish2', item.finish2, target.finish2),
                ('state', item.state, target.state),
            ):
                if (old_val or '').strip() != (new_val or '').strip():
                    metadata_updates.append({
                        'part_number': item.part_number,
                        'revision': item.revision,
                        'field': field,
                        'old_value': old_val or '',
                        'new_value': new_val or ''
                    })

            refreshed_parts.append({
                'item': item,
                'part': target,
                'revision': target.revision,
                'description': target.description or '',
                'material': target.material or '',
                'finish1': target.finish1 or '',
                'finish2': target.finish2 or '',
                'state': target.state or ''
            })

        summary = {
            'total_parts': len(rfq_items),
            'revision_changes': len(revision_updates),
            'metadata_changes': len(metadata_updates),
            'missing_parts': len(missing_parts)
        }

        # Phase 1: report the differences only
        if phase == 'detect':
            return jsonify({
                'success': True,
                'revision_updates': revision_updates,
                'metadata_updates': metadata_updates,
                'missing_parts': missing_parts,
                'summary': summary
            })

        # Phase 2: execute the refresh
        if not rfq.google_drive_folder_id:
            return jsonify({'success': False, 'error': 'RFQ does not have a Google Drive folder'}), 400

        processor = MechanicalRFQProcessor()

        # Pull the latest files from PDM for mechanical parts / assemblies
        parts_for_get_latest = []
        for entry in refreshed_parts:
            part_number = entry['item'].part_number
            if '-MP-' not in part_number.upper() and '-AS-' not in part_number.upper():
                continue
            rev_clean = clean_rev(entry['revision'])
            rev_num = rev_clean.lstrip('0') or '0'
            rev_formatted = f"{int(rev_num):02d}" if rev_num.isdigit() else rev_clean

            extensions = ['.x_t', '.pdf']
            if entry['part'] and entry['part'].part_type and '3d' in entry['part'].part_type.lower():
                extensions.append('.step')
            parts_for_get_latest.append({
                'part_number': part_number,
                'revision': rev_formatted,
                'extensions': extensions
            })
            # For assemblies, also request AI (Assembly Instruction) files
            if '-AS-' in part_number.upper():
                parts_for_get_latest.append({
                    'part_number': f"{part_number}-AI",
                    'revision': rev_formatted,
                    'extensions': ['.pdf']
                })

        if parts_for_get_latest:
            print(f"🔧 RFQ refresh: calling PDM get latest for {len(parts_for_get_latest)} parts...")
            get_latest_result = processor._call_pdm_get_latest(parts_for_get_latest)
            if get_latest_result.get('success'):
                time.sleep(3)  # Wait for files to be available
            else:
                print(f"⚠️ Warning: PDM get latest had issues: {get_latest_result.get('error', 'Unknown error')}")

        # Collect PDF/X_T files (3D-print parts are excluded, as in the export)
        collect_input = [
            {'part_number': e['item'].part_number, 'revision': clean_rev(e['revision'])}
            for e in refreshed_parts
            if '-MP-' in e['item'].part_number.upper()
            and str(e['state']).lower() != '3d print'
        ]
        collected_files = []
        if collect_input:
            file_collection_result = processor.collect_files_for_parts(collect_input)
            if not file_collection_result.get('success', False):
                return jsonify({'success': False, 'error': f"File collection failed: {file_collection_result.get('error', 'Unknown error')}"}), 500
            collected_files = file_collection_result.get('collected_files', [])

        # Build the refreshed RFQ Excel (same columns as the original export)
        temp_dir = tempfile.mkdtemp(prefix=f"rfq_refresh_{rfq.id}_")
        try:
            rows = []
            for i, entry in enumerate(refreshed_parts, start=1):
                rows.append({
                    'ITEM NO.': i,
                    'PART NUMBER': entry['item'].part_number,
                    'Revision': entry['revision'],
                    'Description': entry['description'],
                    'Material': entry['material'],
                    'FINISH1': entry['finish1'],
                    'FINISH2': entry['finish2'],
                    'QTY.': entry['item'].quantity
                })
            df = pd.DataFrame(rows)

            today_str = datetime.now().strftime('%Y-%m-%d')
            safe_rfq_name = re.sub(r'[\\/:*?"<>|]', '_', rfq.rfq_name)
            base_name = f"{safe_rfq_name}_Updated_{today_str}"
            excel_path = os.path.join(temp_dir, f"{base_name}.xlsx")
            df.to_excel(excel_path, index=False, engine='openpyxl')
            processor._format_rfq_excel(excel_path)

            files_to_upload = [excel_path]
            if collected_files:
                zip_path = os.path.join(temp_dir, f"{base_name}.zip")
                with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
                    added = set()
                    for file_path in collected_files:
                        arcname = os.path.basename(file_path)
                        if arcname not in added and os.path.exists(file_path):
                            zipf.write(file_path, arcname)
                            added.add(arcname)
                files_to_upload.append(zip_path)

            from google_sheets.google_drive_upload import get_drive_service, upload_file
            drive_service = get_drive_service()
            if not drive_service:
                return jsonify({'success': False, 'error': 'Failed to connect to Google Drive'}), 500

            uploaded_links = {}
            for file_path in files_to_upload:
                try:
                    link = upload_file(drive_service, file_path, rfq.google_drive_folder_id)
                    if link:
                        uploaded_links[os.path.basename(file_path)] = link
                except Exception as e:
                    print(f"Error uploading {os.path.basename(file_path)}: {e}")
        finally:
            shutil.rmtree(temp_dir, ignore_errors=True)

        if not uploaded_links:
            return jsonify({'success': False, 'error': 'Failed to upload refreshed files to Google Drive'}), 500

        # Update the RFQ items in place with the refreshed metadata
        for entry in refreshed_parts:
            item, part = entry['item'], entry['part']
            if not part:
                continue
            item.part_id = part.id
            item.revision = entry['revision']
            item.material = entry['material']
            item.finish1 = entry['finish1']
            item.finish2 = entry['finish2']
            item.state = entry['state']
        db.session.commit()

        log_action('RFQ_REFRESH', current_user,
                   f'RFQ ID: {rfq.id} ("{rfq.rfq_name}"), revision changes: {len(revision_updates)}, '
                   f'metadata changes: {len(metadata_updates)}, missing parts: {len(missing_parts)}')

        return jsonify({
            'success': True,
            'message': 'RFQ refreshed successfully',
            'rfq_id': rfq.id,
            'revision_updates': revision_updates,
            'metadata_updates': metadata_updates,
            'missing_parts': missing_parts,
            'summary': summary,
            'google_drive': {
                'folder_url': rfq.google_drive_folder_url,
                'links': uploaded_links
            }
        })

    except Exception as e:
        db.session.rollback()
        print(f"Error in refresh_rfq: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


def get_db_unit_cost_in_currency(part_number, revision, po_currency, usd_to_po_rate):
    """Existing database price for a part, expressed in the PO currency.

    Prefers the exact revision, falls back to the latest revision that has a
    cost. Uses source_unit_cost when the part was last purchased in the same
    currency; otherwise converts the stored USD cost. Returns None when no
    comparable price exists (no cost on record, or no exchange rate).
    """
    db_part = Part.query.filter_by(part_number=part_number, revision=revision).first()
    if not db_part or db_part.unit_cost is None:
        db_part = Part.query.filter(
            Part.part_number == part_number,
            Part.unit_cost.isnot(None)
        ).order_by(Part.revision.desc()).first()
    if not db_part or db_part.unit_cost is None:
        return None
    if (db_part.source_currency or '').upper() == po_currency and db_part.source_unit_cost is not None:
        return float(db_part.source_unit_cost)
    if po_currency == 'USD':
        return float(db_part.unit_cost)
    if usd_to_po_rate:
        return round(float(db_part.unit_cost) * usd_to_po_rate, 4)
    return None


@app.route('/api/parts/<part_number>/db-revisions', methods=['GET'])
@login_required
@rfq_create_required
def get_part_db_revisions(part_number):
    """All Part rows for a part number, with state, usage counts and on-disk
    file availability. Lets purchasing inspect and clean up bogus revision
    rows that break the RFQ latest-revision lookup."""
    try:
        parts = Part.query.filter_by(part_number=part_number).order_by(Part.revision.desc()).all()
        if not parts:
            return jsonify({'success': False, 'error': 'Part not found'}), 404

        file_availability = {}
        try:
            from pdm_bom_parser import PdmBomParser
            file_availability = PdmBomParser.check_file_availability(
                [(p.part_number, p.revision, p.part_type or '') for p in parts])
        except Exception as e:
            print(f"Warning: Could not check file availability: {e}")

        revisions = []
        for p in parts:
            flags = file_availability.get((p.part_number, p.revision), {})
            revisions.append({
                'id': p.id,
                'revision': p.revision,
                'state': p.state,
                'status': p.status,
                'eco_number': p.eco_number,
                'part_type': p.part_type,
                'created_at': p.created_at.strftime('%Y-%m-%d %H:%M') if p.created_at else None,
                'has_pdf': bool(flags.get('has_pdf', False)),
                'has_xt': bool(flags.get('has_xt', False)),
                'bom_count': BOMPart.query.filter_by(part_id=p.id).count(),
                'rfq_count': RFQItem.query.filter_by(part_id=p.id).count(),
                'po_count': POItem.query.filter_by(part_id=p.id).count(),
            })
        return jsonify({'success': True, 'part_number': part_number, 'revisions': revisions})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/parts/db-revisions/<int:part_id>', methods=['DELETE'])
@login_required
@rfq_create_required
def delete_part_db_revision(part_id):
    """Delete one Part revision row (manual cleanup of wrong revisions).
    BOM lines pointing at it are removed; RFQ/PO items keep their denormalized
    part_number/revision and are just unlinked. Returns the new latest
    revision (with live file check) so the caller can refresh its view."""
    try:
        part = Part.query.get_or_404(part_id)
        part_number, revision = part.part_number, part.revision

        replacement_refs = PartReplacement.query.filter(
            (PartReplacement.old_part_id == part_id) | (PartReplacement.new_part_id == part_id)
        ).count()
        if replacement_refs:
            return jsonify({
                'success': False,
                'error': f'{part_number} REV{revision} is referenced by {replacement_refs} part replacement record(s) and cannot be deleted.'
            }), 400

        # SQLite FK enforcement is off — unlink/remove referencing rows explicitly
        bom_removed = BOMPart.query.filter_by(part_id=part_id).delete(synchronize_session=False)
        RFQItem.query.filter_by(part_id=part_id).update({'part_id': None}, synchronize_session=False)
        POItem.query.filter_by(part_id=part_id).update({'part_id': None}, synchronize_session=False)
        InventoryTransaction.query.filter_by(part_id=part_id).update({'part_id': None}, synchronize_session=False)

        Part.query.filter_by(id=part_id).delete(synchronize_session=False)
        db.session.commit()

        log_action('DELETE_PART_REVISION', current_user,
                   f'Deleted {part_number} REV{revision} (part id {part_id}) from parts DB'
                   + (f', removed {bom_removed} BOM line(s)' if bom_removed else ''))

        latest = Part.query.filter_by(part_number=part_number).order_by(Part.revision.desc()).first()
        latest_info = None
        if latest:
            flags = {}
            try:
                from pdm_bom_parser import PdmBomParser
                flags = PdmBomParser.check_file_availability(
                    [(latest.part_number, latest.revision, latest.part_type or '')]
                ).get((latest.part_number, latest.revision), {})
            except Exception as e:
                print(f"Warning: Could not check file availability: {e}")
            latest_info = {
                'revision': latest.revision,
                'state': latest.state,
                'has_pdf': bool(flags.get('has_pdf', False)),
                'has_xt': bool(flags.get('has_xt', False)),
            }

        return jsonify({'success': True, 'deleted': f'{part_number} REV{revision}', 'latest': latest_info})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/rfqs/<int:rfq_id>/validate_prices', methods=['POST'])
@login_required
@rfq_create_required
def validate_prices_for_po(rfq_id):
    """Validate prices for PO creation - process quotations and return parts with price matches/conflicts/missing"""
    try:
        from werkzeug.utils import secure_filename
        from gemini_quotation_processor import GeminiQuotationProcessor
        import os
        
        rfq = RFQ.query.get_or_404(rfq_id)
        
        # Get form data
        po_number = request.form.get('po_number', '').strip()
        vendor = request.form.get('vendor', '').strip()
        po_currency = (request.form.get('currency') or 'USD').strip().upper()

        if not po_number or not vendor:
            return jsonify({'success': False, 'error': 'PO number and vendor are required'}), 400

        # Exchange rate (PO-currency units per USD) for converting stored USD
        # part costs into the PO currency, so old-vs-new prices are comparable
        usd_to_po_rate = 1.0 if po_currency == 'USD' else get_cached_or_fetch_rate(po_currency, 'USD')
        
        # Handle multiple quotation files (optional)
        quotation_files = request.files.getlist('quotation')
        extracted_prices = {}
        saved_files = []
        quotation_metadata = {}
        additional_costs_extracted = {}

        # Only process quotations if files were uploaded
        if quotation_files and not all(f.filename == '' for f in quotation_files):
            # Create uploads directory if it doesn't exist
            upload_dir = os.path.join(app.instance_path, 'uploads', 'quotations')
            os.makedirs(upload_dir, exist_ok=True)
            
            # Save uploaded files
            for file in quotation_files:
                if file and file.filename:
                    filename = secure_filename(file.filename)
                    file_path = os.path.join(upload_dir, filename)
                    file.save(file_path)
                    saved_files.append(file_path)
            
            if saved_files:
                # Process quotations using GeminiQuotationProcessor
                processor = GeminiQuotationProcessor()
                extracted_prices_raw = processor.extract_from_multiple_quotations(saved_files, vendor)

                # Convert extracted_prices_raw format to simple dict for matching
                # IMPORTANT: Separate cost items from regular parts BEFORE matching
                additional_costs_extracted = {}  # Cost items (MASTER, MOLD, SILICONE, etc.)
                parts_to_match = {}  # Regular parts only

                for part_num, price_list in extracted_prices_raw.items():
                    if price_list and len(price_list) > 0:
                        first_price = price_list[0]
                        price_data = {
                            'unit_cost': first_price.get('unit_cost'),
                            'order_qty': first_price.get('order_qty'),
                            'total_cost': first_price.get('total_cost')
                        }

                        # Check if this is a cost item (has cost-related suffix or keywords)
                        part_num_upper = part_num.upper()
                        is_cost_item = any(suffix in part_num_upper for suffix in [
                            '-MASTER', '-MOLD', '-SILICONE', '-TOOLING', '-SETUP',
                            '-LABOR', '-DELIVERY', '-SHIPPING', '-ASSEMBLY', '-FEE'
                        ])

                        if is_cost_item:
                            # This is a cost item - keep it separate
                            additional_costs_extracted[part_num] = price_data
                            print(f"[COST ITEM] {part_num} - will be added as additional cost")
                        else:
                            # This is a regular part - will be matched with RFQ
                            parts_to_match[part_num] = price_data
                            print(f"[PART] {part_num} - will be matched with RFQ items")

                extracted_prices = parts_to_match  # Use only regular parts for matching!

                # Extract quotation metadata from the first file
                try:
                    quotation_metadata = processor.extract_metadata(saved_files[0])
                except Exception as meta_err:
                    print(f"Warning: Could not extract quotation metadata: {meta_err}")
                    quotation_metadata = {}

        # Get RFQ items from database
        rfq_items = RFQItem.query.filter_by(rfq_id=rfq_id).all()
        
        # Check for revision updates in BOM and prepare target parts list for AI matching
        target_parts = []
        revision_updates = {}  # Track revision updates: {part_number: {'old_revision': ..., 'new_revision': ...}}
        
        for item in rfq_items:
            # Get latest revision from BOM for this part number
            latest_part = Part.query.filter_by(
                part_number=item.part_number
            ).order_by(Part.revision.desc()).first()
            
            # Check if revision changed
            if latest_part and latest_part.revision != item.revision:
                # Use latest revision for matching and PO
                current_revision = latest_part.revision
                revision_updates[item.part_number] = {
                    'old_revision': item.revision,
                    'new_revision': current_revision,
                    'revision_updated': True
                }
                print(f"Revision update detected for {item.part_number}: {item.revision} → {current_revision}")
            else:
                # No revision change
                current_revision = item.revision
                revision_updates[item.part_number] = {
                    'old_revision': item.revision,
                    'new_revision': current_revision,
                    'revision_updated': False
                }
            
            # Use current (latest) revision for AI matching
            target_parts.append({'part_number': item.part_number, 'revision': current_revision})
        
        # Use AI to intelligently match RFQ parts with extracted parts
        matched_prices = {}
        if extracted_prices:
            print(f"Using AI to match {len(target_parts)} RFQ parts with {len(extracted_prices)} extracted parts...")
            processor = GeminiQuotationProcessor()
            matched_prices = processor.match_parts_intelligently(target_parts, extracted_prices)
            print(f"AI matching completed: {len(matched_prices)} parts matched")

        # Identify unmatched extracted items (potential additional costs)
        matched_extracted_parts = set()
        for target_pn, match_info in matched_prices.items():
            if match_info.get('matched_part_number'):
                matched_extracted_parts.add(match_info['matched_part_number'])

        # Find unmatched extracted parts that could be non-parts
        unmatched_extracted = {pn: price_data for pn, price_data in extracted_prices.items()
                               if pn not in matched_extracted_parts}

        # Extract additional costs (mold, tooling, etc.) from pre-filtered cost items
        # These were already separated from regular parts BEFORE matching
        additional_costs = []

        if additional_costs_extracted:
            print(f"[INFO] Adding {len(additional_costs_extracted)} pre-identified cost items as additional costs...")
            for pn, price_data in additional_costs_extracted.items():
                pn_upper = pn.upper()

                # Determine the type suffix
                cost_type = 'Other'
                base_pn = pn

                if '-MASTER' in pn_upper:
                    cost_type = 'Mold'
                    base_pn = pn.split('-MASTER')[0]
                elif '-MOLD' in pn_upper:
                    cost_type = 'Mold'
                    base_pn = pn.split('-MOLD')[0]
                elif '-SILICONE' in pn_upper:
                    cost_type = 'Silicone/Tooling'
                    base_pn = pn.split('-SILICONE')[0]
                elif '-TOOLING' in pn_upper:
                    cost_type = 'Tooling'
                    base_pn = pn.split('-TOOLING')[0]
                elif '-SETUP' in pn_upper:
                    cost_type = 'Setup'
                    base_pn = pn.split('-SETUP')[0]
                elif '-LABOR' in pn_upper:
                    cost_type = 'Labor'
                elif '-DELIVERY' in pn_upper or '-SHIPPING' in pn_upper:
                    cost_type = 'Delivery'
                elif '-ASSEMBLY' in pn_upper or '-FEE' in pn_upper:
                    cost_type = 'Assembly/Fee'

                additional_costs.append({
                    'part_number': pn,
                    'base_part_number': base_pn,
                    'cost_type': cost_type,
                    'unit_cost': price_data.get('unit_cost'),
                    'quantity': price_data.get('order_qty', 1),
                    'total_cost': price_data.get('total_cost') or ((price_data.get('unit_cost') or 0) * (price_data.get('order_qty') or 1)),
                    'description': f'{cost_type} - {base_pn}'
                })
                print(f"[ADDED] {pn} - {cost_type} (${price_data.get('unit_cost')})")

        # Prepare response data
        parts_data = []
        missing_prices = []
        duplicate_prices = []

        # Real-time file availability check for mechanical/designed parts only
        # Purchased/OTS parts (bearings, fasteners, etc.) don't have PDM revision files
        MECHANICAL_FILE_CHECK_TYPES = {'Mechanical part', 'Assembly', '3D Printing part'}
        file_check_parts = []
        mechanical_parts_set = set()  # Track which part numbers need file checks
        for item in rfq_items:
            part_type = item.part.part_type if item.part else None
            if part_type in MECHANICAL_FILE_CHECK_TYPES:
                rev_info = revision_updates.get(item.part_number, {})
                current_revision = rev_info.get('new_revision', item.revision)
                file_check_parts.append((item.part_number, current_revision, ''))
                mechanical_parts_set.add(item.part_number)

        file_availability = {}
        if file_check_parts:
            try:
                from pdm_bom_parser import PdmBomParser
                file_availability = PdmBomParser.check_file_availability(file_check_parts)
            except Exception as e:
                print(f"Warning: Could not check file availability: {e}")

        for item in rfq_items:
            # Get revision update info
            rev_info = revision_updates.get(item.part_number, {})
            current_revision = rev_info.get('new_revision', item.revision)
            old_revision = rev_info.get('old_revision', item.revision)
            revision_updated = rev_info.get('revision_updated', False)

            # Check real file availability on disk (only for mechanical parts)
            if item.part_number in mechanical_parts_set:
                file_flags = file_availability.get((item.part_number, current_revision), {})
                has_pdf = file_flags.get('has_pdf', False)
                has_xt = file_flags.get('has_xt', False)
                files_missing = not has_pdf
            else:
                # Non-mechanical parts (purchased/OTS) — skip file & revision check entirely
                has_pdf = True
                has_xt = True
                files_missing = False
                revision_updated = False

            part_data = {
                'part_number': item.part_number,
                'revision': current_revision,  # Use latest revision
                'old_revision': old_revision if revision_updated else None,  # Store old revision for reference
                'revision_updated': revision_updated,  # Flag to indicate revision was updated
                'files_missing': files_missing,  # Flag if PDF drawing is missing for this revision
                'pdf_missing': not has_pdf,
                'xt_missing': not has_xt,
                'quantity': item.quantity,
                'material': item.material or '',
                'finish1': item.finish1 or '',
                'finish2': item.finish2 or '',
                'unit_cost': None,
                'total_cost': None,
                'db_unit_cost': get_db_unit_cost_in_currency(
                    item.part_number, current_revision, po_currency, usd_to_po_rate),
                'price_options': [],
                'has_price': False,
                'match_confidence': None,
                'matched_part_number': None
            }

            # Check if we have a matched price from AI matching
            if item.part_number in matched_prices:
                matched_info = matched_prices[item.part_number]
                part_data['has_price'] = True
                part_data['unit_cost'] = matched_info.get('unit_cost')
                part_data['match_confidence'] = matched_info.get('match_confidence', 'unknown')
                part_data['matched_part_number'] = matched_info.get('matched_extracted_part')

                # Create price_options format (keep original format for compatibility)
                part_data['price_options'] = [{
                    'unit_cost': matched_info.get('unit_cost'),
                    'order_qty': matched_info.get('order_qty'),
                    'total_cost': matched_info.get('total_cost'),
                    'source_file': 'quotation',
                    'match_confidence': matched_info.get('match_confidence', 'unknown')
                }]

                # Calculate total cost using our BOM quantity
                if part_data['unit_cost']:
                    part_data['total_cost'] = part_data['unit_cost'] * item.quantity
            else:
                # No matched price from quotation - try to get existing unit cost from database
                part = Part.query.filter_by(
                    part_number=item.part_number,
                    revision=current_revision
                ).first()
                
                if part and part.unit_cost:
                    # Use existing unit cost from database
                    part_data['has_price'] = True
                    part_data['unit_cost'] = float(part.unit_cost)
                    part_data['total_cost'] = float(part.unit_cost) * item.quantity
                    part_data['price_options'] = [{
                        'unit_cost': float(part.unit_cost),
                        'order_qty': item.quantity,
                        'total_cost': float(part.unit_cost) * item.quantity,
                        'source_file': 'database',
                        'match_confidence': 'existing'
                    }]
                else:
                    missing_prices.append(item.part_number)
            
            parts_data.append(part_data)
        
        return jsonify({
            'success': True,
            'po_number': po_number,
            'vendor': vendor,
            'parts': parts_data,
            'additional_costs': additional_costs,
            'missing_prices': missing_prices,
            'duplicate_prices': duplicate_prices,
            'quotation_files': [os.path.basename(f) for f in saved_files],
            'quotation_metadata': quotation_metadata,
            'summary': {
                'total_parts': len(parts_data),
                'parts_with_prices': len([p for p in parts_data if p['has_price']]),
                'missing_prices_count': len(missing_prices),
                'duplicate_prices_count': len(duplicate_prices),
                'additional_costs_total': sum(c.get('total_cost', 0) for c in additional_costs)
            }
        })

    except Exception as e:
        print(f"Error in validate_prices_for_po: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/quotations/process_additional', methods=['POST'])
@login_required
@rfq_create_required
def process_additional_quotations():
    """Process additional quotations uploaded in the price validation modal"""
    try:
        from werkzeug.utils import secure_filename
        from gemini_quotation_processor import GeminiQuotationProcessor
        import os
        
        # Get form data
        rfq_id = request.form.get('rfq_id')
        vendor = request.form.get('vendor', '').strip()
        po_currency = (request.form.get('currency') or 'USD').strip().upper()

        if not rfq_id:
            return jsonify({'success': False, 'error': 'RFQ ID is required'}), 400

        # Rate for converting stored USD part costs into the PO currency (price comparison)
        usd_to_po_rate = 1.0 if po_currency == 'USD' else get_cached_or_fetch_rate(po_currency, 'USD')
        
        # Handle multiple quotation files
        quotation_files = request.files.getlist('quotation')
        if not quotation_files or all(f.filename == '' for f in quotation_files):
            return jsonify({'success': False, 'error': 'At least one quotation file is required'}), 400
        
        # Create uploads directory if it doesn't exist
        upload_dir = os.path.join(app.instance_path, 'uploads', 'quotations')
        os.makedirs(upload_dir, exist_ok=True)
        
        # Save uploaded files
        saved_files = []
        for file in quotation_files:
            if file and file.filename:
                filename = secure_filename(file.filename)
                file_path = os.path.join(upload_dir, filename)
                file.save(file_path)
                saved_files.append(file_path)
        
        if not saved_files:
            return jsonify({'success': False, 'error': 'No valid quotation files uploaded'}), 400
        
        # Process quotations using GeminiQuotationProcessor
        processor = GeminiQuotationProcessor()
        extracted_prices_raw = processor.extract_from_multiple_quotations(saved_files, vendor)
        
        # Convert extracted_prices_raw format to simple dict for matching
        extracted_prices = {}
        for part_num, price_list in extracted_prices_raw.items():
            if price_list and len(price_list) > 0:
                first_price = price_list[0]
                extracted_prices[part_num] = {
                    'unit_cost': first_price.get('unit_cost'),
                    'order_qty': first_price.get('order_qty'),
                    'total_cost': first_price.get('total_cost')
                }
        
        # Get RFQ items from database
        rfq_items = RFQItem.query.filter_by(rfq_id=rfq_id).all()
        
        # Check for revision updates in BOM and prepare target parts list for AI matching
        target_parts = []
        revision_updates = {}  # Track revision updates: {part_number: {'old_revision': ..., 'new_revision': ...}}
        
        for item in rfq_items:
            # Get latest revision from BOM for this part number
            latest_part = Part.query.filter_by(
                part_number=item.part_number
            ).order_by(Part.revision.desc()).first()
            
            # Check if revision changed
            if latest_part and latest_part.revision != item.revision:
                # Use latest revision for matching and PO
                current_revision = latest_part.revision
                revision_updates[item.part_number] = {
                    'old_revision': item.revision,
                    'new_revision': current_revision,
                    'revision_updated': True
                }
                print(f"Revision update detected for {item.part_number}: {item.revision} → {current_revision}")
            else:
                # No revision change
                current_revision = item.revision
                revision_updates[item.part_number] = {
                    'old_revision': item.revision,
                    'new_revision': current_revision,
                    'revision_updated': False
                }
            
            # Use current (latest) revision for AI matching
            target_parts.append({'part_number': item.part_number, 'revision': current_revision})
        
        # Use AI to intelligently match RFQ parts with extracted parts
        matched_prices = {}
        if extracted_prices:
            print(f"Using AI to match {len(target_parts)} RFQ parts with {len(extracted_prices)} extracted parts...")
            processor = GeminiQuotationProcessor()
            matched_prices = processor.match_parts_intelligently(target_parts, extracted_prices)
            print(f"AI matching completed: {len(matched_prices)} parts matched")
        
        # Prepare response data (same format as validate_prices)
        parts_data = []
        missing_prices = []
        duplicate_prices = []
        
        for item in rfq_items:
            # Get revision update info
            rev_info = revision_updates.get(item.part_number, {})
            current_revision = rev_info.get('new_revision', item.revision)
            old_revision = rev_info.get('old_revision', item.revision)
            revision_updated = rev_info.get('revision_updated', False)
            
            part_data = {
                'part_number': item.part_number,
                'revision': current_revision,  # Use latest revision
                'old_revision': old_revision if revision_updated else None,  # Store old revision for reference
                'revision_updated': revision_updated,  # Flag to indicate revision was updated
                'quantity': item.quantity,
                'material': item.material or '',
                'finish1': item.finish1 or '',
                'finish2': item.finish2 or '',
                'unit_cost': None,
                'total_cost': None,
                'db_unit_cost': get_db_unit_cost_in_currency(
                    item.part_number, current_revision, po_currency, usd_to_po_rate),
                'price_options': [],
                'has_price': False,
                'match_confidence': None,
                'matched_part_number': None
            }

            # Check if we have a matched price from AI matching
            if item.part_number in matched_prices:
                matched_info = matched_prices[item.part_number]
                part_data['has_price'] = True
                part_data['unit_cost'] = matched_info.get('unit_cost')
                part_data['match_confidence'] = matched_info.get('match_confidence', 'unknown')
                part_data['matched_part_number'] = matched_info.get('matched_extracted_part')
                
                # Create price_options format (keep original format for compatibility)
                part_data['price_options'] = [{
                    'unit_cost': matched_info.get('unit_cost'),
                    'order_qty': matched_info.get('order_qty'),
                    'total_cost': matched_info.get('total_cost'),
                    'source_file': 'quotation',
                    'match_confidence': matched_info.get('match_confidence', 'unknown')
                }]
                
                # Calculate total cost using our BOM quantity
                if part_data['unit_cost']:
                    part_data['total_cost'] = part_data['unit_cost'] * item.quantity
            else:
                missing_prices.append(item.part_number)
            
            parts_data.append(part_data)
        
        return jsonify({
            'success': True,
            'parts': parts_data,
            'missing_prices': missing_prices,
            'duplicate_prices': duplicate_prices,
            'quotation_files': [os.path.basename(f) for f in saved_files],
            'summary': {
                'total_parts': len(parts_data),
                'parts_with_prices': len([p for p in parts_data if p['has_price']]),
                'missing_prices_count': len(missing_prices),
                'duplicate_prices_count': len(duplicate_prices)
            }
        })
        
    except Exception as e:
        print(f"Error in process_additional_quotations: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/price-validation/export', methods=['POST'])
@login_required
def export_price_validation_excel():
    """Export the PO price validation comparison (database price vs quotation price) to Excel."""
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter
        from werkzeug.utils import secure_filename
        import io

        data = request.json or {}
        po_number = (data.get('po_number') or '').strip()
        vendor = (data.get('vendor') or '').strip()
        currency = (data.get('currency') or 'USD').strip().upper()
        parts = data.get('parts') or []

        symbol = {'EUR': '€', 'ILS': '₪'}.get(currency, '$')
        money_fmt = f'"{symbol}"#,##0.00'
        pct_fmt = '0.0%'

        # Excel's standard "good"/"bad" pastel styles
        GREEN_FILL = PatternFill(start_color='C6EFCE', end_color='C6EFCE', fill_type='solid')
        RED_FILL = PatternFill(start_color='FFC7CE', end_color='FFC7CE', fill_type='solid')
        GREEN_FONT = Font(color='006100')
        RED_FONT = Font(color='9C0006')

        wb = Workbook()
        ws = wb.active
        ws.title = 'Price Validation'

        ws.cell(row=1, column=1, value=f'PO {po_number} — Price Validation').font = Font(bold=True, size=14)
        ws.cell(row=2, column=1,
                value=f'Vendor: {vendor}    Currency: {currency}    Date: {datetime.now().strftime("%Y-%m-%d")}')

        headers = ['#', 'Part Number', 'Revision', 'Qty',
                   'DB Unit Price', 'Quotation Unit Price', 'Unit Diff', 'Diff %',
                   'DB Total', 'Quotation Total', 'Total Diff']
        MONEY_COLS = (5, 6, 7, 9, 10, 11)
        DIFF_COLS = (6, 7, 8, 10, 11)
        header_row = 4
        header_fill = PatternFill(start_color='F3F4F6', end_color='F3F4F6', fill_type='solid')
        for col_idx, header in enumerate(headers, start=1):
            cell = ws.cell(row=header_row, column=col_idx, value=header)
            cell.font = Font(bold=True)
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal='center', vertical='center')

        row = header_row + 1
        sum_db = sum_new = sum_diff = 0.0
        for idx, p in enumerate(parts, start=1):
            qty = p.get('quantity') or 0
            db_price = p.get('db_unit_cost')
            new_price = p.get('unit_cost')
            db_total = db_price * qty if db_price is not None else None
            new_total = new_price * qty if new_price is not None else None
            unit_diff = pct = total_diff = None
            if db_price is not None and new_price is not None:
                unit_diff = new_price - db_price
                total_diff = unit_diff * qty
                pct = (unit_diff / db_price) if db_price else None

            values = [idx, p.get('part_number'), p.get('revision'), qty,
                      db_price, new_price, unit_diff, pct, db_total, new_total, total_diff]
            for col_idx, value in enumerate(values, start=1):
                cell = ws.cell(row=row, column=col_idx, value=value)
                if col_idx in MONEY_COLS:
                    cell.number_format = money_fmt
                elif col_idx == 8:
                    cell.number_format = pct_fmt
            # Green = cheaper than the database price, red = more expensive
            if unit_diff is not None and abs(unit_diff) > 1e-9:
                fill, font = (GREEN_FILL, GREEN_FONT) if unit_diff < 0 else (RED_FILL, RED_FONT)
                for col_idx in DIFF_COLS:
                    cell = ws.cell(row=row, column=col_idx)
                    cell.fill = fill
                    cell.font = font
            if db_total is not None:
                sum_db += db_total
            if new_total is not None:
                sum_new += new_total
            if total_diff is not None:
                sum_diff += total_diff
            row += 1

        # Totals row — each column sums the values present in it
        ws.cell(row=row, column=2, value='TOTAL').font = Font(bold=True)
        for col_idx, total in ((9, sum_db), (10, sum_new), (11, sum_diff)):
            cell = ws.cell(row=row, column=col_idx, value=total)
            cell.number_format = money_fmt
            cell.font = Font(bold=True)
        if abs(sum_diff) > 1e-9:
            cell = ws.cell(row=row, column=11)
            cell.fill = GREEN_FILL if sum_diff < 0 else RED_FILL
            cell.font = Font(bold=True, color='006100' if sum_diff < 0 else '9C0006')
        ws.cell(row=row + 2, column=1,
                value='Diff columns are computed only for parts that have a price in the database.'
                ).font = Font(italic=True, size=9)

        widths = [5, 24, 10, 8, 15, 19, 12, 10, 14, 16, 12]
        for col_idx, width in enumerate(widths, start=1):
            ws.column_dimensions[get_column_letter(col_idx)].width = width

        output = io.BytesIO()
        wb.save(output)
        output.seek(0)

        download_name = secure_filename(f'PO_{po_number}_price_validation.xlsx') or 'price_validation.xlsx'
        return send_file(
            output,
            as_attachment=True,
            download_name=download_name,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/rfqs/<int:rfq_id>/create_po_final', methods=['POST'])
@login_required
@rfq_create_required
def create_po_final(rfq_id):
    """Create final PO with validated prices, collect files, generate Excel/ZIP, and create PO records"""
    try:
        from google_sheets.google_drive_upload import upload_output_files
        from mechanical_rfq_processor import MechanicalRFQProcessor
        import tempfile
        import zipfile
        import pandas as pd
        import os
        
        rfq = RFQ.query.get_or_404(rfq_id)
        data = request.json
        
        po_number = (data.get('po_number') or '').strip()
        vendor = (data.get('vendor') or '').strip()
        lead_time = data.get('lead_time', None)
        currency = (data.get('currency') or 'USD').strip().upper()
        parts_with_prices = data.get('parts_with_prices', [])
        excluded_parts = data.get('excluded_parts', [])
        dont_update_part_costs = data.get('dont_update_part_costs', False)  # Flag to skip updating part costs
        template_vars = data.get('template_vars', None)  # Optional PO document template variables
        discount_percent = data.get('discount_percent', None)  # Discount percentage if applied
        original_total_cost = data.get('original_total_cost', None)  # Original total before discount

        if not po_number or not vendor:
            return jsonify({'success': False, 'error': 'PO number and vendor are required'}), 400

        # Reject duplicate PO numbers up front — failing later (at flush) would
        # leave orphaned Drive artifacts from the file-generation steps
        if PO.query.filter_by(po_number=po_number).first():
            return jsonify({'success': False, 'error': f'PO number {po_number} already exists'}), 400

        # Get exchange rate if currency is not USD
        exchange_rate = None
        if currency != 'USD':
            # Ensure currency is uppercase
            currency_upper = currency.upper()
            exchange_rate = get_cached_or_fetch_rate(currency_upper, 'USD')
            if exchange_rate is None:
                # Try to get more details about why it failed
                logger = get_logger()
                logger.error(f'Failed to get exchange rate for {currency_upper}')
                # Check if we have a cached rate (even if stale)
                cached = CurrencyExchangeRate.query.filter_by(
                    base_currency='USD',
                    target_currency=currency_upper
                ).first()
                if cached:
                    logger.warning(f'Using stale cached rate for {currency_upper}: {cached.rate}')
                    exchange_rate = cached.rate
                else:
                    return jsonify({
                        'success': False, 
                        'error': f'Could not get exchange rate for {currency}. Please try again or contact admin to update rates manually.'
                    }), 400
        
        if not parts_with_prices:
            return jsonify({'success': False, 'error': 'No parts selected for PO'}), 400
        
        # Validate all parts have prices
        missing_prices = [p for p in parts_with_prices if not p.get('unit_cost') or p.get('unit_cost') <= 0]
        if missing_prices:
            return jsonify({'success': False, 'error': f'Parts missing prices: {[p["part_number"] for p in missing_prices]}'}), 400
        
        # Prepare costs: keep original currency for PO.total_cost, convert to USD for POItem.unit_cost (for BOM calculations)
        for part_data in parts_with_prices:
            original_unit_cost = part_data.get('unit_cost', 0)
            quantity = part_data.get('quantity', 1)
            # Store original cost in original currency
            part_data['original_unit_cost'] = original_unit_cost
            part_data['original_currency'] = currency
            # Calculate total cost in original currency (for PO.total_cost)
            if 'total_cost' not in part_data or not part_data.get('total_cost'):
                part_data['total_cost'] = original_unit_cost * quantity
            
            # Calculate USD equivalent for POItem.unit_cost (for BOM cost calculations)
            if currency != 'USD' and exchange_rate:
                part_data['unit_cost_usd'] = original_unit_cost / exchange_rate
            else:
                part_data['unit_cost_usd'] = original_unit_cost
        
        # Use temp directory for file staging — files go directly to Google Drive
        import tempfile
        _po_temp_dir = tempfile.mkdtemp(prefix=f"po_{po_number}_")
        po_local_dir = _po_temp_dir

        # Create PDF & XT subfolder
        pdf_xt_dir = os.path.join(po_local_dir, "PDF & XT")
        os.makedirs(pdf_xt_dir, exist_ok=True)
        
        # Initialize mechanical RFQ processor for file collection
        processor = MechanicalRFQProcessor()
        
        # Check which revisions are actually being requested and if files exist
        # If a revision is requested but file doesn't exist, call get_latest
        parts_needing_get_latest = []
        print(f"DEBUG: Checking {len(parts_with_prices)} parts for file availability...")
        
        # First, ensure parts_with_prices has the latest revisions from database
        for part_data in parts_with_prices:
            if part_data.get('is_additional_cost'):
                continue  # Skip additional cost entries (mold/tooling/setup)
            part_number = part_data['part_number']
            part_revision = part_data['revision']

            # Get latest revision from database
            db_part = Part.query.filter_by(part_number=part_number).order_by(Part.revision.desc()).first()
            if db_part:
                db_revision = db_part.revision  # e.g., "REV02"
                # Normalize for comparison
                db_rev_clean = db_revision.replace('REV', '').replace('rev', '').strip().upper()
                part_rev_clean = part_revision.replace('REV', '').replace('rev', '').strip().upper()
                
                # If database has a newer revision, update part_data
                if db_rev_clean != part_rev_clean:
                    try:
                        db_rev_num = int(db_rev_clean.lstrip('0') or '0')
                        part_rev_num = int(part_rev_clean.lstrip('0') or '0')
                        if db_rev_num > part_rev_num:
                            # Update to latest revision
                            part_data['revision'] = db_revision
                            part_data['revision_updated'] = True
                            part_data['old_revision'] = part_revision
                            part_revision = db_revision
                            print(f"Updated {part_number} revision: {part_data.get('old_revision')} → {db_revision}")
                    except ValueError:
                        pass
        
        # Always call PDM get_latest to ensure we have the most recent files from PDM
        # This ensures files are refreshed even if they exist locally, preventing stale files
        # when running the same PO process multiple times in the same day
        # Only fetch files for mechanical/designed parts — purchased/OTS parts don't have PDM files
        MECHANICAL_FILE_CHECK_TYPES = {'Mechanical part', 'Assembly', '3D Printing part'}
        parts_for_get_latest = []
        for part_data in parts_with_prices:
            if part_data.get('is_additional_cost'):
                continue  # Skip additional cost entries (mold/tooling/setup)
            part_number = part_data['part_number']
            part_revision = part_data['revision']

            # Skip PDM file fetch for non-mechanical parts
            db_part_check = Part.query.filter_by(part_number=part_number).first()
            if db_part_check and db_part_check.part_type not in MECHANICAL_FILE_CHECK_TYPES:
                continue

            # Format revision for get_latest (normalize to "02" format)
            rev_clean = part_revision.replace('REV', '').replace('rev', '').strip().upper()
            rev_num = rev_clean.lstrip('0') or '0'
            rev_formatted = f"{int(rev_num):02d}" if rev_num.isdigit() else rev_clean

            extensions = ['.x_t', '.pdf']
            # For 3D printing parts, also get STEP files
            db_part_for_type = Part.query.filter_by(part_number=part_number).first()
            if db_part_for_type and db_part_for_type.part_type and '3d' in db_part_for_type.part_type.lower():
                extensions.append('.step')

            parts_for_get_latest.append({
                'part_number': part_number,
                'revision': rev_formatted,
                'extensions': extensions
            })

            # For assemblies, also request AI (Assembly Instruction) files
            if '-AS-' in part_number.upper():
                parts_for_get_latest.append({
                    'part_number': f"{part_number}-AI",
                    'revision': rev_formatted,
                    'extensions': ['.pdf']
                })
        
        # Always call get_latest to refresh files from PDM
        if parts_for_get_latest:
            print(f"🔧 Calling PDM get latest for {len(parts_for_get_latest)} parts to ensure fresh files...")
            print(f"DEBUG: Parts for get_latest: {parts_for_get_latest}")
            get_latest_result = processor._call_pdm_get_latest(parts_for_get_latest)
            if get_latest_result.get('success'):
                print(f"✅ Successfully retrieved latest files for {get_latest_result.get('retrieved_count', 0)} parts")
                # Wait for files to be available
                import time
                time.sleep(3)
            else:
                error_msg = get_latest_result.get('error', 'Unknown error')
                print(f"⚠️ Warning: PDM get latest had issues: {error_msg}")
                print(f"DEBUG: get_latest_result = {get_latest_result}")

            # Update file availability flags in DB after get-latest
            try:
                from pdm_bom_parser import PdmBomParser
                scan_parts = []
                for pd in parts_with_prices:
                    if pd.get('is_additional_cost'):
                        continue  # Skip additional cost entries
                    db_part = Part.query.filter_by(part_number=pd['part_number'], revision=pd['revision']).first()
                    pt = db_part.part_type if db_part else ''
                    scan_parts.append((pd['part_number'], pd['revision'], pt))
                availability = PdmBomParser.check_file_availability(scan_parts)
                for (pn, rev), flags in availability.items():
                    part = Part.query.filter_by(part_number=pn, revision=rev).first()
                    if part:
                        part.has_pdf = flags.get('has_pdf', False)
                        part.has_ai_pdf = flags.get('has_ai_pdf', False)
                        part.has_step = flags.get('has_step', False)
                        part.step_files = json.dumps(flags.get('step_files', [])) if flags.get('step_files') else None
                        part.has_xt = flags.get('has_xt', False)
                db.session.commit()
                print(f"Updated file availability flags for {len(availability)} parts after PO get-latest")
            except Exception as scan_err:
                print(f"Warning: File availability scan after PO get-latest failed: {scan_err}")
        
        # Collect files for mechanical parts only (purchased/OTS parts don't have PDM files)
        mechanical_parts_for_files = []
        for p in parts_with_prices:
            if p.get('is_additional_cost'):
                continue
            dbp = Part.query.filter_by(part_number=p['part_number']).first()
            if dbp and dbp.part_type in MECHANICAL_FILE_CHECK_TYPES:
                mechanical_parts_for_files.append(p)
        file_collection_result = processor.collect_files_for_parts(mechanical_parts_for_files)
        
        if not file_collection_result.get('success', False):
            return jsonify({'success': False, 'error': f'File collection failed: {file_collection_result.get("error", "Unknown error")}'}), 500
        
        # Enrich parts data with description, material, finish from database
        # Note: parts_with_prices already contains latest revisions from validate_prices endpoint
        enriched_parts = []
        for part_data in parts_with_prices:
            # Skip DB enrichment for additional cost entries (mold/tooling/setup)
            if part_data.get('is_additional_cost'):
                enriched_part = part_data.copy()
                # Use cost_type as description (e.g., "Mold", "Tooling", "Setup")
                enriched_part['description'] = part_data.get('description') or part_data.get('cost_type', 'Additional Cost')
                enriched_parts.append(enriched_part)
                continue

            # Get part record from database using the revision from part_data (which is already the latest)
            part_record = Part.query.filter_by(
                part_number=part_data['part_number'],
                revision=part_data['revision']  # This is already the latest revision from validate_prices
            ).first()

            # If part not found with this revision, try to get latest revision as fallback
            if not part_record:
                latest_part = Part.query.filter_by(
                    part_number=part_data['part_number']
                ).order_by(Part.revision.desc()).first()
                if latest_part:
                    part_record = latest_part
                    # Update part_data to use the latest revision found
                    part_data['revision'] = latest_part.revision
                    print(f"Updated revision for {part_data['part_number']} to {latest_part.revision}")

            # Create enriched part data
            enriched_part = part_data.copy()
            enriched_part['description'] = part_record.description if part_record else ''
            enriched_part['material'] = part_record.material if part_record else ''
            enriched_part['finish1'] = part_record.finish1 if part_record else ''
            enriched_part['finish2'] = part_record.finish2 if part_record else ''
            enriched_parts.append(enriched_part)
        
        # Create PO Excel file with date
        date_str = datetime.now().strftime('%Y-%m-%d')
        po_excel_path = os.path.join(po_local_dir, f"{po_number} - {date_str}.xlsx")
        _create_po_excel(enriched_parts, po_excel_path, po_number, vendor, discount_percent, original_total_cost)
        
        # Copy PDF and XT files to local folder (already filtered by revision)
        # Note: shutil.copy2 will overwrite existing files, ensuring we always have the latest
        # This prevents stale files when running the same PO process multiple times in the same day
        collected_files = file_collection_result.get('collected_files', [])
        local_files = []
        
        for file_path in collected_files:
            dest_path = os.path.join(pdf_xt_dir, os.path.basename(file_path))
            try:
                import shutil
                shutil.copy2(file_path, dest_path)
                local_files.append(dest_path)
                print(f"Copied {os.path.basename(file_path)} to local folder (overwritten if existed)")
            except Exception as e:
                print(f"Error copying {file_path}: {e}")
        
        # Create ZIP file with collected files and date
        po_zip_path = os.path.join(po_local_dir, f"{po_number} - {date_str}.zip")
        with zipfile.ZipFile(po_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            # Add collected PDF and XT files
            for file_path in local_files:
                if os.path.exists(file_path):
                    zipf.write(file_path, os.path.basename(file_path))
        
        # Upload to Google Drive
        files_to_upload = [po_excel_path, po_zip_path]
        
        upload_result = upload_output_files(files_to_upload, f"PO {po_number}", 'po')

        # Clean up temp directory after upload
        try:
            import shutil as _shutil
            _shutil.rmtree(_po_temp_dir, ignore_errors=True)
            print(f"Cleaned up temp PO directory: {_po_temp_dir}")
        except Exception as cleanup_err:
            print(f"Warning: Failed to clean up temp directory: {cleanup_err}")

        if not upload_result or not upload_result.get('links'):
            return jsonify({'success': False, 'error': 'Failed to upload files to Google Drive'}), 500

        # Get latest BOM revision for this assembly
        # RFQ has bom_id which references BOMInstance
        latest_bom_revision = rfq.bom_revision  # Default fallback
        
        if rfq.bom_id:
            # Get the BOMInstance to find assembly_part_number
            bom_instance = BOMInstance.query.get(rfq.bom_id)
            if bom_instance:
                # Find all BOMs with the same assembly_part_number
                # Order by assembly_revision descending to get the latest
                latest_bom = BOMInstance.query.filter_by(
                    assembly_part_number=bom_instance.assembly_part_number
                ).order_by(BOMInstance.assembly_revision.desc()).first()
                
                if latest_bom:
                    latest_bom_revision = latest_bom.assembly_revision
                    # Clean up revision format - remove "REV00-", "REV0-", "REV-" prefixes if present
                    # Handle cases like "REV00-v4" -> "v4" or "REV00-04" -> "04"
                    import re
                    # Remove REV00-, REV0-, REV- prefixes (case insensitive)
                    latest_bom_revision = re.sub(r'^REV0{0,2}-?', '', latest_bom_revision, flags=re.IGNORECASE)
                    # Also handle "REV-" at the start
                    latest_bom_revision = re.sub(r'^REV-', '', latest_bom_revision, flags=re.IGNORECASE)
                    print(f"Updated PO BOM revision from {rfq.bom_revision} to {latest_bom_revision} (latest)")
        
        # Calculate total PO cost in ORIGINAL currency (not converted to USD)
        # parts_with_prices already has costs in the original currency from frontend
        # Use manual_total_cost if provided (for discounts/overrides), otherwise calculate from parts
        manual_total_cost = data.get('manual_total_cost')
        if manual_total_cost is not None:
            total_po_cost = float(manual_total_cost)
        else:
            total_po_cost = sum(part_data.get('total_cost', 0) for part_data in parts_with_prices)
        
        # Create PO record in database
        po = PO(
            rfq_id=rfq_id,
            bom_id=rfq.bom_id,
            bom_name=rfq.bom_name,
            bom_revision=latest_bom_revision,  # Use latest instead of rfq.bom_revision
            po_number=po_number,
            vendor=vendor,
            total_cost=total_po_cost,  # In original currency
            lead_time=int(lead_time) if lead_time is not None and lead_time != '' else None,
            currency=currency,
            exchange_rate=exchange_rate,
            google_drive_folder_id=upload_result.get('folder_id'),
            google_drive_folder_url=upload_result.get('folder_url'),
            created_by=current_user.id
        )
        db.session.add(po)
        db.session.flush()  # Get PO ID
        
        # Create PO items
        for part_data in parts_with_prices:
            if part_data.get('is_additional_cost'):
                # Create POItem for additional costs (mold/tooling) — no linked Part record
                po_item = POItem(
                    po_id=po.id,
                    part_id=None,
                    part_number=part_data['part_number'],
                    revision='',
                    quantity=part_data.get('quantity', 1),
                    unit_cost=part_data.get('unit_cost_usd', part_data.get('unit_cost', 0)),
                    total_cost=part_data.get('unit_cost_usd', part_data.get('unit_cost', 0)) * part_data.get('quantity', 1),
                    currency=currency,
                    original_unit_cost=part_data.get('original_unit_cost', part_data.get('unit_cost', 0)),
                    original_currency=part_data.get('original_currency', currency),
                    material=part_data.get('cost_type', 'Mold'),
                    finish1='',
                    finish2=''
                )
                db.session.add(po_item)
                continue

            # Look up Part record to link po_item.part_id
            linked_part = Part.query.filter_by(
                part_number=part_data['part_number'],
                revision=part_data['revision']
            ).first()
            po_item = POItem(
                po_id=po.id,
                part_id=linked_part.id if linked_part else None,
                part_number=part_data['part_number'],
                revision=part_data['revision'],
                quantity=part_data['quantity'],
                unit_cost=part_data['unit_cost_usd'],  # Store in USD for BOM calculations
                total_cost=part_data['unit_cost_usd'] * part_data['quantity'],  # Total in USD for POItem
                currency=currency,
                original_unit_cost=part_data.get('original_unit_cost'),
                original_currency=part_data.get('original_currency', currency),
                material=part_data.get('material', ''),
                finish1=part_data.get('finish1', ''),
                finish2=part_data.get('finish2', '')
            )
            db.session.add(po_item)

        # Update Part records with pricing and vendor info
        # Note: parts_with_prices already contains latest revisions from validate_prices endpoint
        affected_part_ids = []
        for part_data in parts_with_prices:
            if part_data.get('is_additional_cost'):
                continue  # Skip additional cost entries — no Part record to update
            # Use the revision from part_data (which is already the latest revision)
            part = Part.query.filter_by(
                part_number=part_data['part_number'],
                revision=part_data['revision']  # This is already the latest revision
            ).first()
            
            # If part not found with this revision, try to get latest revision as fallback
            if not part:
                latest_part = Part.query.filter_by(
                    part_number=part_data['part_number']
                ).order_by(Part.revision.desc()).first()
                if latest_part:
                    part = latest_part
                    # Update part_data to use the latest revision found
                    part_data['revision'] = latest_part.revision
                    print(f"Updated revision for {part_data['part_number']} to {latest_part.revision} in Part update")
            
            if part:
                # Only update part fields if neither the global flag nor the per-part flag is set
                keep_existing = part_data.get('keep_existing_price', False)
                if not dont_update_part_costs and not keep_existing:
                    part.unit_cost = part_data['unit_cost_usd']  # Store in USD
                    part.vendor = vendor
                    part.order_qty = part_data['quantity']
                    # Store original currency info if not USD
                    if currency != 'USD':
                        part.source_currency = currency
                        part.source_unit_cost = part_data.get('original_unit_cost')
                    else:
                        part.source_currency = None
                        part.source_unit_cost = None
                else:
                    reason = 'dont_update_part_costs flag' if dont_update_part_costs else 'keep_existing_price flag'
                    print(f"DEBUG: Skipping part field updates for {part_data['part_number']} ({reason})")
                
                # Always update po_orders for tracking, regardless of flag
                try:
                    existing_po_orders = (part.po_orders or '').strip()
                    if existing_po_orders:
                        po_numbers = [p.strip() for p in existing_po_orders.split(',') if p.strip()]
                    else:
                        po_numbers = []
                    # Add current PO number if not already present
                    if po_number not in po_numbers:
                        po_numbers.append(po_number)
                    part.po_orders = ', '.join(po_numbers)
                except Exception as e:
                    print(f"ERROR: Failed to update po_orders for {part_data['part_number']}: {e}")
                    # Fallback: just set the PO number
                    part.po_orders = po_number
                affected_part_ids.append(part.id)
                
                # Recalculate price_per_bom for all BOMParts using this part
                bom_parts = BOMPart.query.filter_by(part_id=part.id).all()
                for bom_part in bom_parts:
                    if part.unit_cost and bom_part.quantity:
                        bom_part.price_per_bom = float(part.unit_cost) * float(bom_part.quantity)
                        bom_part.updated_at = datetime.utcnow()
        
        # Update BOMItem records (using latest revision)
        for part_data in parts_with_prices:
            bom_items = BOMItem.query.filter_by(
                part_number=part_data['part_number'],
                revision=part_data['revision']  # This is already the latest revision
            ).all()
            
            for bom_item in bom_items:
                # Respect the same skip flags as the Part update, and store USD
                # (part_data['unit_cost'] is in the PO's original currency)
                if not dont_update_part_costs and not part_data.get('keep_existing_price', False):
                    bom_item.unit_cost = part_data['unit_cost_usd']
                    bom_item.vendor = vendor
                    bom_item.order_qty = part_data['quantity']
                # Update po_orders with comma-separated values (append, don't overwrite)
                try:
                    existing_po_orders = (bom_item.po_orders or '').strip()
                    if existing_po_orders:
                        po_numbers = [p.strip() for p in existing_po_orders.split(',') if p.strip()]
                    else:
                        po_numbers = []
                    # Add current PO number if not already present
                    if po_number not in po_numbers:
                        po_numbers.append(po_number)
                    bom_item.po_orders = ', '.join(po_numbers)
                except Exception as e:
                    print(f"ERROR: Failed to update po_orders for BOMItem {part_data['part_number']}: {e}")
                    # Fallback: just set the PO number
                    bom_item.po_orders = po_number
        
        # Update RFQ status and add excluded parts note
        rfq.status = 'converted_to_po'
        print(f"DEBUG: Excluded parts count: {len(excluded_parts)}")
        print(f"DEBUG: Excluded parts: {excluded_parts}")
        if excluded_parts:
            excluded_part_numbers = [p['part_number'] for p in excluded_parts]
            rfq.excluded_parts_note = f"Excluded parts in PO {po_number}: {', '.join(excluded_part_numbers)}"
            print(f"DEBUG: Set excluded_parts_note: {rfq.excluded_parts_note}")
        else:
            print("DEBUG: No excluded parts, not setting note")

        # Persist the PO-document template vars so edits can regenerate the doc
        # without asking the user to re-fill them
        if template_vars:
            try:
                po.po_doc_vars = json.dumps(template_vars)
            except Exception as tv_err:
                print(f"Warning: could not store po_doc_vars: {tv_err}")

        db.session.commit()
        
        # Cascade price updates to assemblies
        if affected_part_ids:
            cascade_price_updates(affected_part_ids)

        
        # Log the action
        log_action('PO_CREATE', current_user,
                   f'PO ID: {po.id}, PO Number: {po_number}, Vendor: {vendor}, RFQ ID: {rfq_id}, BOM: "{rfq.bom_name}", Parts: {len(parts_with_prices)}, Total Cost: ${total_po_cost:.2f}')

        # Generate PO Google Doc from template (if template_vars provided)
        po_doc_url = None
        if template_vars:
            try:
                from google_sheets.google_drive_upload import fill_po_template
                from datetime import datetime as dt_now

                po_data = {
                    'po_number': po_number,
                    'vendor': vendor,
                    'currency': currency,
                    'total_cost': total_po_cost,
                    'po_date': dt_now.now().strftime('%Y-%m-%d'),
                    'discount_percent': discount_percent,
                    'original_total_cost': original_total_cost
                }
                template_parts = [{
                    'part_number': p.get('part_number', ''),
                    'revision': p.get('revision', '') or '',
                    'description': p.get('description', '') or '',
                    'quantity': p.get('quantity', 1),
                    'unit_cost': p.get('unit_cost', 0),
                    'total_cost': p.get('total_cost', 0)
                } for p in enriched_parts]

                target_folder = '1TekcCTE10yai1labe9foBcDE7KFH-7Fn'
                doc_result = fill_po_template(po_data, template_parts, template_vars, target_folder)
                if doc_result:
                    po_doc_url = doc_result.get('doc_url')
                    print(f"PO document generated: {po_doc_url}")
                else:
                    print("Warning: PO document generation returned None")
            except Exception as doc_err:
                print(f"Warning: PO document generation failed: {doc_err}")
                import traceback
                traceback.print_exc()

        return jsonify({
            'success': True,
            'message': 'PO created successfully',
            'po_id': po.id,
            'po_number': po_number,
            'total_cost': total_po_cost,
            'google_drive': {
                'folder_url': upload_result.get('folder_url'),
                'excel_url': list(upload_result.get('links', {}).values())[0] if upload_result.get('links') else '',
                'zip_url': list(upload_result.get('links', {}).values())[1] if len(upload_result.get('links', {})) > 1 else ''
            },
            'po_doc_url': po_doc_url,
            'summary': {
                'parts_count': len(parts_with_prices),
                'excluded_count': len(excluded_parts),
                'total_cost': total_po_cost
            }
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"Error in create_po_final: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

def _create_po_excel(parts_data, excel_path, po_number, vendor, discount_percent=None, original_total_cost=None):
    """Create PO Excel file with proper formatting"""
    try:
        wb = Workbook()
        ws = wb.active
        ws.title = "Purchase Order"

        # Headers
        headers = [
            'ITEM NO.', 'PART NUMBER', 'Revision', 'Description', 'Material',
            'FINISH1', 'FINISH2', 'QTY.', 'Unit Cost', 'Total Cost'
        ]

        # Write headers
        for col, header in enumerate(headers, 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.font = Font(bold=True)
            cell.fill = PatternFill(start_color="CCCCCC", end_color="CCCCCC", fill_type="solid")
            cell.alignment = Alignment(horizontal='center', vertical='center')

        # Write data
        for row, part in enumerate(parts_data, 2):
            ws.cell(row=row, column=1, value=row - 1)  # ITEM NO.
            ws.cell(row=row, column=2, value=part['part_number'])
            ws.cell(row=row, column=3, value=part['revision'])
            ws.cell(row=row, column=4, value=part.get('description', ''))
            ws.cell(row=row, column=5, value=part.get('material', ''))
            ws.cell(row=row, column=6, value=part.get('finish1', ''))
            ws.cell(row=row, column=7, value=part.get('finish2', ''))
            ws.cell(row=row, column=8, value=part['quantity'])

            # Unit Cost with $ formatting
            unit_cost_cell = ws.cell(row=row, column=9, value=part['unit_cost'])
            unit_cost_cell.number_format = '$#,##0.00'

            # Total Cost with $ formatting
            total_cost_cell = ws.cell(row=row, column=10, value=part['total_cost'])
            total_cost_cell.number_format = '$#,##0.00'

        # Add summary rows at the bottom
        summary_start_row = len(parts_data) + 2  # After header + data rows

        if discount_percent and original_total_cost:
            # Total Cost (before discount)
            label_cell = ws.cell(row=summary_start_row, column=9, value='Total Cost:')
            label_cell.font = Font(bold=True)
            label_cell.alignment = Alignment(horizontal='right')
            orig_total_cell = ws.cell(row=summary_start_row, column=10, value=original_total_cost)
            orig_total_cell.number_format = '$#,##0.00'
            orig_total_cell.font = Font(bold=True)

            # Discount row
            discount_label = ws.cell(row=summary_start_row + 1, column=9, value='Discount:')
            discount_label.font = Font(bold=True, color="FF0000")
            discount_label.alignment = Alignment(horizontal='right')
            discount_val = ws.cell(row=summary_start_row + 1, column=10, value=f'-{discount_percent}%')
            discount_val.font = Font(bold=True, color="FF0000")

            # Total after discount
            discounted_total = sum(p.get('total_cost', 0) for p in parts_data)
            after_label = ws.cell(row=summary_start_row + 2, column=9, value='Total After Discount:')
            after_label.font = Font(bold=True)
            after_label.alignment = Alignment(horizontal='right')
            after_total_cell = ws.cell(row=summary_start_row + 2, column=10, value=discounted_total)
            after_total_cell.number_format = '$#,##0.00'
            after_total_cell.font = Font(bold=True, size=12)
        else:
            # Simple total row (no discount)
            total_label = ws.cell(row=summary_start_row, column=9, value='Total:')
            total_label.font = Font(bold=True)
            total_label.alignment = Alignment(horizontal='right')
            total_val = ws.cell(row=summary_start_row, column=10, value=sum(p.get('total_cost', 0) for p in parts_data))
            total_val.number_format = '$#,##0.00'
            total_val.font = Font(bold=True, size=12)

        # Auto-adjust column widths
        for column in ws.columns:
            max_length = 0
            column_letter = column[0].column_letter
            for cell in column:
                try:
                    if len(str(cell.value)) > max_length:
                        max_length = len(str(cell.value))
                except:
                    pass
            adjusted_width = min(max_length + 2, 50)
            ws.column_dimensions[column_letter].width = adjusted_width

        # Add PO info at the top
        ws.insert_rows(1, 3)
        ws.cell(row=1, column=1, value=f"Purchase Order: {po_number}")
        ws.cell(row=1, column=1).font = Font(bold=True, size=14)
        ws.cell(row=2, column=1, value=f"Date: {datetime.now().strftime('%Y-%m-%d')}")

        wb.save(excel_path)

    except Exception as e:
        print(f"Error creating PO Excel: {e}")
        raise

@app.route('/api/pos/<int:po_id>/edit', methods=['POST'])
@login_required
@rfq_create_required
def edit_po(po_id):
    """Edit a PO that has NOT yet been received. Updates header fields, replaces
    PO line items, and regenerates the Excel + ZIP in the existing Drive folder
    (old PO Excel/ZIP files are removed first so the folder reflects the new PO).
    """
    try:
        from google_sheets.google_drive_upload import get_drive_service, upload_file
        from mechanical_rfq_processor import MechanicalRFQProcessor
        import tempfile, zipfile, os, shutil

        po = PO.query.get_or_404(po_id)

        if po.status == 'received' or po.po_received:
            return jsonify({
                'success': False,
                'error': 'Cannot edit a PO that has already been received. Use "Undo Received" first if you need to make changes.'
            }), 400

        data = request.json or {}
        new_vendor = (data.get('vendor') or '').strip() or po.vendor
        new_lead_time = data.get('lead_time')
        new_currency = (data.get('currency') or po.currency or 'USD').strip().upper()
        parts_with_prices = data.get('parts_with_prices', [])
        # PO document regeneration: explicit template_vars win; otherwise fall
        # back to the vars stored at PO creation when regenerate_doc is set.
        template_vars = data.get('template_vars', None)
        regenerate_doc = bool(data.get('regenerate_doc'))
        if not template_vars and regenerate_doc and po.po_doc_vars:
            try:
                template_vars = json.loads(po.po_doc_vars)
                print(f"[edit_po] using stored po_doc_vars for {po.po_number}")
            except Exception as tv_err:
                print(f"[edit_po] could not parse stored po_doc_vars: {tv_err}")

        if not parts_with_prices:
            return jsonify({'success': False, 'error': 'PO must have at least one line item'}), 400

        missing_prices = [p for p in parts_with_prices if not p.get('unit_cost') or float(p.get('unit_cost') or 0) <= 0]
        if missing_prices:
            return jsonify({
                'success': False,
                'error': f'Parts missing prices: {[p["part_number"] for p in missing_prices]}'
            }), 400

        # Currency conversion setup
        exchange_rate = None
        if new_currency != 'USD':
            exchange_rate = get_cached_or_fetch_rate(new_currency, 'USD')
            if exchange_rate is None:
                cached = CurrencyExchangeRate.query.filter_by(
                    base_currency='USD', target_currency=new_currency
                ).first()
                if cached:
                    exchange_rate = cached.rate
                else:
                    return jsonify({
                        'success': False,
                        'error': f'Could not get exchange rate for {new_currency}.'
                    }), 400

        for part_data in parts_with_prices:
            original_unit_cost = float(part_data.get('unit_cost') or 0)
            quantity = int(part_data.get('quantity') or 1)
            part_data['original_unit_cost'] = original_unit_cost
            part_data['original_currency'] = new_currency
            part_data['quantity'] = quantity
            part_data['total_cost'] = original_unit_cost * quantity
            if new_currency != 'USD' and exchange_rate:
                part_data['unit_cost_usd'] = original_unit_cost / exchange_rate
            else:
                part_data['unit_cost_usd'] = original_unit_cost

        total_po_cost = sum(p.get('total_cost', 0) for p in parts_with_prices)

        # Stage files locally
        _po_edit_tmp = tempfile.mkdtemp(prefix=f"po_edit_{po.po_number}_")
        pdf_xt_dir = os.path.join(_po_edit_tmp, "PDF & XT")
        os.makedirs(pdf_xt_dir, exist_ok=True)

        processor = MechanicalRFQProcessor()

        # Resolve revisions + enrich with DB metadata FIRST, so that file
        # collection below uses the exact revisions the PO items will carry
        # (previously files were fetched with the dialog's revisions and the
        # PO was bumped to latest afterwards, leaving stale PDFs/XTs).
        enriched_parts = []
        for pd_ in parts_with_prices:
            rec = None
            if (pd_.get('revision') or '').strip():
                rec = Part.query.filter_by(part_number=pd_['part_number'], revision=pd_['revision']).first()
                if not rec:
                    latest = Part.query.filter_by(part_number=pd_['part_number']).order_by(Part.revision.desc()).first()
                    if latest:
                        rec = latest
                        pd_['revision'] = latest.revision
            ep = pd_.copy()
            ep['description'] = (rec.description if rec else pd_.get('description', '')) or ''
            ep['material']    = (rec.material if rec else pd_.get('material', '')) or ''
            ep['finish1']     = (rec.finish1 if rec else pd_.get('finish1', '')) or ''
            ep['finish2']     = (rec.finish2 if rec else pd_.get('finish2', '')) or ''
            enriched_parts.append(ep)

        # PDM get_latest for mechanical parts (using the resolved revisions)
        MECHANICAL_TYPES = {'Mechanical part', 'Assembly', '3D Printing part'}
        get_latest_list = []
        for pd_ in parts_with_prices:
            if pd_.get('is_additional_cost') or not (pd_.get('revision') or '').strip():
                continue
            dbp = Part.query.filter_by(part_number=pd_['part_number']).first()
            if not dbp or dbp.part_type not in MECHANICAL_TYPES:
                continue
            rev_clean = pd_['revision'].replace('REV', '').replace('rev', '').strip().upper()
            try:
                rev_fmt = f"{int(rev_clean):02d}"
            except ValueError:
                rev_fmt = rev_clean
            exts = ['.x_t', '.pdf']
            if dbp.part_type and '3d' in dbp.part_type.lower():
                exts.append('.step')
            get_latest_list.append({'part_number': pd_['part_number'], 'revision': rev_fmt, 'extensions': exts})
            if '-AS-' in pd_['part_number'].upper():
                get_latest_list.append({'part_number': f"{pd_['part_number']}-AI", 'revision': rev_fmt, 'extensions': ['.pdf']})

        if get_latest_list:
            try:
                gl_result = processor._call_pdm_get_latest(get_latest_list)
                if not gl_result.get('success'):
                    print(f"[edit_po] PDM get_latest warning: {gl_result.get('error')}")
                import time
                time.sleep(3)
            except Exception as gl_err:
                print(f"[edit_po] PDM get_latest warning: {gl_err}")

        # Collect PDF/XT for mechanical parts (resolved revisions)
        mechanical_parts = []
        for p in parts_with_prices:
            if p.get('is_additional_cost') or not (p.get('revision') or '').strip():
                continue
            dbp = Part.query.filter_by(part_number=p['part_number']).first()
            if dbp and dbp.part_type in MECHANICAL_TYPES:
                mechanical_parts.append(p)
        file_collection_result = processor.collect_files_for_parts(mechanical_parts) if mechanical_parts else {'success': True, 'collected_files': []}
        for mf in (file_collection_result.get('missing_files') or []):
            print(f"[edit_po] WARNING: no PDF/XT found for {mf}")

        # Build Excel
        date_str = datetime.now().strftime('%Y-%m-%d')
        excel_path = os.path.join(_po_edit_tmp, f"{po.po_number} - {date_str}.xlsx")
        _create_po_excel(enriched_parts, excel_path, po.po_number, new_vendor)

        # Copy PDF/XT into staging
        for fp in (file_collection_result.get('collected_files') or []):
            try:
                shutil.copy2(fp, os.path.join(pdf_xt_dir, os.path.basename(fp)))
            except Exception as cp_err:
                print(f"[edit_po] copy warn: {cp_err}")

        # Build ZIP
        zip_path = os.path.join(_po_edit_tmp, f"{po.po_number} - {date_str}.zip")
        with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            for fname in os.listdir(pdf_xt_dir):
                fp = os.path.join(pdf_xt_dir, fname)
                if os.path.isfile(fp):
                    zf.write(fp, fname)

        def _drive_remove(svc, file_id, fname):
            """Best-effort removal: hard delete -> trash -> rename to 'OLD - <name>'.
            The service account often isn't the file owner, in which case
            files().delete() returns 404 even though list() can see the file."""
            try:
                svc.files().delete(fileId=file_id, supportsAllDrives=True).execute()
                print(f"[edit_po] deleted old Drive file: {fname}")
                return True
            except Exception as del_err:
                print(f"[edit_po] delete failed for {fname}: {del_err}")
            try:
                svc.files().update(fileId=file_id, body={'trashed': True},
                                   supportsAllDrives=True).execute()
                print(f"[edit_po] trashed old Drive file: {fname}")
                return True
            except Exception as trash_err:
                print(f"[edit_po] trash failed for {fname}: {trash_err}")
            try:
                svc.files().update(fileId=file_id, body={'name': f'OLD - {fname}'},
                                   supportsAllDrives=True).execute()
                print(f"[edit_po] renamed old Drive file to: OLD - {fname}")
                return True
            except Exception as ren_err:
                print(f"[edit_po] rename failed for {fname}: {ren_err}")
            return False

        # Replace files in the Drive folder
        uploaded_links = {}
        if po.google_drive_folder_id:
            drive_service = get_drive_service()
            if drive_service:
                try:
                    list_q = (
                        f"'{po.google_drive_folder_id}' in parents and trashed=false "
                        f"and (name contains '{po.po_number}')"
                    )
                    existing = drive_service.files().list(
                        q=list_q, spaces='drive', fields='files(id,name)',
                        supportsAllDrives=True, includeItemsFromAllDrives=True
                    ).execute().get('files', [])
                    for f in existing:
                        fname = f.get('name', '')
                        if fname.lower().endswith('.xlsx') or fname.lower().endswith('.zip'):
                            _drive_remove(drive_service, f['id'], fname)
                except Exception as list_err:
                    print(f"[edit_po] folder list failed: {list_err}")

                for fp in [excel_path, zip_path]:
                    if os.path.exists(fp):
                        link = upload_file(drive_service, fp, po.google_drive_folder_id)
                        if link:
                            uploaded_links[os.path.basename(fp)] = link
        else:
            # PO has no Drive folder linked (e.g. standalone POs created before
            # the file pipeline existed) — find/create one and link it
            try:
                from google_sheets.google_drive_upload import upload_output_files
                up_res = upload_output_files([excel_path, zip_path], f"PO {po.po_number}", 'po')
                if up_res:
                    po.google_drive_folder_id = up_res.get('folder_id')
                    po.google_drive_folder_url = up_res.get('folder_url')
                    uploaded_links = up_res.get('links', {}) or {}
                    print(f"[edit_po] created/linked Drive folder for {po.po_number}")
            except Exception as up_err:
                print(f"[edit_po] folder create/upload failed: {up_err}")

        # Update PO + replace items
        po.vendor = new_vendor
        po.currency = new_currency
        po.exchange_rate = exchange_rate
        po.total_cost = total_po_cost
        if new_lead_time not in (None, ''):
            try:
                po.lead_time = int(new_lead_time)
            except (TypeError, ValueError):
                pass

        # Snapshot old vs new real-part sets (additional-cost lines have no revision)
        old_part_numbers = {poi.part_number for poi in po.po_items if (poi.revision or '').strip()}
        new_part_numbers = {
            p['part_number'] for p in parts_with_prices
            if not p.get('is_additional_cost') and (p.get('revision') or '').strip()
        }
        removed_part_numbers = old_part_numbers - new_part_numbers
        added_part_numbers = new_part_numbers - old_part_numbers

        POItem.query.filter_by(po_id=po.id).delete()
        db.session.flush()

        for pd_ in parts_with_prices:
            if pd_.get('is_additional_cost'):
                item = POItem(
                    po_id=po.id, part_id=None,
                    part_number=pd_['part_number'], revision='',
                    quantity=pd_.get('quantity', 1),
                    unit_cost=pd_.get('unit_cost_usd', pd_.get('unit_cost', 0)),
                    total_cost=pd_.get('unit_cost_usd', pd_.get('unit_cost', 0)) * pd_.get('quantity', 1),
                    currency=new_currency,
                    original_unit_cost=pd_.get('original_unit_cost', pd_.get('unit_cost', 0)),
                    original_currency=new_currency,
                    material=pd_.get('cost_type', 'Mold'),
                )
                db.session.add(item)
                continue

            linked = Part.query.filter_by(part_number=pd_['part_number'], revision=pd_['revision']).first()
            item = POItem(
                po_id=po.id,
                part_id=linked.id if linked else None,
                part_number=pd_['part_number'],
                revision=pd_['revision'],
                quantity=pd_['quantity'],
                unit_cost=pd_['unit_cost_usd'],
                total_cost=pd_['unit_cost_usd'] * pd_['quantity'],
                currency=new_currency,
                original_unit_cost=pd_.get('original_unit_cost'),
                original_currency=new_currency,
                material=pd_.get('material', ''),
                finish1=pd_.get('finish1', ''),
                finish2=pd_.get('finish2', ''),
            )
            db.session.add(item)

        # Sync po_orders tracking on Part + BOMItem so every BOM shows the
        # correct PO after items were added to / removed from this PO.
        def _po_list(orders_str):
            return [p.strip() for p in (orders_str or '').split(',') if p.strip()]

        for pn in removed_part_numbers:
            for part_rec in Part.query.filter_by(part_number=pn).all():
                nums = [p for p in _po_list(part_rec.po_orders) if p != po.po_number]
                part_rec.po_orders = ', '.join(nums) if nums else None
            for bi in BOMItem.query.filter_by(part_number=pn).all():
                nums = [p for p in _po_list(bi.po_orders) if p != po.po_number]
                bi.po_orders = ', '.join(nums) if nums else None

        for pd_ in parts_with_prices:
            if pd_.get('is_additional_cost') or pd_['part_number'] not in added_part_numbers:
                continue
            part_rec = Part.query.filter_by(
                part_number=pd_['part_number'], revision=pd_['revision']
            ).first() or Part.query.filter_by(
                part_number=pd_['part_number']
            ).order_by(Part.revision.desc()).first()
            if part_rec:
                nums = _po_list(part_rec.po_orders)
                if po.po_number not in nums:
                    nums.append(po.po_number)
                part_rec.po_orders = ', '.join(nums)
            for bi in BOMItem.query.filter_by(part_number=pd_['part_number']).all():
                nums = _po_list(bi.po_orders)
                if po.po_number not in nums:
                    nums.append(po.po_number)
                bi.po_orders = ', '.join(nums)

        # Remember the (possibly updated) doc template vars for future edits
        if template_vars:
            try:
                po.po_doc_vars = json.dumps(template_vars)
            except Exception as tv_err:
                print(f"[edit_po] could not store po_doc_vars: {tv_err}")

        db.session.commit()

        try:
            shutil.rmtree(_po_edit_tmp, ignore_errors=True)
        except Exception:
            pass

        # Regenerate PO Google Doc from template (if template_vars provided).
        # The old doc (named after the PO number) is removed first so the
        # folder only ever holds the current version.
        po_doc_url = None
        if template_vars:
            try:
                from google_sheets.google_drive_upload import fill_po_template

                target_folder = '1TekcCTE10yai1labe9foBcDE7KFH-7Fn'
                edited_doc_name = f"{po.po_number}-edited"
                try:
                    doc_service = get_drive_service()
                    if doc_service:
                        # Remove the original doc AND any previous "-edited" copies
                        doc_q = (
                            f"'{target_folder}' in parents and trashed=false "
                            f"and (name='{po.po_number}' or name='{edited_doc_name}') "
                            f"and mimeType='application/vnd.google-apps.document'"
                        )
                        old_docs = doc_service.files().list(
                            q=doc_q, spaces='drive', fields='files(id,name)',
                            supportsAllDrives=True, includeItemsFromAllDrives=True
                        ).execute().get('files', [])
                        for f in old_docs:
                            _drive_remove(doc_service, f['id'], f.get('name', ''))
                except Exception as doc_del_err:
                    print(f"[edit_po] could not remove old PO doc: {doc_del_err}")

                po_data = {
                    'po_number': po.po_number,
                    'vendor': new_vendor,
                    'currency': new_currency,
                    'total_cost': total_po_cost,
                    'po_date': datetime.now().strftime('%Y-%m-%d'),
                }
                template_parts = [{
                    'part_number': p.get('part_number', ''),
                    'revision': p.get('revision', '') or '',
                    'description': p.get('description', '') or '',
                    'quantity': p.get('quantity', 1),
                    'unit_cost': p.get('unit_cost', 0),
                    'total_cost': p.get('total_cost', 0)
                } for p in enriched_parts]

                doc_result = fill_po_template(po_data, template_parts, template_vars, target_folder,
                                              doc_name=edited_doc_name)
                if doc_result:
                    po_doc_url = doc_result.get('doc_url')
                    print(f"[edit_po] PO document regenerated as '{edited_doc_name}': {po_doc_url}")
                else:
                    print("[edit_po] Warning: PO document regeneration returned None")
            except Exception as doc_err:
                print(f"[edit_po] Warning: PO document regeneration failed: {doc_err}")
                import traceback
                traceback.print_exc()

        log_action('PO_EDIT', current_user,
                   f'PO ID: {po.id}, PO Number: {po.po_number}, items={len(parts_with_prices)}, '
                   f'added={sorted(added_part_numbers)}, removed={sorted(removed_part_numbers)}, '
                   f'doc_regenerated={bool(po_doc_url)}')

        return jsonify({
            'success': True,
            'message': f'PO {po.po_number} updated',
            'po_id': po.id,
            'po_number': po.po_number,
            'total_cost': po.total_cost,
            'currency': po.currency,
            'drive_links': uploaded_links,
            'po_doc_url': po_doc_url,
        })

    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/pos/<int:po_id>/regenerate', methods=['POST'])
@login_required
@rfq_create_required
def regenerate_po(po_id):
    """Regenerate PO with latest revisions - supports two phases: detect and execute"""
    try:
        from google_sheets.google_drive_upload import upload_output_files
        from mechanical_rfq_processor import MechanicalRFQProcessor
        import tempfile
        import zipfile
        import pandas as pd
        import os
        import time
        
        po = PO.query.get_or_404(po_id)
        phase = request.args.get('phase', 'execute')  # 'detect' or 'execute'
        
        # Get PO items
        po_items = po.po_items
        if not po_items:
            return jsonify({'success': False, 'error': 'PO has no items'}), 400
        
        # Prepare parts data from PO items
        parts_data = []
        revision_updates = []

        for po_item in po_items:
            part_number = po_item.part_number
            current_revision = po_item.revision
            current_price = po_item.unit_cost

            # Get latest revision from database
            latest_part = Part.query.filter_by(
                part_number=part_number
            ).order_by(Part.revision.desc()).first()

            if not latest_part:
                # Part doesn't exist anymore, skip or use current data
                parts_data.append({
                    'part_number': part_number,
                    'revision': current_revision,
                    'quantity': po_item.quantity,
                    'unit_cost': current_price,
                    'unit_cost_usd': current_price,
                    'total_cost': current_price * po_item.quantity,
                    'material': po_item.material or '',
                    'finish1': po_item.finish1 or '',
                    'finish2': po_item.finish2 or ''
                })
                continue

            latest_revision = latest_part.revision

            # Normalize revisions for comparison
            current_rev_clean = current_revision.replace('REV', '').replace('rev', '').strip().upper()
            latest_rev_clean = latest_revision.replace('REV', '').replace('rev', '').strip().upper()

            revision_changed = False

            # Check if revision changed
            if current_rev_clean != latest_rev_clean:
                try:
                    current_rev_num = int(current_rev_clean.lstrip('0') or '0')
                    latest_rev_num = int(latest_rev_clean.lstrip('0') or '0')
                    if latest_rev_num > current_rev_num:
                        revision_changed = True
                except ValueError:
                    # If can't parse, consider it changed if strings differ
                    if current_revision != latest_revision:
                        revision_changed = True

            # Track revision updates only (prices kept from PO)
            if revision_changed:
                revision_updates.append({
                    'part_number': part_number,
                    'old_revision': current_revision,
                    'new_revision': latest_revision,
                    'revision_changed': True
                })

            # Prepare part data with latest revision but keep existing PO price
            parts_data.append({
                'part_number': part_number,
                'revision': latest_revision if revision_changed else current_revision,
                'quantity': po_item.quantity,
                'unit_cost': current_price,  # Keep existing PO price
                'unit_cost_usd': current_price,
                'total_cost': current_price * po_item.quantity,
                'material': po_item.material or '',
                'finish1': po_item.finish1 or '',
                'finish2': po_item.finish2 or ''
            })
        
        # Phase 1: Only detect and return changes
        if phase == 'detect':
            return jsonify({
                'success': True,
                'revision_updates': revision_updates,
                'price_updates': [],
                'summary': {
                    'total_parts': len(po_items),
                    'revision_changes': len(revision_updates),
                    'price_changes': 0
                }
            })
        
        # Phase 2: Execute regeneration
        if not po.google_drive_folder_id:
            return jsonify({'success': False, 'error': 'PO does not have a Google Drive folder'}), 400
        
        # Use temp directory — files go directly to Google Drive
        import tempfile
        _po_regen_temp_dir = tempfile.mkdtemp(prefix=f"po_regen_{po.po_number}_")
        po_local_dir = _po_regen_temp_dir

        # Create PDF & XT subfolder
        pdf_xt_dir = os.path.join(po_local_dir, "PDF & XT")
        os.makedirs(pdf_xt_dir, exist_ok=True)
        
        # Initialize mechanical RFQ processor
        processor = MechanicalRFQProcessor()
        
        # Format parts for get_latest
        parts_for_get_latest = []
        for part_data in parts_data:
            part_number = part_data['part_number']
            part_revision = part_data['revision']

            # Format revision for get_latest (normalize to "02" format)
            rev_clean = part_revision.replace('REV', '').replace('rev', '').strip().upper()
            rev_num = rev_clean.lstrip('0') or '0'
            rev_formatted = f"{int(rev_num):02d}" if rev_num.isdigit() else rev_clean

            extensions = ['.x_t', '.pdf']
            db_part_for_type = Part.query.filter_by(part_number=part_number).first()
            if db_part_for_type and db_part_for_type.part_type and '3d' in db_part_for_type.part_type.lower():
                extensions.append('.step')

            parts_for_get_latest.append({
                'part_number': part_number,
                'revision': rev_formatted,
                'extensions': extensions
            })

            # For assemblies, also request AI (Assembly Instruction) files
            if '-AS-' in part_number.upper():
                parts_for_get_latest.append({
                    'part_number': f"{part_number}-AI",
                    'revision': rev_formatted,
                    'extensions': ['.pdf']
                })
        
        # Call PDM get_latest to ensure fresh files
        if parts_for_get_latest:
            print(f"🔧 Calling PDM get latest for {len(parts_for_get_latest)} parts...")
            get_latest_result = processor._call_pdm_get_latest(parts_for_get_latest)
            if get_latest_result.get('success'):
                print(f"✅ Successfully retrieved latest files for {get_latest_result.get('retrieved_count', 0)} parts")
                time.sleep(3)  # Wait for files to be available
            else:
                error_msg = get_latest_result.get('error', 'Unknown error')
                print(f"⚠️ Warning: PDM get latest had issues: {error_msg}")
        
        # Collect files for parts
        file_collection_result = processor.collect_files_for_parts(parts_data)
        
        if not file_collection_result.get('success', False):
            return jsonify({'success': False, 'error': f'File collection failed: {file_collection_result.get("error", "Unknown error")}'}), 500
        
        # Enrich parts data with description from database
        enriched_parts = []
        for part_data in parts_data:
            part_record = Part.query.filter_by(
                part_number=part_data['part_number'],
                revision=part_data['revision']
            ).first()
            
            if not part_record:
                # Try to get latest revision as fallback
                latest_part = Part.query.filter_by(
                    part_number=part_data['part_number']
                ).order_by(Part.revision.desc()).first()
                if latest_part:
                    part_record = latest_part
                    part_data['revision'] = latest_part.revision
            
            enriched_part = part_data.copy()
            enriched_part['description'] = part_record.description if part_record else ''
            enriched_part['material'] = part_record.material if part_record else part_data.get('material', '')
            enriched_part['finish1'] = part_record.finish1 if part_record else part_data.get('finish1', '')
            enriched_part['finish2'] = part_record.finish2 if part_record else part_data.get('finish2', '')
            enriched_parts.append(enriched_part)
        
        # Create PO Excel file
        date_str = datetime.now().strftime('%Y-%m-%d')
        po_excel_path = os.path.join(po_local_dir, f"{po.po_number} - {date_str}.xlsx")
        _create_po_excel(enriched_parts, po_excel_path, po.po_number, po.vendor)
        
        # Copy PDF and XT files to local folder
        collected_files = file_collection_result.get('collected_files', [])
        local_files = []
        
        for file_path in collected_files:
            dest_path = os.path.join(pdf_xt_dir, os.path.basename(file_path))
            try:
                import shutil
                shutil.copy2(file_path, dest_path)
                local_files.append(dest_path)
                print(f"Copied {os.path.basename(file_path)} to local folder")
            except Exception as e:
                print(f"Error copying {file_path}: {e}")
        
        # Create ZIP file
        po_zip_path = os.path.join(po_local_dir, f"{po.po_number} - {date_str}.zip")
        with zipfile.ZipFile(po_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            # Add collected PDF and XT files
            for file_path in local_files:
                if os.path.exists(file_path):
                    zipf.write(file_path, os.path.basename(file_path))
        
        # Upload to Google Drive (add new files with date and "Updated" suffix)
        files_to_upload = [po_excel_path, po_zip_path]
        
        # Use existing folder ID
        from google_sheets.google_drive_upload import get_drive_service, upload_file
        drive_service = get_drive_service()
        if not drive_service:
            return jsonify({'success': False, 'error': 'Failed to connect to Google Drive'}), 500
        
        # Add "Updated" suffix to filenames
        # If date already exists in filename, just add "_Updated"
        # If no date, add date and "_Updated"
        import re
        current_date = datetime.now().strftime('%Y-%m-%d')
        uploaded_links = {}
        for file_path in files_to_upload:
            if os.path.exists(file_path):
                # Get original filename and extension
                original_filename = os.path.basename(file_path)
                name, ext = os.path.splitext(original_filename)
                
                # Check if filename already contains a date pattern (YYYY-MM-DD)
                date_pattern = r'\d{4}-\d{2}-\d{2}'
                has_date = bool(re.search(date_pattern, name))
                
                # Create new filename with "Updated" suffix
                # If date already exists: "PO-001 - 2024-01-15_Updated.xlsx"
                # If no date: "PO-001_Updated_2024-01-15.xlsx"
                if has_date:
                    # Date already in filename, just add Updated
                    new_filename = f"{name}_Updated{ext}"
                else:
                    # No date in filename, add date and Updated
                    new_filename = f"{name}_Updated_{current_date}{ext}"
                
                # Create a temporary copy with the new name for upload
                import tempfile
                import shutil
                temp_dir = tempfile.gettempdir()
                temp_file_path = os.path.join(temp_dir, new_filename)
                shutil.copy2(file_path, temp_file_path)
                
                try:
                    # Upload with new filename (won't replace existing files)
                    link = upload_file(drive_service, temp_file_path, po.google_drive_folder_id)
                    if link:
                        uploaded_links[new_filename] = link
                    # Clean up temp file
                    if os.path.exists(temp_file_path):
                        os.remove(temp_file_path)
                except Exception as e:
                    print(f"Error uploading {new_filename}: {e}")
                    # Clean up temp file on error
                    if os.path.exists(temp_file_path):
                        try:
                            os.remove(temp_file_path)
                        except:
                            pass
        
        # Clean up temp directory after upload
        try:
            import shutil as _shutil2
            _shutil2.rmtree(_po_regen_temp_dir, ignore_errors=True)
            print(f"Cleaned up temp PO regen directory: {_po_regen_temp_dir}")
        except Exception as cleanup_err:
            print(f"Warning: Failed to clean up temp directory: {cleanup_err}")

        if not uploaded_links:
            return jsonify({'success': False, 'error': 'Failed to upload files to Google Drive'}), 500

        # Update PO items with new revisions only (prices stay unchanged)
        for po_item, part_data in zip(po_items, parts_data):
            po_item.revision = part_data['revision']
            # Update material/finish if available
            if part_data.get('material'):
                po_item.material = part_data['material']
            if part_data.get('finish1'):
                po_item.finish1 = part_data['finish1']
            if part_data.get('finish2'):
                po_item.finish2 = part_data['finish2']
        
        db.session.commit()
        
        # Log the action
        log_action('PO_REGENERATE', current_user,
                   f'PO ID: {po.id}, PO Number: {po.po_number}, Revision Updates: {len(revision_updates)}')

        return jsonify({
            'success': True,
            'message': 'PO regenerated successfully',
            'po_id': po.id,
            'po_number': po.po_number,
            'revision_updates': revision_updates,
            'price_updates': [],
            'summary': {
                'total_parts': len(po_items),
                'revision_changes': len(revision_updates),
                'price_changes': 0
            },
            'google_drive': {
                'folder_url': po.google_drive_folder_url,
                'links': uploaded_links
            }
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"Error in regenerate_po: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/rfqs/<int:rfq_id>/create_po', methods=['POST'])
@login_required
@rfq_create_required
def create_po_from_rfq(rfq_id):
    """Create PO from RFQ"""
    try:
        from werkzeug.utils import secure_filename
        from gemini_quotation_processor import GeminiQuotationProcessor
        
        rfq = RFQ.query.get_or_404(rfq_id)
        data = request.form
        po_number = (data.get('po_number') or '').strip()
        vendor = (data.get('vendor') or '').strip()
        
        if not po_number:
            return jsonify({'success': False, 'error': 'PO number is required'}), 400
        if not vendor:
            return jsonify({'success': False, 'error': 'Vendor is required'}), 400
        
        # Check if PO number already exists
        if PO.query.filter_by(po_number=po_number).first():
            return jsonify({'success': False, 'error': f'PO number {po_number} already exists'}), 400
        
        # Handle quotation upload if provided
        quotation_path = None
        extracted_prices = {}
        
        if 'quotation' in request.files:
            quotation_file = request.files['quotation']
            if quotation_file.filename:
                # Save uploaded file
                upload_dir = os.path.join(app.instance_path, 'uploads', 'quotations')
                os.makedirs(upload_dir, exist_ok=True)
                filename = secure_filename(quotation_file.filename)
                quotation_path = os.path.join(upload_dir, f"{po_number}_{filename}")
                quotation_file.save(quotation_path)
                
                # Extract prices using Gemini AI
                try:
                    gemini_api_key = os.environ.get('GEMINI_API_KEY')
                    processor = GeminiQuotationProcessor(api_key=gemini_api_key)
                    extracted_prices = processor.extract_from_quotation(quotation_path, vendor)
                except Exception as e:
                    print(f"Warning: Failed to extract prices from quotation: {e}")
                    # Continue without prices - validation will catch this
        
        # Get prices from database for parts that don't have extracted prices
        for rfq_item in rfq.rfq_items:
            if rfq_item.part_number not in extracted_prices:
                # Try to get price from Part record
                if rfq_item.part_id:
                    part = Part.query.get(rfq_item.part_id)
                    if part and part.unit_cost:
                        extracted_prices[rfq_item.part_number] = {
                            'unit_cost': part.unit_cost,
                            'order_qty': rfq_item.quantity,
                            'total_cost': part.unit_cost * rfq_item.quantity
                        }
        
        # Validate all RFQ items have prices only if quotation was uploaded
        # If no quotation uploaded, allow PO creation without prices (manual entry later)
        if quotation_path:
            missing_prices = []
            for rfq_item in rfq.rfq_items:
                if rfq_item.part_number not in extracted_prices:
                    missing_prices.append(rfq_item.part_number)
            
            if missing_prices:
                return jsonify({
                    'success': False,
                    'error': f'Cannot create PO: Missing prices for parts: {", ".join(missing_prices)}. Please upload a quotation or ensure prices exist in the database.'
                }), 400
        
        # Create PO Excel and ZIP files
        from mechanical_rfq_processor import MechanicalRFQProcessor
        from google_sheets.google_drive_upload import upload_output_files
        import zipfile
        
        processor = MechanicalRFQProcessor()
        output_dir = os.path.join(processor.base_directory, rfq.bom_name)
        os.makedirs(output_dir, exist_ok=True)
        
        today_str = datetime.now().strftime('%Y-%m-%d')
        po_excel_name = f"PO {po_number} - {today_str}.xlsx"
        po_zip_name = f"PO {po_number} - {today_str}.zip"
        po_excel_path = os.path.join(output_dir, po_excel_name)
        po_zip_path = os.path.join(output_dir, po_zip_name)
        
        # Create Excel with pricing
        import pandas as pd
        from openpyxl import Workbook
        from openpyxl.utils.dataframe import dataframe_to_rows
        
        wb = Workbook()
        ws = wb.active
        if ws:
            ws.title = "PO"
            
            # Add headers
            headers = ['ITEM NO.', 'PART NUMBER', 'Revision', 'Description', 'Material', 
                      'FINISH1', 'FINISH2', 'QTY.', 'Unit Cost', 'Total Cost']
            ws.append(headers)
            
            # Add data rows
            for idx, rfq_item in enumerate(rfq.rfq_items, start=1):
                price_data = extracted_prices.get(rfq_item.part_number, {})
                unit_cost = price_data.get('unit_cost', 0)
                qty = rfq_item.quantity
                total_cost = unit_cost * qty
                
                row = [
                    idx,
                    rfq_item.part_number,
                    rfq_item.revision,
                    '',  # Description
                    rfq_item.material or '',
                    rfq_item.finish1 or '',
                    rfq_item.finish2 or '',
                    qty,
                    unit_cost,
                    total_cost
                ]
                ws.append(row)
            
            wb.save(po_excel_path)
        
        # Create ZIP file
        with zipfile.ZipFile(po_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            # Add PDF & XT files if available
            pdf_xt_folder = os.path.join(output_dir, "PDF & XT")
            if os.path.exists(pdf_xt_folder):
                for root, dirs, files in os.walk(pdf_xt_folder):
                    for file in files:
                        file_path = os.path.join(root, file)
                        arcname = os.path.relpath(file_path, pdf_xt_folder)
                        zipf.write(file_path, arcname)
        
        # Upload to Google Drive
        folder_name = f"PO {po_number}"
        uploaded_result = upload_output_files([po_excel_path, po_zip_path], folder_name, file_type='po')
        google_drive_folder_url = None
        google_drive_folder_id = None
        
        if uploaded_result:
            google_drive_folder_url = uploaded_result.get('folder_url')
            google_drive_folder_id = uploaded_result.get('folder_id')
        
        # Calculate total PO cost first
        total_po_cost = 0
        for rfq_item in rfq.rfq_items:
            price_data = extracted_prices.get(rfq_item.part_number, {})
            unit_cost = price_data.get('unit_cost', 0)
            qty = rfq_item.quantity
            total_po_cost += unit_cost * qty
        
        # Create PO record
        po = PO(
            rfq_id=rfq_id,
            bom_id=rfq.bom_id,
            bom_name=rfq.bom_name,
            bom_revision=rfq.bom_revision,
            po_number=po_number,
            vendor=vendor,
            total_cost=total_po_cost,  # Set total cost when creating PO
            google_drive_folder_id=google_drive_folder_id,
            google_drive_folder_url=google_drive_folder_url,
            quotation_file_path=quotation_path,
            created_by=current_user.id
        )
        db.session.add(po)
        
        # Create POItem records and update Part/BOMItem
        for rfq_item in rfq.rfq_items:
            price_data = extracted_prices.get(rfq_item.part_number, {})
            unit_cost = price_data.get('unit_cost', 0)
            qty = rfq_item.quantity
            total_cost = unit_cost * qty
            
            po_item = POItem(
                po_id=po.id,
                part_id=rfq_item.part_id,
                part_number=rfq_item.part_number,
                revision=rfq_item.revision,
                quantity=qty,
                unit_cost=unit_cost,
                total_cost=total_cost,
                material=rfq_item.material,
                finish1=rfq_item.finish1,
                finish2=rfq_item.finish2
            )
            db.session.add(po_item)
            
            # Update Part table
            if rfq_item.part_id:
                part = Part.query.get(rfq_item.part_id)
                if part:
                    part.unit_cost = unit_cost
                    part.order_qty = (part.order_qty or 0) + qty

                    # Update po_orders (comma-separated convention; tolerate legacy JSON arrays)
                    existing_pos = _parse_po_orders(part.po_orders)
                    if po_number not in existing_pos:
                        existing_pos.append(po_number)
                    part.po_orders = ', '.join(existing_pos)
                    
                    # Update vendor
                    if vendor:
                        part.vendor = vendor
            
            # Update BOMItem if exists
            if rfq.bom_id:
                bom_item = BOMItem.query.filter_by(
                    bom_id=rfq.bom_id,
                    part_number=rfq_item.part_number
                ).first()
                if bom_item:
                    bom_item.unit_cost = unit_cost
                    bom_item.order_qty = (bom_item.order_qty or 0) + qty
                    existing_pos = _parse_po_orders(bom_item.po_orders)
                    if po_number not in existing_pos:
                        existing_pos.append(po_number)
                    bom_item.po_orders = ', '.join(existing_pos)
                    if vendor:
                        bom_item.vendor = vendor
        
        # Update RFQ status
        rfq.status = 'converted_to_po'
        
        db.session.commit()
        
        # Log the action
        po_items_count = len(rfq.rfq_items)
        total_cost = sum(item.total_cost for item in POItem.query.filter_by(po_id=po.id).all()) if po.id else 0
        log_action('PO_CREATE', current_user, 
                   f'PO ID: {po.id}, PO Number: {po_number}, Vendor: {vendor}, RFQ ID: {rfq_id}, BOM: "{rfq.bom_name}", Items: {po_items_count}, Total Cost: ${total_cost:.2f}')
        
        return jsonify({
            'success': True,
            'message': 'PO created successfully',
            'po': {
                'id': po.id,
                'po_number': po.po_number,
                'currency': po.currency,
                'google_drive_folder_url': google_drive_folder_url
            }
        })
        
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

# ============================================================================
# PO DELIVERY PERFORMANCE (late deliveries + vendor on-time stats)
# ============================================================================

def _po_expected_date(po):
    """Expected arrival for a PO.
    Parent POs: po_date + lead_time days. Deliveries (child POs): po_date IS
    the promised delivery date (add_po_delivery sets it that way)."""
    if not po.po_date:
        return None
    if po.parent_po_id:
        return po.po_date
    if po.lead_time is None:
        return None
    try:
        return po.po_date + timedelta(days=int(po.lead_time))
    except (TypeError, ValueError):
        return None


@app.route('/api/pos/delivery-performance', methods=['GET'])
@login_required
def get_delivery_performance():
    """Late/upcoming open POs plus per-vendor on-time statistics.
    A PO is 'late' when today is past its expected date and it isn't received.
    Vendor stats are computed from received POs (received_date vs expected).

    Only MAIN POs are tracked. Child deliveries are ignored entirely — they
    aren't always individually marked received (e.g. the parent is completed
    directly), which made completed orders show up as late sub-deliveries."""
    try:
        try:
            upcoming_days = max(1, min(int(request.args.get('upcoming_days', 7)), 60))
        except (TypeError, ValueError):
            upcoming_days = 7

        now = datetime.utcnow()
        pos = PO.query.filter(PO.parent_po_id.is_(None)).all()

        def po_summary(po, expected):
            return {
                'id': po.id,
                'po_number': po.po_number,
                'vendor': po.vendor,
                'is_delivery': po.parent_po_id is not None,
                'po_date': po.po_date.isoformat() if po.po_date else None,
                'lead_time': po.lead_time,
                'expected_date': expected.isoformat() if expected else None,
                'total_cost': po.total_cost,
                'currency': po.currency or 'USD',
                'status': po.status,
            }

        late, upcoming, no_eta = [], [], []
        vendor_stats = {}  # vendor -> aggregates

        for po in pos:
            expected = _po_expected_date(po)
            vendor = (po.vendor or 'Unknown').strip() or 'Unknown'

            if po.po_received:
                # Received: feed vendor statistics when we can compute punctuality
                if expected and po.received_date:
                    vs = vendor_stats.setdefault(vendor, {
                        'vendor': vendor, 'received_pos': 0, 'on_time': 0,
                        'late': 0, 'delay_days_total': 0, 'max_delay_days': 0,
                    })
                    vs['received_pos'] += 1
                    delay = (po.received_date - expected).days
                    if delay <= 0:
                        vs['on_time'] += 1
                    else:
                        vs['late'] += 1
                        vs['delay_days_total'] += delay
                        vs['max_delay_days'] = max(vs['max_delay_days'], delay)
            elif po.status != 'cancelled':
                # Open main PO: classify against today
                if not expected:
                    no_eta.append(po_summary(po, None))
                elif expected < now:
                    entry = po_summary(po, expected)
                    entry['days_overdue'] = (now - expected).days
                    late.append(entry)
                elif expected <= now + timedelta(days=upcoming_days):
                    entry = po_summary(po, expected)
                    entry['days_until_due'] = (expected - now).days
                    upcoming.append(entry)

        late.sort(key=lambda e: e['days_overdue'], reverse=True)
        upcoming.sort(key=lambda e: e['days_until_due'])

        vendors = []
        for vs in vendor_stats.values():
            total = vs['received_pos']
            vendors.append({
                'vendor': vs['vendor'],
                'received_pos': total,
                'on_time': vs['on_time'],
                'late': vs['late'],
                'on_time_rate': round(100.0 * vs['on_time'] / total, 1) if total else None,
                'avg_delay_days': round(vs['delay_days_total'] / vs['late'], 1) if vs['late'] else 0,
                'max_delay_days': vs['max_delay_days'],
            })
        vendors.sort(key=lambda v: (v['on_time_rate'] if v['on_time_rate'] is not None else 101, -v['received_pos']))

        return jsonify({
            'success': True,
            'as_of': now.isoformat(),
            'upcoming_days': upcoming_days,
            'late_pos': late,
            'upcoming_pos': upcoming,
            'open_pos_without_eta': no_eta,
            'vendor_stats': vendors,
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/pos', methods=['GET'])
@login_required
def get_pos():
    """Get all POs"""
    try:
        # Check if total_cost column exists by trying a simple query
        # If it fails, we'll use a workaround
        try:
            # Try to query with total_cost - if column doesn't exist, this will fail
            test_query = db.session.query(PO.id, PO.total_cost).limit(1).all()
            total_cost_column_exists = True
        except Exception as e:
            if 'total_cost' in str(e).lower():
                total_cost_column_exists = False
                print("Warning: total_cost column does not exist. Please run migration: python migrate_add_po_total_cost.py")
            else:
                raise
        
        # Query POs
        if total_cost_column_exists:
            pos = PO.query.order_by(PO.po_date.desc()).all()
        else:
            # Column doesn't exist - query without it using raw SQL
            from sqlalchemy import text
            result_set = db.session.execute(text("""
                SELECT id, rfq_id, bom_id, bom_name, bom_revision, po_number, vendor, 
                       po_date, status, po_received, received_date, google_drive_folder_id, 
                       google_drive_folder_url, quotation_file_path, waybill, invoice_number, created_by
                FROM po 
                ORDER BY po_date DESC
            """))
            # Create PO objects manually without using ORM (to avoid total_cost column)
            pos = []
            for row in result_set:
                # Create a simple object with all the attributes
                class TempPO:
                    def __init__(self, row_data):
                        self.id = row_data[0]
                        self.rfq_id = row_data[1]
                        self.bom_id = row_data[2]
                        self.bom_name = row_data[3]
                        self.bom_revision = row_data[4]
                        self.po_number = row_data[5]
                        self.vendor = row_data[6]
                        self.po_date = row_data[7]
                        self.status = row_data[8]
                        self.po_received = row_data[9]
                        self.received_date = row_data[10]
                        self.google_drive_folder_id = row_data[11]
                        self.google_drive_folder_url = row_data[12]
                        self.quotation_file_path = row_data[13]
                        self.waybill = row_data[14]
                        self.invoice_number = row_data[15]
                        self.created_by = row_data[16]
                        self.total_cost = None  # Will be calculated from items
                        # Get po_items using raw query to avoid ORM issues
                        items_result = db.session.execute(text("""
                            SELECT id, part_number, revision, quantity, unit_cost, total_cost,
                                   material, finish1, finish2
                            FROM po_item
                            WHERE po_id = :po_id
                        """), {'po_id': self.id})
                        self.po_items = []
                        for item_row in items_result:
                            class TempPOItem:
                                def __init__(self, item_data):
                                    self.id = item_data[0]
                                    self.part_number = item_data[1]
                                    self.revision = item_data[2]
                                    self.quantity = item_data[3]
                                    self.unit_cost = item_data[4]
                                    self.total_cost = item_data[5]
                                    self.material = item_data[6]
                                    self.finish1 = item_data[7]
                                    self.finish2 = item_data[8]
                            self.po_items.append(TempPOItem(item_row))
                pos.append(TempPO(row))
        
        result = []
        for po in pos:
            # Calculate total_cost from items (column may not exist yet)
            total_cost = sum(item.total_cost for item in po.po_items)
            
            # Try to use stored total_cost if column exists and has a value
            if total_cost_column_exists:
                try:
                    stored_total = getattr(po, 'total_cost', None)
                    if stored_total is not None:
                        total_cost = stored_total
                    else:
                        # Update the stored total_cost for future use
                        try:
                            po.total_cost = total_cost
                            db.session.commit()
                        except:
                            db.session.rollback()
                except:
                    pass
            
            # Safely get waybill, invoice_number, lead_time, and parent_po_id, handling cases where columns might not exist yet
            try:
                waybill = getattr(po, 'waybill', None)
                invoice_number = getattr(po, 'invoice_number', None)
                lead_time = getattr(po, 'lead_time', None)
                parent_po_id = getattr(po, 'parent_po_id', None)
            except AttributeError:
                waybill = None
                invoice_number = None
                lead_time = None
                parent_po_id = None
            
            # Check if PO has QC data
            has_qc_data = POQCItem.query.filter_by(po_id=po.id).first() is not None
            
            # Get child POs if this is a parent
            child_pos = []
            if not parent_po_id:  # Only check for children if this is not a child itself
                try:
                    child_po_records = PO.query.filter_by(parent_po_id=po.id).all()
                    child_pos = [{
                        'id': child.id,
                        'po_number': child.po_number,
                        'total_cost': getattr(child, 'total_cost', None) or sum(item.total_cost for item in child.po_items),
                        'currency': getattr(child, 'currency', 'USD') or 'USD',
                        'lead_time': getattr(child, 'lead_time', None),
                        'po_date': child.po_date.isoformat() if child.po_date else None,
                        'waybill': getattr(child, 'waybill', None),
                        'invoice_number': getattr(child, 'invoice_number', None),
                        'po_received': getattr(child, 'po_received', False)
                    } for child in child_po_records]
                except:
                    pass
            
            # Get parent PO info if this is a child
            parent_po_number = None
            if parent_po_id:
                try:
                    parent_po = PO.query.get(parent_po_id)
                    if parent_po:
                        parent_po_number = parent_po.po_number
                except:
                    pass
            
            # Get currency field
            try:
                currency = getattr(po, 'currency', 'USD') or 'USD'
            except AttributeError:
                currency = 'USD'
            
            # Get creator username
            creator_username = None
            if po.created_by:
                creator = User.query.get(po.created_by)
                if creator:
                    creator_username = creator.username
            
            result.append({
                'id': po.id,
                'po_number': po.po_number,
                'bom_id': po.bom_id,
                'bom_name': po.bom_name,
                'bom_revision': po.bom_revision,
                'vendor': po.vendor,
                'po_date': po.po_date.isoformat(),
                'status': po.status,
                'po_received': po.po_received,
                'received_date': po.received_date.isoformat() if po.received_date else None,
                'parts_count': len(po.po_items),
                'total_cost': total_cost,
                'currency': currency,
                'has_qc_data': has_qc_data,
                'google_drive_folder_url': po.google_drive_folder_url,
                'waybill': waybill,
                'invoice_number': invoice_number,
                'lead_time': lead_time,
                'parent_po_id': parent_po_id,
                'parent_po_number': parent_po_number,
                'child_pos': child_pos,
                'is_parent': len(child_pos) > 0,
                'is_child': parent_po_id is not None,
                'created_by': creator_username
            })
        return jsonify({'success': True, 'pos': result})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>', methods=['GET'])
@login_required
def get_po_details(po_id):
    """Get PO details with items"""
    try:
        po = PO.query.get_or_404(po_id)
        
        # If this is a child PO, get items from parent PO
        po_to_use = po
        if po.parent_po_id:
            parent_po = PO.query.get(po.parent_po_id)
            if parent_po:
                po_to_use = parent_po
        
        items = []
        for item in po_to_use.po_items:
            # Get warehouse box from part if available
            warehouse_box = None
            if item.part_id:
                part = Part.query.get(item.part_id)
                if part:
                    warehouse_box = part.warehouse_box_number
            # If not found by part_id, try to find by part_number and revision
            if not warehouse_box:
                part = Part.query.filter_by(
                    part_number=item.part_number,
                    revision=item.revision
                ).first()
                if part:
                    warehouse_box = part.warehouse_box_number
            
            items.append({
                'id': item.id,
                'part_number': item.part_number,
                'revision': item.revision,
                'quantity': item.quantity,
                'unit_cost': item.unit_cost,
                'total_cost': item.total_cost,
                'original_unit_cost': item.original_unit_cost,
                'original_currency': item.original_currency,
                'material': item.material,
                'finish1': item.finish1,
                'finish2': item.finish2,
                'warehouse_box_number': warehouse_box
            })
        # Get QC data if exists
        qc_items = POQCItem.query.filter_by(po_id=po_id).all()
        qc_data = []
        for qc_item in qc_items:
            qc_data.append({
                'id': qc_item.id,
                'po_item_id': qc_item.po_item_id,
                'part_number': qc_item.part_number,
                'revision': qc_item.revision,
                'quantity_in_po': qc_item.quantity_in_po,
                'qty_arrived': qc_item.qty_arrived,
                'qty_approved': qc_item.qty_approved,
                'qc_approved': qc_item.qc_approved,
                'warehouse_box_number': qc_item.warehouse_box_number,
                'notes': qc_item.notes,
                'created_at': qc_item.created_at.isoformat() if qc_item.created_at else None
            })
        
        return jsonify({
            'success': True,
            'po': {
                'id': po.id,
                'po_number': po.po_number,
                'bom_name': po.bom_name,
                'bom_revision': po.bom_revision,
                'vendor': po.vendor,
                'po_date': po.po_date.isoformat(),
                'status': po.status,
                'po_received': po.po_received,
                'google_drive_folder_url': po.google_drive_folder_url,
                'parent_po_id': po.parent_po_id,
                'currency': po.currency or 'USD',
                'lead_time': po.lead_time,
                'total_cost': po.total_cost,
                'has_doc_vars': bool(po.po_doc_vars),
            },
            'items': items,
            'qc_data': qc_data,
            'has_qc_data': len(qc_data) > 0
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/pos/<int:po_id>/mark_sent', methods=['POST'])
@login_required
def mark_po_sent_to_vendor(po_id):
    """Mark PO as sent to vendor"""
    try:
        po = PO.query.get_or_404(po_id)
        
        if po.status == 'pending':
            po.status = 'sent_to_vendor'
            db.session.commit()
            
            # Log the action
            log_action('PO_UPDATE', current_user, 
                       f'PO ID: {po_id}, PO Number: {po.po_number}, Status: pending -> sent_to_vendor')
            
            return jsonify({'success': True, 'message': 'PO marked as sent to vendor'})
        else:
            return jsonify({'success': False, 'error': 'PO is not in pending status'}), 400
        
    except Exception as e:
        db.session.rollback()
        print(f"Error marking PO as sent: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/mark_received', methods=['POST'])
@login_required
def mark_po_received(po_id):
    """Mark PO as received and update inventory with QC approval data"""
    try:
        po = PO.query.get_or_404(po_id)
        set_inventory_context('po_received', po.po_number)

        if po.po_received:
            return jsonify({'success': False, 'error': 'PO already marked as received'}), 400

        # Block direct receiving of parent POs that have deliveries
        if not po.parent_po_id:  # This is a parent PO
            child_count = PO.query.filter_by(parent_po_id=po.id).count()
            if child_count > 0:
                return jsonify({
                    'success': False,
                    'error': 'This PO has deliveries. Please receive individual deliveries instead.'
                }), 400

        # Get QC data from request (optional - for backward compatibility)
        qc_data = request.json.get('qc_data', []) if request.json else []
        # Get revision decisions from frontend (for revision mismatch handling)
        revision_decisions = request.json.get('revision_decisions', {}) if request.json else {}

        # Create a map of QC data by part_number_revision for quick lookup
        qc_data_map = {}
        if qc_data:
            for qc_item in qc_data:
                key = f"{qc_item.get('part_number')}_{qc_item.get('revision')}"
                qc_data_map[key] = qc_item

        # Update PO status (save pre-receive status for undo)
        po.pre_receive_status = po.status
        po.status = 'received'
        po.po_received = True
        po.received_date = datetime.utcnow()

        # For child POs, use parent PO's items instead
        po_items_to_process = po.po_items
        if po.parent_po_id:
            parent_po = PO.query.get(po.parent_po_id)
            if parent_po:
                po_items_to_process = parent_po.po_items
        
        # Save QC data to database
        for po_item in po_items_to_process:
            key = f"{po_item.part_number}_{po_item.revision}"
            qc_item_data = qc_data_map.get(key, {})
            
            # Create or update QC item record
            qc_item = POQCItem.query.filter_by(
                po_id=po_id,
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            
            if not qc_item:
                qc_item = POQCItem(
                    po_id=po_id,
                    po_item_id=po_item.id,
                    part_number=po_item.part_number,
                    revision=po_item.revision,
                    quantity_in_po=po_item.quantity
                )
                db.session.add(qc_item)
            
            # Update QC item with data from request.
            # If this item was NOT sent in the request (key not in qc_data_map), it means
            # the frontend filtered it out because it was already pre-approved via
            # save_po_qc_data. In that case, preserve the existing DB values.
            if key in qc_data_map:
                qc_item.qty_arrived = qc_item_data.get('qty_arrived', po_item.quantity)
                qc_item.qty_approved = qc_item_data.get('qty_approved', po_item.quantity)
                qc_item.qc_approved = qc_item_data.get('qc_approved', False)
                if qc_item_data.get('warehouse_box_number') is not None:
                    qc_item.warehouse_box_number = qc_item_data['warehouse_box_number']
                if qc_item_data.get('notes') is not None:
                    qc_item.notes = qc_item_data['notes']
            # else: item not in request — preserve existing DB values (already set by save_po_qc_data)
        
        # Update inventory, order_qty, and po_orders for QC-approved parts only
        parts_not_found = []
        parts_resolved = []
        for po_item in po_items_to_process:
            decision_key = f"{po_item.part_number}_{po_item.revision}"
            decision = revision_decisions.get(decision_key, {})
            decision_action = decision.get('action')  # 'upgrade', 'keep_original', or None

            if decision_action == 'upgrade' and decision.get('target_revision'):
                # User chose to apply inventory to the newer revision
                part = Part.query.filter_by(
                    part_number=po_item.part_number,
                    revision=decision['target_revision']
                ).first()
                if part:
                    # If target revision has no price but old one does, copy price over
                    old_part = Part.query.filter_by(
                        part_number=po_item.part_number,
                        revision=po_item.revision
                    ).first()
                    if old_part and not part.unit_cost and old_part.unit_cost:
                        part.unit_cost = old_part.unit_cost
                        part.vendor = part.vendor or old_part.vendor
                        part.source_currency = part.source_currency or old_part.source_currency
                        part.source_unit_cost = part.source_unit_cost or old_part.source_unit_cost
                        # Recalculate price_per_bom for all BOMParts using this part
                        for bp in BOMPart.query.filter_by(part_id=part.id).all():
                            if part.unit_cost and bp.quantity:
                                bp.price_per_bom = float(part.unit_cost) * float(bp.quantity)
                    print(f"INFO: User chose to upgrade {po_item.part_number} REV{po_item.revision} -> REV{part.revision}")
                    parts_resolved.append(f"{po_item.part_number} REV{po_item.revision} → REV{part.revision} (user upgrade)")
                else:
                    print(f"WARNING: Target revision {decision['target_revision']} not found for {po_item.part_number}")
                    part, _ = resolve_part_with_fallback(po_item.part_number, po_item.revision)
            elif decision_action == 'keep_original':
                # User chose to keep the original PO revision
                part = Part.query.filter_by(
                    part_number=po_item.part_number,
                    revision=po_item.revision
                ).first()
                if not part:
                    # Original revision doesn't exist, fall back
                    part, _ = resolve_part_with_fallback(po_item.part_number, po_item.revision)
                print(f"INFO: User chose to keep original revision for {po_item.part_number} REV{po_item.revision}")
            else:
                # No decision (no mismatch or backward compatibility) - use existing fallback
                part, used_fallback = resolve_part_with_fallback(po_item.part_number, po_item.revision)
                if used_fallback:
                    print(f"INFO: Resolved {po_item.part_number} REV{po_item.revision} -> REV{part.revision} (backward compatible)")
                    parts_resolved.append(f"{po_item.part_number} REV{po_item.revision} → REV{part.revision}")

            if not part:
                print(f"WARNING: Part {po_item.part_number} REV{po_item.revision} not found (no compatible revision)")
                parts_not_found.append(f"{po_item.part_number} REV{po_item.revision}")
                continue

            # Record revision decision on QC item for audit trail
            if decision_action:
                qc_item = POQCItem.query.filter_by(
                    po_id=po_id,
                    part_number=po_item.part_number,
                    revision=po_item.revision
                ).first()
                if qc_item:
                    qc_item.resolved_to_revision = part.revision
                    qc_item.revision_decision = decision_action
                # Add note to Part for audit trail
                note_date = datetime.utcnow().strftime('%Y-%m-%d')
                existing_notes = (part.notes or '').strip()
                if decision_action == 'upgrade':
                    new_note = f"[{note_date}] PO {po.po_number}: Ordered as REV{po_item.revision}, received and applied to REV{part.revision}"
                else:
                    latest_part = Part.query.filter_by(part_number=po_item.part_number).filter(
                        Part.status != 'obsolete').order_by(Part.revision.desc()).first()
                    latest_rev = latest_part.revision if latest_part else '?'
                    new_note = f"[{note_date}] PO {po.po_number}: Received at REV{po_item.revision} (latest BOM: REV{latest_rev})"
                part.notes = f"{existing_notes}\n{new_note}".strip() if existing_notes else new_note

            # Check if this part is QC approved
            key = f"{po_item.part_number}_{po_item.revision}"
            qc_item_data = qc_data_map.get(key, {})

            if key not in qc_data_map:
                # Item was NOT sent in the request — it was pre-approved via partial receive
                # (handlePartialReceive calls save_po_qc_data + partial_receive_po which already
                #  updated inventory).  Just carry the warehouse box from DB if set; skip all
                # inventory/order_qty updates to avoid double-counting.
                existing_qc_item = POQCItem.query.filter_by(
                    po_id=po_id,
                    part_number=po_item.part_number,
                    revision=po_item.revision
                ).first()
                if existing_qc_item and existing_qc_item.warehouse_box_number:
                    part.warehouse_box_number = existing_qc_item.warehouse_box_number
                print(f"DEBUG: {po_item.part_number} skipping inventory update - pre-approved via partial receive")
                continue

            is_qc_approved = qc_item_data.get('qc_approved', False)
            print(f"DEBUG: {po_item.part_number} is_qc_approved={is_qc_approved}")

            # Update warehouse box number if provided (regardless of QC approval)
            if qc_item_data.get('warehouse_box_number'):
                part.warehouse_box_number = qc_item_data.get('warehouse_box_number')
                print(f"DEBUG: Updated warehouse_box_number for {po_item.part_number}: {part.warehouse_box_number}")

            # Only update inventory if QC approved - use qty_approved instead of po_item.quantity
            if is_qc_approved:
                # Update inventory using qty_approved
                qty_approved = qc_item_data.get('qty_approved', po_item.quantity)
                current_inventory = part.inventory or 0
                new_inventory = current_inventory + qty_approved
                part.inventory = new_inventory
                print(f"DEBUG: Updated inventory for {po_item.part_number}: {current_inventory} + {qty_approved} = {new_inventory}")
            else:
                print(f"DEBUG: Skipping inventory update for {po_item.part_number} - not QC approved")
            
            # Update po_orders and order_qty only if QC approved
            if is_qc_approved:
                # For child POs (deliveries), check if parent PO is already tracked
                # Deliveries should NOT add to order_qty - only parent PO should add when created/received
                is_child_po = po.parent_po_id is not None
                parent_po_number = None
                if is_child_po:
                    parent_po = PO.query.get(po.parent_po_id)
                    if parent_po:
                        parent_po_number = parent_po.po_number
                
                # Update po_orders first (to check if PO already exists)
                po_already_tracked = False
                try:
                    existing_po_orders = (part.po_orders or '').strip()
                    if existing_po_orders:
                        # Parse existing PO numbers (comma-separated)
                        po_numbers = [p.strip() for p in existing_po_orders.split(',') if p.strip()]
                    else:
                        po_numbers = []
                    
                    # For child POs, check if parent PO is already tracked
                    # For parent POs, check if current PO is already tracked
                    if is_child_po and parent_po_number:
                        po_already_tracked = parent_po_number in po_numbers
                        # Don't add delivery PO number to po_orders - only track parent PO
                        if not po_already_tracked:
                            # This shouldn't happen - parent PO should be in po_orders when created
                            print(f"WARNING: Parent PO {parent_po_number} not found in po_orders for {po_item.part_number}")
                    else:
                        po_already_tracked = po.po_number in po_numbers
                        # Add current PO number if not already present (for parent POs only)
                        if not po_already_tracked:
                            po_numbers.append(po.po_number)
                            part.po_orders = ', '.join(po_numbers)
                            print(f"DEBUG: Added PO {po.po_number} to po_orders for {po_item.part_number}: {part.po_orders}")
                        else:
                            print(f"DEBUG: PO {po.po_number} already in po_orders for {po_item.part_number}: {part.po_orders}")
                            part.po_orders = ', '.join(po_numbers)  # Update anyway to ensure consistency
                except Exception as e:
                    print(f"ERROR: Failed to update po_orders for {po_item.part_number}: {e}")
                    import traceback
                    traceback.print_exc()
                
                # Update order_qty (sum across all POs - only add if PO wasn't already tracked)
                # IMPORTANT: Child POs (deliveries) should NEVER add to order_qty
                # order_qty should only be updated when parent PO is created or received
                # Deliveries only affect inventory when received, not order_qty
                if not is_child_po:
                    # Only update order_qty for parent POs
                    # Use qty_approved for order_qty update
                    qty_approved = qc_item_data.get('qty_approved', po_item.quantity)
                    current_order_qty = part.order_qty or 0
                    if not po_already_tracked:
                        new_order_qty = current_order_qty + qty_approved
                        part.order_qty = new_order_qty
                        print(f"DEBUG: Updated order_qty for {po_item.part_number}: {current_order_qty} + {qty_approved} = {new_order_qty}")
                    else:
                        print(f"DEBUG: Skipping order_qty update for {po_item.part_number} - PO already tracked (current order_qty: {current_order_qty})")
                else:
                    # Child PO (delivery) - do NOT update order_qty
                    # order_qty was already set when parent PO was created
                    print(f"DEBUG: Skipping order_qty update for {po_item.part_number} - this is a delivery (child PO), order_qty should not change")
            
            # Debug: Verify all updates before commit
            print(f"DEBUG: Part {po_item.part_number} before commit - inventory: {part.inventory}, order_qty: {part.order_qty}, po_orders: {part.po_orders}, warehouse_box: {part.warehouse_box_number}")
        
        # Debug: Check all parts before commit
        print("=" * 60)
        print("DEBUG: BEFORE COMMIT - Part status:")
        for po_item in po.po_items:
            part = Part.query.filter_by(
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            if part:
                print(f"  Part {po_item.part_number} REV{po_item.revision}:")
                print(f"    - inventory: {part.inventory}")
                print(f"    - order_qty: {part.order_qty}")
                print(f"    - po_orders: {part.po_orders}")
            else:
                print(f"  WARNING: Part {po_item.part_number} REV{po_item.revision} NOT FOUND")
        
        print("=" * 60)
        print("DEBUG: Committing changes to database...")
        db.session.commit()
        print("DEBUG: Commit successful!")
        print("=" * 60)
        
        # Update assembly inventories for QC-approved parts only
        # (use po_items_to_process — child/delivery POs carry their items on the parent)
        try:
            for po_item in po_items_to_process:
                key = f"{po_item.part_number}_{po_item.revision}"
                qc_item_data = qc_data_map.get(key, {})
                # Fall back to DB value when item not in request (pre-approved)
                if key in qc_data_map:
                    is_qc_approved = qc_item_data.get('qc_approved', False)
                else:
                    _qc = POQCItem.query.filter_by(po_id=po_id, part_number=po_item.part_number, revision=po_item.revision).first()
                    is_qc_approved = _qc.qc_approved if _qc else False

                if is_qc_approved:
                    part, _ = resolve_part_with_fallback(po_item.part_number, po_item.revision)
                    if part:
                        update_assembly_inventories_for_part(part.id)
        except Exception as e:
            print(f"Warning: Error updating assembly inventories after PO received: {e}")
            # Don't fail the whole request if this fails
        
        # Log the action
        items_count = len(po.po_items) if po.po_items else 0
        log_action('PO_UPDATE', current_user, 
                   f'PO ID: {po_id}, PO Number: {po.po_number}, Status: received, Items: {items_count}, Inventory updated')
        
        # Debug: Verify all parts after commit by querying fresh from database
        print("DEBUG: AFTER COMMIT - Verifying database state:")
        for po_item in po.po_items:
            # Fresh query to verify database state
            part = Part.query.filter_by(
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            if part:
                print(f"  Part {po_item.part_number} REV{po_item.revision}:")
                print(f"    - inventory: {part.inventory}")
                print(f"    - order_qty: {part.order_qty}")
                print(f"    - po_orders: {part.po_orders}")
                
                # Verify the data matches expectations
                expected_order_qty = (part.order_qty or 0)
                if expected_order_qty > 0:
                    print(f"    ✓ order_qty saved successfully: {expected_order_qty}")
                else:
                    print(f"    ✗ WARNING: order_qty is 0 or None!")
            else:
                print(f"  ERROR: Part {po_item.part_number} REV{po_item.revision} NOT FOUND AFTER COMMIT")
        print("=" * 60)
        
        # Auto-mark parent PO as received if this is a child PO and all quantities are fulfilled
        parent_auto_received = False
        if po.parent_po_id:
            parent_po_obj = PO.query.get(po.parent_po_id)
            if parent_po_obj and not parent_po_obj.po_received:
                # Single query: sum approved qty per (part_number, revision) across all child POs
                from sqlalchemy import func as sql_func
                sibling_ids_sq = db.session.query(PO.id).filter(PO.parent_po_id == parent_po_obj.id).subquery()
                received_totals = db.session.query(
                    POQCItem.part_number,
                    POQCItem.revision,
                    sql_func.coalesce(sql_func.sum(POQCItem.qty_approved), 0)
                ).filter(
                    POQCItem.po_id.in_(db.session.query(sibling_ids_sq)),
                    POQCItem.qc_approved == True
                ).group_by(POQCItem.part_number, POQCItem.revision).all()
                received_map = {(pn, rev): qty for pn, rev, qty in received_totals}
                all_fulfilled = all(
                    received_map.get((item.part_number, item.revision), 0) >= item.quantity
                    for item in parent_po_obj.po_items
                )
                if all_fulfilled:
                    parent_po_obj.pre_receive_status = parent_po_obj.status
                    parent_po_obj.status = 'received'
                    parent_po_obj.po_received = True
                    parent_po_obj.received_date = datetime.utcnow()
                    db.session.commit()
                    parent_auto_received = True
                    print(f"DEBUG: Auto-marked parent PO {parent_po_obj.po_number} as received - all quantities fulfilled across deliveries")

        return jsonify({
            'success': True,
            'message': 'PO marked as received and inventory updated',
            'parent_auto_received': parent_auto_received,
            'parts_not_found': parts_not_found,
            'parts_resolved': parts_resolved
        })
    except Exception as e:
        db.session.rollback()
        print(f"Error marking PO as received: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/partial_receive', methods=['POST'])
@login_required
def partial_receive_po(po_id):
    """Partially receive PO items - mark only selected items as received and update inventory"""
    try:
        po = PO.query.get_or_404(po_id)
        set_inventory_context('po_partial_receive', po.po_number)

        # Get QC data from request
        qc_data = request.json.get('qc_data', []) if request.json else []
        # Get revision decisions from frontend (for revision mismatch handling)
        revision_decisions = request.json.get('revision_decisions', {}) if request.json else {}

        if not qc_data:
            return jsonify({'success': False, 'error': 'No QC data provided'}), 400

        # Create a map of QC data by part_number_revision for quick lookup
        qc_data_map = {}
        checked_items = []
        for qc_item in qc_data:
            # Only process items that are checked (not already received)
            if qc_item.get('checked', False) and not qc_item.get('received', False):
                key = f"{qc_item.get('part_number')}_{qc_item.get('revision')}"
                qc_data_map[key] = qc_item
                checked_items.append(key)

        if not checked_items:
            return jsonify({'success': False, 'error': 'No items selected for receiving'}), 400

        # For child POs, use parent PO's items instead
        po_items_to_process = po.po_items
        if po.parent_po_id:
            parent_po = PO.query.get(po.parent_po_id)
            if parent_po:
                po_items_to_process = parent_po.po_items

        # Save QC data to database and update inventory for checked items only
        received_count = 0
        inventory_updated_part_ids = []
        parts_not_found = []  # Parts that couldn't be found at all
        parts_resolved = []   # Parts resolved via backward-compatible fallback
        for po_item in po_items_to_process:
            key = f"{po_item.part_number}_{po_item.revision}"

            # Only process if this item is in the checked items list
            if key not in checked_items:
                continue

            qc_item_data = qc_data_map.get(key, {})

            # Create or update QC item record
            qc_item = POQCItem.query.filter_by(
                po_id=po_id,
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()

            if not qc_item:
                qc_item = POQCItem(
                    po_id=po_id,
                    po_item_id=po_item.id,
                    part_number=po_item.part_number,
                    revision=po_item.revision,
                    quantity_in_po=po_item.quantity
                )
                db.session.add(qc_item)

            # Update QC item with data from request
            qc_item.qty_arrived = qc_item_data.get('qty_arrived', po_item.quantity)
            qc_item.qty_approved = qc_item_data.get('qty_approved', po_item.quantity)
            qc_item.qc_approved = qc_item_data.get('qc_approved', False) or qc_item_data.get('checked', False)
            # Preserve previously saved values when the request omits them
            qc_item.warehouse_box_number = qc_item_data.get('warehouse_box_number') or qc_item.warehouse_box_number or ''
            qc_item.notes = qc_item_data.get('notes') or qc_item.notes or ''

            # Resolve part using revision decisions (same logic as mark_received)
            decision = revision_decisions.get(key, {})
            decision_action = decision.get('action')

            if decision_action == 'upgrade' and decision.get('target_revision'):
                part = Part.query.filter_by(
                    part_number=po_item.part_number,
                    revision=decision['target_revision']
                ).first()
                if part:
                    old_part = Part.query.filter_by(
                        part_number=po_item.part_number,
                        revision=po_item.revision
                    ).first()
                    if old_part and not part.unit_cost and old_part.unit_cost:
                        part.unit_cost = old_part.unit_cost
                        part.vendor = part.vendor or old_part.vendor
                        part.source_currency = part.source_currency or old_part.source_currency
                        part.source_unit_cost = part.source_unit_cost or old_part.source_unit_cost
                        for bp in BOMPart.query.filter_by(part_id=part.id).all():
                            if part.unit_cost and bp.quantity:
                                bp.price_per_bom = float(part.unit_cost) * float(bp.quantity)
                    parts_resolved.append(f"{po_item.part_number} REV{po_item.revision} → REV{part.revision} (user upgrade)")
                else:
                    part, _ = resolve_part_with_fallback(po_item.part_number, po_item.revision)
            elif decision_action == 'keep_original':
                part = Part.query.filter_by(
                    part_number=po_item.part_number,
                    revision=po_item.revision
                ).first()
                if not part:
                    part, _ = resolve_part_with_fallback(po_item.part_number, po_item.revision)
            else:
                part, used_fallback = resolve_part_with_fallback(po_item.part_number, po_item.revision)
                if used_fallback:
                    parts_resolved.append(f"{po_item.part_number} REV{po_item.revision} → REV{part.revision}")

            if not part:
                print(f"WARNING: Part {po_item.part_number} REV{po_item.revision} not found (no compatible revision)")
                parts_not_found.append(f"{po_item.part_number} REV{po_item.revision}")
                continue

            # Record revision decision on QC item for audit trail
            if decision_action:
                qc_item.resolved_to_revision = part.revision
                qc_item.revision_decision = decision_action
                note_date = datetime.utcnow().strftime('%Y-%m-%d')
                existing_notes = (part.notes or '').strip()
                if decision_action == 'upgrade':
                    new_note = f"[{note_date}] PO {po.po_number}: Ordered as REV{po_item.revision}, received and applied to REV{part.revision}"
                else:
                    latest_part = Part.query.filter_by(part_number=po_item.part_number).filter(
                        Part.status != 'obsolete').order_by(Part.revision.desc()).first()
                    latest_rev = latest_part.revision if latest_part else '?'
                    new_note = f"[{note_date}] PO {po.po_number}: Received at REV{po_item.revision} (latest BOM: REV{latest_rev})"
                part.notes = f"{existing_notes}\n{new_note}".strip() if existing_notes else new_note

            is_qc_approved = qc_item.qc_approved

            # Update warehouse box number if provided (regardless of QC approval)
            if qc_item_data.get('warehouse_box_number'):
                part.warehouse_box_number = qc_item_data.get('warehouse_box_number')
                print(f"DEBUG: Updated warehouse_box_number for {po_item.part_number}: {part.warehouse_box_number}")
            
            # Only update inventory if QC approved
            if is_qc_approved:
                # Update inventory using qty_approved
                qty_approved = qc_item_data.get('qty_approved', po_item.quantity)
                current_inventory = part.inventory or 0
                new_inventory = current_inventory + qty_approved
                part.inventory = new_inventory
                inventory_updated_part_ids.append(part.id)
                print(f"DEBUG: Updated inventory for {po_item.part_number}: {current_inventory} + {qty_approved} = {new_inventory}")
                received_count += 1
            else:
                print(f"DEBUG: Skipping inventory update for {po_item.part_number} - not QC approved")

        db.session.commit()

        # Propagate inventory changes to parent assemblies (same as full receive)
        try:
            for _pid in set(inventory_updated_part_ids):
                update_assembly_inventories_for_part(_pid)
        except Exception as e:
            print(f"Warning: Error updating assembly inventories after partial receive: {e}")

        # Log the action
        log_action('PO_UPDATE', current_user,
                   f'PO ID: {po_id}, PO Number: {po.po_number}, Partial receive: {received_count} item(s), Inventory updated')

        # Auto-mark parent PO as received if this is a child PO and all quantities are fulfilled
        parent_auto_received = False
        if po.parent_po_id:
            parent_po_obj = PO.query.get(po.parent_po_id)
            if parent_po_obj and not parent_po_obj.po_received:
                # Single query: sum approved qty per (part_number, revision) across all child POs
                from sqlalchemy import func as sql_func
                sibling_ids_sq = db.session.query(PO.id).filter(PO.parent_po_id == parent_po_obj.id).subquery()
                received_totals = db.session.query(
                    POQCItem.part_number,
                    POQCItem.revision,
                    sql_func.coalesce(sql_func.sum(POQCItem.qty_approved), 0)
                ).filter(
                    POQCItem.po_id.in_(db.session.query(sibling_ids_sq)),
                    POQCItem.qc_approved == True
                ).group_by(POQCItem.part_number, POQCItem.revision).all()
                received_map = {(pn, rev): qty for pn, rev, qty in received_totals}
                all_fulfilled = all(
                    received_map.get((item.part_number, item.revision), 0) >= item.quantity
                    for item in parent_po_obj.po_items
                )
                if all_fulfilled:
                    parent_po_obj.pre_receive_status = parent_po_obj.status
                    parent_po_obj.status = 'received'
                    parent_po_obj.po_received = True
                    parent_po_obj.received_date = datetime.utcnow()
                    db.session.commit()
                    parent_auto_received = True
                    print(f"DEBUG: Auto-marked parent PO {parent_po_obj.po_number} as received - all quantities fulfilled across deliveries")

        # Auto-mark this PO as received if all its items are now QC-approved.
        # Items already fully received by OTHER deliveries (0 remaining) are
        # ignored here — a later/top-up delivery only needs to approve the
        # items that still had a remaining balance to be considered received.
        po_auto_received = False
        if not po.po_received:
            # Compute quantity already received across sibling deliveries and the
            # parent PO itself, EXCLUDING this delivery's contribution.
            received_by_others = {}  # part_key -> qty approved elsewhere
            if po.parent_po_id:
                sibling_pos = PO.query.filter_by(parent_po_id=po.parent_po_id).all()
            else:
                sibling_pos = []
            related_ids = {sp.id for sp in sibling_pos}
            if po.parent_po_id:
                related_ids.add(po.parent_po_id)
            related_ids.discard(po_id)  # exclude this delivery
            for rel_id in related_ids:
                for qc in POQCItem.query.filter_by(po_id=rel_id, qc_approved=True).all():
                    key = f"{qc.part_number}_{qc.revision}"
                    received_by_others[key] = received_by_others.get(key, 0) + (qc.qty_approved or 0)

            all_items_approved = True
            for po_item in po_items_to_process:
                key = f"{po_item.part_number}_{po_item.revision}"
                # Skip items already fully fulfilled by other deliveries
                if received_by_others.get(key, 0) >= (po_item.quantity or 0):
                    continue
                qc_item = POQCItem.query.filter_by(
                    po_id=po_id,
                    part_number=po_item.part_number,
                    revision=po_item.revision,
                    qc_approved=True
                ).first()
                if not qc_item:
                    all_items_approved = False
                    break
            if all_items_approved:
                po.pre_receive_status = po.status
                po.status = 'received'
                po.po_received = True
                po.received_date = datetime.utcnow()
                db.session.commit()
                po_auto_received = True
                print(f"DEBUG: Auto-marked PO {po.po_number} as received - all items QC-approved")

        return jsonify({
            'success': True,
            'message': f'{received_count} part(s) received and inventory updated',
            'parent_auto_received': parent_auto_received,
            'po_auto_received': po_auto_received,
            'parts_not_found': parts_not_found,
            'parts_resolved': parts_resolved
        })
    except Exception as e:
        db.session.rollback()
        print(f"Error partially receiving PO: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/warehouse-box/check-duplicate', methods=['POST'])
@login_required
def check_warehouse_box_duplicate():
    """Check if a warehouse box number already exists in the database"""
    try:
        data = request.json
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        warehouse_box_number = (data.get('warehouse_box_number') or '').strip()
        exclude_part_id = data.get('exclude_part_id')
        
        if not warehouse_box_number:
            return jsonify({
                'success': True,
                'exists': False,
                'partInfo': None
            })
        
        # Search for the warehouse box number in the Part table
        query = Part.query.filter_by(warehouse_box_number=warehouse_box_number)
        
        # Exclude a specific part if provided (useful when editing)
        if exclude_part_id:
            query = query.filter(Part.id != exclude_part_id)
        
        existing_part = query.first()
        
        if existing_part:
            return jsonify({
                'success': True,
                'exists': True,
                'partInfo': {
                    'id': existing_part.id,
                    'part_number': existing_part.part_number,
                    'revision': existing_part.revision,
                    'warehouse_box_number': existing_part.warehouse_box_number
                }
            })
        else:
            return jsonify({
                'success': True,
                'exists': False,
                'partInfo': None
            })
    except Exception as e:
        print(f"Error checking warehouse box duplicate: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/undo_part_received', methods=['POST'])
@login_required
def undo_part_received(po_id):
    """Undo received status for a single part - subtract from inventory only"""
    try:
        po = PO.query.get_or_404(po_id)
        set_inventory_context('po_part_undo', po.po_number)

        # Get part_number and revision from request
        data = request.json
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        part_number = data.get('part_number')
        revision = data.get('revision')
        
        if not part_number or not revision:
            return jsonify({'success': False, 'error': 'part_number and revision are required'}), 400
        
        # Find the PO item (for child POs, items belong to parent)
        po_to_search = po
        if po.parent_po_id:
            parent = PO.query.get(po.parent_po_id)
            if parent:
                po_to_search = parent

        po_item = None
        for item in po_to_search.po_items:
            if item.part_number == part_number and item.revision == revision:
                po_item = item
                break

        if not po_item:
            return jsonify({'success': False, 'error': f'Part {part_number} REV{revision} not found in this PO'}), 404

        # Find the QC item
        qc_item = POQCItem.query.filter_by(
            po_id=po_id,
            part_number=part_number,
            revision=revision
        ).first()
        
        # Check if part was received - either qc_approved is True, or qty_approved > 0 (for parts received before the fix)
        if not qc_item:
            return jsonify({'success': False, 'error': f'Part {part_number} REV{revision} has no QC data'}), 400
        
        # Allow undo if qc_approved is True OR if qty_approved > 0 (handles parts received before the fix)
        is_received = qc_item.qc_approved or (qc_item.qty_approved and qc_item.qty_approved > 0)
        if not is_received:
            return jsonify({'success': False, 'error': f'Part {part_number} REV{revision} is not marked as received'}), 400
        
        # Find the master part record (with backward-compatible fallback)
        part, used_fallback = resolve_part_with_fallback(part_number, revision)

        # Subtract from inventory if part exists in Part table
        if part:
            if used_fallback:
                print(f"INFO: Undo resolved {part_number} REV{revision} -> REV{part.revision} (backward compatible)")
            qty_to_subtract = qc_item.qty_approved if qc_item.qty_approved is not None else po_item.quantity
            current_inventory = part.inventory or 0
            new_inventory = max(0, current_inventory - qty_to_subtract)
            part.inventory = new_inventory
            print(f"DEBUG: Subtracted from inventory for {part_number}: {current_inventory} - {qty_to_subtract} = {new_inventory}")
        else:
            # Part not in Part table - just log a warning but continue with undo
            print(f"WARNING: Part {part_number} REV{revision} not found (no compatible revision) - skipping inventory update but still removing QC item")

        # Delete the QC item from the database since the part is no longer received
        db.session.delete(qc_item)
        print(f"DEBUG: Deleted QC item for {part_number} REV{revision} - part is no longer in received state")

        db.session.commit()

        # Propagate the inventory change to parent assemblies
        if part:
            try:
                update_assembly_inventories_for_part(part.id)
            except Exception as e:
                print(f"Warning: Error updating assembly inventories after part undo: {e}")

        # Log the action
        log_action('PO_UPDATE', current_user,
                   f'PO ID: {po_id}, PO Number: {po.po_number}, Undo part received: {part_number} REV{revision}, Inventory subtracted')
        
        return jsonify({
            'success': True,
            'message': f'Part {part_number} REV{revision} received status undone and inventory updated'
        })
    except Exception as e:
        db.session.rollback()
        print(f"Error undoing part received: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

