@app.route('/api/user-settings', methods=['PUT'])
@login_required
def update_user_settings():
    """Allow users to update their own profile and password"""
    try:
        data = request.json

        # Update profile fields
        if 'username' in data:
            new_username = data['username'].strip()
            if new_username and new_username != current_user.username:
                existing = User.query.filter(User.username == new_username, User.id != current_user.id).first()
                if existing:
                    return jsonify({'success': False, 'error': 'Username already taken'}), 400
                current_user.username = new_username

        if 'email' in data:
            new_email = data['email'].strip()
            if new_email and new_email != current_user.email:
                existing = User.query.filter(User.email == new_email, User.id != current_user.id).first()
                if existing:
                    return jsonify({'success': False, 'error': 'Email already taken'}), 400
                current_user.email = new_email

        if 'phone' in data:
            current_user.phone = data['phone'].strip() if data['phone'] else ''

        # Password change
        if data.get('new_password'):
            current_password = data.get('current_password', '')
            if not current_password:
                return jsonify({'success': False, 'error': 'Current password is required to change password'}), 400
            if not check_password_hash(current_user.password_hash, current_password):
                return jsonify({'success': False, 'error': 'Current password is incorrect'}), 400
            current_user.password_hash = generate_password_hash(data['new_password'])

        db.session.commit()

        log_action('USER_SETTINGS_UPDATE', current_user,
                   f'User {current_user.username} updated their settings')

        return jsonify({
            'success': True,
            'message': 'Settings updated successfully',
            'user': {
                'id': current_user.id,
                'username': current_user.username,
                'email': current_user.email,
                'role': current_user.role,
                'phone': current_user.phone
            }
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/qc_data', methods=['GET'])
@login_required
def get_po_qc_data(po_id):
    """Get QC data for a PO"""
    try:
        po = PO.query.get_or_404(po_id)
        qc_items = POQCItem.query.filter_by(po_id=po_id).all()

        qc_data = []
        for qc_item in qc_items:
            # Check if this part exists at the exact revision in the Part table
            part_exists = Part.query.filter_by(
                part_number=qc_item.part_number,
                revision=qc_item.revision
            ).first() is not None

            has_compatible_fallback = False
            if not part_exists:
                fallback_part, _ = resolve_part_with_fallback(qc_item.part_number, qc_item.revision)
                has_compatible_fallback = fallback_part is not None

            qc_data.append({
                'id': qc_item.id,
                'po_item_id': qc_item.po_item_id,
                'part_number': qc_item.part_number,
                'revision': qc_item.revision,
                'quantity_in_po': qc_item.quantity_in_po,
                'qty_arrived': qc_item.qty_arrived,
                'qty_approved': qc_item.qty_approved,
                'qc_approved': qc_item.qc_approved,
                'warehouse_box_number': qc_item.warehouse_box_number,
                'notes': qc_item.notes,
                'created_at': qc_item.created_at.isoformat() if qc_item.created_at else None,
                'part_exists': part_exists,
                'has_compatible_fallback': has_compatible_fallback
            })

        return jsonify({
            'success': True,
            'qc_data': qc_data,
            'has_qc_data': len(qc_data) > 0
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/revision_mismatches', methods=['GET'])
@login_required
def get_po_revision_mismatches(po_id):
    """Detect revision mismatches between PO items and latest Part revisions in the BOM."""
    try:
        po = PO.query.get_or_404(po_id)
        po_items = POItem.query.filter_by(po_id=po_id).all()

        mismatches = []
        for po_item in po_items:
            # Find exact match part
            exact_part = Part.query.filter_by(
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()

            # Find the latest active revision of this part
            latest_part = Part.query.filter_by(
                part_number=po_item.part_number
            ).filter(Part.status != 'obsolete').order_by(Part.revision.desc()).first()

            if not latest_part:
                continue

            latest_rev = latest_part.revision
            po_rev = po_item.revision

            # Check if there's a mismatch
            if latest_rev != po_rev:
                mismatches.append({
                    'part_number': po_item.part_number,
                    'po_revision': po_rev,
                    'latest_revision': latest_rev,
                    'po_item_id': po_item.id,
                    'exact_match_exists': exact_part is not None,
                    'latest_part_id': latest_part.id,
                    'part_type': latest_part.part_type,
                    'backward_compatible': latest_part.backward_compatible if latest_part.backward_compatible is not None else True,
                    'part_name': latest_part.part_name or po_item.part_number,
                })

        return jsonify({
            'success': True,
            'mismatches': mismatches,
            'total_items': len(po_items),
            'mismatch_count': len(mismatches)
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/qc_data', methods=['POST'])
@login_required
def save_po_qc_data(po_id):
    """Save QC data for a PO (without marking as received)"""
    try:
        po = PO.query.get_or_404(po_id)
        qc_data = request.json.get('qc_data', []) if request.json else []
        
        if not qc_data:
            return jsonify({'success': False, 'error': 'No QC data provided'}), 400
        
        # Save or update QC items
        for qc_item_data in qc_data:
            qc_item = POQCItem.query.filter_by(
                po_id=po_id,
                part_number=qc_item_data.get('part_number'),
                revision=qc_item_data.get('revision')
            ).first()
            
            # Find corresponding po_item (for child POs, items belong to parent)
            search_po_id = po_id
            if po.parent_po_id:
                search_po_id = po.parent_po_id
            po_item = POItem.query.filter_by(
                po_id=search_po_id,
                part_number=qc_item_data.get('part_number'),
                revision=qc_item_data.get('revision')
            ).first()
            
            if not qc_item:
                qc_item = POQCItem(
                    po_id=po_id,
                    po_item_id=po_item.id if po_item else None,
                    part_number=qc_item_data.get('part_number'),
                    revision=qc_item_data.get('revision'),
                    quantity_in_po=qc_item_data.get('quantity_in_po', 0)
                )
                db.session.add(qc_item)
            
            # Update QC item
            # Never downgrade qc_approved from True to False - once approved, only undo_part_received can reset it
            new_qc_approved = qc_item_data.get('qc_approved', False)
            if qc_item.qc_approved and not new_qc_approved:
                # Item was already approved (received) - don't overwrite its approval or qty values
                # Only update non-destructive fields
                qc_item.warehouse_box_number = qc_item_data.get('warehouse_box_number', '') or qc_item.warehouse_box_number
                qc_item.notes = qc_item_data.get('notes', '') or qc_item.notes
            else:
                qc_item.qty_arrived = qc_item_data.get('qty_arrived', qc_item.quantity_in_po)
                qc_item.qty_approved = qc_item_data.get('qty_approved', qc_item.quantity_in_po)
                qc_item.qc_approved = new_qc_approved
                qc_item.warehouse_box_number = qc_item_data.get('warehouse_box_number', '')
                qc_item.notes = qc_item_data.get('notes', '')
        
        # Also update warehouse_box_number on the Part table for all items that have one
        for qc_item_data in qc_data:
            wbox = (qc_item_data.get('warehouse_box_number') or '').strip()
            if wbox:
                part = Part.query.filter_by(
                    part_number=qc_item_data.get('part_number'),
                    revision=qc_item_data.get('revision')
                ).first()
                if part and part.warehouse_box_number != wbox:
                    part.warehouse_box_number = wbox

        db.session.commit()
        return jsonify({'success': True, 'message': 'QC data saved successfully'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/remaining_quantities', methods=['GET'])
@login_required
def get_remaining_quantities(po_id):
    """Get remaining quantities for a parent PO across all deliveries"""
    try:
        # Expire all cached objects to ensure fresh data from database
        db.session.expire_all()

        po = PO.query.get_or_404(po_id)
        print(f"DEBUG remaining_quantities: Called with po_id={po_id}, po.parent_po_id={po.parent_po_id}")

        # Determine the parent PO
        parent_po = po
        if po.parent_po_id:
            parent_po = PO.query.get(po.parent_po_id)
            if not parent_po:
                return jsonify({'success': False, 'error': 'Parent PO not found'}), 404

        print(f"DEBUG remaining_quantities: Parent PO id={parent_po.id}, number={parent_po.po_number}")

        # Get parent PO items (source of truth for total quantities)
        parent_items = parent_po.po_items
        print(f"DEBUG remaining_quantities: Parent has {len(parent_items)} items")

        # Get all child POs (deliveries)
        child_pos = PO.query.filter_by(parent_po_id=parent_po.id).all()
        print(f"DEBUG remaining_quantities: Found {len(child_pos)} child POs: {[(c.id, c.po_number) for c in child_pos]}")

        # Aggregate qty_approved across ALL deliveries where qc_approved=True
        cumulative_received = {}  # part_key -> total qty_approved

        for child in child_pos:
            qc_items = POQCItem.query.filter_by(po_id=child.id).all()
            print(f"DEBUG remaining_quantities: Child PO {child.id} ({child.po_number}) has {len(qc_items)} QC items")
            for qc_item in qc_items:
                print(f"  QC item: {qc_item.part_number} REV{qc_item.revision} - qc_approved={qc_item.qc_approved}, qty_approved={qc_item.qty_approved}")
                if qc_item.qc_approved:
                    key = f"{qc_item.part_number}_{qc_item.revision}"
                    cumulative_received[key] = cumulative_received.get(key, 0) + (qc_item.qty_approved or 0)

        # Also check parent PO itself for QC data (backward compatibility)
        parent_qc_items = POQCItem.query.filter_by(po_id=parent_po.id).all()
        for qc_item in parent_qc_items:
            if qc_item.qc_approved:
                key = f"{qc_item.part_number}_{qc_item.revision}"
                cumulative_received[key] = cumulative_received.get(key, 0) + (qc_item.qty_approved or 0)

        print(f"DEBUG remaining_quantities: Cumulative received: {cumulative_received}")

        # Build result: for each parent item, show original qty, total received, remaining
        remaining = []
        all_fulfilled = True
        for item in parent_items:
            key = f"{item.part_number}_{item.revision}"
            total_ordered = item.quantity
            total_received = cumulative_received.get(key, 0)
            qty_remaining = max(0, total_ordered - total_received)

            if qty_remaining > 0:
                all_fulfilled = False

            remaining.append({
                'part_number': item.part_number,
                'revision': item.revision,
                'total_ordered': total_ordered,
                'total_received': total_received,
                'qty_remaining': qty_remaining
            })
            print(f"DEBUG remaining_quantities: {item.part_number} REV{item.revision}: ordered={total_ordered}, received={total_received}, remaining={qty_remaining}")

        response = jsonify({
            'success': True,
            'parent_po_id': parent_po.id,
            'remaining': remaining,
            'all_fulfilled': all_fulfilled,
            'delivery_count': len(child_pos)
        })
        # Prevent browser caching so each delivery gets fresh data
        response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        response.headers['Pragma'] = 'no-cache'
        return response
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/refresh_part_revision', methods=['POST'])
@login_required
def refresh_part_revision(po_id):
    """Update a PO part's revision to the latest revision found in the Part table"""
    try:
        po = PO.query.get_or_404(po_id)
        data = request.get_json()
        part_number = data.get('part_number')
        old_revision = data.get('old_revision')

        if not part_number or not old_revision:
            return jsonify({'success': False, 'error': 'part_number and old_revision are required'}), 400

        # Determine parent PO for POItem lookup
        parent_po_id = po.parent_po_id or po.id

        # Find the POItem on the parent PO
        po_item = POItem.query.filter_by(
            po_id=parent_po_id,
            part_number=part_number,
            revision=old_revision
        ).first()

        if not po_item:
            return jsonify({'success': False, 'error': f'POItem {part_number} REV{old_revision} not found'}), 404

        # Find the latest Part record for this part_number (any revision)
        all_parts = Part.query.filter(
            Part.part_number == part_number,
            Part.status == 'active'
        ).all()

        if not all_parts:
            return jsonify({'success': False, 'error': f'No active Part records found for {part_number}'}), 404

        # Sort by revision number descending to get the latest
        def rev_sort_key(p):
            try:
                return int(normalize_revision(p.revision).replace('REV', ''))
            except (ValueError, TypeError):
                return 0

        all_parts.sort(key=rev_sort_key, reverse=True)
        latest_part = all_parts[0]
        new_revision = latest_part.revision

        if new_revision == old_revision:
            return jsonify({'success': False, 'error': f'{part_number} is already at the latest revision ({old_revision})'}), 400

        # Update POItem revision
        po_item.revision = new_revision
        print(f"INFO: Updated POItem {part_number} revision: {old_revision} -> {new_revision}")

        # Update all QC items across all child POs (and the parent PO itself)
        all_po_ids = [parent_po_id]
        child_pos = PO.query.filter_by(parent_po_id=parent_po_id).all()
        for child in child_pos:
            all_po_ids.append(child.id)

        qc_updated = 0
        for pid in all_po_ids:
            qc_items = POQCItem.query.filter_by(
                po_id=pid,
                part_number=part_number,
                revision=old_revision
            ).all()
            for qc_item in qc_items:
                qc_item.revision = new_revision
                qc_updated += 1

        db.session.commit()

        print(f"INFO: Refreshed {part_number} from {old_revision} to {new_revision} (POItem + {qc_updated} QC items)")

        return jsonify({
            'success': True,
            'new_revision': new_revision,
            'part_name': latest_part.part_name,
            'qc_items_updated': qc_updated
        })
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/pos/<int:po_id>/qc_data/export', methods=['GET'])
@login_required
def export_po_qc_data(po_id):
    """Export QC data to Excel"""
    try:
        po = PO.query.get_or_404(po_id)
        qc_items = POQCItem.query.filter_by(po_id=po_id).all()
        
        if not qc_items:
            return jsonify({'success': False, 'error': 'No QC data found for this PO'}), 404
        
        # Create Excel workbook
        wb = Workbook()
        ws = wb.active
        ws.title = "QC Data"
        
        # Headers
        headers = [
            'Part Number', 'Revision', 'Quantity in PO', 'QTY Arrived', 'QTY Approved', 'QC Approved', 
            'Warehouse Box Number', 'Notes', 'Created At'
        ]
        
        # Write headers
        for col, header in enumerate(headers, 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.font = Font(bold=True)
            cell.fill = PatternFill(start_color="CCCCCC", end_color="CCCCCC", fill_type="solid")
            cell.alignment = Alignment(horizontal='center', vertical='center')
        
        # Write data
        for row, qc_item in enumerate(qc_items, 2):
            ws.cell(row=row, column=1, value=qc_item.part_number)
            ws.cell(row=row, column=2, value=qc_item.revision)
            ws.cell(row=row, column=3, value=qc_item.quantity_in_po)
            ws.cell(row=row, column=4, value=qc_item.qty_arrived or qc_item.quantity_in_po)
            ws.cell(row=row, column=5, value=qc_item.qty_approved or qc_item.quantity_in_po)
            ws.cell(row=row, column=6, value='Yes' if qc_item.qc_approved else 'No')
            ws.cell(row=row, column=7, value=qc_item.warehouse_box_number or '')
            ws.cell(row=row, column=8, value=qc_item.notes or '')
            ws.cell(row=row, column=9, value=qc_item.created_at.strftime('%Y-%m-%d %H:%M:%S') if qc_item.created_at else '')
        
        # Auto-adjust column widths
        for col in range(1, len(headers) + 1):
            column_letter = get_column_letter(col)
            ws.column_dimensions[column_letter].width = 20
        
        # Save to BytesIO
        excel_buffer = BytesIO()
        wb.save(excel_buffer)
        excel_buffer.seek(0)
        
        # Return as download
        return send_file(
            excel_buffer,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=f'PO_{po.po_number}_QC_Data.xlsx'
        )
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

# Part Classification Rule Management API
@app.route('/api/admin/part-classifier/rules', methods=['GET', 'POST'])
@admin_panel_required
def part_classifier_rules():
    """Get all classification rules or create a new one"""
    if request.method == 'GET':
        try:
            rules = PartClassificationRule.query.order_by(
                PartClassificationRule.part_type,
                PartClassificationRule.priority,
                PartClassificationRule.keyword
            ).all()
            return jsonify([{
                'id': rule.id,
                'part_type': rule.part_type,
                'keyword': rule.keyword,
                'classification_method': rule.classification_method,
                'priority': rule.priority,
                'is_active': rule.is_active,
                'created_at': rule.created_at.isoformat(),
                'created_by': rule.created_by
            } for rule in rules])
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)}), 500
    
    elif request.method == 'POST':
        try:
            data = request.json
            part_type = (data.get('part_type') or '').strip()
            keyword = (data.get('keyword') or '').strip()
            classification_method = data.get('classification_method', 'keyword')
            is_active = data.get('is_active', True)
            
            if not part_type or not keyword:
                return jsonify({'success': False, 'error': 'Part type and keyword are required'}), 400
            
            # Validate that part type exists in PartType table
            part_type_obj = PartType.query.filter_by(name=part_type, is_active=True).first()
            if not part_type_obj:
                return jsonify({'success': False, 'error': f'Part type "{part_type}" does not exist. Please create it first in Part Types management.'}), 400
            
            # Check for duplicate keyword for same part type
            existing = PartClassificationRule.query.filter_by(
                part_type=part_type,
                keyword=keyword
            ).first()
            if existing:
                return jsonify({'success': False, 'error': 'This keyword already exists for this part type'}), 400
            
            # Auto-assign priority based on existing rules count for this part type
            existing_count = PartClassificationRule.query.filter_by(part_type=part_type).count()
            auto_priority = existing_count * 10 + 10  # Auto-increment by 10
            
            rule = PartClassificationRule(
                part_type=part_type,
                keyword=keyword,
                classification_method=classification_method,
                priority=auto_priority,
                is_active=is_active,
                created_by=current_user.id
            )
            db.session.add(rule)
            db.session.commit()
            
            # Reload classifier rules
            from part_classifier import part_classifier
            part_classifier.reload_rules(db.session)
            
            log_action('CREATE_CLASSIFICATION_RULE', current_user,
                      f'Created classification rule: {keyword} -> {part_type}')
            
            return jsonify({
                'success': True,
                'rule': {
                    'id': rule.id,
                    'part_type': rule.part_type,
                    'keyword': rule.keyword,
                    'classification_method': rule.classification_method,
                    'priority': rule.priority,
                    'is_active': rule.is_active
                }
            }), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/admin/part-classifier/rules/<int:rule_id>', methods=['PUT', 'DELETE'])
@admin_panel_required
def part_classifier_rule(rule_id):
    """Update or delete a classification rule"""
    rule = PartClassificationRule.query.get_or_404(rule_id)
    
    if request.method == 'PUT':
        try:
            data = request.json
            if 'part_type' in data:
                new_part_type = data['part_type'].strip()
                # Validate that part type exists in PartType table
                part_type_obj = PartType.query.filter_by(name=new_part_type, is_active=True).first()
                if not part_type_obj:
                    return jsonify({'success': False, 'error': f'Part type "{new_part_type}" does not exist. Please create it first in Part Types management.'}), 400
                rule.part_type = new_part_type
            if 'keyword' in data:
                rule.keyword = data['keyword'].strip()
            if 'classification_method' in data:
                rule.classification_method = data['classification_method']
            if 'is_active' in data:
                rule.is_active = data['is_active']
            if 'priority' in data:
                rule.priority = data['priority']
            
            rule.updated_at = datetime.utcnow()
            db.session.commit()
            
            # Reload classifier rules
            from part_classifier import part_classifier
            part_classifier.reload_rules(db.session)
            
            log_action('UPDATE_CLASSIFICATION_RULE', current_user,
                      f'Updated classification rule {rule_id}: {rule.keyword} -> {rule.part_type}')
            
            return jsonify({
                'success': True,
                'rule': {
                    'id': rule.id,
                    'part_type': rule.part_type,
                    'keyword': rule.keyword,
                    'classification_method': rule.classification_method,
                    'priority': rule.priority,
                    'is_active': rule.is_active
                }
            })
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500
    
    elif request.method == 'DELETE':
        try:
            keyword = rule.keyword
            part_type = rule.part_type
            db.session.delete(rule)
            db.session.commit()
            
            # Reload classifier rules
            from part_classifier import part_classifier
            part_classifier.reload_rules(db.session)
            
            log_action('DELETE_CLASSIFICATION_RULE', current_user,
                      f'Deleted classification rule: {keyword} -> {part_type}')
            
            return jsonify({'success': True})
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500

# Part Types Management API
@app.route('/api/admin/part-types', methods=['GET', 'POST'])
@admin_panel_required
def part_types():
    """Get all managed part types or create a new one"""
    if request.method == 'GET':
        try:
            part_types = PartType.query.filter_by(is_active=True).order_by(PartType.name).all()
            
            # Get part counts for each type
            type_data = []
            for pt in part_types:
                part_count = Part.query.filter_by(part_type=pt.name).count()
                type_data.append({
                    'id': pt.id,
                    'name': pt.name,
                    'color': pt.color or '#6c757d',
                    'part_count': part_count,
                    'created_at': pt.created_at.isoformat() if pt.created_at else None,
                    'updated_at': pt.updated_at.isoformat() if pt.updated_at else None,
                    'created_by': pt.created_by
                })
            
            return jsonify(type_data)
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)}), 500
    
    elif request.method == 'POST':
        try:
            data = request.json
            name = (data.get('name') or '').strip()
            color = (data.get('color') or '#6c757d').strip()
            
            if not name:
                return jsonify({'success': False, 'error': 'Part type name is required'}), 400
            
            # Check for duplicate
            existing = PartType.query.filter_by(name=name).first()
            if existing:
                if existing.is_active:
                    return jsonify({'success': False, 'error': 'Part type with this name already exists'}), 400
                else:
                    # Reactivate soft-deleted type
                    existing.is_active = True
                    existing.updated_at = datetime.utcnow()
                    db.session.commit()
                    log_action('CREATE_PART_TYPE', current_user,
                              f'Reactivated part type: {name}')
                    return jsonify({
                        'success': True,
                        'part_type': {
                            'id': existing.id,
                            'name': existing.name,
                            'color': existing.color or '#6c757d',
                            'part_count': Part.query.filter_by(part_type=existing.name).count()
                        }
                    }), 200
            
            part_type = PartType(
                name=name,
                color=color,
                created_by=current_user.id
            )
            db.session.add(part_type)
            db.session.commit()
            
            log_action('CREATE_PART_TYPE', current_user,
                      f'Created part type: {name}')
            
            return jsonify({
                'success': True,
                'part_type': {
                    'id': part_type.id,
                    'name': part_type.name,
                    'color': part_type.color or '#6c757d',
                    'part_count': 0
                }
            }), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/admin/part-types/<int:type_id>', methods=['PUT', 'DELETE'])
@admin_panel_required
def part_type_item(type_id):
    """Update (rename) or delete a part type"""
    part_type = PartType.query.get_or_404(type_id)
    
    if request.method == 'PUT':
        try:
            data = request.json
            new_name = (data.get('name') or '').strip()
            new_color = (data.get('color') or '').strip()
            
            if not new_name:
                return jsonify({'success': False, 'error': 'Part type name is required'}), 400
            
            # Prevent renaming "Unknown" type
            if part_type.name == 'Unknown':
                return jsonify({'success': False, 'error': 'Cannot rename the "Unknown" part type'}), 400
            
            # Check for duplicate (excluding current type)
            existing = PartType.query.filter(
                PartType.name == new_name,
                PartType.id != type_id
            ).first()
            if existing:
                return jsonify({'success': False, 'error': 'Part type with this name already exists'}), 400
            
            old_name = part_type.name
            part_type.name = new_name
            if new_color:
                part_type.color = new_color
            part_type.updated_at = datetime.utcnow()
            
            # Update all Part records with the old type name
            parts_updated = Part.query.filter_by(part_type=old_name).update(
                {'part_type': new_name}, synchronize_session=False
            )
            
            # Update all PartClassificationRule records referencing the old type
            rules_updated = PartClassificationRule.query.filter_by(part_type=old_name).update(
                {'part_type': new_name}, synchronize_session=False
            )
            
            db.session.commit()
            
            log_action('UPDATE_PART_TYPE', current_user,
                      f'Renamed part type from "{old_name}" to "{new_name}" (updated {parts_updated} parts, {rules_updated} rules)')
            
            # Reload classifier rules
            from part_classifier import part_classifier
            part_classifier.reload_rules(db.session)
            
            return jsonify({
                'success': True,
                'part_type': {
                    'id': part_type.id,
                    'name': part_type.name,
                    'color': part_type.color or '#6c757d',
                    'part_count': Part.query.filter_by(part_type=new_name).count()
                },
                'parts_updated': parts_updated,
                'rules_updated': rules_updated
            })
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500
    
    elif request.method == 'DELETE':
        try:
            # Prevent deleting "Unknown" type
            if part_type.name == 'Unknown':
                return jsonify({'success': False, 'error': 'Cannot delete the "Unknown" part type'}), 400
            
            type_name = part_type.name
            part_count = Part.query.filter_by(part_type=type_name).count()
            
            # Get Unknown type (must exist)
            unknown_type = PartType.query.filter_by(name='Unknown').first()
            if not unknown_type:
                # Create Unknown type if it doesn't exist
                unknown_type = PartType(name='Unknown', created_by=current_user.id)
                db.session.add(unknown_type)
                db.session.flush()
            
            # Reassign all parts to Unknown
            if part_count > 0:
                Part.query.filter_by(part_type=type_name).update(
                    {'part_type': 'Unknown'}, synchronize_session=False
                )
            
            # Delete or deactivate classification rules referencing this type
            rules_to_delete = PartClassificationRule.query.filter_by(part_type=type_name).all()
            for rule in rules_to_delete:
                db.session.delete(rule)
            
            # Soft delete the type
            part_type.is_active = False
            part_type.updated_at = datetime.utcnow()
            
            db.session.commit()
            
            log_action('DELETE_PART_TYPE', current_user,
                      f'Deleted part type: {type_name} (reassigned {part_count} parts to Unknown, deleted {len(rules_to_delete)} rules)')
            
            # Reload classifier rules
            from part_classifier import part_classifier
            part_classifier.reload_rules(db.session)
            
            return jsonify({
                'success': True,
                'parts_reassigned': part_count,
                'rules_deleted': len(rules_to_delete)
            })
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/admin/part-types/migrate', methods=['POST'])
@admin_panel_required
def migrate_part_types():
    """Migration endpoint to populate PartType table from existing Part.part_type values"""
    try:
        # Get all distinct part types from Part table
        existing_types = db.session.query(Part.part_type).distinct().filter(
            Part.part_type.isnot(None),
            Part.part_type != ''
        ).all()
        
        type_names = [t[0] for t in existing_types if t[0]]
        created_count = 0
        skipped_count = 0
        
        # Default colors for common part types
        default_colors = {
            'Assembly': '#1976d2',
            'Mechanical part': '#7b1fa2',
            '3D Printing part': '#f57c00',
            'OTS': '#0097a7',
            'Inhouse electrical part': '#388e3c',
            'External electrical part': '#388e3c',
            'Bearings': '#c2185b',
            'Cross Roller Bearings': '#c2185b',
            'Fasteners': '#689f38',
            'Cables': '#00796b',
            'Motors': '#f9a825',
            'Gears': '#7b1fa2',
            'Unknown': '#6c757d'
        }
        
        # Ensure "Unknown" exists
        unknown_type = PartType.query.filter_by(name='Unknown').first()
        if not unknown_type:
            unknown_type = PartType(name='Unknown', color=default_colors.get('Unknown', '#6c757d'), created_by=current_user.id)
            db.session.add(unknown_type)
            created_count += 1
        
        # Create PartType records for each unique type
        for type_name in type_names:
            existing = PartType.query.filter_by(name=type_name).first()
            if not existing:
                color = default_colors.get(type_name, '#6c757d')
                part_type = PartType(name=type_name, color=color, created_by=current_user.id)
                db.session.add(part_type)
                created_count += 1
            else:
                # Update color if it doesn't have one
                if not existing.color and type_name in default_colors:
                    existing.color = default_colors[type_name]
                skipped_count += 1
        
        db.session.commit()
        
        log_action('MIGRATE_PART_TYPES', current_user,
                  f'Migrated part types: {created_count} created, {skipped_count} already existed')
        
        return jsonify({
            'success': True,
            'created': created_count,
            'skipped': skipped_count,
            'total_types': len(type_names) + (1 if not unknown_type else 0)
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

