@app.route('/api/admin/vendor-list/unmatched', methods=['GET'])
@require_any_role('admin', 'engineer', 'finance', 'floor_manager', 'system')
def vendor_list_unmatched():
    """Return distinct Part.vendor strings that don't match any VendorList entry, with fuzzy suggestions."""
    import difflib
    canonical = [v.name for v in VendorList.query.order_by(VendorList.name).all()]
    canonical_set = set(canonical)

    rows = (db.session.query(Part.vendor, db.func.count(Part.id).label('cnt'))
            .filter(Part.vendor != None, Part.vendor != '')
            .group_by(Part.vendor)
            .all())

    unmatched = []
    for vendor_string, cnt in rows:
        if vendor_string not in canonical_set:
            suggestions = difflib.get_close_matches(vendor_string, canonical, n=3, cutoff=0.4)
            unmatched.append({
                'vendor_string': vendor_string,
                'parts_count': cnt,
                'suggestions': suggestions
            })

    unmatched.sort(key=lambda x: x['parts_count'], reverse=True)
    return jsonify({'success': True, 'unmatched': unmatched, 'canonical': canonical})


@app.route('/api/admin/vendor-list/bulk-remap', methods=['POST'])
@require_any_role('admin', 'engineer', 'finance', 'floor_manager', 'system')
def vendor_list_bulk_remap():
    """Bulk remap old Part.vendor strings to canonical VendorList names."""
    data = request.json
    mappings = data.get('mappings', [])  # [{old_string, new_name}, ...]
    if not mappings:
        return jsonify({'success': False, 'error': 'No mappings provided'}), 400

    total_parts = 0
    try:
        for mapping in mappings:
            old_string = (mapping.get('old_string') or '').strip()
            new_name = (mapping.get('new_name') or '').strip()
            if not old_string or not new_name:
                continue
            count = Part.query.filter(Part.vendor == old_string).update(
                {'vendor': new_name}, synchronize_session=False
            )
            VendorCategoryAssignment.query.filter(
                VendorCategoryAssignment.vendor_string == old_string
            ).update({'vendor_string': new_name}, synchronize_session=False)
            total_parts += count

        db.session.commit()
        log_action('BULK_REMAP_VENDORS', current_user,
                   f'Bulk remapped {len(mappings)} vendor strings, {total_parts} parts updated')
        return jsonify({'success': True, 'total_parts_updated': total_parts})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


