@app.route('/api/admin/part-classifier/rules/import', methods=['POST'])
@admin_panel_required
def import_classification_rules():
    """Import classification rules from JSON"""
    try:
        data = request.json
        rules_data = data.get('rules', [])
        
        if not rules_data:
            return jsonify({'success': False, 'error': 'No rules data provided'}), 400
        
        imported_count = 0
        skipped_count = 0
        errors = []
        
        for rule_data in rules_data:
            try:
                part_type = rule_(data.get('part_type') or '').strip()
                keyword = rule_(data.get('keyword') or '').strip()
                
                if not part_type or not keyword:
                    errors.append(f'Rule missing part_type or keyword: {rule_data}')
                    continue
                
                part_type_obj = PartType.query.filter_by(name=part_type, is_active=True).first()
                if not part_type_obj:
                    errors.append(f'Part type "{part_type}" does not exist for rule: {keyword}')
                    continue
                
                existing = PartClassificationRule.query.filter_by(
                    part_type=part_type,
                    keyword=keyword
                ).first()
                if existing:
                    skipped_count += 1
                    continue
                
                rule = PartClassificationRule(
                    part_type=part_type,
                    keyword=keyword,
                    classification_method=rule_data.get('classification_method', 'keyword'),
                    priority=rule_data.get('priority', 100),
                    is_active=rule_data.get('is_active', True),
                    created_by=current_user.id
                )
                db.session.add(rule)
                imported_count += 1
            except Exception as e:
                errors.append(f'Error importing rule: {str(e)}')
        
        db.session.commit()
        
        from part_classifier import part_classifier
        part_classifier.reload_rules(db.session)
        
        log_action('IMPORT_CLASSIFICATION_RULES', current_user,
                  f'Imported {imported_count} classification rules, skipped {skipped_count}')
        
        return jsonify({
            'success': True,
            'imported': imported_count,
            'skipped': skipped_count,
            'errors': errors
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

# Unused Parts Management
@app.route('/api/admin/unused-parts', methods=['GET'])
@admin_panel_required
def get_unused_parts():
    """Get all parts that are not referenced in any BOM"""
    try:
        # Query parts not referenced in any BOMPart — uses subquery instead of materializing ID list
        from sqlalchemy import not_

        used_subquery = db.session.query(BOMPart.part_id).distinct().subquery()
        unused_parts = db.session.query(Part).filter(
            ~Part.id.in_(db.session.query(used_subquery))
        ).all()
        
        print(f"DEBUG get_unused_parts: Found {len(unused_parts)} unused parts")
        
        # Convert to list of dictionaries
        parts_list = []
        for part in unused_parts:
            parts_list.append({
                'id': part.id,
                'part_number': part.part_number,
                'revision': part.revision,
                'part_name': part.part_name,
                'description': part.description,
                'part_type': part.part_type,
                'material': part.material,
                'state': part.state,
                'vendor': part.vendor,
                'manufacturer': part.manufacturer,
                'unit_cost': part.unit_cost,
                'created_at': part.created_at.isoformat() if part.created_at else None,
                'updated_at': part.updated_at.isoformat() if part.updated_at else None,
            })
        
        return jsonify({
            'success': True,
            'parts': parts_list,
            'count': len(parts_list)
        })
    except Exception as e:
        import traceback
        error_trace = traceback.format_exc()
        print(f"Error in get_unused_parts: {e}\n{error_trace}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/admin/unused-parts', methods=['DELETE'])
@admin_panel_required
def delete_unused_parts():
    """Delete unused parts (with safety check)"""
    try:
        data = request.json
        part_ids = data.get('part_ids', [])
        
        if not part_ids:
            return jsonify({'success': False, 'error': 'No part IDs provided'}), 400
        
        # Ensure part_ids is a list
        if not isinstance(part_ids, list):
            part_ids = [part_ids]
        
        # Safety check: Verify all parts are still unused before deletion
        used_part_ids = db.session.query(BOMPart.part_id).filter(
            BOMPart.part_id.in_(part_ids)
        ).distinct().all()
        used_part_ids = [pid[0] for pid in used_part_ids]
        
        if used_part_ids:
            return jsonify({
                'success': False,
                'error': f'Some parts are now in use and cannot be deleted. Part IDs: {used_part_ids}'
            }), 400
        
        # Get part details for logging
        parts_to_delete = Part.query.filter(Part.id.in_(part_ids)).all()
        part_numbers = [f'{p.part_number} REV{p.revision}' for p in parts_to_delete]
        
        # Delete the parts
        deleted_count = Part.query.filter(Part.id.in_(part_ids)).delete(synchronize_session=False)
        db.session.commit()
        
        # Log the action
        log_action('DELETE_UNUSED_PARTS', current_user,
                  f'Deleted {deleted_count} unused parts: {", ".join(part_numbers)}')
        
        return jsonify({
            'success': True,
            'deleted_count': deleted_count,
            'message': f'Successfully deleted {deleted_count} unused part(s)'
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

