@app.route('/api/currency/rates/update', methods=['POST'])
@admin_panel_required
def update_currency_rates():
    """Update exchange rates (from API or manual override)"""
    try:
        data = request.json
        target_currency = (data.get('target_currency') or '').strip().upper()
        rate = data.get('rate')
        source = data.get('source', 'manual')  # 'api' or 'manual'
        
        if not target_currency or rate is None:
            return jsonify({'success': False, 'error': 'target_currency and rate are required'}), 400
        
        if source == 'api':
            # Fetch from API
            fetched_rate = get_cached_or_fetch_rate(target_currency, 'USD')
            if fetched_rate:
                return jsonify({
                    'success': True,
                    'rate': fetched_rate,
                    'message': f'Updated {target_currency} rate from API'
                })
            else:
                return jsonify({'success': False, 'error': 'Failed to fetch rate from API'}), 500
        else:
            # Manual override
            try:
                rate_float = float(rate)
                if rate_float <= 0:
                    return jsonify({'success': False, 'error': 'Rate must be positive'}), 400
                
                cached_rate = CurrencyExchangeRate.query.filter_by(
                    base_currency='USD',
                    target_currency=target_currency
                ).first()
                
                if cached_rate:
                    cached_rate.rate = rate_float
                    cached_rate.last_updated = datetime.utcnow()
                    cached_rate.source = 'manual'
                else:
                    cached_rate = CurrencyExchangeRate(
                        base_currency='USD',
                        target_currency=target_currency,
                        rate=rate_float,
                        last_updated=datetime.utcnow(),
                        source='manual'
                    )
                    db.session.add(cached_rate)
                
                db.session.commit()
                
                log_action('UPDATE_EXCHANGE_RATE', current_user,
                          f'Manually updated {target_currency} rate to {rate_float}')
                
                return jsonify({
                    'success': True,
                    'rate': rate_float,
                    'message': f'Updated {target_currency} rate manually'
                })
            except ValueError:
                return jsonify({'success': False, 'error': 'Invalid rate value'}), 400
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/currency/convert', methods=['GET'])
@login_required
def convert_currency_api():
    """Convert amount between currencies"""
    try:
        amount = float(request.args.get('amount', 0))
        from_currency = request.args.get('from', 'USD').upper()
        to_currency = request.args.get('to', 'USD').upper()
        
        converted = convert_currency(amount, from_currency, to_currency)
        
        if converted is None:
            return jsonify({
                'success': False,
                'error': f'Could not convert {from_currency} to {to_currency}'
            }), 400
        
        return jsonify({
            'success': True,
            'amount': amount,
            'from_currency': from_currency,
            'to_currency': to_currency,
            'converted_amount': converted
        })
    except ValueError:
        return jsonify({'success': False, 'error': 'Invalid amount'}), 400
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

