@app.route('/api/admin/part-classifier/reclassify-all', methods=['POST'])
@admin_panel_required
def reclassify_all_parts():
    """Reclassify all parts in all BOMs based on current classification rules"""
    try:
        from part_classifier import part_classifier
        
        # Reload rules first
        part_classifier.reload_rules(db.session)
        
        # Get all parts
        all_parts = Part.query.all()
        updated_count = 0
        
        for part in all_parts:
            # Reclassify using current rules
            new_part_type = part_classifier.classify_part(
                part.part_number,
                part.state,
                part.description
            )
            
            # Update if classification changed
            if part.part_type != new_part_type:
                part.part_type = new_part_type
                updated_count += 1
        
        db.session.commit()
        
        log_action('RECLASSIFY_ALL_PARTS', current_user,
                  f'Reclassified {updated_count} parts')
        
        return jsonify({
            'success': True, 
            'message': f'Successfully reclassified {updated_count} parts',
            'updated_count': updated_count,
            'total_parts': len(all_parts)
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

# Project Badge Management API
@app.route('/api/badges', methods=['GET', 'POST'])
@login_required
def badges_api():
    """Project badge management API"""
    if request.method == 'GET':
        badges = ProjectBadge.query.filter_by(is_active=True).order_by(ProjectBadge.name).all()
        return jsonify([{
            'id': badge.id,
            'name': badge.name,
            'color': badge.color,
            'created_at': badge.created_at.isoformat(),
            'created_by': badge.created_by,
            'is_active': badge.is_active
        } for badge in badges])
    
    elif request.method == 'POST':
        # Only admins can create badges
        if not current_user.can_access_admin():
            return jsonify({'success': False, 'error': 'Only admins can create badges'}), 403
        
        data = request.json
        name = (data.get('name') or '').strip()
        color = data.get('color', '#1976d2')
        
        if not name:
            return jsonify({'success': False, 'error': 'Badge name is required'}), 400
        
        # Check for duplicate names
        if ProjectBadge.query.filter_by(name=name, is_active=True).first():
            return jsonify({'success': False, 'error': 'Badge name already exists'}), 400
        
        badge = ProjectBadge(
            name=name,
            color=color,
            created_by=current_user.id
        )
        db.session.add(badge)
        db.session.commit()
        
        # Log the action
        log_action('BADGE_CREATE', current_user, 
                   f'Badge ID: {badge.id}, Name: "{name}", Color: {color}')
        
        return jsonify({
            'success': True,
            'message': 'Badge created successfully',
            'badge': {
                'id': badge.id,
                'name': badge.name,
                'color': badge.color
            }
        })

@app.route('/api/badges/<int:badge_id>', methods=['PUT', 'DELETE'])
@admin_required
def badge_api(badge_id):
    """Update or delete a specific badge"""
    badge = ProjectBadge.query.get_or_404(badge_id)
    
    if request.method == 'PUT':
        data = request.json
        
        if 'name' in data:
            new_name = data['name'].strip()
            if not new_name:
                return jsonify({'success': False, 'error': 'Badge name cannot be empty'}), 400
            
            # Check for duplicate names (excluding current badge)
            if ProjectBadge.query.filter(ProjectBadge.name == new_name, ProjectBadge.id != badge_id, ProjectBadge.is_active == True).first():
                return jsonify({'success': False, 'error': 'Badge name already exists'}), 400
            
            badge.name = new_name
        
        if 'color' in data:
            badge.color = data['color']
        
        if 'is_active' in data:
            badge.is_active = data['is_active']
        
        db.session.commit()
        
        # Log the action
        log_action('BADGE_UPDATE', current_user, 
                   f'Badge ID: {badge_id}, Name: "{badge.name}", Color: {badge.color}')
        
        return jsonify({
            'success': True,
            'message': 'Badge updated successfully',
            'badge': {
                'id': badge.id,
                'name': badge.name,
                'color': badge.color,
                'is_active': badge.is_active
            }
        })
    
    elif request.method == 'DELETE':
        # Soft delete - mark as inactive
        badge_name = badge.name
        badge.is_active = False
        db.session.commit()
        
        # Log the action
        log_action('BADGE_DELETE', current_user, 
                   f'Badge ID: {badge_id}, Name: "{badge_name}" (marked inactive)')
        
        return jsonify({'success': True, 'message': 'Badge deleted successfully'})

@app.route('/api/pos/<int:po_id>/undo_received', methods=['POST'])
@login_required
def undo_po_received(po_id):
    """Undo PO received status (admin only) - subtract from inventory and order_qty"""
    try:
        # Check if user is admin
        if current_user.role != 'admin':
            return jsonify({'success': False, 'error': 'Only admin users can undo PO received status'}), 403
        
        po = PO.query.get_or_404(po_id)
        set_inventory_context('po_receive_undo', po.po_number)

        if not po.po_received:
            return jsonify({'success': False, 'error': 'PO is not marked as received'}), 400

        # A parent PO auto-received via its deliveries never added inventory itself —
        # undoing it here would double-subtract. Undo the individual deliveries instead.
        received_children = PO.query.filter_by(parent_po_id=po.id, po_received=True).count()
        if received_children:
            return jsonify({'success': False,
                            'error': 'This PO was received via deliveries. Undo the individual deliveries instead.'}), 400

        # Restore PO to its status before it was marked received
        po.status = po.pre_receive_status or 'sent_to_vendor'
        po.pre_receive_status = None
        po.po_received = False
        po.received_date = None
        
        # For child POs (deliveries), use parent PO's items instead
        po_items_to_process = po.po_items
        if po.parent_po_id:
            parent_po = PO.query.get(po.parent_po_id)
            if parent_po:
                po_items_to_process = parent_po.po_items
        
        # Check if this is a child PO (delivery)
        is_child_po = po.parent_po_id is not None
        
        # Subtract from inventory, order_qty, and remove PO from po_orders for all parts in this PO (master Part table only)
        for po_item in po_items_to_process:
            # Find the master part record (with backward-compatible fallback)
            part, used_fallback = resolve_part_with_fallback(po_item.part_number, po_item.revision)

            if not part:
                print(f"WARNING: Part {po_item.part_number} REV{po_item.revision} not found (no compatible revision)")
                continue
            if used_fallback:
                print(f"INFO: Undo resolved {po_item.part_number} REV{po_item.revision} -> REV{part.revision} (backward compatible)")

            # Get QC data to use the actual received quantity (qty_approved) if available
            qc_item = POQCItem.query.filter_by(
                po_id=po_id,
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            
            # Use qty_approved if available, otherwise use po_item.quantity
            qty_to_subtract = qc_item.qty_approved if qc_item and qc_item.qty_approved is not None else po_item.quantity
            
            # Subtract from inventory
            current_inventory = part.inventory or 0
            new_inventory = max(0, current_inventory - qty_to_subtract)
            part.inventory = new_inventory
            print(f"DEBUG: Subtracted from inventory for {po_item.part_number}: {current_inventory} - {qty_to_subtract} = {new_inventory}")
            
            # IMPORTANT: Child POs (deliveries) should NEVER subtract from order_qty
            # order_qty should only be updated for parent POs
            # Deliveries never added to order_qty, so they shouldn't subtract from it either
            if not is_child_po:
                # Only subtract from order_qty for parent POs
                current_order_qty = part.order_qty or 0
                new_order_qty = max(0, current_order_qty - qty_to_subtract)
                part.order_qty = new_order_qty
                print(f"DEBUG: Subtracted from order_qty for {po_item.part_number}: {current_order_qty} - {qty_to_subtract} = {new_order_qty}")
            else:
                # Child PO (delivery) - do NOT subtract from order_qty
                print(f"DEBUG: Skipping order_qty subtraction for {po_item.part_number} - this is a delivery (child PO), order_qty should not change")
            
            # Remove this PO from po_orders (comma-separated list)
            # For child POs, we don't add delivery PO numbers to po_orders, so nothing to remove
            # For parent POs, remove the PO number
            if not is_child_po:
                try:
                    existing_po_orders = (part.po_orders or '').strip()
                    if existing_po_orders:
                        # Parse existing PO numbers (comma-separated)
                        po_numbers = [p.strip() for p in existing_po_orders.split(',') if p.strip()]
                        # Remove current PO number
                        po_numbers = [p for p in po_numbers if p != po.po_number]
                        # Update po_orders (empty if no POs left)
                        part.po_orders = ', '.join(po_numbers) if po_numbers else None
                    else:
                        part.po_orders = None
                    print(f"DEBUG: Updated po_orders after undo for {po_item.part_number}: {part.po_orders}")
                except Exception as e:
                    print(f"ERROR: Failed to update po_orders on undo for {po_item.part_number}: {e}")
                    import traceback
                    traceback.print_exc()
            else:
                print(f"DEBUG: Skipping po_orders update for {po_item.part_number} - this is a delivery (child PO), delivery PO numbers are not tracked in po_orders")
            
            # Debug: Verify all updates before commit
            print(f"DEBUG: Part {po_item.part_number} before commit (undo) - inventory: {part.inventory}, order_qty: {part.order_qty}, po_orders: {part.po_orders}")
        
        # Debug: Check all parts before commit (undo)
        print("=" * 60)
        print("DEBUG: BEFORE COMMIT (UNDO) - Part status:")
        for po_item in po_items_to_process:
            part = Part.query.filter_by(
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            if part:
                print(f"  Part {po_item.part_number} REV{po_item.revision}:")
                print(f"    - inventory: {part.inventory}")
                print(f"    - order_qty: {part.order_qty}")
                print(f"    - po_orders: {part.po_orders}")
        
        # Reset all QC items' qc_approved to False so they don't show as received when modal reopens
        qc_items_to_reset = POQCItem.query.filter_by(po_id=po_id).all()
        for qc_item in qc_items_to_reset:
            if qc_item.qc_approved:
                qc_item.qc_approved = False
                print(f"DEBUG: Reset qc_approved to False for {qc_item.part_number} REV{qc_item.revision} on PO {po.po_number}")

        # If this is a child PO, also un-receive the parent PO if it was auto-received
        if po.parent_po_id:
            parent_po_for_undo = PO.query.get(po.parent_po_id)
            if parent_po_for_undo and parent_po_for_undo.po_received:
                parent_po_for_undo.status = parent_po_for_undo.pre_receive_status or 'sent_to_vendor'
                parent_po_for_undo.pre_receive_status = None
                parent_po_for_undo.po_received = False
                parent_po_for_undo.received_date = None
                print(f"DEBUG: Un-marking parent PO {parent_po_for_undo.po_number} as received since delivery was undone")

        print("=" * 60)
        print("DEBUG: Committing undo changes to database...")
        db.session.commit()
        print("DEBUG: Undo commit successful!")
        print("=" * 60)

        # Update assembly inventories for all parts in this PO
        try:
            for po_item in po_items_to_process:
                part = Part.query.filter_by(
                    part_number=po_item.part_number,
                    revision=po_item.revision
                ).first()
                if part:
                    update_assembly_inventories_for_part(part.id)
        except Exception as e:
            print(f"Warning: Error updating assembly inventories after PO undo: {e}")
            # Don't fail the whole request if this fails

        # Log the action
        items_count = len(po.po_items) if po.po_items else 0
        log_action('PO_UPDATE', current_user,
                   f'PO ID: {po_id}, PO Number: {po.po_number}, Undo received status, Items: {items_count}, Inventory/order_qty reverted')

        # Debug: Verify all parts after commit
        print("DEBUG: AFTER COMMIT (UNDO) - Verifying database state:")
        for po_item in po_items_to_process:
            part = Part.query.filter_by(
                part_number=po_item.part_number,
                revision=po_item.revision
            ).first()
            if part:
                print(f"  Part {po_item.part_number} REV{po_item.revision}:")
                print(f"    - inventory: {part.inventory}")
                print(f"    - order_qty: {part.order_qty}")
                print(f"    - po_orders: {part.po_orders}")
                print(f"    Undo completed successfully")
        print("=" * 60)

        return jsonify({'success': True, 'message': 'PO received status undone and inventory/order_qty updated'})
    except Exception as e:
        db.session.rollback()
        print(f"Error undoing PO received: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

