def cascade_price_updates(part_ids):
    """
    Cascade price updates through the BOM hierarchy.
    When a part price changes, update all BOMPart.price_per_bom entries,
    then recalculate assembly costs bottom-up.
    
    Returns:
        set: Set of affected assembly part numbers (part_number strings)
    """
    affected_assembly_part_numbers = set()
    
    try:
        # Step 1: Update all BOMPart.price_per_bom for the affected parts
        bom_parts = BOMPart.query.filter(BOMPart.part_id.in_(part_ids)).all()
        
        affected_boms = set()
        for bom_part in bom_parts:
            # Update price_per_bom = unit_cost × quantity
            bom_part.price_per_bom = (bom_part.part.unit_cost or 0) * bom_part.quantity
            affected_boms.add(bom_part.bom_id)
        
        # Also check if any of the updated parts ARE assemblies themselves
        # If so, we need to recalculate their BOM costs and add those BOMs to affected_boms
        for part_id in part_ids:
            part = Part.query.get(part_id)
            if part:
                # Check if this part is an assembly (has a BOMInstance)
                assembly_bom = BOMInstance.query.filter_by(
                    assembly_part_number=part.part_number,
                    assembly_revision=part.revision,
                    is_latest=True
                ).first()
                
                if assembly_bom:
                    # This part is an assembly, so we need to recalculate its cost
                    # Add its BOM to affected_boms so it gets recalculated
                    affected_boms.add(assembly_bom.id)
        
        db.session.commit()
        
        # Step 2: Recalculate assembly costs for affected BOMs
        # We need to process them in hierarchical order (bottom-up)
        processed_assemblies = set()
        
        def recalculate_assembly_cost(bom_id, depth=0):
            """Recursively calculate assembly cost bottom-up"""
            if depth > 10:  # Prevent infinite recursion
                return
            
            if bom_id in processed_assemblies:
                return
            
            bom = BOMInstance.query.get(bom_id)
            if not bom:
                return
            
            # Track this assembly as affected (it contains updated parts or is a parent)
            affected_assembly_part_numbers.add(bom.assembly_part_number)
            
            # First, check if this BOM contains any sub-assemblies
            # If so, calculate those first
            bom_parts = BOMPart.query.filter_by(bom_id=bom_id).all()
            
            # Get the main assembly part to exclude it from its own BOM calculation
            main_assembly_part = Part.query.filter_by(
                part_number=bom.assembly_part_number,
                revision=bom.assembly_revision
            ).first()
            main_assembly_part_id = main_assembly_part.id if main_assembly_part else None
            
            for bom_part in bom_parts:
                # Check if this part is an assembly
                sub_bom = BOMInstance.query.filter_by(
                    assembly_part_number=bom_part.part.part_number,
                    assembly_revision=bom_part.part.revision,
                    is_latest=True
                ).first()
                
                if sub_bom and sub_bom.id in affected_boms:
                    # Recursively calculate the sub-assembly first
                    recalculate_assembly_cost(sub_bom.id, depth + 1)
            
            # Now calculate this assembly's cost
            # EXCLUDE the main assembly part from its own BOM calculation to prevent double-counting
            total_cost = sum(
                (bp.price_per_bom or 0) for bp in bom_parts 
                if main_assembly_part_id is None or bp.part_id != main_assembly_part_id
            )
            
            # Update the Part.unit_cost for this assembly
            assembly_part = Part.query.filter_by(
                part_number=bom.assembly_part_number,
                revision=bom.assembly_revision
            ).first()
            
            if not assembly_part:
                # Try to find by part number only (without revision)
                assembly_part = Part.query.filter_by(
                    part_number=bom.assembly_part_number
                ).order_by(Part.revision.desc()).first()
            
            if assembly_part:
                # Always update the unit_cost, even if it's the same (ensures consistency)
                assembly_part.unit_cost = total_cost
                
                # This assembly's price changed, so update BOMParts that use it
                parent_bom_parts = BOMPart.query.filter_by(part_id=assembly_part.id).all()
                for parent_bp in parent_bom_parts:
                    parent_bp.price_per_bom = (assembly_part.unit_cost or 0) * parent_bp.quantity
                    affected_boms.add(parent_bp.bom_id)
            
            processed_assemblies.add(bom_id)
        
        # Process all affected BOMs
        # Use a while loop to handle newly discovered parent BOMs
        boms_to_process = list(affected_boms)
        processed_count = 0
        max_iterations = 100  # Safety limit to prevent infinite loops
        
        while processed_count < len(boms_to_process) and processed_count < max_iterations:
            bom_id = boms_to_process[processed_count]
            recalculate_assembly_cost(bom_id)
            processed_count += 1
            
            # Check if new BOMs were added during processing
            if len(affected_boms) > len(boms_to_process):
                # Add newly discovered BOMs to the processing list
                new_boms = affected_boms - set(boms_to_process)
                boms_to_process.extend(new_boms)
        
        db.session.commit()
        
        return affected_assembly_part_numbers
        
    except Exception as e:
        db.session.rollback()
        print(f"Error cascading price updates: {e}")
        raise


@app.route('/api/admin/bom-cost/sum-by-type', methods=['GET'])
@login_required
@require_any_role('admin', 'finance', 'system')
def get_cost_sum_by_type():
    """Get total cost sum grouped by part type"""
    try:
        # This is a bit complex because we need to sum (qty * unit_cost) for all parts in the selected BOMs
        # BUT the requirement says "sum prices from db, by the type".
        # If it means sum of all parts in DB by type, that's easy.
        # If it means sum of parts in selected BOMs by type, that's harder.
        # "I also want to add a section that can sum prices from db, by the type. in the same way"
        # "in the same way" implies selection.
        # Let's assume it means "Sum of all parts in the database of this type".
        
        part_type = request.args.get('type')
        if not part_type:
            return jsonify({'success': False, 'error': 'Type parameter required'}), 400
            
        # Get all parts of this type
        parts = Part.query.filter_by(part_type=part_type, status='active').all()
        
        total_sum = sum((part.unit_cost or 0) for part in parts)
        
        return jsonify({
            'success': True,
            'type': part_type,
            'total_sum': total_sum,
            'count': len(parts)
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

