@app.route('/api/admin/bom-cost/robot-config', methods=['GET'])
@login_required
@require_any_role('admin', 'finance', 'system')
def get_bom_cost_robot_config():
    """Get cost robot config with limbs (from dissolved BOMs) and robot image from Robot Assembly."""
    try:
        badge_id = request.args.get('badge_id', type=int)
        if not badge_id:
            return jsonify({'success': False, 'error': 'badge_id required'}), 400

        # Get robot image from Robot Assembly's RobotConfig
        ra_config = RobotConfig.query.filter_by(badge_id=badge_id, is_active=True).first()
        robot_image_path = ra_config.robot_image_path if ra_config else None
        robot_image_data = ra_config.robot_image_data if ra_config else None

        # Get CostRobotConfig for limb data
        config = CostRobotConfig.query.filter_by(badge_id=badge_id, is_active=True).first()
        if not config:
            # Return config with just the robot image (no limbs yet)
            if not ra_config:
                return jsonify({'success': True, 'config': None})
            return jsonify({
                'success': True,
                'config': {
                    'id': None,
                    'badge_id': badge_id,
                    'robot_image_path': robot_image_path,
                    'robot_image_data': robot_image_data,
                    'limbs': [],
                }
            })

        limbs = CostRobotLimb.query.filter_by(
            config_id=config.id, is_active=True
        ).order_by(CostRobotLimb.display_order).all()

        limbs_data = []
        for limb in limbs:
            mappings = LimbCostMapping.query.filter_by(limb_id=limb.id).all()
            assigned_items = []
            limb_total_cost = 0
            for m in mappings:
                if m.dissolved_bom_id:
                    dbom = DissolvedBOM.query.get(m.dissolved_bom_id)
                    if dbom:
                        parts = json.loads(dbom.dissolved_parts_json) if dbom.dissolved_parts_json else []
                        # Live price from Part table
                        cost = 0
                        for p in parts:
                            pn = p.get('part_number', '') or p.get('Part Number', '')
                            rev = p.get('revision', '') or p.get('Revision', '')
                            qty = p.get('quantity', 0) or p.get('QTY.', 0) or 0
                            live_part = Part.query.filter_by(part_number=pn, revision=rev).first() if pn else None
                            uc = (live_part.unit_cost or 0) if live_part else (p.get('unit_cost', 0) or 0)
                            cost += float(uc) * float(qty)
                        limb_total_cost += cost
                        assigned_items.append({
                            'type': 'dissolved',
                            'dissolved_bom_id': dbom.id,
                            'name': dbom.name,
                            'cost': round(cost, 2),
                        })
                elif m.bom_id:
                    bom = BOMInstance.query.get(m.bom_id)
                    if bom:
                        cost = bom.unit_cost or 0
                        limb_total_cost += cost
                        assigned_items.append({
                            'type': 'bom',
                            'bom_id': bom.id,
                            'name': f"{bom.description or bom.assembly_part_number} {bom.version or ''}".strip(),
                            'cost': round(cost, 2),
                        })

            limbs_data.append({
                'id': limb.id,
                'name': limb.name,
                'region_type': limb.region_type,
                'region_coords': json.loads(limb.region_coords) if limb.region_coords else None,
                'display_order': limb.display_order,
                'color': limb.color,
                'assigned_items': assigned_items,
                'total_cost': round(limb_total_cost, 2),
            })

        return jsonify({
            'success': True,
            'config': {
                'id': config.id,
                'badge_id': config.badge_id,
                'robot_image_path': robot_image_path,
                'robot_image_data': robot_image_data,
                'limbs': limbs_data,
            }
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


