@app.route('/api/admin/bom-cost/robot-config', methods=['POST'])
@login_required
@require_any_role('admin')
def create_cost_robot_config():
    """Create or update cost robot config (image upload)"""
    try:
        badge_id = request.form.get('badge_id', type=int) or (request.get_json() or {}).get('badge_id')
        if not badge_id:
            return jsonify({'success': False, 'error': 'badge_id required'}), 400

        config = CostRobotConfig.query.filter_by(badge_id=badge_id).first()
        if not config:
            config = CostRobotConfig(badge_id=badge_id, created_by=current_user.id if current_user else None)
            db.session.add(config)

        # Handle image upload
        if 'robot_image' in request.files:
            import base64
            file = request.files['robot_image']
            if file and file.filename:
                image_data = base64.b64encode(file.read()).decode('utf-8')
                config.robot_image_data = image_data
                config.robot_image_path = None
        elif request.is_json:
            data = request.get_json()
            if 'robot_image_data' in data:
                config.robot_image_data = data['robot_image_data']

        config.is_active = True
        db.session.commit()

        return jsonify({
            'success': True,
            'config': {
                'id': config.id,
                'badge_id': config.badge_id,
                'robot_image_path': config.robot_image_path,
                'has_image': bool(config.robot_image_data or config.robot_image_path),
            }
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


