@app.route('/api/admin/bom-cost/limbs', methods=['POST'])
@login_required
@require_any_role('admin')
def create_cost_robot_limb():
    """Create a new limb on the cost robot config"""
    try:
        data = request.get_json()
        badge_id = data.get('badge_id')
        name = (data.get('name') or '').strip()

        if not badge_id or not name:
            return jsonify({'success': False, 'error': 'badge_id and name required'}), 400

        config = CostRobotConfig.query.filter_by(badge_id=badge_id, is_active=True).first()
        if not config:
            return jsonify({'success': False, 'error': 'No cost robot config for this project'}), 404

        max_order = db.session.query(db.func.max(CostRobotLimb.display_order)).filter_by(config_id=config.id).scalar() or 0

        limb = CostRobotLimb(
            config_id=config.id,
            name=name,
            display_order=max_order + 1,
            color=data.get('color', '#4B2C6F'),
        )
        db.session.add(limb)
        db.session.commit()

        return jsonify({
            'success': True,
            'limb': {'id': limb.id, 'name': limb.name, 'display_order': limb.display_order, 'color': limb.color}
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


