@app.route('/api/admin/bom-cost/robot-overview', methods=['GET'])
@login_required
@require_any_role('admin', 'finance', 'system')
def get_bom_cost_robot_overview():
    """Get robot image (auto-detected from Robot Assembly) + all dissolved BOMs with polygon regions.
    No badge parameter needed — finds the first RobotConfig with an image."""
    try:
        # Find first RobotConfig that has an image
        ra_config = RobotConfig.query.filter(
            RobotConfig.is_active == True,
            db.or_(RobotConfig.robot_image_data != None, RobotConfig.robot_image_path != None)
        ).first()

        robot_image_data = ra_config.robot_image_data if ra_config else None
        robot_image_path = ra_config.robot_image_path if ra_config else None
        source_badge_id = ra_config.badge_id if ra_config else None

        # Get badge name for display
        source_badge_name = None
        if source_badge_id:
            badge = ProjectBadge.query.get(source_badge_id)
            source_badge_name = badge.name if badge else None

        # Get all dissolved BOMs with polygon data
        dissolved = DissolvedBOM.query.order_by(DissolvedBOM.name).all()
        items = []
        for d in dissolved:
            parts = json.loads(d.dissolved_parts_json) if d.dissolved_parts_json else []
            cost = 0
            for p in parts:
                pn = p.get('part_number', '') or p.get('Part Number', '')
                rev = p.get('revision', '') or p.get('Revision', '')
                qty = p.get('quantity', 0) or p.get('QTY.', 0) or 0
                live_part = Part.query.filter_by(part_number=pn, revision=rev).first() if pn else None
                uc = (live_part.unit_cost or 0) if live_part else (p.get('unit_cost', 0) or 0)
                cost += float(uc) * float(qty)

            # Find polygon region if any CostRobotLimb is linked to this dissolved BOM
            region_coords = None
            limb_id = None
            mapping = LimbCostMapping.query.filter_by(dissolved_bom_id=d.id).first()
            if mapping:
                limb = CostRobotLimb.query.get(mapping.limb_id)
                if limb and limb.region_coords:
                    region_coords = json.loads(limb.region_coords)
                    limb_id = limb.id

            items.append({
                'id': d.id,
                'name': d.name,
                'cost': round(cost, 2),
                'parts_count': len(parts),
                'limb_id': limb_id,
                'region_coords': region_coords,
            })

        return jsonify({
            'success': True,
            'robot_image_data': robot_image_data,
            'robot_image_path': robot_image_path,
            'source_badge_id': source_badge_id,
            'source_badge_name': source_badge_name,
            'dissolved_boms': items,
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


