@app.route('/api/admin/bom-cost/robot-figures', methods=['POST'])
@login_required
@require_any_role('admin')
def create_bom_cost_robot_figure():
    """Create a new robot figure: creates a ProjectBadge + RobotConfig with uploaded image."""
    try:
        import base64
        name = request.form.get('name', '').strip()
        if not name:
            return jsonify({'success': False, 'error': 'Name is required'}), 400

        # Check if badge name already exists
        existing_badge = ProjectBadge.query.filter_by(name=name).first()
        if existing_badge:
            # Check if it already has a RobotConfig with an image
            existing_config = RobotConfig.query.filter_by(badge_id=existing_badge.id, is_active=True).first()
            if existing_config and (existing_config.robot_image_data or existing_config.robot_image_path):
                return jsonify({'success': False, 'error': f'A robot figure for "{name}" already exists'}), 400
            badge = existing_badge
        else:
            badge = ProjectBadge(
                name=name,
                color=request.form.get('color', '#1976d2'),
                created_by=current_user.id if current_user else None,
                is_active=True,
            )
            db.session.add(badge)
            db.session.flush()

        # Handle image
        if 'robot_image' not in request.files:
            return jsonify({'success': False, 'error': 'Robot image is required'}), 400

        file = request.files['robot_image']
        if not file or not file.filename:
            return jsonify({'success': False, 'error': 'Robot image is required'}), 400

        image_data = base64.b64encode(file.read()).decode('utf-8')

        # Create or update RobotConfig
        config = RobotConfig.query.filter_by(badge_id=badge.id).first()
        if config:
            config.robot_image_data = image_data
            config.robot_image_path = None
            config.is_active = True
        else:
            config = RobotConfig(
                badge_id=badge.id,
                robot_image_data=image_data,
                is_active=True,
                created_by=current_user.id if current_user else None,
            )
            db.session.add(config)

        db.session.commit()

        return jsonify({
            'success': True,
            'figure': {
                'badge_id': badge.id,
                'badge_name': badge.name,
                'badge_color': badge.color,
                'robot_image_data': image_data,
                'robot_image_path': None,
            }
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


