@app.route('/api/admin/bom-cost/dissolved-bom-limbs', methods=['GET'])
@login_required
@require_any_role('admin', 'finance', 'system')
def get_dissolved_bom_limbs():
    """Get all dissolved BOMs with their polygon regions for the cost robot figure.
    Auto-creates CostRobotLimb entries linked to dissolved BOMs as needed."""
    try:
        badge_id = request.args.get('badge_id', type=int)
        if not badge_id:
            return jsonify({'success': False, 'error': 'badge_id required'}), 400

        # Ensure a CostRobotConfig exists for this badge (create if not)
        config = CostRobotConfig.query.filter_by(badge_id=badge_id).first()
        if not config:
            config = CostRobotConfig(badge_id=badge_id, is_active=True,
                                      created_by=current_user.id if current_user else None)
            db.session.add(config)
            db.session.flush()

        # Get all dissolved BOMs
        dissolved = DissolvedBOM.query.order_by(DissolvedBOM.name).all()

        result = []
        for d in dissolved:
            parts = json.loads(d.dissolved_parts_json) if d.dissolved_parts_json else []
            # Live price calculation from Part table
            cost = 0
            for p in parts:
                pn = p.get('part_number', '') or p.get('Part Number', '')
                rev = p.get('revision', '') or p.get('Revision', '')
                qty = p.get('quantity', 0) or p.get('QTY.', 0) or 0
                live_part = Part.query.filter_by(part_number=pn, revision=rev).first() if pn else None
                uc = (live_part.unit_cost or 0) if live_part else (p.get('unit_cost', 0) or 0)
                cost += float(uc) * float(qty)

            # Find existing CostRobotLimb linked to this dissolved BOM via LimbCostMapping
            mapping = LimbCostMapping.query.filter_by(dissolved_bom_id=d.id).join(
                CostRobotLimb, CostRobotLimb.id == LimbCostMapping.limb_id
            ).filter(CostRobotLimb.config_id == config.id).first()

            limb = CostRobotLimb.query.get(mapping.limb_id) if mapping else None

            result.append({
                'dissolved_bom_id': d.id,
                'name': d.name,
                'cost': round(cost, 2),
                'parts_count': len(parts),
                'dissolve_mode': d.dissolve_mode,
                'limb_id': limb.id if limb else None,
                'region_coords': json.loads(limb.region_coords) if limb and limb.region_coords else None,
                'color': limb.color if limb else '#4B2C6F',
            })

        db.session.commit()
        return jsonify({'success': True, 'dissolved_bom_limbs': result, 'config_id': config.id})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/bom-cost/dissolved-bom-limbs/<int:dissolved_bom_id>/region', methods=['PUT'])
@login_required
@require_any_role('admin')
def save_dissolved_bom_region(dissolved_bom_id):
    """Save polygon region for a dissolved BOM on the cost robot figure.
    Auto-creates CostRobotLimb and LimbCostMapping if needed."""
    try:
        data = request.get_json()
        badge_id = data.get('badge_id')
        region_coords = data.get('region_coords')  # [[x,y], ...] or null to clear

        if not badge_id:
            return jsonify({'success': False, 'error': 'badge_id required'}), 400

        dbom = DissolvedBOM.query.get(dissolved_bom_id)
        if not dbom:
            return jsonify({'success': False, 'error': 'Dissolved BOM not found'}), 404

        config = CostRobotConfig.query.filter_by(badge_id=badge_id).first()
        if not config:
            config = CostRobotConfig(badge_id=badge_id, is_active=True,
                                      created_by=current_user.id if current_user else None)
            db.session.add(config)
            db.session.flush()

        # Find or create the CostRobotLimb for this dissolved BOM
        mapping = LimbCostMapping.query.filter_by(dissolved_bom_id=dissolved_bom_id).join(
            CostRobotLimb, CostRobotLimb.id == LimbCostMapping.limb_id
        ).filter(CostRobotLimb.config_id == config.id).first()

        if mapping:
            limb = CostRobotLimb.query.get(mapping.limb_id)
        else:
            # Create limb + mapping
            max_order = db.session.query(db.func.max(CostRobotLimb.display_order)).filter_by(config_id=config.id).scalar() or 0
            limb = CostRobotLimb(
                config_id=config.id,
                name=dbom.name,
                display_order=max_order + 1,
                color='#4B2C6F',
            )
            db.session.add(limb)
            db.session.flush()
            new_mapping = LimbCostMapping(
                limb_id=limb.id,
                dissolved_bom_id=dissolved_bom_id,
                created_by=current_user.id if current_user else None,
            )
            db.session.add(new_mapping)

        limb.region_coords = json.dumps(region_coords) if region_coords else None
        db.session.commit()

        return jsonify({
            'success': True,
            'limb_id': limb.id,
            'region_coords': region_coords,
        })
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/bom-cost/limb-mappings/<int:limb_id>', methods=['PUT'])
@login_required
@require_any_role('admin', 'finance', 'system')
def update_limb_cost_mappings(limb_id):
    """Replace all BOM/dissolved BOM assignments for a cost limb"""
    try:
        limb = CostRobotLimb.query.get_or_404(limb_id)
        data = request.get_json()
        # Accepts: { items: [{ type: 'dissolved', id: 5 }, { type: 'bom', id: 12 }] }
        items = data.get('items', [])

        LimbCostMapping.query.filter_by(limb_id=limb_id).delete()

        for item in items:
            mapping = LimbCostMapping(
                limb_id=limb_id,
                created_by=current_user.id if current_user else None,
            )
            if item.get('type') == 'dissolved':
                mapping.dissolved_bom_id = item['id']
            else:
                mapping.bom_id = item['id']
            db.session.add(mapping)

        db.session.commit()
        return jsonify({'success': True, 'message': f'Updated mappings for limb "{limb.name}"'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/bom-cost/available-boms', methods=['GET'])
@login_required
@require_any_role('admin', 'finance', 'system')
def get_available_boms_for_cost():
    """Get all dissolved BOMs + regular BOMs available for assignment"""
    try:
        badge_id = request.args.get('badge_id', type=int)
        if not badge_id:
            return jsonify({'success': False, 'error': 'badge_id required'}), 400

        # Dissolved BOMs (not badge-scoped currently, return all)
        dissolved = DissolvedBOM.query.order_by(DissolvedBOM.name).all()
        dissolved_list = []
        for d in dissolved:
            parts = json.loads(d.dissolved_parts_json) if d.dissolved_parts_json else []
            cost = sum((p.get('unit_cost', 0) or 0) * (p.get('quantity', 0) or p.get('QTY.', 0) or 0) for p in parts)
            dissolved_list.append({
                'type': 'dissolved',
                'id': d.id,
                'name': d.name,
                'cost': round(cost, 2),
                'parts_count': len(parts),
                'dissolve_mode': d.dissolve_mode,
            })

        # Regular BOMs for this badge
        boms = BOMInstance.query.filter_by(badge_id=badge_id, is_latest=True, status='active').order_by(BOMInstance.assembly_part_number).all()
        bom_list = [{
            'type': 'bom',
            'id': b.id,
            'name': f"{b.description or b.assembly_part_number} {b.version or ''}".strip(),
            'cost': round(b.unit_cost or 0, 2),
            'assembly_part_number': b.assembly_part_number,
        } for b in boms]

        return jsonify({
            'success': True,
            'dissolved_boms': dissolved_list,
            'boms': bom_list,
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


